// Goi du lieu 007 - Tieng Viet lop 5 HOC KY 1 (v1.16: 8 mua cum 1-8; bo sung v1.16: muc 2 cho Bai 11/16/22/26/28/29 (+2) va Bai 1/4/5/6/8/14/15/23/27/31 (+1), muc 1 cho Bai 20 (+1); nguon cau hoi nen-004-v1 giu nguyen, bo sung chi gop trong app 007)
window.__GOI007 = window.__GOI007 || {};
window.__GOI007["tieng-viet-5"] = {"cacMua":[{"anhBia":"thanh-am-tuoi-tho","anhCanTao":[{"khoa":"thanh-am-tuoi-tho","moTa":"Một thung lũng xanh trong Khu Vườn Ngôn Từ lúc sớm mai: chuông gió bạc treo trên cành cây rung theo gió, cánh đồng hoa trải dài tới bến sông êm đềm, một chú ngựa con bằng mây trắng tung vó trên đồi cỏ; Cô Ong Chăm Chữ đeo kính bay phía trước, Biệt đội Ánh Sao áo trắng khăn quàng đỏ đi giữa hoa; một góc thung lũng bị sương xám phủ mờ. Phong cách 3D Pixar, không chữ."}],"cacBai":["1","2","3","4"],"cacChuDe":["1"],"id":"tv5-c1","lop":5,"mon":"Tiếng Việt","nhanVat":{"Cô Ong Chăm Chữ":"Cô Ong Chăm Chữ — ong thợ chăm chỉ của Khu Vườn Ngôn Từ, bay lượn đọc chính tả vui; là người đọc lời giải thích sau mỗi thử thách trong thế giới Tiếng Việt.","Minh Anh":"Đội trưởng Biệt đội Ánh Sao — quyết đoán, luôn đi đầu.","Sương Mù":"Sương Mù Quên Lãng — thế lực xám lạnh chuyên xóa chữ và kiến thức trong các cuốn sách.","Thảo Nguyên":"Bạn ngôn ngữ — hoạt bát, giỏi chữ nghĩa và tiếng Việt.","Thủ thư Số":"Người giữ sách của Thư viện Ánh Sao — hiền từ, hiểu biết, luôn đưa ra lời giải thích sau mỗi thử thách.","Tuấn Kiệt":"Bạn kỹ thuật — mê máy móc, thao tác nhanh và chính xác.","Đức Trí":"Bạn logic — điềm tĩnh, hay suy luận trước khi hành động."},"tap":[{"bai":"1","canh":[{"anh":"canh-dau","dong":[{"loi":"Sau những khu vườn của khối 3 và khối 4, Khu Vườn Ngôn Từ mở ra một khu vườn cuối — khu vườn của các bạn lớp 5, nơi những trang sách mang theo cả một thời tiểu học sắp khép lại.","nv":"Người kể"},{"loi":"Chào các cháu lớp 5! Các cháu là đàn anh đàn chị lớn nhất trường rồi đấy. Khu vườn này bắt đầu bằng chủ điểm Thế giới tuổi thơ — những thanh âm trong trẻo nhất của tuổi nhỏ.","nv":"Cô Ong Chăm Chữ"},{"loi":"Bài đầu tiên là Thanh âm của gió ạ? Chỉ nghe tên thôi đã thấy mát lành rồi.","nv":"Minh Anh"},{"loi":"Đúng thế. Bài đọc tả tiếng gió qua cảm nhận tinh tế của tác giả. Đọc bài này, các cháu để ý những từ ngữ gợi tả âm thanh và hình ảnh so sánh nhé.","nv":"Cô Ong Chăm Chữ"},{"loi":"Từ ngữ gợi tả làm cho tiếng gió như có hình, có nhạc ngay trước mắt mình ạ.","nv":"Thảo Nguyên"},{"loi":"Nhưng Sương Mù đã làm nhòe mất mấy đoạn tả gió hay nhất rồi. Đọc kỹ từng chi tiết, cả lớp sẽ khôi phục được bản nhạc của gió!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Thung lũng gió có hai lối vào. Cả lớp chọn lối nào trước nhé!","nv":"Đức Trí"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"canh-chu","dong":[{"loi":"Quả chữ trên cây này ghi những từ ngữ tả tiếng gió. Hái đúng quả là nghe rõ tiếng gió thì thầm!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"canh-chu","danChuyen":"Ngay lối vào thung lũng, Cây quả chữ mọc bên triền cỏ, cành lá rung rinh theo từng cơn gió nhẹ. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"1","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cây quả chữ — hái quả từ ngữ gợi tả"},{"canh":[{"anh":"cau-suong","dong":[{"loi":"Câu văn tả gió cũng có nhịp như nhạc. Đứng trên cầu, nghe kỹ từng câu là nhận ra ngay!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Một chiếc cầu nhỏ bắc qua con suối đầu nguồn dẫn vào thung lũng gió. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"1","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cầu vần thơ — nghe nhịp câu văn"}]},{"anh":"canh-kho","bienCo":{"dong":[{"loi":"Ối, sương tràn xuống bất ngờ, chữ trên các thẻ mờ đi rồi!","nv":"Minh Anh"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"1","mucDo":[1],"soCau":1}},"danChuyen":"Đi sâu vào thung lũng, Biệt đội gặp Dòng suối câu chảy quanh bãi cỏ nơi tác giả lắng nghe gió hát. Muốn hiểu điều tác giả gửi gắm phải nắm được ý chính của từng đoạn. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"1","mucDo":[2],"soCau":1}},{"anh":"kho-sang","danChuyen":"Cuối thung lũng là Hòm thư bí mật, nơi cất những cảm nhận về tuổi thơ trong bài đọc. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"1","mucDo":[1,2],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Tiếng gió hiện ra trọn vẹn rồi — khi vi vu, khi rì rào, thân thương như giọng của tuổi thơ!","nv":"Thảo Nguyên"},{"loi":"Cô tặng biệt đội Chiếc Chuông Gió Bạc. Nghe kìa... phía trước có một cánh đồng hoa đang nở rộ dưới nắng.","nv":"Cô Ong Chăm Chữ"},{"loi":"Cả một biển hoa! Đẹp quá đi mất!","nv":"Tuấn Kiệt"},{"loi":"Tập sau, biệt đội mình ra cánh đồng hoa nhé cả lớp!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t1","ten":"Tập 1 — Thanh âm của gió","tomTatTapTruoc":"Biệt đội Ánh Sao bước vào khu vườn cuối của Khu Vườn Ngôn Từ — khu vườn dành cho các bạn lớp 5, những người anh chị lớn nhất của trường tiểu học. Ngay cổng vườn, tiếng gió thổi qua những trang sách nghe như một bản nhạc không lời...","tuan":"1","vatPham":"Chiếc Chuông Gió Bạc"},{"bai":"2","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao đi dọc triền cỏ và bước ra một cánh đồng hoa mênh mông, nơi câu chuyện Cánh đồng hoa đang chờ.","nv":"Người kể"},{"loi":"Bài Cánh đồng hoa tả vẻ đẹp của thiên nhiên qua con mắt của những người biết yêu và biết ngắm nhìn. Các cháu để ý trình tự miêu tả: từ xa đến gần, từ toàn cảnh đến chi tiết.","nv":"Cô Ong Chăm Chữ"},{"loi":"Nắm trình tự tả cảnh là mình kể lại được cả cánh đồng theo đúng thứ tự ạ.","nv":"Đức Trí"},{"loi":"Bài còn giàu hình ảnh nhân hóa — hoa cỏ như biết nói, biết cười với người ngắm hoa.","nv":"Thảo Nguyên"},{"loi":"Sương đã làm phai màu mấy luống hoa đẹp nhất rồi. Đọc thật kỹ, cả lớp sẽ trả lại sắc màu cho cánh đồng!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Cánh đồng có hai lối mòn hoa. Cả lớp chọn lối nào trước?","nv":"Minh Anh"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"cau-suong","dong":[{"loi":"Đứng trên cầu nhìn xuống là thấy toàn cảnh cánh đồng. Theo nhịp tả từ xa đến gần nhé!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Cầu vần thơ bắc qua con mương nhỏ chia cánh đồng làm hai nửa, từ trên cầu nhìn xuống hoa trải dài như thảm. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"2","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cầu vần thơ — theo nhịp tả cảnh"},{"canh":[{"anh":"canh-chu","dong":[{"loi":"Quả chữ trên cây này ghi các chi tiết tả hoa. Hái đúng quả chi tiết là luống hoa rõ thêm một phần!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"canh-chu","danChuyen":"Cây quả chữ mọc giữa cánh đồng, bóng cây che một phần luống hoa đầu tiên chưa rõ màu. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"2","mucDo":[1],"soCau":1}}],"nhan":"Đến Cây quả chữ — hái quả chi tiết"}]},{"anh":"kho-sang","bienCo":{"dong":[{"loi":"Sương làm đường trơn quá, mình suýt trượt chân rồi!","nv":"Tuấn Kiệt"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"2","mucDo":[1],"soCau":1}},"danChuyen":"Giữa cánh đồng là Hòm thư bí mật của người trồng hoa, cất những dòng cảm nhận về vẻ đẹp thiên nhiên. Muốn mở hòm phải hiểu điều tác giả muốn nói qua từng chi tiết. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"2","mucDo":[2],"soCau":1}},{"anh":"canh-kho","danChuyen":"Bên kia cánh đồng, Dòng suối câu chảy qua bãi đất nơi những chi tiết hay nhất của bài đọc đang chờ được vớt lên. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"2","mucDo":[2,3],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Cánh đồng hoa rực rỡ trở lại rồi! Tả cảnh theo trình tự, thêm nhân hóa là cảnh vật sống hẳn lên!","nv":"Đức Trí"},{"loi":"Cô tặng biệt đội Hạt Hoa Ánh Sáng. Nhưng nghe kìa... có tiếng vó ngựa gõ nhịp từ phía đồi xa.","nv":"Cô Ong Chăm Chữ"},{"loi":"Như có một cậu bé đang cưỡi ngựa trong trí tưởng tượng vậy!","nv":"Thảo Nguyên"},{"loi":"Tập sau mình lên đồi gặp cậu bé ấy nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t2","ten":"Tập 2 — Cánh đồng hoa rực rỡ","tomTatTapTruoc":"Tập trước: Biệt đội khôi phục bản nhạc Thanh âm của gió, học cách nhận ra từ ngữ gợi tả và ý chính của bài đọc, rồi nhận Chiếc Chuông Gió Bạc. Cuối tập, một cánh đồng hoa rực rỡ hiện ra trước mắt...","tuan":"1","vatPham":"Hạt Hoa Ánh Sáng"},{"bai":"3","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao leo lên đồi cỏ, nơi bài thơ Tuổi Ngựa đang bay theo gió — bài thơ về một cậu bé giàu trí tưởng tượng.","nv":"Người kể"},{"loi":"Tuổi Ngựa là bài thơ đầy ắp hình ảnh: cậu bé tưởng tượng mình là chú ngựa con tung vó qua bao miền đất. Đọc thơ, các cháu cảm nhận nhịp điệu và những hình ảnh tưởng tượng bay bổng nhé.","nv":"Cô Ong Chăm Chữ"},{"loi":"Mỗi khổ thơ là một miền đất mới — tưởng tượng đưa người đọc đi xa thật xa ạ.","nv":"Thảo Nguyên"},{"loi":"Bài thơ còn cho thấy tình cảm của cậu bé với mẹ và quê hương ẩn sau những chuyến đi tưởng tượng.","nv":"Đức Trí"},{"loi":"Sương đã làm mờ mất mấy khổ thơ hay rồi. Đọc kỹ từng hình ảnh, cả lớp sẽ cùng chú ngựa con tung vó trở lại!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Đồi cỏ có hai sườn dốc. Cả lớp chọn sườn nào để lên trước?","nv":"Tuấn Kiệt"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"canh-kho","dong":[{"loi":"Thẻ câu trên suối ghi các khổ thơ theo trình tự chuyến đi tưởng tượng. Vớt đúng thẻ đầu tiên nhé!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"canh-kho","danChuyen":"Dòng suối câu chảy quanh chân đồi, in bóng mây trời xuống mặt nước trong veo. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"3","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Dòng suối câu — xuôi theo khổ thơ"},{"canh":[{"anh":"kho-sang","dong":[{"loi":"Trong hòm là những dòng mơ ước của cậu bé tuổi ngựa. Đọc kỹ là hiểu ngay tâm hồn cậu bé!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"kho-sang","danChuyen":"Dưới bóng cây đầu đồi, Hòm thư bí mật nằm im lìm, nắp hòm khắc hình một chú ngựa con đang tung vó. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"3","mucDo":[1],"soCau":1}}],"nhan":"Mở Hòm thư bí mật — đọc mơ ước của cậu bé"}]},{"anh":"canh-chu","bienCo":{"dong":[{"loi":"Ơ, sương che mất một nửa đáp án rồi, mình đọc không rõ nữa!","nv":"Thảo Nguyên"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"3","mucDo":[1],"soCau":1}},"danChuyen":"Giữa đồi, Cây quả chữ che mất phần thơ tả những miền đất trong tưởng tượng. Muốn thơ rõ phải nắm đúng hình ảnh và ý nghĩa của từng khổ. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"3","mucDo":[2],"soCau":1}},{"anh":"cau-suong","danChuyen":"Muốn xuống đồi phải qua Cầu vần thơ, nơi thử thách về nhịp điệu và từ ngữ gợi hình của bài thơ đang chờ. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"3","mucDo":[2,3],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Bài thơ rõ hẳn rồi — chú ngựa con tung vó qua bao miền đất mà lòng vẫn hướng về mẹ và quê nhà!","nv":"Thảo Nguyên"},{"loi":"Cô tặng biệt đội Chiếc Móng Ngựa Vàng. Nghe kìa... dưới chân đồi là một bến sông êm đềm, nơi bao kỷ niệm tuổi thơ neo đậu.","nv":"Cô Ong Chăm Chữ"},{"loi":"Bến sông ấy chắc là nơi quen thuộc của rất nhiều bạn nhỏ.","nv":"Minh Anh"},{"loi":"Tập sau mình xuống bến sông nhé cả lớp!","nv":"Tuấn Kiệt"}],"loai":"thoai"}],"id":"t3","ten":"Tập 3 — Tuổi Ngựa tung vó","tomTatTapTruoc":"Tập trước: Biệt đội khôi phục cánh đồng hoa, học cách tả cảnh theo trình tự và nhận ra hình ảnh nhân hóa, rồi nhận Hạt Hoa Ánh Sáng. Cuối tập, tiếng vó ngựa gõ nhịp vọng lại từ phía đồi xa...","tuan":"2","vatPham":"Chiếc Móng Ngựa Vàng"},{"bai":"4","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao xuống bến sông quê, nơi bài văn Bến sông tuổi thơ kể về những kỷ niệm trong trẻo bên dòng sông quê hương.","nv":"Người kể"},{"loi":"Bài Bến sông tuổi thơ gợi lại những kỷ niệm êm đềm: tắm sông, thả thuyền, nghe tiếng quê hương. Đọc bài này, các cháu để ý chi tiết gợi cảm xúc và cách tác giả gắn kỷ niệm với con người quê nhà.","nv":"Cô Ong Chăm Chữ"},{"loi":"Chi tiết nhỏ thôi mà gợi cả một trời kỷ niệm ạ.","nv":"Minh Anh"},{"loi":"Giọng văn nhẹ nhàng, tha thiết — đọc lên là thấy tình yêu quê hương trong từng câu chữ.","nv":"Thảo Nguyên"},{"loi":"Sương đã làm nhòe mất đoạn kết của bài văn rồi. Đọc kỹ từng phần, cả lớp sẽ nối lại được dòng kỷ niệm!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Bến sông có hai lối xuống nước. Cả lớp chọn lối nào trước?","nv":"Minh Anh"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"cau-suong","dong":[{"loi":"Đứng trên cầu nghe rõ tiếng nước vỗ mạn thuyền. Câu văn hay là nhận ra ngay!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Cầu vần thơ bắc qua con lạch nhỏ dẫn ra bến sông, ván cầu khắc những đợt sóng lăn tăn. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"4","mucDo":[1],"soCau":1}}],"nhan":"Qua Cầu vần thơ — nghe tiếng sông quê"},{"canh":[{"anh":"canh-kho","dong":[{"loi":"Thẻ câu trên suối ghi các kỷ niệm theo trình tự bài văn. Vớt đúng thẻ là nối được dòng kỷ niệm!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"canh-kho","danChuyen":"Dòng suối câu chảy êm ra bến sông lớn, mang theo những thẻ câu còn mờ chữ. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"4","mucDo":[1],"soCau":1}}],"nhan":"Xuôi Dòng suối câu — theo dòng kỷ niệm"}]},{"anh":"kho-sang","bienCo":{"dong":[{"loi":"Sương kéo đến dày quá, mọi thứ nhòe đi như nhìn qua kính mờ!","nv":"Đức Trí"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"4","mucDo":[1],"soCau":1}},"danChuyen":"Trên bến sông là Hòm thư bí mật, cất những dòng tâm sự của người con xa quê nhớ về bến sông tuổi thơ. Muốn mở hòm phải hiểu điều tác giả gửi gắm. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"4","mucDo":[2],"soCau":1}},{"anh":"canh-chu","danChuyen":"Trước khi rời bến, Cây quả chữ bên gốc gạo còn một thử thách về từ ngữ và ý nghĩa của bài văn. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"4","mucDo":[1,2],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Dòng kỷ niệm nối lại trọn vẹn rồi! Bến sông tuổi thơ là nơi neo giữ những năm tháng trong trẻo nhất!","nv":"Minh Anh"},{"loi":"Cô tặng biệt đội Chiếc Mái Chèo Gỗ. Nhưng nhìn kìa...","nv":"Cô Ong Chăm Chữ"},{"loi":"Khà... khà... Bốn câu chuyện tuổi thơ thì đã sao? Cổng Thanh Âm vẫn nằm trong tay ta...","nv":"Sương Mù"},{"loi":"Cổng Thanh Âm hiện ra ở cuối bến sông, và Sương Mù đang giữ cổng! Cả lớp ơi, tập đặc biệt — mình cùng phá cổng nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t4","ten":"Tập 4 — Bến sông tuổi thơ","tomTatTapTruoc":"Tập trước: Biệt đội cùng chú ngựa con trong bài thơ Tuổi Ngựa tung vó qua những miền đất tưởng tượng, cảm nhận nhịp thơ và tình cảm gia đình, rồi nhận Chiếc Móng Ngựa Vàng. Cuối tập, một bến sông êm đềm hiện ra dưới chân đồi...","tuan":"2","vatPham":"Chiếc Mái Chèo Gỗ"},{"bai":"1+2+3+4","canh":[{"anh":"canh-trum","dong":[{"loi":"Ta là Sương Mù Quên Lãng. Khiên sương của ta chỉ vỡ khi gặp câu trả lời đúng. Các ngươi dám thử không?","nv":"Sương Mù"},{"loi":"Biệt đội Ánh Sao sẵn sàng! Từ ngữ gợi tả, trình tự, hình ảnh thơ — chúng mình đều nắm chắc!","nv":"Minh Anh"},{"loi":"Luật phá cổng: trên cổng có bốn ô chiêu thức phát sáng. Chọn chiêu thức là đáp án đúng, khiên sương nứt một phần. Bình tĩnh đọc kỹ, các cháu nhé.","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-trum","danChuyen":"Sương Mù thổi một làn khói che mất bản nhạc của gió. Cả lớp chọn chiêu thức đúng về từ ngữ gợi tả và ý chính của bài Thanh âm của gió nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"1","mucDo":[2],"soCau":1}},{"anh":"canh-trum","danChuyen":"Khiên sương rung lên! Sương Mù tung đòn Cánh đồng hoa với trình tự tả cảnh và hình ảnh nhân hóa. Cả lớp chọn chiêu thức đúng để phá tiếp nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"2","mucDo":[2],"soCau":1}},{"anh":"canh-trum","danChuyen":"Sương Mù làm mờ những khổ thơ Tuổi Ngựa trong làn khói. Cả lớp chọn chiêu thức đúng về hình ảnh tưởng tượng và tình cảm trong thơ nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"3","mucDo":[2,3],"soCau":1}},{"anh":"canh-trum","danChuyen":"Đòn cuối cùng! Sương Mù dồn hết sức vào Bến sông tuổi thơ. Cả lớp chọn chiêu thức đúng để phá tan khiên sương nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"4","mucDo":[2],"soCau":1}},{"anh":"cua-mo","dong":[{"loi":"Thôi được... Cổng này là của các ngươi. Nhưng phía trước là những hạt mầm và một hành tinh lạ, sương của ta còn dày lắm...","nv":"Sương Mù"},{"loi":"Cổng Thanh Âm đã mở! Biệt đội nhận Chìa Cổng Thanh Âm. Thanh âm tuổi thơ — các cháu đã giữ trọn được rồi.","nv":"Cô Ong Chăm Chữ"},{"loi":"Phía sau cổng có tiếng hạt mầm tách vỏ và tiếng bóng lăn trên sân cỏ...","nv":"Đức Trí"},{"loi":"Đó là mùa tiếp theo đang chờ! Hẹn gặp cả lớp ở mùa sau nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"trum","laTapTrum":true,"ten":"Tập đặc biệt — Cổng Thanh Âm","tomTatTapTruoc":"Biệt đội đã khôi phục bốn câu chuyện đầu tiên của chủ điểm Thế giới tuổi thơ: thanh âm của gió, cánh đồng hoa, chú ngựa con trong tưởng tượng và bến sông quê nhà. Giờ đây, Sương Mù Quên Lãng đang giữ Cổng Thanh Âm bằng một khiên sương dày...","tuan":"2","vatPham":"Chìa Cổng Thanh Âm"}],"tenMua":"Mùa 1 — Thanh Âm Tuổi Thơ","tomTatMua":"Khu vườn cuối của Khu Vườn Ngôn Từ mở cửa đón các bạn lớp 5 bằng chủ điểm Thế giới tuổi thơ. Sương Mù Quên Lãng đã lén vào trước, làm nhòe những trang sách trong trẻo nhất: tiếng gió thì thầm, cánh đồng hoa rực rỡ, chú ngựa con trong trí tưởng tượng và bến sông quê nhà. Cùng Cô Ong Chăm Chữ, Biệt đội Ánh Sao khôi phục từng thanh âm tuổi thơ để mở Cổng Thanh Âm."},{"anhBia":"hanh-tinh-tuoi-nho","anhCanTao":[{"khoa":"hanh-tinh-tuoi-nho","moTa":"Một hành tinh nhỏ xinh lơ lửng trong Khu Vườn Ngôn Từ: trên bề mặt hành tinh có luống mầm xanh vừa nhú, một sân cỏ tròn với quả bóng, tủ kính trưng bày những món đồ sưu tập lạ và một đài quan sát nhỏ hướng lên trời sao; Cô Ong Chăm Chữ đeo kính bay vòng quanh, Biệt đội Ánh Sao áo trắng khăn quàng đỏ đứng trên hành tinh vẫy tay; một góc hành tinh bị sương xám phủ mờ. Phong cách 3D Pixar, không chữ."}],"cacBai":["5","6","7","8"],"cacChuDe":["1"],"id":"tv5-c2","lop":5,"mon":"Tiếng Việt","nhanVat":{"Cô Ong Chăm Chữ":"Cô Ong Chăm Chữ — ong thợ chăm chỉ của Khu Vườn Ngôn Từ, bay lượn đọc chính tả vui; là người đọc lời giải thích sau mỗi thử thách trong thế giới Tiếng Việt.","Minh Anh":"Đội trưởng Biệt đội Ánh Sao — quyết đoán, luôn đi đầu.","Sương Mù":"Sương Mù Quên Lãng — thế lực xám lạnh chuyên xóa chữ và kiến thức trong các cuốn sách.","Thảo Nguyên":"Bạn ngôn ngữ — hoạt bát, giỏi chữ nghĩa và tiếng Việt.","Thủ thư Số":"Người giữ sách của Thư viện Ánh Sao — hiền từ, hiểu biết, luôn đưa ra lời giải thích sau mỗi thử thách.","Tuấn Kiệt":"Bạn kỹ thuật — mê máy móc, thao tác nhanh và chính xác.","Đức Trí":"Bạn logic — điềm tĩnh, hay suy luận trước khi hành động."},"tap":[{"bai":"5","canh":[{"anh":"canh-dau","dong":[{"loi":"Qua Cổng Thanh Âm, Biệt đội Ánh Sao bước vào khu đất ươm của Khu Vườn Ngôn Từ, nơi bài thơ Tiếng hạt nảy mầm kể về sức sống kỳ diệu của những hạt giống.","nv":"Người kể"},{"loi":"Bài thơ tả khoảnh khắc hạt giống nảy mầm bằng những hình ảnh rất đỗi dịu dàng. Đọc thơ, các cháu để ý cách tác giả nhân hóa hạt mầm và nhịp thơ nhẹ như hơi thở.","nv":"Cô Ong Chăm Chữ"},{"loi":"Hạt mầm như một em bé đang vươn vai thức dậy vậy ạ.","nv":"Thảo Nguyên"},{"loi":"Bài thơ còn gửi gắm niềm tin vào sự lớn lên — nhỏ bé mà kiên cường.","nv":"Đức Trí"},{"loi":"Sương đã phủ mờ mấy luống mầm non rồi. Đọc kỹ từng hình ảnh, cả lớp sẽ đánh thức được những hạt mầm!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Khu đất ươm có hai lối vào giữa các luống mầm. Cả lớp chọn lối nào trước nhé!","nv":"Đức Trí"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"canh-chu","dong":[{"loi":"Quả chữ trên cây này ghi những hình ảnh trong bài thơ. Hái đúng quả là mầm nhú thêm một lá!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"canh-chu","danChuyen":"Ngay lối vào khu đất ươm, Cây quả chữ mọc bên luống mầm đầu tiên, cành lá che một phần bài thơ chưa rõ chữ. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"5","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cây quả chữ — hái quả hình ảnh thơ"},{"canh":[{"anh":"cau-suong","dong":[{"loi":"Nhịp thơ nhẹ nhàng như tiếng mầm tách vỏ. Đứng trên cầu nghe kỹ là nhận ra ngay!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Một chiếc cầu nhỏ bắc qua mương nước tưới dẫn vào giữa khu đất ươm. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"5","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cầu vần thơ — nghe nhịp nảy mầm"}]},{"anh":"canh-kho","bienCo":{"dong":[{"loi":"Ối, sương tràn xuống bất ngờ, chữ trên các thẻ mờ đi rồi!","nv":"Minh Anh"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"5","mucDo":[1],"soCau":1}},"danChuyen":"Giữa khu đất ươm, Dòng suối câu chảy quanh luống mầm lớn nhất. Muốn mầm vươn cao phải hiểu điều tác giả gửi gắm qua hình ảnh hạt giống. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"5","mucDo":[2],"soCau":1}},{"anh":"kho-sang","danChuyen":"Cuối khu đất ươm là Hòm thư bí mật, nơi cất những cảm nhận về sức sống và sự lớn lên trong bài thơ. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"5","mucDo":[2,3],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Những hạt mầm vươn lên xanh mướt rồi! Nhỏ bé mà kiên cường — như chúng mình đang lớn lên từng ngày!","nv":"Thảo Nguyên"},{"loi":"Cô tặng biệt đội Chiếc Mầm Non Xanh. Nghe kìa... phía sân cỏ vọng lại tiếng reo hò và tiếng bóng lăn.","nv":"Cô Ong Chăm Chữ"},{"loi":"Có một trận bóng đang diễn ra ở sân trước!","nv":"Tuấn Kiệt"},{"loi":"Tập sau, biệt đội mình ra sân cỏ nhé cả lớp!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t1","ten":"Tập 1 — Tiếng hạt nảy mầm","tomTatTapTruoc":"Mùa trước: Biệt đội mở Cổng Thanh Âm, giữ trọn bốn câu chuyện tuổi thơ và nhận Chìa Cổng Thanh Âm. Phía sau cổng, một khu đất ươm mầm đang chờ, nơi những hạt giống nhỏ bắt đầu tách vỏ...","tuan":"3","vatPham":"Chiếc Mầm Non Xanh"},{"bai":"6","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao chạy ra sân cỏ của khu vườn, nơi bài văn Ngôi sao sân cỏ kể về một cầu thủ nhỏ tài năng và đầy nỗ lực.","nv":"Người kể"},{"loi":"Bài văn kể về hành trình rèn luyện của một bạn nhỏ yêu bóng đá. Đọc bài này, các cháu để ý trình tự sự việc và những chi tiết cho thấy sự khổ luyện của nhân vật.","nv":"Cô Ong Chăm Chữ"},{"loi":"Tài năng chỉ nở hoa khi có khổ luyện — chi tiết nào trong bài cho thấy điều đó là phải nắm chắc ạ.","nv":"Đức Trí"},{"loi":"Giọng văn hào hứng, giàu hình ảnh sân cỏ, đọc mà như đang xem trận đấu thật.","nv":"Thảo Nguyên"},{"loi":"Sương đã làm mờ mất bảng thành tích của ngôi sao nhỏ rồi. Đọc kỹ từng chi tiết, cả lớp sẽ khôi phục được câu chuyện sân cỏ!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Sân cỏ có hai cánh vào sân. Cả lớp chọn cánh nào trước?","nv":"Minh Anh"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"cau-suong","dong":[{"loi":"Đứng trên cầu nhìn xuống là thấy toàn cảnh sân cỏ. Theo nhịp trận đấu từ đầu đến cuối nhé!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Cầu vần thơ bắc qua đường chạy quanh sân cỏ, từ trên cầu nhìn xuống sân xanh mướt. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"6","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cầu vần thơ — theo nhịp trận đấu"},{"canh":[{"anh":"canh-chu","dong":[{"loi":"Quả chữ trên cây này ghi các chi tiết về sự rèn luyện của nhân vật. Hái đúng quả là hiểu ngôi sao nhỏ thêm một phần!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"canh-chu","danChuyen":"Cây quả chữ mọc bên khán đài, bóng cây che một phần bảng thành tích chưa rõ chữ. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"6","mucDo":[1],"soCau":1}}],"nhan":"Đến Cây quả chữ — hái quả chi tiết khổ luyện"}]},{"anh":"kho-sang","bienCo":{"dong":[{"loi":"Sương làm đường trơn quá, mình suýt trượt chân rồi!","nv":"Tuấn Kiệt"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"6","mucDo":[1],"soCau":1}},"danChuyen":"Bên sân cỏ là Hòm thư bí mật của đội bóng, cất những dòng về ước mơ và nghị lực. Muốn mở hòm phải hiểu điều tác giả muốn nói qua câu chuyện. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"6","mucDo":[2],"soCau":1}},{"anh":"canh-kho","danChuyen":"Sau trận đấu, Dòng suối câu chảy qua bãi tập, thẻ câu hỏi về những chi tiết hay nhất của bài văn đang chờ. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"6","mucDo":[2,3],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Câu chuyện sân cỏ hiện ra trọn vẹn rồi! Ngôi sao sáng nhất là ngôi sao của sự khổ luyện!","nv":"Đức Trí"},{"loi":"Cô tặng biệt đội Chiếc Huy Chương Sân Cỏ. Nhưng nhìn kìa... trong phòng trưng bày bên sân có một bộ sưu tập rất lạ đang bị sương phủ.","nv":"Cô Ong Chăm Chữ"},{"loi":"Bộ sưu tập gì mà trông độc đáo thế nhỉ?","nv":"Thảo Nguyên"},{"loi":"Tập sau mình vào phòng trưng bày xem nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t2","ten":"Tập 2 — Ngôi sao sân cỏ","tomTatTapTruoc":"Tập trước: Biệt đội đánh thức những hạt mầm trong bài thơ Tiếng hạt nảy mầm, cảm nhận hình ảnh nhân hóa và niềm tin vào sự lớn lên, rồi nhận Chiếc Mầm Non Xanh. Cuối tập, tiếng reo hò vọng lại từ sân cỏ phía trước...","tuan":"3","vatPham":"Chiếc Huy Chương Sân Cỏ"},{"bai":"7","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao bước vào phòng trưng bày của khu vườn, nơi bài văn Bộ sưu tập độc đáo giới thiệu một bộ sưu tập không giống ai.","nv":"Người kể"},{"loi":"Bài văn tả một bộ sưu tập rất riêng của một bạn nhỏ — mỗi món đồ là một kỷ niệm, một câu chuyện. Đọc bài này, các cháu để ý cách tác giả chọn chi tiết tiêu biểu để tả từng món đồ.","nv":"Cô Ong Chăm Chữ"},{"loi":"Chi tiết tiêu biểu làm cho món đồ hiện lên sống động, không lẫn với món nào khác ạ.","nv":"Thảo Nguyên"},{"loi":"Bài còn cho thấy niềm đam mê và sự trân trọng của người sưu tập với những điều nhỏ bé.","nv":"Đức Trí"},{"loi":"Sương đã làm lạc mất mấy nhãn chú thích của bộ sưu tập rồi. Đọc kỹ từng chi tiết, cả lớp sẽ gắn lại đúng nhãn cho từng món!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Phòng trưng bày có hai dãy tủ kính. Cả lớp chọn dãy nào trước?","nv":"Tuấn Kiệt"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"canh-kho","dong":[{"loi":"Thẻ câu trên suối ghi các món đồ theo trình tự bài văn. Vớt đúng thẻ đầu tiên nhé!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"canh-kho","danChuyen":"Dòng suối câu chảy dọc phòng trưng bày, in bóng những tủ kính xuống mặt nước. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"7","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Dòng suối câu — theo dấu từng món đồ"},{"canh":[{"anh":"kho-sang","dong":[{"loi":"Trong hòm là những dòng kể về nguồn gốc các món đồ. Đọc thư là hiểu vì sao chúng độc đáo!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"kho-sang","danChuyen":"Dưới dãy tủ kính đầu tiên, Hòm thư bí mật nằm im lìm, nắp hòm khắc hình một chiếc kính lúp nhỏ. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"7","mucDo":[1],"soCau":1}}],"nhan":"Mở Hòm thư bí mật — đọc câu chuyện của món đồ"}]},{"anh":"canh-chu","bienCo":{"dong":[{"loi":"Ơ, sương che mất một nửa đáp án rồi, mình đọc không rõ nữa!","nv":"Thảo Nguyên"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"7","mucDo":[1],"soCau":1}},"danChuyen":"Giữa phòng trưng bày, Cây quả chữ che mất phần tả món đồ tiêu biểu nhất. Muốn tủ kính rõ phải chọn đúng chi tiết tác giả đã tả. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"7","mucDo":[2],"soCau":1}},{"anh":"cau-suong","danChuyen":"Muốn ra khỏi phòng trưng bày phải qua Cầu vần thơ, nơi thử thách về từ ngữ miêu tả và ý nghĩa của bài văn đang chờ. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"7","mucDo":[2,3],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Bộ sưu tập hiện ra trọn vẹn rồi — độc đáo vì mỗi món đồ đều mang một câu chuyện riêng!","nv":"Thảo Nguyên"},{"loi":"Cô tặng biệt đội Chiếc Kính Lúp Nhỏ. Nghe kìa... trên nóc phòng trưng bày có một đài quan sát hướng lên bầu trời đầy sao.","nv":"Cô Ong Chăm Chữ"},{"loi":"Như đang nhìn ra một hành tinh xa lạ nào đó vậy!","nv":"Đức Trí"},{"loi":"Tập sau mình lên đài quan sát nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t3","ten":"Tập 3 — Bộ sưu tập độc đáo","tomTatTapTruoc":"Tập trước: Biệt đội khôi phục câu chuyện Ngôi sao sân cỏ, nắm trình tự sự việc và bài học về sự khổ luyện, rồi nhận Chiếc Huy Chương Sân Cỏ. Cuối tập, một bộ sưu tập lạ trong phòng trưng bày khiến cả đội tò mò...","tuan":"4","vatPham":"Chiếc Kính Lúp Nhỏ"},{"bai":"8","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao leo lên đài quan sát của khu vườn, nơi bài văn Hành tinh kì lạ mở ra một thế giới tưởng tượng đầy bất ngờ.","nv":"Người kể"},{"loi":"Bài văn đưa người đọc đến một hành tinh lạ bằng trí tưởng tượng phong phú của tác giả. Đọc bài này, các cháu để ý những chi tiết tưởng tượng và cách tác giả so sánh hành tinh lạ với Trái Đất của chúng ta.","nv":"Cô Ong Chăm Chữ"},{"loi":"So sánh giúp mình hình dung hành tinh lạ rõ hơn hẳn ạ.","nv":"Minh Anh"},{"loi":"Bài còn gợi câu hỏi lớn: con người cần trân trọng hành tinh xanh của mình như thế nào.","nv":"Thảo Nguyên"},{"loi":"Sương vũ trụ đã phủ mờ mất bản đồ của hành tinh lạ rồi. Đọc kỹ từng chi tiết, cả lớp sẽ vẽ lại được bản đồ ấy!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Đài quan sát có hai ống kính hướng về hai phía. Cả lớp chọn phía nào trước?","nv":"Minh Anh"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"cau-suong","dong":[{"loi":"Đứng trên cầu nghe rõ những tín hiệu lạ từ hành tinh xa. Câu văn hay là nhận ra ngay!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Cầu vần thơ bắc qua con suối nhỏ dẫn lên đài quan sát, ván cầu khắc những ngôi sao lấp lánh. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"8","mucDo":[1],"soCau":1}}],"nhan":"Qua Cầu vần thơ — nghe tín hiệu hành tinh"},{"canh":[{"anh":"canh-kho","dong":[{"loi":"Thẻ câu trên suối ghi hành trình khám phá hành tinh theo trình tự bài văn. Vớt đúng thẻ là nối được hành trình!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"canh-kho","danChuyen":"Dòng suối câu chảy êm qua chân đài quan sát, mang theo những thẻ câu còn mờ chữ. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"8","mucDo":[1],"soCau":1}}],"nhan":"Xuôi Dòng suối câu — theo hành trình khám phá"}]},{"anh":"kho-sang","bienCo":{"dong":[{"loi":"Sương kéo đến dày quá, mọi thứ nhòe đi như nhìn qua kính mờ!","nv":"Đức Trí"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"8","mucDo":[1],"soCau":1}},"danChuyen":"Trên đài quan sát là Hòm thư bí mật, cất những dòng suy ngẫm về Trái Đất sau chuyến đi tưởng tượng. Muốn mở hòm phải hiểu điều tác giả gửi gắm. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"8","mucDo":[2],"soCau":1}},{"anh":"canh-chu","danChuyen":"Trước khi rời đài, Cây quả chữ bên ống kính lớn còn một thử thách về từ ngữ và ý nghĩa của bài văn. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"8","mucDo":[1,2],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Bản đồ hành tinh lạ vẽ lại xong rồi! Càng đi xa trong tưởng tượng, càng yêu hành tinh xanh của mình!","nv":"Minh Anh"},{"loi":"Cô tặng biệt đội Mảnh Sao Băng Nhỏ. Nhưng nhìn kìa...","nv":"Cô Ong Chăm Chữ"},{"loi":"Khà... khà... Bốn câu chuyện nữa thì đã sao? Cổng Hành Tinh vẫn nằm trong tay ta...","nv":"Sương Mù"},{"loi":"Cổng Hành Tinh hiện ra giữa đài quan sát, và Sương Mù đang giữ cổng! Cả lớp ơi, tập đặc biệt — mình cùng phá cổng nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t4","ten":"Tập 4 — Hành tinh kì lạ","tomTatTapTruoc":"Tập trước: Biệt đội gắn lại nhãn cho Bộ sưu tập độc đáo, học cách chọn chi tiết tiêu biểu khi miêu tả, rồi nhận Chiếc Kính Lúp Nhỏ. Cuối tập, một đài quan sát hướng lên bầu trời đầy sao mở ra trên nóc phòng trưng bày...","tuan":"4","vatPham":"Mảnh Sao Băng Nhỏ"},{"bai":"5+6+7+8","canh":[{"anh":"canh-trum","dong":[{"loi":"Ta là Sương Mù Quên Lãng. Khiên sương của ta chỉ vỡ khi gặp câu trả lời đúng. Các ngươi dám thử không?","nv":"Sương Mù"},{"loi":"Biệt đội Ánh Sao sẵn sàng! Hình ảnh thơ, trình tự, chi tiết tiêu biểu — chúng mình đều nắm chắc!","nv":"Minh Anh"},{"loi":"Luật phá cổng: trên cổng có bốn ô chiêu thức phát sáng. Chọn chiêu thức là đáp án đúng, khiên sương nứt một phần. Bình tĩnh đọc kỹ, các cháu nhé.","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-trum","danChuyen":"Sương Mù thổi một làn khói che mất những luống mầm non. Cả lớp chọn chiêu thức đúng về hình ảnh và ý nghĩa của bài Tiếng hạt nảy mầm nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"5","mucDo":[2,3],"soCau":1}},{"anh":"canh-trum","danChuyen":"Khiên sương rung lên! Sương Mù tung đòn Ngôi sao sân cỏ với trình tự sự việc và bài học khổ luyện. Cả lớp chọn chiêu thức đúng để phá tiếp nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"6","mucDo":[2,3],"soCau":1}},{"anh":"canh-trum","danChuyen":"Sương Mù làm lạc nhãn chú thích của bộ sưu tập trong làn khói. Cả lớp chọn chiêu thức đúng về chi tiết tiêu biểu nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"7","mucDo":[2],"soCau":1}},{"anh":"canh-trum","danChuyen":"Đòn cuối cùng! Sương Mù dồn hết sức vào Hành tinh kì lạ. Cả lớp chọn chiêu thức đúng để phá tan khiên sương nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"8","mucDo":[2],"soCau":1}},{"anh":"cua-mo","dong":[{"loi":"Thôi được... Cổng này là của các ngươi. Nhưng phía sau cổng là cổng trời và những hang động sâu, sương của ta còn dày lắm...","nv":"Sương Mù"},{"loi":"Cổng Hành Tinh đã mở! Biệt đội nhận Chìa Cổng Hành Tinh. Trí tưởng tượng của tuổi thơ — các cháu đã giữ trọn được rồi.","nv":"Cô Ong Chăm Chữ"},{"loi":"Phía sau cổng có tiếng gió hú qua cổng trời và tiếng nước nhỏ giọt trong hang sâu...","nv":"Đức Trí"},{"loi":"Đó là chủ điểm Thiên nhiên kì thú đang chờ! Hẹn gặp cả lớp ở mùa tiếp theo nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"trum","laTapTrum":true,"ten":"Tập đặc biệt — Cổng Hành Tinh","tomTatTapTruoc":"Biệt đội đã khôi phục bốn câu chuyện tiếp theo của chủ điểm Thế giới tuổi thơ: hạt mầm nảy lên, ngôi sao sân cỏ, bộ sưu tập độc đáo và hành tinh kì lạ trong tưởng tượng. Giờ đây, Sương Mù Quên Lãng đang giữ Cổng Hành Tinh bằng một khiên sương dày...","tuan":"4","vatPham":"Chìa Cổng Hành Tinh"}],"tenMua":"Mùa 2 — Hành Tinh Tuổi Nhỏ","tomTatMua":"Chủ điểm Thế giới tuổi thơ đưa Biệt đội Ánh Sao đi tiếp qua những miền tưởng tượng phong phú: hạt mầm tách vỏ vươn lên, ngôi sao nhỏ khổ luyện trên sân cỏ, bộ sưu tập độc đáo của một bạn nhỏ và hành tinh kì lạ chỉ có trong mơ. Sương Mù Quên Lãng phủ mờ từng trang sách, và biệt đội phải khôi phục tất cả để mở Cổng Hành Tinh."},{"anhBia":"cong-troi-ki-thu","anhCanTao":[{"khoa":"cong-troi-ki-thu","moTa":"Một cổng trời bằng đá phủ mây trắng trên đỉnh núi cao trong Khu Vườn Ngôn Từ: qua cổng nhìn xuống thấy rừng xanh trải dài, miệng hang động phát sáng lấp lánh và vịnh biển với những hòn đảo đá nhô lên mặt nước phía xa; Cô Ong Chăm Chữ đeo kính bay trước cổng, Biệt đội Ánh Sao áo trắng khăn quàng đỏ bước lên bậc đá; một góc cổng bị sương xám phủ mờ. Phong cách 3D Pixar, không chữ."}],"cacBai":["9","10","11","12"],"cacChuDe":["2"],"id":"tv5-c3","lop":5,"mon":"Tiếng Việt","nhanVat":{"Cô Ong Chăm Chữ":"Cô Ong Chăm Chữ — ong thợ chăm chỉ của Khu Vườn Ngôn Từ, bay lượn đọc chính tả vui; là người đọc lời giải thích sau mỗi thử thách trong thế giới Tiếng Việt.","Minh Anh":"Đội trưởng Biệt đội Ánh Sao — quyết đoán, luôn đi đầu.","Sương Mù":"Sương Mù Quên Lãng — thế lực xám lạnh chuyên xóa chữ và kiến thức trong các cuốn sách.","Thảo Nguyên":"Bạn ngôn ngữ — hoạt bát, giỏi chữ nghĩa và tiếng Việt.","Thủ thư Số":"Người giữ sách của Thư viện Ánh Sao — hiền từ, hiểu biết, luôn đưa ra lời giải thích sau mỗi thử thách.","Tuấn Kiệt":"Bạn kỹ thuật — mê máy móc, thao tác nhanh và chính xác.","Đức Trí":"Bạn logic — điềm tĩnh, hay suy luận trước khi hành động."},"tap":[{"bai":"9","canh":[{"anh":"canh-dau","dong":[{"loi":"Qua Cổng Hành Tinh, Biệt đội Ánh Sao bước vào chủ điểm Thiên nhiên kì thú. Trước mặt biệt đội là một cổng trời cao ngất, nơi bài văn Trước cổng trời mở ra khung cảnh núi non hùng vĩ.","nv":"Người kể"},{"loi":"Bài Trước cổng trời tả cảnh thiên nhiên ở vùng núi cao qua cảm nhận của tác giả. Đọc bài này, các cháu để ý trình tự miêu tả không gian và những hình ảnh so sánh làm cảnh vật hiện lên sống động.","nv":"Cô Ong Chăm Chữ"},{"loi":"Tả cảnh theo trình tự không gian — từ dưới lên trên, từ gần ra xa — là cảnh hiện ra có lớp lang ạ.","nv":"Đức Trí"},{"loi":"Giọng văn trầm hùng mà tha thiết, nghe như tác giả đang đứng giữa mây trời thật vậy.","nv":"Thảo Nguyên"},{"loi":"Sương núi đã hòa cùng Sương Mù làm mờ mất mấy đoạn tả cảnh hay nhất rồi. Đọc kỹ từng chi tiết, cả lớp sẽ mở được khung trời ấy!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Sườn núi có hai lối lên cổng trời. Cả lớp chọn lối nào trước nhé!","nv":"Đức Trí"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"canh-chu","dong":[{"loi":"Quả chữ trên cây này ghi các chi tiết tả núi non. Hái đúng quả là khung cảnh rõ thêm một phần!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"canh-chu","danChuyen":"Ngay lối lên núi, Cây quả chữ mọc bên triền đá, cành lá che một phần bài văn chưa rõ chữ. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"9","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cây quả chữ — hái quả chi tiết tả cảnh"},{"canh":[{"anh":"cau-suong","dong":[{"loi":"Câu văn tả cảnh cũng có nhịp như nhạc núi. Đứng trên cầu, nghe kỹ từng câu là nhận ra ngay!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Một chiếc cầu nhỏ bắc qua con suối đầu nguồn dưới chân núi. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"9","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cầu vần thơ — nghe nhịp câu văn tả cảnh"}]},{"anh":"canh-kho","bienCo":{"dong":[{"loi":"Ối, sương tràn xuống bất ngờ, chữ trên các thẻ mờ đi rồi!","nv":"Minh Anh"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"9","mucDo":[1],"soCau":1}},"danChuyen":"Đi sâu vào sườn núi, Biệt đội gặp Dòng suối câu chảy quanh bãi đá nơi tác giả ngắm nhìn cổng trời. Muốn hiểu điều tác giả gửi gắm phải nắm được ý chính của từng đoạn. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"9","mucDo":[2],"soCau":1}},{"anh":"kho-sang","danChuyen":"Gần đỉnh núi là Hòm thư bí mật, nơi cất những cảm nhận về vẻ đẹp hùng vĩ của thiên nhiên trong bài văn. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"9","mucDo":[2,3],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Khung cảnh cổng trời hiện ra trọn vẹn rồi — núi cao, mây trắng, hùng vĩ mà thơ mộng!","nv":"Thảo Nguyên"},{"loi":"Cô tặng biệt đội Chiếc Lông Vũ Mây. Nghe kìa... phía sau cổng trời là một khu rừng xanh thẳm đang thì thầm.","nv":"Cô Ong Chăm Chữ"},{"loi":"Cả một biển rừng xanh ngút ngàn!","nv":"Tuấn Kiệt"},{"loi":"Tập sau, biệt đội mình vào rừng xanh nhé cả lớp!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t1","ten":"Tập 1 — Trước cổng trời","tomTatTapTruoc":"Mùa trước: Biệt đội mở Cổng Hành Tinh, giữ trọn trí tưởng tượng của tuổi thơ và nhận Chìa Cổng Hành Tinh. Phía sau cổng, gió hú qua một cổng trời cao vút và tiếng nước nhỏ giọt vọng ra từ hang sâu...","tuan":"5","vatPham":"Chiếc Lông Vũ Mây"},{"bai":"10","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao bước vào khu rừng nguyên sinh, nơi bài văn Kì diệu rừng xanh kể về thế giới sống động của muôn loài trong rừng.","nv":"Người kể"},{"loi":"Bài văn tả rừng xanh như một thế giới có linh hồn: cây cối, muông thú, tiếng chim, ánh nắng xuyên qua tán lá. Các cháu để ý cách tác giả chọn chi tiết và dùng từ ngữ gợi tả để rừng hiện lên sống động.","nv":"Cô Ong Chăm Chữ"},{"loi":"Mỗi chi tiết là một mảnh ghép — ghép lại là cả khu rừng thở cùng một nhịp ạ.","nv":"Thảo Nguyên"},{"loi":"Bài còn nhắc mình biết trân trọng và bảo vệ rừng xanh nữa.","nv":"Đức Trí"},{"loi":"Sương đã làm lạc mất mấy lối mòn trong rừng rồi. Đọc kỹ từng chi tiết, cả lớp sẽ tìm lại được trái tim của rừng xanh!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Rừng có hai lối mòn xanh. Cả lớp chọn lối nào trước?","nv":"Minh Anh"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"cau-suong","dong":[{"loi":"Đứng trên cầu nghe rõ tiếng chim và tiếng lá xào xạc. Theo nhịp của rừng nhé!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Cầu vần thơ bắc qua con suối rừng trong vắt, từ trên cầu nhìn xuống thấy bóng cây soi mặt nước. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"10","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cầu vần thơ — theo nhịp rừng xanh"},{"canh":[{"anh":"canh-chu","dong":[{"loi":"Quả chữ trên cây này ghi các chi tiết tả rừng. Hái đúng quả chi tiết là lối mòn rõ thêm một đoạn!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"canh-chu","danChuyen":"Cây quả chữ mọc giữa rừng già, bóng cây che một phần lối mòn đầu tiên chưa rõ dấu. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"10","mucDo":[1],"soCau":1}}],"nhan":"Đến Cây quả chữ — hái quả chi tiết rừng"}]},{"anh":"kho-sang","bienCo":{"dong":[{"loi":"Sương làm đường trơn quá, mình suýt trượt chân rồi!","nv":"Tuấn Kiệt"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"10","mucDo":[1],"soCau":1}},"danChuyen":"Giữa rừng là Hòm thư bí mật của người giữ rừng, cất những dòng về tình yêu thiên nhiên. Muốn mở hòm phải hiểu điều tác giả muốn nói qua từng chi tiết. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"10","mucDo":[2],"soCau":1}},{"anh":"canh-kho","danChuyen":"Bên kia rừng, Dòng suối câu chảy qua bãi đất nơi những chi tiết hay nhất của bài văn đang chờ được vớt lên. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"10","mucDo":[2,3],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Khu rừng hiện ra trọn vẹn rồi! Rừng xanh kì diệu vì muôn loài cùng chung sống hài hòa!","nv":"Đức Trí"},{"loi":"Cô tặng biệt đội Chiếc Lá Rừng Pha Lê. Nhưng nghe kìa... sâu dưới lòng đất có tiếng nước nhỏ giọt và tiếng vọng của một hang động khổng lồ.","nv":"Cô Ong Chăm Chữ"},{"loi":"Hang động nào mà sâu thẳm đến thế nhỉ?","nv":"Thảo Nguyên"},{"loi":"Tập sau mình xuống hang khám phá nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t2","ten":"Tập 2 — Kì diệu rừng xanh","tomTatTapTruoc":"Tập trước: Biệt đội khôi phục khung cảnh Trước cổng trời, học cách tả cảnh theo trình tự không gian, rồi nhận Chiếc Lông Vũ Mây. Cuối tập, một khu rừng xanh thẳm hiện ra sau cổng trời...","tuan":"5","vatPham":"Chiếc Lá Rừng Pha Lê"},{"bai":"11","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao lần theo tiếng nước nhỏ giọt và bước vào hang Sơn Đoòng — hang động lớn bậc nhất thế giới, niềm tự hào của Việt Nam, trong bài văn Hang Sơn Đoòng - những điều kì thú.","nv":"Người kể"},{"loi":"Bài văn giới thiệu những điều kỳ thú của hang Sơn Đoòng bằng số liệu và hình ảnh ấn tượng: hang cao đến mức chứa được cả tòa nhà, có cả rừng và sông ngầm bên trong. Các cháu để ý cách tác giả dùng số liệu để thuyết phục người đọc.","nv":"Cô Ong Chăm Chữ"},{"loi":"Số liệu cụ thể làm cho điều kỳ thú trở nên đáng tin và choáng ngợp hơn hẳn ạ.","nv":"Đức Trí"},{"loi":"Đọc mà tự hào quá — thiên nhiên Việt Nam mình kỳ vĩ thật!","nv":"Thảo Nguyên"},{"loi":"Sương hang đã làm mờ mất mấy bảng số liệu của hang rồi. Đọc kỹ từng chi tiết, cả lớp sẽ khôi phục được những điều kì thú ấy!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Miệng hang có hai lối xuống. Cả lớp chọn lối nào trước?","nv":"Tuấn Kiệt"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"canh-kho","dong":[{"loi":"Thẻ câu trên suối ghi các điều kì thú theo trình tự bài văn. Vớt đúng thẻ đầu tiên nhé!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"canh-kho","danChuyen":"Dòng suối câu chảy ngầm trong hang, in bóng những măng đá lấp lánh xuống mặt nước. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"11","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Dòng suối câu — xuôi dòng sông ngầm"},{"canh":[{"anh":"kho-sang","dong":[{"loi":"Trong hòm là những dòng nhật ký của đoàn thám hiểm hang. Đọc kỹ là hình dung được cả hang động!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"kho-sang","danChuyen":"Bên miệng hang, Hòm thư bí mật nằm im lìm, nắp hòm khắc hình một giọt nước đang nhỏ xuống. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"11","mucDo":[1],"soCau":1}}],"nhan":"Mở Hòm thư bí mật — đọc nhật ký thám hiểm"}]},{"anh":"canh-chu","bienCo":{"dong":[{"loi":"Ơ, sương che mất một nửa đáp án rồi, mình đọc không rõ nữa!","nv":"Thảo Nguyên"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"11","mucDo":[1],"soCau":1}},"danChuyen":"Sâu trong hang, Cây quả chữ mọc bên hố sụt khổng lồ, che mất phần văn tả ánh sáng trời rọi xuống lòng hang. Muốn hang rõ phải nắm đúng số liệu và chi tiết tác giả đã nêu. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"11","mucDo":[1],"soCau":1}},{"anh":"cau-suong","danChuyen":"Muốn ra khỏi hang phải qua Cầu vần thơ bắc qua sông ngầm, nơi thử thách về từ ngữ và ý nghĩa của bài văn đang chờ. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"11","mucDo":[1],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Hang Sơn Đoòng hiện ra kỳ vĩ rồi — có rừng, có sông, có cả bầu trời riêng trong lòng đất!","nv":"Thảo Nguyên"},{"loi":"Cô tặng biệt đội Viên Ngọc Thạch Hang Động. Nghe kìa... phía xa có tiếng sóng vỗ và những hòn đảo xanh nhô lên mặt vịnh.","nv":"Cô Ong Chăm Chữ"},{"loi":"Đó là vịnh Hạ Long với hàng nghìn hòn đảo!","nv":"Minh Anh"},{"loi":"Tập sau mình ra vịnh nhé cả lớp!","nv":"Tuấn Kiệt"}],"loai":"thoai"}],"id":"t3","ten":"Tập 3 — Hang Sơn Đoòng kì thú","tomTatTapTruoc":"Tập trước: Biệt đội tìm lại trái tim của rừng xanh, học cách chọn chi tiết gợi tả, rồi nhận Chiếc Lá Rừng Pha Lê. Cuối tập, tiếng nước nhỏ giọt vọng lên từ một hang động khổng lồ dưới lòng đất...","tuan":"6","vatPham":"Viên Ngọc Thạch Hang Động"},{"bai":"12","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao ra tới bờ vịnh, nơi bài văn Những hòn đảo trên vịnh Hạ Long giới thiệu vẻ đẹp của hàng nghìn hòn đảo đá vôi trên mặt biển quê hương.","nv":"Người kể"},{"loi":"Bài văn tả các hòn đảo trên vịnh Hạ Long bằng những hình ảnh gợi hình sinh động — mỗi đảo một dáng, một tên gọi gắn với truyền thuyết. Các cháu để ý cách tác giả quan sát và liên tưởng khi miêu tả.","nv":"Cô Ong Chăm Chữ"},{"loi":"Liên tưởng làm cho đảo đá như có hình hài và câu chuyện riêng ạ.","nv":"Minh Anh"},{"loi":"Đọc bài này mới thấy biển đảo quê hương mình đẹp và đáng tự hào biết bao.","nv":"Thảo Nguyên"},{"loi":"Sương biển đã làm mờ mất mấy hòn đảo đẹp nhất trên bản đồ vịnh rồi. Đọc kỹ từng chi tiết, cả lớp sẽ vẽ lại được vịnh xanh!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Bờ vịnh có hai bến thuyền. Cả lớp chọn bến nào trước?","nv":"Minh Anh"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"cau-suong","dong":[{"loi":"Đứng trên cầu nghe rõ tiếng sóng vỗ vào chân đảo. Câu văn hay là nhận ra ngay!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Cầu vần thơ bắc qua con lạch nhỏ dẫn ra bến thuyền, ván cầu khắc những đợt sóng lăn tăn. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"12","mucDo":[1],"soCau":1}}],"nhan":"Qua Cầu vần thơ — nghe sóng vịnh hát"},{"canh":[{"anh":"canh-kho","dong":[{"loi":"Thẻ câu trên suối ghi hành trình ra vịnh theo trình tự bài văn. Vớt đúng thẻ là nối được hành trình!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"canh-kho","danChuyen":"Dòng suối câu chảy êm ra bờ vịnh, mang theo những thẻ câu còn mờ chữ. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"12","mucDo":[1],"soCau":1}}],"nhan":"Xuôi Dòng suối câu — theo hành trình ra đảo"}]},{"anh":"kho-sang","bienCo":{"dong":[{"loi":"Sương kéo đến dày quá, mọi thứ nhòe đi như nhìn qua kính mờ!","nv":"Đức Trí"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"12","mucDo":[1],"soCau":1}},"danChuyen":"Trên bến thuyền là Hòm thư bí mật, cất những dòng cảm nhận về vẻ đẹp biển đảo quê hương. Muốn mở hòm phải hiểu điều tác giả gửi gắm. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"12","mucDo":[2],"soCau":1}},{"anh":"canh-chu","danChuyen":"Trước khi rời vịnh, Cây quả chữ bên gốc phi lao còn một thử thách về từ ngữ và ý nghĩa của bài văn. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"12","mucDo":[2,3],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Vịnh Hạ Long hiện ra trọn vẹn rồi — nghìn đảo một dáng, đẹp như một bức tranh thủy mặc khổng lồ!","nv":"Minh Anh"},{"loi":"Cô tặng biệt đội Viên Ngọc Vịnh Xanh. Nhưng nhìn kìa...","nv":"Cô Ong Chăm Chữ"},{"loi":"Khà... khà... Bốn kỳ quan thiên nhiên thì đã sao? Cổng Trời vẫn nằm trong tay ta...","nv":"Sương Mù"},{"loi":"Cổng Trời hiện ra giữa mặt vịnh, và Sương Mù đang giữ cổng! Cả lớp ơi, tập đặc biệt — mình cùng phá cổng nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t4","ten":"Tập 4 — Những hòn đảo trên vịnh Hạ Long","tomTatTapTruoc":"Tập trước: Biệt đội khôi phục những điều kì thú của hang Sơn Đoòng, học cách dùng số liệu để thuyết phục, rồi nhận Viên Ngọc Thạch Hang Động. Cuối tập, tiếng sóng vỗ vọng lại từ vịnh biển phía xa...","tuan":"6","vatPham":"Viên Ngọc Vịnh Xanh"},{"bai":"9+10+11+12","canh":[{"anh":"canh-trum","dong":[{"loi":"Ta là Sương Mù Quên Lãng. Khiên sương của ta chỉ vỡ khi gặp câu trả lời đúng. Các ngươi dám thử không?","nv":"Sương Mù"},{"loi":"Biệt đội Ánh Sao sẵn sàng! Trình tự tả cảnh, chi tiết gợi tả, số liệu thuyết phục — chúng mình đều nắm chắc!","nv":"Minh Anh"},{"loi":"Luật phá cổng: trên cổng có bốn ô chiêu thức phát sáng. Chọn chiêu thức là đáp án đúng, khiên sương nứt một phần. Bình tĩnh đọc kỹ, các cháu nhé.","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-trum","danChuyen":"Sương Mù thổi một làn khói che mất khung cảnh cổng trời. Cả lớp chọn chiêu thức đúng về trình tự tả cảnh và hình ảnh so sánh nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"9","mucDo":[2],"soCau":1}},{"anh":"canh-trum","danChuyen":"Khiên sương rung lên! Sương Mù tung đòn Kì diệu rừng xanh với những chi tiết gợi tả sống động. Cả lớp chọn chiêu thức đúng để phá tiếp nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"10","mucDo":[2],"soCau":1}},{"anh":"canh-trum","danChuyen":"Sương Mù làm mờ những số liệu kỳ thú của hang Sơn Đoòng trong làn khói. Cả lớp chọn chiêu thức đúng về hang động khổng lồ này nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"11","mucDo":[1],"soCau":1}},{"anh":"canh-trum","danChuyen":"Đòn cuối cùng! Sương Mù dồn hết sức vào những hòn đảo trên vịnh Hạ Long. Cả lớp chọn chiêu thức đúng để phá tan khiên sương nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"12","mucDo":[2],"soCau":1}},{"anh":"cua-mo","dong":[{"loi":"Thôi được... Cổng này là của các ngươi. Nhưng phía sau cổng là núi lửa và sa mạc nóng bỏng, sương của ta còn dày lắm...","nv":"Sương Mù"},{"loi":"Cổng Trời đã mở! Biệt đội nhận Chìa Cổng Trời. Thiên nhiên kì thú của quê hương — các cháu đã giữ trọn được rồi.","nv":"Cô Ong Chăm Chữ"},{"loi":"Phía sau cổng có hơi nóng phả ra và ánh mặt trời chói chang...","nv":"Đức Trí"},{"loi":"Đó là hành trình vòng quanh thiên nhiên thế giới đang chờ! Hẹn gặp cả lớp ở mùa tiếp theo nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"trum","laTapTrum":true,"ten":"Tập đặc biệt — Cổng Trời","tomTatTapTruoc":"Biệt đội đã khôi phục bốn kỳ quan của chủ điểm Thiên nhiên kì thú: cổng trời hùng vĩ, rừng xanh sống động, hang Sơn Đoòng kỳ thú và vịnh Hạ Long nghìn đảo. Giờ đây, Sương Mù Quên Lãng đang giữ Cổng Trời bằng một khiên sương dày...","tuan":"6","vatPham":"Chìa Cổng Trời"}],"tenMua":"Mùa 3 — Cổng Trời Kì Thú","tomTatMua":"Chủ điểm Thiên nhiên kì thú đưa Biệt đội Ánh Sao lên cổng trời mây trắng, vào rừng xanh muôn loài, xuống hang Sơn Đoòng khổng lồ và ra vịnh Hạ Long nghìn đảo. Sương Mù Quên Lãng phủ mờ từng kỳ quan, và biệt đội phải khôi phục tất cả để mở Cổng Trời."},{"anhBia":"dao-xanh-thien-nhien","anhCanTao":[{"khoa":"dao-xanh-thien-nhien","moTa":"Một ốc đảo xanh kỳ diệu giữa biển cát vàng trong Khu Vườn Ngôn Từ: giữa ốc đảo có hồ nước trong veo, mầm non vừa nhú bên bờ, phía xa là ngọn núi lửa đang phun khói nhẹ và vầng mặt trời lớn mọc sau đụn cát; Cô Ong Chăm Chữ đeo kính bay trên mặt hồ, Biệt đội Ánh Sao áo trắng khăn quàng đỏ đứng bên gốc chà là; một góc ốc đảo bị sương xám phủ mờ. Phong cách 3D Pixar, không chữ."}],"cacBai":["13","14","15","16"],"cacChuDe":["2"],"id":"tv5-c4","lop":5,"mon":"Tiếng Việt","nhanVat":{"Cô Ong Chăm Chữ":"Cô Ong Chăm Chữ — ong thợ chăm chỉ của Khu Vườn Ngôn Từ, bay lượn đọc chính tả vui; là người đọc lời giải thích sau mỗi thử thách trong thế giới Tiếng Việt.","Minh Anh":"Đội trưởng Biệt đội Ánh Sao — quyết đoán, luôn đi đầu.","Sương Mù":"Sương Mù Quên Lãng — thế lực xám lạnh chuyên xóa chữ và kiến thức trong các cuốn sách.","Thảo Nguyên":"Bạn ngôn ngữ — hoạt bát, giỏi chữ nghĩa và tiếng Việt.","Thủ thư Số":"Người giữ sách của Thư viện Ánh Sao — hiền từ, hiểu biết, luôn đưa ra lời giải thích sau mỗi thử thách.","Tuấn Kiệt":"Bạn kỹ thuật — mê máy móc, thao tác nhanh và chính xác.","Đức Trí":"Bạn logic — điềm tĩnh, hay suy luận trước khi hành động."},"tap":[{"bai":"13","canh":[{"anh":"canh-dau","dong":[{"loi":"Qua Cổng Trời, Biệt đội Ánh Sao bắt đầu hành trình thiên nhiên thế giới. Điểm dừng đầu tiên là một triền đất vừa qua mùa khô, nơi bài thơ Mầm non kể về những mầm cây vươn dậy sau mưa.","nv":"Người kể"},{"loi":"Bài thơ Mầm non tả khoảnh khắc những mầm cây đội đất vươn lên bằng hình ảnh nhân hóa đầy sức sống. Đọc thơ, các cháu cảm nhận nhịp điệu vui tươi và thông điệp về sự sống hồi sinh nhé.","nv":"Cô Ong Chăm Chữ"},{"loi":"Mầm non như những em bé vừa tỉnh giấc, vươn vai đón nắng ạ.","nv":"Thảo Nguyên"},{"loi":"Bài thơ còn gợi niềm tin: sau những ngày khô hạn, sự sống luôn trở lại.","nv":"Đức Trí"},{"loi":"Sương đã phủ mờ mấy luống mầm đầu mùa rồi. Đọc kỹ từng hình ảnh, cả lớp sẽ đánh thức được những mầm non!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Triền đất có hai lối vào giữa các luống mầm. Cả lớp chọn lối nào trước nhé!","nv":"Đức Trí"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"canh-chu","dong":[{"loi":"Quả chữ trên cây này ghi những hình ảnh trong bài thơ. Hái đúng quả là mầm vươn thêm một lá!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"canh-chu","danChuyen":"Ngay lối vào triền đất, Cây quả chữ mọc bên luống mầm đầu tiên, cành lá che một phần bài thơ chưa rõ chữ. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"13","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cây quả chữ — hái quả hình ảnh thơ"},{"canh":[{"anh":"cau-suong","dong":[{"loi":"Nhịp thơ rộn ràng như tiếng mầm đội đất. Đứng trên cầu nghe kỹ là nhận ra ngay!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Một chiếc cầu nhỏ bắc qua mương nước mưa dẫn vào giữa triền đất. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"13","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cầu vần thơ — nghe nhịp hồi sinh"}]},{"anh":"canh-kho","bienCo":{"dong":[{"loi":"Ối, sương tràn xuống bất ngờ, chữ trên các thẻ mờ đi rồi!","nv":"Minh Anh"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"13","mucDo":[1],"soCau":1}},"danChuyen":"Giữa triền đất, Dòng suối câu chảy quanh luống mầm xanh nhất. Muốn mầm vươn cao phải hiểu điều tác giả gửi gắm qua hình ảnh mầm non. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"13","mucDo":[2],"soCau":1}},{"anh":"kho-sang","danChuyen":"Cuối triền đất là Hòm thư bí mật, nơi cất những cảm nhận về sức sống và niềm hy vọng trong bài thơ. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"13","mucDo":[2,3],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Những mầm non vươn dậy xanh mướt rồi! Sự sống hồi sinh sau mưa — kỳ diệu biết bao!","nv":"Thảo Nguyên"},{"loi":"Cô tặng biệt đội Chiếc Lá Non Đầu Mùa. Nghe kìa... phía xa có tiếng rì rầm của những ngọn núi đang nóng rẫy.","nv":"Cô Ong Chăm Chữ"},{"loi":"Núi gì mà nóng rẫy thế nhỉ? Như có lửa ở bên trong vậy!","nv":"Tuấn Kiệt"},{"loi":"Tập sau, biệt đội mình đến gần những ngọn núi ấy nhé cả lớp!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t1","ten":"Tập 1 — Mầm non vươn dậy","tomTatTapTruoc":"Mùa trước: Biệt đội mở Cổng Trời, giữ trọn bốn kỳ quan thiên nhiên và nhận Chìa Cổng Trời. Phía sau cổng, hơi nóng của núi lửa và ánh mặt trời chói chang mở ra hành trình thiên nhiên vòng quanh thế giới...","tuan":"7","vatPham":"Chiếc Lá Non Đầu Mùa"},{"bai":"14","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao tiến về dãy núi xa, nơi bài văn Những ngọn núi nóng rẫy giới thiệu về núi lửa — những ngọn núi chứa lửa bên trong lòng đất.","nv":"Người kể"},{"loi":"Bài văn giải thích hiện tượng núi lửa bằng những thông tin khoa học rõ ràng: vì sao núi phun lửa, dung nham là gì, núi lửa gây hại và cũng mang lại lợi ích ra sao. Các cháu để ý cách tác giả sắp xếp thông tin theo từng ý chính.","nv":"Cô Ong Chăm Chữ"},{"loi":"Mỗi đoạn một ý chính rõ ràng — nắm ý chính là hiểu cả bài ạ.","nv":"Đức Trí"},{"loi":"Đọc mà vừa hồi hộp vừa thêm hiểu biết về Trái Đất của mình.","nv":"Thảo Nguyên"},{"loi":"Sương núi lửa đã làm mờ mất mấy đoạn giải thích quan trọng rồi. Đọc kỹ từng ý, cả lớp sẽ khôi phục được bài văn!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Sườn núi có hai lối lên vành miệng núi. Cả lớp chọn lối nào trước?","nv":"Minh Anh"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"cau-suong","dong":[{"loi":"Đứng trên cầu nhìn xuống là thấy dòng dung nham đỏ rực trong tưởng tượng. Theo mạch giải thích từ đầu nhé!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Cầu vần thơ bắc qua khe núi nhỏ, từ trên cầu nhìn xuống thấy những vệt đá núi lửa đen bóng. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"14","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cầu vần thơ — theo mạch giải thích"},{"canh":[{"anh":"canh-chu","dong":[{"loi":"Quả chữ trên cây này ghi các ý chính của từng đoạn. Hái đúng quả là hiểu ngọn núi thêm một phần!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"canh-chu","danChuyen":"Cây quả chữ mọc bên sườn núi, bóng cây che một phần đoạn văn đầu tiên chưa rõ chữ. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"14","mucDo":[1],"soCau":1}}],"nhan":"Đến Cây quả chữ — hái quả ý chính"}]},{"anh":"kho-sang","bienCo":{"dong":[{"loi":"Sương làm đường trơn quá, mình suýt trượt chân rồi!","nv":"Tuấn Kiệt"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"14","mucDo":[1],"soCau":1}},"danChuyen":"Bên sườn núi là Hòm thư bí mật của nhà địa chất, cất những dòng về sức mạnh của Trái Đất. Muốn mở hòm phải hiểu điều tác giả muốn nói qua từng ý chính. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"14","mucDo":[2],"soCau":1}},{"anh":"canh-kho","danChuyen":"Dưới chân núi, Dòng suối câu chảy qua bãi đá, thẻ câu hỏi về những chi tiết hay nhất của bài văn đang chờ. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"14","mucDo":[1,2],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Bài văn hiện ra trọn vẹn rồi! Núi lửa nóng rẫy mà cũng góp phần tạo nên đất đai màu mỡ!","nv":"Đức Trí"},{"loi":"Cô tặng biệt đội Viên Đá Núi Lửa. Nghe kìa... trên cao có một bài ca đang vang lên chào mặt trời mọc.","nv":"Cô Ong Chăm Chữ"},{"loi":"Bài ca về mặt trời — nghe tên đã thấy rực rỡ rồi!","nv":"Thảo Nguyên"},{"loi":"Tập sau mình đón mặt trời mọc nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t2","ten":"Tập 2 — Những ngọn núi nóng rẫy","tomTatTapTruoc":"Tập trước: Biệt đội đánh thức những mầm non sau mưa, cảm nhận hình ảnh nhân hóa và niềm tin vào sự sống, rồi nhận Chiếc Lá Non Đầu Mùa. Cuối tập, tiếng rì rầm vọng lại từ những ngọn núi nóng rẫy phía xa...","tuan":"7","vatPham":"Viên Đá Núi Lửa"},{"bai":"15","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao leo lên đỉnh đồi trước bình minh, nơi bài thơ Bài ca về mặt trời ca ngợi mặt trời — nguồn sáng và nguồn sống của muôn loài.","nv":"Người kể"},{"loi":"Bài thơ ca ngợi mặt trời bằng những hình ảnh đẹp và giọng điệu trang trọng, biết ơn. Đọc thơ, các cháu để ý cách tác giả nhân hóa mặt trời và những điều mặt trời mang đến cho con người, cây cỏ.","nv":"Cô Ong Chăm Chữ"},{"loi":"Mặt trời trong thơ như một người bạn lớn, mỗi sáng lại về đánh thức muôn loài ạ.","nv":"Thảo Nguyên"},{"loi":"Bài thơ còn nhắc mình biết ơn những điều tưởng như bình thường quanh mình.","nv":"Đức Trí"},{"loi":"Sương sớm đã làm mờ mất mấy khổ thơ rực rỡ nhất rồi. Đọc kỹ từng hình ảnh, cả lớp sẽ đón được mặt trời lên!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Đỉnh đồi có hai sườn đón nắng. Cả lớp chọn sườn nào lên trước?","nv":"Tuấn Kiệt"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"canh-kho","dong":[{"loi":"Thẻ câu trên suối ghi các khổ thơ theo trình tự bài ca. Vớt đúng thẻ đầu tiên nhé!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"canh-kho","danChuyen":"Dòng suối câu chảy quanh chân đồi, in bóng những tia nắng đầu tiên xuống mặt nước. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"15","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Dòng suối câu — xuôi theo khổ thơ"},{"canh":[{"anh":"kho-sang","dong":[{"loi":"Trong hòm là những dòng ca ngợi mặt trời của muôn loài. Đọc kỹ là thấy lòng biết ơn trong từng câu!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"kho-sang","danChuyen":"Dưới bóng cây đầu đồi, Hòm thư bí mật nằm im lìm, nắp hòm khắc hình một vầng mặt trời đang lên. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"15","mucDo":[1],"soCau":1}}],"nhan":"Mở Hòm thư bí mật — đọc lời ca ngợi mặt trời"}]},{"anh":"canh-chu","bienCo":{"dong":[{"loi":"Ơ, sương che mất một nửa đáp án rồi, mình đọc không rõ nữa!","nv":"Thảo Nguyên"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"15","mucDo":[1],"soCau":1}},"danChuyen":"Giữa đỉnh đồi, Cây quả chữ che mất phần thơ tả những điều mặt trời mang đến cho muôn loài. Muốn thơ rõ phải nắm đúng hình ảnh và ý nghĩa của từng khổ. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"15","mucDo":[2],"soCau":1}},{"anh":"cau-suong","danChuyen":"Muốn xuống đồi phải qua Cầu vần thơ, nơi thử thách về nhịp điệu và từ ngữ gợi hình của bài thơ đang chờ. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"15","mucDo":[1,2],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Mặt trời lên rực rỡ rồi! Bài ca vang khắp đồi — nguồn sáng, nguồn sống cho muôn loài!","nv":"Thảo Nguyên"},{"loi":"Cô tặng biệt đội Tia Nắng Đầu Ngày. Nghe kìa... gió nóng thổi về từ một vùng đất cát mênh mông phía xa.","nv":"Cô Ong Chăm Chữ"},{"loi":"Cả một biển cát vàng — đó là sa mạc Xa-ha-ra!","nv":"Minh Anh"},{"loi":"Tập sau mình vào sa mạc nhé cả lớp!","nv":"Tuấn Kiệt"}],"loai":"thoai"}],"id":"t3","ten":"Tập 3 — Bài ca về mặt trời","tomTatTapTruoc":"Tập trước: Biệt đội khôi phục bài văn về những ngọn núi nóng rẫy, học cách nắm ý chính từng đoạn, rồi nhận Viên Đá Núi Lửa. Cuối tập, một bài ca vang lên chào mặt trời mọc trên cao...","tuan":"8","vatPham":"Tia Nắng Đầu Ngày"},{"bai":"16","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao bước vào rìa sa mạc Xa-ha-ra — sa mạc nóng lớn nhất thế giới, nơi bài văn Xin chào, Xa-ha-ra mở ra một vùng đất khắc nghiệt mà kỳ thú.","nv":"Người kể"},{"loi":"Bài văn giới thiệu sa mạc Xa-ha-ra qua lời chào thân thiện: cát vàng mênh mông, nắng nóng gay gắt, những ốc đảo xanh và sự sống kiên cường. Các cháu để ý cách tác giả chọn chi tiết tiêu biểu để tả một vùng đất xa lạ.","nv":"Cô Ong Chăm Chữ"},{"loi":"Chi tiết tiêu biểu giúp người đọc hình dung sa mạc rõ như đang đứng giữa biển cát ạ.","nv":"Minh Anh"},{"loi":"Giọng văn như một người hướng dẫn viên thân thiện đang dẫn mình đi thăm sa mạc vậy.","nv":"Thảo Nguyên"},{"loi":"Sương cát đã làm mờ mất mấy đoạn tả sa mạc hay nhất rồi. Đọc kỹ từng chi tiết, cả lớp sẽ vượt qua được biển cát!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Rìa sa mạc có hai lối vào giữa các đụn cát. Cả lớp chọn lối nào trước?","nv":"Minh Anh"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"cau-suong","dong":[{"loi":"Đứng trên cầu nghe rõ tiếng gió thổi qua đụn cát. Câu văn hay là nhận ra ngay!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Cầu vần thơ bắc qua con lạch khô dẫn vào sa mạc, ván cầu khắc những đợt sóng cát lăn tăn. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"16","mucDo":[1],"soCau":1}}],"nhan":"Qua Cầu vần thơ — nghe gió cát hát"},{"canh":[{"anh":"canh-kho","dong":[{"loi":"Thẻ câu trên suối ghi hành trình qua sa mạc theo trình tự bài văn. Vớt đúng thẻ là tìm được ốc đảo!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"canh-kho","danChuyen":"Dòng suối câu chảy êm về phía ốc đảo, mang theo những thẻ câu còn mờ chữ. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"16","mucDo":[1],"soCau":1}}],"nhan":"Xuôi Dòng suối câu — theo dấu ốc đảo"}]},{"anh":"kho-sang","bienCo":{"dong":[{"loi":"Sương kéo đến dày quá, mọi thứ nhòe đi như nhìn qua kính mờ!","nv":"Đức Trí"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"16","mucDo":[1],"soCau":1}},"danChuyen":"Bên ốc đảo là Hòm thư bí mật, cất những dòng cảm nhận về sự sống kiên cường giữa sa mạc. Muốn mở hòm phải hiểu điều tác giả gửi gắm. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"16","mucDo":[1],"soCau":1}},{"anh":"canh-chu","danChuyen":"Trước khi rời sa mạc, Cây quả chữ bên gốc chà là còn một thử thách về từ ngữ và ý nghĩa của bài văn. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"16","mucDo":[3],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Sa mạc Xa-ha-ra hiện ra trọn vẹn rồi — khắc nghiệt mà kỳ thú, và sự sống vẫn kiên cường vươn lên!","nv":"Minh Anh"},{"loi":"Cô tặng biệt đội Hạt Cát Vàng Xa-ha-ra. Nhưng nhìn kìa...","nv":"Cô Ong Chăm Chữ"},{"loi":"Khà... khà... Bốn miền thiên nhiên thế giới thì đã sao? Cổng Đảo Xanh vẫn nằm trong tay ta...","nv":"Sương Mù"},{"loi":"Cổng Đảo Xanh hiện ra giữa ốc đảo, và Sương Mù đang giữ cổng! Cả lớp ơi, tập đặc biệt — mình cùng phá cổng nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t4","ten":"Tập 4 — Xin chào, Xa-ha-ra","tomTatTapTruoc":"Tập trước: Biệt đội đón mặt trời lên cùng Bài ca về mặt trời, cảm nhận hình ảnh nhân hóa và lòng biết ơn, rồi nhận Tia Nắng Đầu Ngày. Cuối tập, gió nóng thổi về từ biển cát mênh mông phía xa...","tuan":"8","vatPham":"Hạt Cát Vàng Xa-ha-ra"},{"bai":"13+14+15+16","canh":[{"anh":"canh-trum","dong":[{"loi":"Ta là Sương Mù Quên Lãng. Khiên sương của ta chỉ vỡ khi gặp câu trả lời đúng. Các ngươi dám thử không?","nv":"Sương Mù"},{"loi":"Biệt đội Ánh Sao sẵn sàng! Hình ảnh thơ, ý chính, chi tiết tiêu biểu — chúng mình đều nắm chắc!","nv":"Minh Anh"},{"loi":"Luật phá cổng: trên cổng có bốn ô chiêu thức phát sáng. Chọn chiêu thức là đáp án đúng, khiên sương nứt một phần. Bình tĩnh đọc kỹ, các cháu nhé.","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-trum","danChuyen":"Sương Mù thổi một làn khói che mất những luống mầm non. Cả lớp chọn chiêu thức đúng về hình ảnh và ý nghĩa của bài Mầm non nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"13","mucDo":[2],"soCau":1}},{"anh":"canh-trum","danChuyen":"Khiên sương rung lên! Sương Mù tung đòn Những ngọn núi nóng rẫy với những ý chính về núi lửa. Cả lớp chọn chiêu thức đúng để phá tiếp nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"14","mucDo":[2],"soCau":1}},{"anh":"canh-trum","danChuyen":"Sương Mù làm mờ những khổ thơ Bài ca về mặt trời trong làn khói. Cả lớp chọn chiêu thức đúng về hình ảnh mặt trời trong thơ nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"15","mucDo":[2],"soCau":1}},{"anh":"canh-trum","danChuyen":"Đòn cuối cùng! Sương Mù dồn hết sức vào sa mạc Xa-ha-ra. Cả lớp chọn chiêu thức đúng để phá tan khiên sương nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"16","mucDo":[3],"soCau":1}},{"anh":"cua-mo","dong":[{"loi":"Thôi được... Cổng này là của các ngươi. Nhưng phía sau cổng là con đường học tập dài, sương của ta còn dày lắm...","nv":"Sương Mù"},{"loi":"Cổng Đảo Xanh đã mở! Biệt đội nhận Chìa Cổng Đảo Xanh. Thiên nhiên thế giới kỳ thú — các cháu đã giữ trọn được rồi.","nv":"Cô Ong Chăm Chữ"},{"loi":"Phía sau cổng có tiếng trống trường và một lá thư cổ kính đang mở ra...","nv":"Đức Trí"},{"loi":"Đó là chủ điểm Trên con đường học tập đang chờ! Hẹn gặp cả lớp ở mùa tiếp theo nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"trum","laTapTrum":true,"ten":"Tập đặc biệt — Cổng Đảo Xanh","tomTatTapTruoc":"Biệt đội đã khôi phục bốn miền thiên nhiên thế giới: mầm non hồi sinh, núi lửa nóng rẫy, bài ca về mặt trời và sa mạc Xa-ha-ra mênh mông. Giờ đây, Sương Mù Quên Lãng đang giữ Cổng Đảo Xanh bằng một khiên sương dày...","tuan":"8","vatPham":"Chìa Cổng Đảo Xanh"}],"tenMua":"Mùa 4 — Đảo Xanh Hạ Long","tomTatMua":"Hành trình thiên nhiên của Biệt đội Ánh Sao đi vòng quanh thế giới: mầm non đội đất sau mưa, những ngọn núi lửa nóng rẫy, bài ca ca ngợi mặt trời và biển cát Xa-ha-ra mênh mông. Sương Mù Quên Lãng phủ mờ từng miền đất, và biệt đội phải khôi phục tất cả để mở Cổng Đảo Xanh."},{"anhBia":"con-duong-hoc-tap","anhCanTao":[{"khoa":"con-duong-hoc-tap","moTa":"Một con đường lát bằng những trang sách mở dẫn lên đồi tri thức trong Khu Vườn Ngôn Từ: bên đường có cột cờ sân trường ngày khai giảng, một chiếc đèn bàn sáng trên bàn học dưới tán cây và những dấu chân nhỏ in dọc đường; Cô Ong Chăm Chữ đeo kính bay phía trước, Biệt đội Ánh Sao áo trắng khăn quàng đỏ bước đi trên con đường sách; một đoạn đường bị sương xám phủ mờ. Phong cách 3D Pixar, không chữ."}],"cacBai":["17","18","19","20"],"cacChuDe":["3"],"id":"tv5-c5","lop":5,"mon":"Tiếng Việt","nhanVat":{"Cô Ong Chăm Chữ":"Cô Ong Chăm Chữ — ong thợ chăm chỉ của Khu Vườn Ngôn Từ, bay lượn đọc chính tả vui; là người đọc lời giải thích sau mỗi thử thách trong thế giới Tiếng Việt.","Minh Anh":"Đội trưởng Biệt đội Ánh Sao — quyết đoán, luôn đi đầu.","Sương Mù":"Sương Mù Quên Lãng — thế lực xám lạnh chuyên xóa chữ và kiến thức trong các cuốn sách.","Thảo Nguyên":"Bạn ngôn ngữ — hoạt bát, giỏi chữ nghĩa và tiếng Việt.","Thủ thư Số":"Người giữ sách của Thư viện Ánh Sao — hiền từ, hiểu biết, luôn đưa ra lời giải thích sau mỗi thử thách.","Tuấn Kiệt":"Bạn kỹ thuật — mê máy móc, thao tác nhanh và chính xác.","Đức Trí":"Bạn logic — điềm tĩnh, hay suy luận trước khi hành động."},"tap":[{"bai":"17","canh":[{"anh":"canh-dau","dong":[{"loi":"Qua Cổng Đảo Xanh, Biệt đội Ánh Sao bước vào chủ điểm Trên con đường học tập. Trang sách đầu tiên là Thư gửi các học sinh — bức thư Bác Hồ gửi học sinh cả nước nhân ngày khai trường đầu tiên của nước Việt Nam độc lập.","nv":"Người kể"},{"loi":"Bức thư chan chứa tình yêu thương và niềm tin của Bác dành cho thế hệ trẻ. Đọc thư, các cháu để ý những lời căn dặn ân cần và hiểu trách nhiệm học tập của người học sinh.","nv":"Cô Ong Chăm Chữ"},{"loi":"Lời Bác viết từ rất lâu rồi mà đọc lên vẫn thấy ấm áp và gần gũi ạ.","nv":"Minh Anh"},{"loi":"Mỗi câu trong thư đều là một lời nhắn gửi về việc học — học để xây dựng đất nước.","nv":"Thảo Nguyên"},{"loi":"Sương đã làm nhòe mất mấy dòng thư quý giá rồi. Đọc kỹ từng lời căn dặn, cả lớp sẽ khôi phục được bức thư!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Sân trường ngày khai giảng có hai lối vào lớp. Cả lớp chọn lối nào trước nhé!","nv":"Đức Trí"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"canh-chu","dong":[{"loi":"Quả chữ trên cây này ghi những lời căn dặn trong thư. Hái đúng quả là bức thư rõ thêm một dòng!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"canh-chu","danChuyen":"Ngay lối vào sân trường, Cây quả chữ mọc bên cột cờ, cành lá che một phần bức thư chưa rõ chữ. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"17","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cây quả chữ — hái quả lời căn dặn"},{"canh":[{"anh":"cau-suong","dong":[{"loi":"Giọng thư của Bác ân cần như lời cha dặn con. Đứng trên cầu, nghe kỹ từng câu là nhận ra ngay!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Một chiếc cầu nhỏ bắc qua con suối trong sân trường dẫn vào dãy lớp học. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"17","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cầu vần thơ — nghe giọng thư ân cần"}]},{"anh":"canh-kho","bienCo":{"dong":[{"loi":"Ối, sương tràn xuống bất ngờ, chữ trên các thẻ mờ đi rồi!","nv":"Minh Anh"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"17","mucDo":[1],"soCau":1}},"danChuyen":"Giữa sân trường, Dòng suối câu chảy quanh bục cột cờ nơi bức thư được đọc lên trang trọng. Muốn hiểu hết ý Bác phải nắm được điều mỗi đoạn thư gửi gắm. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"17","mucDo":[2],"soCau":1}},{"anh":"kho-sang","danChuyen":"Cuối sân trường là Hòm thư bí mật, nơi cất chính những lá thư của học sinh viết đáp lại lời Bác dặn. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"17","mucDo":[2,3],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Bức thư hiện ra trọn vẹn rồi! Lời Bác dặn vẫn còn nguyên sức ấm cho mọi thế hệ học sinh!","nv":"Thảo Nguyên"},{"loi":"Cô tặng biệt đội Lá Thư Ngày Khai Trường. Nghe kìa... trong thư viện có một tấm gương tự học đang sáng lên.","nv":"Cô Ong Chăm Chữ"},{"loi":"Tấm gương tự học — chắc là câu chuyện về một bạn học rất giỏi mà không cần ai nhắc!","nv":"Tuấn Kiệt"},{"loi":"Tập sau, biệt đội mình vào thư viện nhé cả lớp!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t1","ten":"Tập 1 — Thư gửi các học sinh","tomTatTapTruoc":"Mùa trước: Biệt đội mở Cổng Đảo Xanh, giữ trọn thiên nhiên thế giới và nhận Chìa Cổng Đảo Xanh. Phía sau cổng, tiếng trống trường vang lên và một lá thư cổ kính từ những ngày đầu của nước nhà đang mở ra...","tuan":"9","vatPham":"Lá Thư Ngày Khai Trường"},{"bai":"18","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao bước vào thư viện của khu vườn, nơi bài văn Tấm gương tự học kể về những con người biết tự học suốt đời.","nv":"Người kể"},{"loi":"Bài văn giới thiệu những tấm gương tự học tiêu biểu — họ học bằng ý chí và niềm say mê, không chờ ai nhắc nhở. Các cháu để ý cách tác giả chọn chi tiết để làm nổi bật tinh thần tự học của từng nhân vật.","nv":"Cô Ong Chăm Chữ"},{"loi":"Chi tiết về thói quen học tập hằng ngày là chi tiết đắt nhất để thấy ý chí của nhân vật ạ.","nv":"Đức Trí"},{"loi":"Đọc xong chỉ muốn về nhà tự mở sách ra học ngay thôi ạ.","nv":"Thảo Nguyên"},{"loi":"Sương đã làm mờ mất mấy trang viết về tấm gương sáng rồi. Đọc kỹ từng chi tiết, cả lớp sẽ làm sáng lại tấm gương!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Thư viện có hai dãy kệ sách. Cả lớp chọn dãy nào trước?","nv":"Minh Anh"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"cau-suong","dong":[{"loi":"Đứng trên cầu nhìn xuống là thấy những bàn học sáng đèn. Theo dấu các tấm gương tự học nhé!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Cầu vần thơ bắc qua con suối nhỏ trong thư viện, từ trên cầu nhìn xuống thấy những dãy bàn đọc sách. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"18","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cầu vần thơ — theo dấu tấm gương"},{"canh":[{"anh":"canh-chu","dong":[{"loi":"Quả chữ trên cây này ghi các chi tiết về ý chí tự học. Hái đúng quả là tấm gương sáng thêm một phần!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"canh-chu","danChuyen":"Cây quả chữ mọc giữa thư viện, bóng cây che một phần trang sách đầu tiên chưa rõ chữ. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"18","mucDo":[1],"soCau":1}}],"nhan":"Đến Cây quả chữ — hái quả chi tiết ý chí"}]},{"anh":"kho-sang","bienCo":{"dong":[{"loi":"Sương làm đường trơn quá, mình suýt trượt chân rồi!","nv":"Tuấn Kiệt"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"18","mucDo":[1],"soCau":1}},"danChuyen":"Giữa thư viện là Hòm thư bí mật, cất những dòng nhật ký học tập của các tấm gương sáng. Muốn mở hòm phải hiểu điều tác giả muốn nói qua câu chuyện. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"18","mucDo":[2],"soCau":1}},{"anh":"canh-kho","danChuyen":"Bên cửa sổ thư viện, Dòng suối câu chảy qua bãi đất nơi những chi tiết hay nhất của bài văn đang chờ được vớt lên. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"18","mucDo":[2,3],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Tấm gương tự học sáng rõ rồi! Tự học là chiếc chìa khóa mở mọi cánh cửa tri thức!","nv":"Đức Trí"},{"loi":"Cô tặng biệt đội Chiếc Đèn Bàn Nhỏ. Nhưng nhìn kìa... trong xưởng sáng tạo bên thư viện có những bàn tay đang trải nghiệm để làm ra cái mới.","nv":"Cô Ong Chăm Chữ"},{"loi":"Trải nghiệm để sáng tạo — nghe đã thấy thú vị rồi!","nv":"Thảo Nguyên"},{"loi":"Tập sau mình vào xưởng sáng tạo nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t2","ten":"Tập 2 — Tấm gương tự học","tomTatTapTruoc":"Tập trước: Biệt đội khôi phục Thư gửi các học sinh, hiểu những lời căn dặn ân cần của Bác Hồ, rồi nhận Lá Thư Ngày Khai Trường. Cuối tập, một tấm gương tự học sáng lên trong thư viện...","tuan":"9","vatPham":"Chiếc Đèn Bàn Nhỏ"},{"bai":"19","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao bước vào xưởng sáng tạo của khu vườn, nơi bài văn Trải nghiệm để sáng tạo bàn về cách học qua làm thật, thử thật.","nv":"Người kể"},{"loi":"Bài văn cho thấy: sáng tạo không tự nhiên mà có, nó đến từ trải nghiệm — dám thử, dám sai và rút kinh nghiệm. Các cháu để ý cách tác giả đưa dẫn chứng để làm rõ từng ý kiến của mình.","nv":"Cô Ong Chăm Chữ"},{"loi":"Ý kiến nào cũng có dẫn chứng đi kèm thì mới thuyết phục ạ.","nv":"Đức Trí"},{"loi":"Thử làm thật một lần nhớ lâu hơn đọc mười lần — đúng là trải nghiệm quý thật.","nv":"Thảo Nguyên"},{"loi":"Sương đã làm mờ mất mấy đoạn dẫn chứng quan trọng rồi. Đọc kỹ từng phần, cả lớp sẽ khôi phục được bài văn!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Xưởng sáng tạo có hai khu làm việc. Cả lớp chọn khu nào trước?","nv":"Tuấn Kiệt"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"canh-kho","dong":[{"loi":"Thẻ câu trên suối ghi các ý của bài văn theo trình tự lập luận. Vớt đúng thẻ đầu tiên nhé!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"canh-kho","danChuyen":"Dòng suối câu chảy dọc xưởng sáng tạo, in bóng những bàn làm việc xuống mặt nước. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"19","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Dòng suối câu — theo mạch lập luận"},{"canh":[{"anh":"kho-sang","dong":[{"loi":"Trong hòm là những ghi chép sau mỗi lần trải nghiệm của các bạn nhỏ. Đọc kỹ là hiểu vì sao trải nghiệm sinh sáng tạo!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"kho-sang","danChuyen":"Bên khu làm việc đầu tiên, Hòm thư bí mật nằm im lìm, nắp hòm khắc hình một chiếc bút đang vẽ. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"19","mucDo":[1],"soCau":1}}],"nhan":"Mở Hòm thư bí mật — đọc ghi chép trải nghiệm"}]},{"anh":"canh-chu","bienCo":{"dong":[{"loi":"Ơ, sương che mất một nửa đáp án rồi, mình đọc không rõ nữa!","nv":"Thảo Nguyên"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"19","mucDo":[1],"soCau":1}},"danChuyen":"Giữa xưởng, Cây quả chữ che mất phần văn nêu dẫn chứng tiêu biểu nhất. Muốn bài rõ phải nắm đúng cách tác giả làm rõ ý kiến của mình. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"19","mucDo":[2],"soCau":1}},{"anh":"cau-suong","danChuyen":"Muốn ra khỏi xưởng phải qua Cầu vần thơ, nơi thử thách về từ ngữ và ý nghĩa của bài văn đang chờ. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"19","mucDo":[2,3],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Bài văn hiện ra trọn vẹn rồi! Dám trải nghiệm, dám thử sai — sáng tạo sẽ đến!","nv":"Thảo Nguyên"},{"loi":"Cô tặng biệt đội Chiếc Bút Sáng Tạo. Nghe kìa... phía phòng tập có tiếng luyện rèn đều đặn, ngày này qua ngày khác.","nv":"Cô Ong Chăm Chữ"},{"loi":"Khổ luyện thành tài — chắc là câu chuyện của những người bền bỉ lắm.","nv":"Minh Anh"},{"loi":"Tập sau mình đến phòng tập nhé cả lớp!","nv":"Tuấn Kiệt"}],"loai":"thoai"}],"id":"t3","ten":"Tập 3 — Trải nghiệm để sáng tạo","tomTatTapTruoc":"Tập trước: Biệt đội làm sáng lại Tấm gương tự học, học cách chọn chi tiết làm nổi bật ý chí, rồi nhận Chiếc Đèn Bàn Nhỏ. Cuối tập, một xưởng sáng tạo với những bàn tay đang trải nghiệm mở ra bên thư viện...","tuan":"10","vatPham":"Chiếc Bút Sáng Tạo"},{"bai":"20","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao đến phòng tập của khu vườn, nơi bài văn Khổ luyện thành tài kể về những con người đạt thành công nhờ rèn luyện bền bỉ.","nv":"Người kể"},{"loi":"Bài văn cho thấy không có thành công nào đến dễ dàng: đằng sau mỗi thành tài là bao ngày khổ luyện thầm lặng. Các cháu để ý trình tự kể chuyện và những chi tiết về quá trình rèn luyện của nhân vật.","nv":"Cô Ong Chăm Chữ"},{"loi":"Chi tiết về những ngày tập luyện vất vả là chi tiết làm mình khâm phục nhất ạ.","nv":"Minh Anh"},{"loi":"Đọc xong mới hiểu: tài năng nở hoa trên đất của sự bền bỉ.","nv":"Thảo Nguyên"},{"loi":"Sương đã làm mờ mất mấy trang kể về những ngày khổ luyện rồi. Đọc kỹ từng chi tiết, cả lớp sẽ nối lại được hành trình thành tài!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Phòng tập có hai khu luyện rèn. Cả lớp chọn khu nào trước?","nv":"Minh Anh"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"cau-suong","dong":[{"loi":"Đứng trên cầu nghe rõ nhịp luyện tập đều đặn. Theo trình tự hành trình của nhân vật nhé!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Cầu vần thơ bắc qua con suối nhỏ dẫn vào phòng tập, ván cầu khắc những giọt mồ hôi lấp lánh. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"20","mucDo":[1],"soCau":1}}],"nhan":"Qua Cầu vần thơ — theo nhịp khổ luyện"},{"canh":[{"anh":"canh-kho","dong":[{"loi":"Thẻ câu trên suối ghi hành trình rèn luyện theo trình tự bài văn. Vớt đúng thẻ là nối được hành trình!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"canh-kho","danChuyen":"Dòng suối câu chảy êm qua phòng tập, mang theo những thẻ câu còn mờ chữ. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"20","mucDo":[1],"soCau":1}}],"nhan":"Xuôi Dòng suối câu — theo hành trình thành tài"}]},{"anh":"kho-sang","bienCo":{"dong":[{"loi":"Sương kéo đến dày quá, mọi thứ nhòe đi như nhìn qua kính mờ!","nv":"Đức Trí"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"20","mucDo":[1,2],"soCau":1}},"danChuyen":"Trong phòng tập là Hòm thư bí mật, cất những dòng tâm sự của người khổ luyện sau mỗi ngày dài. Muốn mở hòm phải hiểu điều tác giả gửi gắm. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"20","mucDo":[2],"soCau":1}},{"anh":"canh-chu","danChuyen":"Trước khi rời phòng tập, Cây quả chữ bên cửa sổ còn một thử thách về từ ngữ và ý nghĩa của bài văn. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"20","mucDo":[2,3],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Hành trình khổ luyện hiện ra trọn vẹn rồi! Thành tài không tự đến — nó đến từ bền bỉ mỗi ngày!","nv":"Minh Anh"},{"loi":"Cô tặng biệt đội Giọt Mồ Hôi Vàng. Nhưng nhìn kìa...","nv":"Cô Ong Chăm Chữ"},{"loi":"Khà... khà... Bốn bài học về con đường học tập thì đã sao? Cổng Học Tập vẫn nằm trong tay ta...","nv":"Sương Mù"},{"loi":"Cổng Học Tập hiện ra giữa sân trường, và Sương Mù đang giữ cổng! Cả lớp ơi, tập đặc biệt — mình cùng phá cổng nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t4","ten":"Tập 4 — Khổ luyện thành tài","tomTatTapTruoc":"Tập trước: Biệt đội khôi phục bài văn Trải nghiệm để sáng tạo, học cách dùng dẫn chứng làm rõ ý kiến, rồi nhận Chiếc Bút Sáng Tạo. Cuối tập, tiếng luyện rèn đều đặn vọng lại từ phòng tập phía xa...","tuan":"10","vatPham":"Giọt Mồ Hôi Vàng"},{"bai":"17+18+19+20","canh":[{"anh":"canh-trum","dong":[{"loi":"Ta là Sương Mù Quên Lãng. Khiên sương của ta chỉ vỡ khi gặp câu trả lời đúng. Các ngươi dám thử không?","nv":"Sương Mù"},{"loi":"Biệt đội Ánh Sao sẵn sàng! Lời căn dặn, chi tiết ý chí, dẫn chứng, trình tự — chúng mình đều nắm chắc!","nv":"Minh Anh"},{"loi":"Luật phá cổng: trên cổng có bốn ô chiêu thức phát sáng. Chọn chiêu thức là đáp án đúng, khiên sương nứt một phần. Bình tĩnh đọc kỹ, các cháu nhé.","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-trum","danChuyen":"Sương Mù thổi một làn khói che mất bức thư của Bác Hồ. Cả lớp chọn chiêu thức đúng về những lời căn dặn trong Thư gửi các học sinh nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"17","mucDo":[2],"soCau":1}},{"anh":"canh-trum","danChuyen":"Khiên sương rung lên! Sương Mù tung đòn Tấm gương tự học với những chi tiết về ý chí. Cả lớp chọn chiêu thức đúng để phá tiếp nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"18","mucDo":[2],"soCau":1}},{"anh":"canh-trum","danChuyen":"Sương Mù làm mờ những dẫn chứng của bài Trải nghiệm để sáng tạo trong làn khói. Cả lớp chọn chiêu thức đúng về cách làm rõ ý kiến nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"19","mucDo":[2],"soCau":1}},{"anh":"canh-trum","danChuyen":"Đòn cuối cùng! Sương Mù dồn hết sức vào hành trình Khổ luyện thành tài. Cả lớp chọn chiêu thức đúng để phá tan khiên sương nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"20","mucDo":[2],"soCau":1}},{"anh":"cua-mo","dong":[{"loi":"Thôi được... Cổng này là của các ngươi. Nhưng phía sau cổng là cả một thế giới trong trang sách, sương của ta còn dày lắm...","nv":"Sương Mù"},{"loi":"Cổng Học Tập đã mở! Biệt đội nhận Chìa Cổng Học Tập. Con đường học tập — các cháu đã đi vững những bước đầu rồi.","nv":"Cô Ong Chăm Chữ"},{"loi":"Phía sau cổng có mùi giấy sách thơm và tiếng lật trang xào xạc...","nv":"Đức Trí"},{"loi":"Đó là thế giới trong trang sách đang chờ! Hẹn gặp cả lớp ở mùa tiếp theo nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"trum","laTapTrum":true,"ten":"Tập đặc biệt — Cổng Học Tập","tomTatTapTruoc":"Biệt đội đã khôi phục bốn bài học của chủ điểm Trên con đường học tập: lá thư của Bác Hồ, tấm gương tự học, trải nghiệm để sáng tạo và hành trình khổ luyện thành tài. Giờ đây, Sương Mù Quên Lãng đang giữ Cổng Học Tập bằng một khiên sương dày...","tuan":"10","vatPham":"Chìa Cổng Học Tập"}],"tenMua":"Mùa 5 — Con Đường Học Tập","tomTatMua":"Chủ điểm Trên con đường học tập mở ra bằng bức thư Bác Hồ gửi học sinh ngày khai trường đầu tiên, rồi đưa Biệt đội Ánh Sao gặp những tấm gương tự học, học cách trải nghiệm để sáng tạo và khâm phục những hành trình khổ luyện thành tài. Sương Mù Quên Lãng phủ mờ từng bài học, và biệt đội phải khôi phục tất cả để mở Cổng Học Tập."},{"anhBia":"trang-sach-tuoi-tho","anhCanTao":[{"khoa":"trang-sach-tuoi-tho","moTa":"Một trang sách khổng lồ mở ra như cánh cổng trong Khu Vườn Ngôn Từ: từ trang sách bước ra chú dế mang ba lô phiêu lưu, những cuốn truyện cổ tích xếp thành cầu thang và một chiếc kính hiển vi nhỏ sáng lấp lánh; Cô Ong Chăm Chữ đeo kính bay trên trang sách, Biệt đội Ánh Sao áo trắng khăn quàng đỏ đứng giữa trang giấy; một góc trang sách bị sương xám phủ mờ. Phong cách 3D Pixar, không chữ."}],"cacBai":["21","22","23","24"],"cacChuDe":["3"],"id":"tv5-c6","lop":5,"mon":"Tiếng Việt","nhanVat":{"Cô Ong Chăm Chữ":"Cô Ong Chăm Chữ — ong thợ chăm chỉ của Khu Vườn Ngôn Từ, bay lượn đọc chính tả vui; là người đọc lời giải thích sau mỗi thử thách trong thế giới Tiếng Việt.","Minh Anh":"Đội trưởng Biệt đội Ánh Sao — quyết đoán, luôn đi đầu.","Sương Mù":"Sương Mù Quên Lãng — thế lực xám lạnh chuyên xóa chữ và kiến thức trong các cuốn sách.","Thảo Nguyên":"Bạn ngôn ngữ — hoạt bát, giỏi chữ nghĩa và tiếng Việt.","Thủ thư Số":"Người giữ sách của Thư viện Ánh Sao — hiền từ, hiểu biết, luôn đưa ra lời giải thích sau mỗi thử thách.","Tuấn Kiệt":"Bạn kỹ thuật — mê máy móc, thao tác nhanh và chính xác.","Đức Trí":"Bạn logic — điềm tĩnh, hay suy luận trước khi hành động."},"tap":[{"bai":"21","canh":[{"anh":"canh-dau","dong":[{"loi":"Qua Cổng Học Tập, Biệt đội Ánh Sao bước vào một thư viện kỳ diệu, nơi bài văn Thế giới trong trang sách mở ra cả vũ trụ trong từng cuốn sách nhỏ.","nv":"Người kể"},{"loi":"Bài văn nói về sức mạnh của sách: mỗi trang sách mở ra một thế giới — có tri thức, có những miền đất xa, có những người bạn mới. Các cháu để ý cách tác giả nêu những điều sách mang lại cho người đọc.","nv":"Cô Ong Chăm Chữ"},{"loi":"Đọc một cuốn sách là đi một chuyến du hành mà không cần rời khỏi ghế ạ.","nv":"Thảo Nguyên"},{"loi":"Bài còn gợi cho mình cách chọn sách và đọc sách sao cho hiệu quả.","nv":"Đức Trí"},{"loi":"Sương đã làm nhòe mất mấy trang sách quý trong thư viện rồi. Đọc kỹ từng ý, cả lớp sẽ mở lại được thế giới trong trang sách!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Thư viện kỳ diệu có hai dãy kệ cao ngất. Cả lớp chọn dãy nào trước nhé!","nv":"Đức Trí"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"canh-chu","dong":[{"loi":"Quả chữ trên cây này ghi những điều sách mang đến cho người đọc. Hái đúng quả là trang sách rõ thêm một phần!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"canh-chu","danChuyen":"Ngay lối vào thư viện, Cây quả chữ mọc xuyên qua dãy kệ đầu tiên, cành lá che một phần trang sách chưa rõ chữ. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"21","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cây quả chữ — hái quả điều sách mang lại"},{"canh":[{"anh":"cau-suong","dong":[{"loi":"Tiếng lật trang xào xạc như nhạc. Đứng trên cầu, nghe kỹ từng câu văn là nhận ra ngay!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Một chiếc cầu nhỏ bắc qua con suối trong thư viện dẫn tới dãy kệ phía trong. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"21","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cầu vần thơ — nghe tiếng lật trang"}]},{"anh":"canh-kho","bienCo":{"dong":[{"loi":"Ối, sương tràn xuống bất ngờ, chữ trên các thẻ mờ đi rồi!","nv":"Minh Anh"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"21","mucDo":[1],"soCau":1}},"danChuyen":"Giữa thư viện, Dòng suối câu chảy quanh bàn đọc sách lớn nhất. Muốn mở được thế giới trong sách phải nắm được điều tác giả gửi gắm qua từng ý. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"21","mucDo":[2],"soCau":1}},{"anh":"kho-sang","danChuyen":"Cuối thư viện là Hòm thư bí mật, nơi cất những dòng cảm nhận của các bạn nhỏ sau mỗi cuốn sách hay. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"21","mucDo":[2,3],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Thế giới trong trang sách mở ra trọn vẹn rồi! Mỗi cuốn sách là một cánh cửa thần kỳ!","nv":"Thảo Nguyên"},{"loi":"Cô tặng biệt đội Chiếc Đánh Dấu Trang Vàng. Nghe kìa... từ kệ sách tuổi thơ vọng lại tiếng cười của những câu chuyện ấu thơ xưa.","nv":"Cô Ong Chăm Chữ"},{"loi":"Những câu chuyện ngày bé — ai cũng có một kho chuyện ấu thơ!","nv":"Tuấn Kiệt"},{"loi":"Tập sau, biệt đội mình về với những câu chuyện ấu thơ nhé cả lớp!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t1","ten":"Tập 1 — Thế giới trong trang sách","tomTatTapTruoc":"Mùa trước: Biệt đội mở Cổng Học Tập, giữ trọn bốn bài học về con đường học tập và nhận Chìa Cổng Học Tập. Phía sau cổng, mùi giấy sách thơm thoang thoảng và tiếng lật trang xào xạc mời gọi...","tuan":"11","vatPham":"Chiếc Đánh Dấu Trang Vàng"},{"bai":"22","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao dừng lại trước kệ sách tuổi thơ, nơi bài văn Từ những câu chuyện ấu thơ kể về những bài học đầu đời đến từ những câu chuyện được nghe từ bé.","nv":"Người kể"},{"loi":"Bài văn cho thấy những câu chuyện ấu thơ — chuyện cổ tích, chuyện bà kể — đã gieo vào lòng trẻ nhỏ những hạt mầm tốt đẹp đầu tiên. Các cháu để ý cách tác giả kể lại kỷ niệm và rút ra ý nghĩa của những câu chuyện xưa.","nv":"Cô Ong Chăm Chữ"},{"loi":"Mỗi câu chuyện bà kể là một bài học làm người đầu tiên ạ.","nv":"Thảo Nguyên"},{"loi":"Bài còn nhắc mình biết ơn những người đã kể chuyện và dạy dỗ mình từ thuở bé.","nv":"Đức Trí"},{"loi":"Sương đã làm lạc mất mấy trang chuyện ấu thơ rồi. Đọc kỹ từng kỷ niệm, cả lớp sẽ nối lại được dòng chuyện xưa!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Kệ sách tuổi thơ có hai ngăn chuyện. Cả lớp chọn ngăn nào trước?","nv":"Minh Anh"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"cau-suong","dong":[{"loi":"Đứng trên cầu nghe rõ giọng kể chuyện trầm ấm của bà. Theo dòng kỷ niệm từ đầu nhé!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Cầu vần thơ bắc qua con suối nhỏ trong thư viện, từ trên cầu nhìn xuống thấy những cuốn truyện tranh sặc sỡ. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"22","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cầu vần thơ — theo giọng kể chuyện xưa"},{"canh":[{"anh":"canh-chu","dong":[{"loi":"Quả chữ trên cây này ghi các kỷ niệm trong bài văn. Hái đúng quả là dòng chuyện rõ thêm một đoạn!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"canh-chu","danChuyen":"Cây quả chữ mọc bên kệ sách tuổi thơ, bóng cây che một phần trang chuyện đầu tiên chưa rõ chữ. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"22","mucDo":[1],"soCau":1}}],"nhan":"Đến Cây quả chữ — hái quả kỷ niệm ấu thơ"}]},{"anh":"kho-sang","bienCo":{"dong":[{"loi":"Sương làm đường trơn quá, mình suýt trượt chân rồi!","nv":"Tuấn Kiệt"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"22","mucDo":[1],"soCau":1}},"danChuyen":"Giữa kệ sách là Hòm thư bí mật, cất những dòng cảm nhận về những câu chuyện đầu đời. Muốn mở hòm phải hiểu điều tác giả muốn nói qua từng kỷ niệm. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"22","mucDo":[1],"soCau":1}},{"anh":"canh-kho","danChuyen":"Bên cửa sổ thư viện, Dòng suối câu chảy qua bãi đất nơi những chi tiết hay nhất của bài văn đang chờ được vớt lên. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"22","mucDo":[3],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Dòng chuyện ấu thơ nối lại trọn vẹn rồi! Những câu chuyện đầu đời là hành trang theo mình mãi!","nv":"Đức Trí"},{"loi":"Cô tặng biệt đội Cuộn Chỉ Kể Chuyện. Nhưng nhìn kìa... trên kệ bên có một cuốn sách nổi tiếng với một chú dế phiêu lưu đang bị sương phủ.","nv":"Cô Ong Chăm Chữ"},{"loi":"Dế Mèn phiêu lưu kí — cuốn sách tuổi thơ của bao thế hệ!","nv":"Thảo Nguyên"},{"loi":"Tập sau mình mở cuốn sách ấy nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t2","ten":"Tập 2 — Từ những câu chuyện ấu thơ","tomTatTapTruoc":"Tập trước: Biệt đội mở lại Thế giới trong trang sách, hiểu sức mạnh của sách đối với người đọc, rồi nhận Chiếc Đánh Dấu Trang Vàng. Cuối tập, tiếng cười vọng lại từ kệ sách tuổi thơ...","tuan":"11","vatPham":"Cuộn Chỉ Kể Chuyện"},{"bai":"23","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao cầm lên cuốn sách gối đầu giường của bao thế hệ học trò, nơi bài văn Giới thiệu sách Dế Mèn phiêu lưu kí hướng dẫn cách giới thiệu một cuốn sách hay.","nv":"Người kể"},{"loi":"Bài văn mẫu cho thấy cách giới thiệu sách: nêu tên sách, tác giả, nội dung chính và lý do nên đọc. Các cháu để ý trình tự giới thiệu và những chi tiết được chọn để hấp dẫn người nghe.","nv":"Cô Ong Chăm Chữ"},{"loi":"Giới thiệu sách hay là phải làm người nghe muốn cầm sách lên đọc ngay ạ.","nv":"Đức Trí"},{"loi":"Dế Mèn phiêu lưu kí của nhà văn Tô Hoài — chú dế kiêu căng ngày nào đã học được bao bài học đường đời.","nv":"Thảo Nguyên"},{"loi":"Sương đã làm mờ mất tấm thiệp giới thiệu sách rồi. Đọc kỹ từng phần, cả lớp sẽ viết lại được lời giới thiệu!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Bàn giới thiệu sách có hai phía trưng bày. Cả lớp chọn phía nào trước?","nv":"Tuấn Kiệt"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"canh-kho","dong":[{"loi":"Thẻ câu trên suối ghi các phần giới thiệu sách theo trình tự. Vớt đúng thẻ đầu tiên nhé!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"canh-kho","danChuyen":"Dòng suối câu chảy dọc bàn trưng bày, in bóng bìa sách Dế Mèn xuống mặt nước. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"23","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Dòng suối câu — theo trình tự giới thiệu"},{"canh":[{"anh":"kho-sang","dong":[{"loi":"Trong hòm là những dòng cảm nhận của các bạn nhỏ sau khi đọc Dế Mèn phiêu lưu kí. Đọc kỹ là thấy vì sao cuốn sách được yêu quý!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"kho-sang","danChuyen":"Bên bàn trưng bày, Hòm thư bí mật nằm im lìm, nắp hòm khắc hình một chú dế đang phiêu lưu. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"23","mucDo":[1],"soCau":1}}],"nhan":"Mở Hòm thư bí mật — đọc cảm nhận về Dế Mèn"}]},{"anh":"canh-chu","bienCo":{"dong":[{"loi":"Ơ, sương che mất một nửa đáp án rồi, mình đọc không rõ nữa!","nv":"Thảo Nguyên"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"23","mucDo":[1],"soCau":1}},"danChuyen":"Giữa bàn trưng bày, Cây quả chữ che mất phần giới thiệu nội dung chính của cuốn sách. Muốn thiệp rõ phải nắm đúng cách tác giả chọn chi tiết để giới thiệu. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"23","mucDo":[2],"soCau":1}},{"anh":"cau-suong","danChuyen":"Muốn rời bàn trưng bày phải qua Cầu vần thơ, nơi thử thách về từ ngữ và ý nghĩa của bài văn đang chờ. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"23","mucDo":[1,2],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Tấm thiệp giới thiệu hiện ra trọn vẹn rồi! Một cuốn sách hay xứng đáng được giới thiệu cho thật nhiều bạn đọc!","nv":"Thảo Nguyên"},{"loi":"Cô tặng biệt đội Tấm Thiệp Giới Thiệu Sách. Nghe kìa... phía thư viện vọng lại câu chuyện về một nhà bác học tự học thành tài.","nv":"Cô Ong Chăm Chữ"},{"loi":"Nhà Phi-lít — người học bằng cả niềm say mê!","nv":"Minh Anh"},{"loi":"Tập sau mình gặp nhà Phi-lít nhé cả lớp!","nv":"Tuấn Kiệt"}],"loai":"thoai"}],"id":"t3","ten":"Tập 3 — Giới thiệu sách Dế Mèn phiêu lưu kí","tomTatTapTruoc":"Tập trước: Biệt đội nối lại dòng chuyện ấu thơ, hiểu ý nghĩa của những câu chuyện đầu đời, rồi nhận Cuộn Chỉ Kể Chuyện. Cuối tập, cuốn Dế Mèn phiêu lưu kí nổi tiếng hiện ra trên kệ bên...","tuan":"12","vatPham":"Tấm Thiệp Giới Thiệu Sách"},{"bai":"24","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao đến góc khoa học của thư viện, nơi bài văn Tinh thần học tập của nhà Phi-lít kể về một con người ham học hiếm có.","nv":"Người kể"},{"loi":"Bài văn kể về nhà Phi-lít — người say mê học hỏi đến quên ăn quên ngủ, tự học thành tài dù hoàn cảnh khó khăn. Các cháu để ý những chi tiết cho thấy tinh thần học tập đáng khâm phục của ông.","nv":"Cô Ong Chăm Chữ"},{"loi":"Chi tiết về những đêm miệt mài bên sách vở là chi tiết làm mình xúc động nhất ạ.","nv":"Minh Anh"},{"loi":"Tinh thần ấy nhắc chúng mình: muốn giỏi phải say mê và bền bỉ với việc học.","nv":"Thảo Nguyên"},{"loi":"Sương đã làm mờ mất mấy trang kể về nhà Phi-lít rồi. Đọc kỹ từng chi tiết, cả lớp sẽ khôi phục được câu chuyện!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Góc khoa học có hai bàn thí nghiệm. Cả lớp chọn bàn nào trước?","nv":"Minh Anh"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"cau-suong","dong":[{"loi":"Đứng trên cầu nghe rõ tiếng lật sách thâu đêm. Theo trình tự câu chuyện về nhà Phi-lít nhé!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Cầu vần thơ bắc qua con suối nhỏ dẫn vào góc khoa học, ván cầu khắc những vì sao và ống nghiệm. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"24","mucDo":[1],"soCau":1}}],"nhan":"Qua Cầu vần thơ — theo dấu nhà bác học"},{"canh":[{"anh":"canh-kho","dong":[{"loi":"Thẻ câu trên suối ghi hành trình học tập của nhà Phi-lít theo trình tự bài văn. Vớt đúng thẻ là nối được hành trình!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"canh-kho","danChuyen":"Dòng suối câu chảy êm qua góc khoa học, mang theo những thẻ câu còn mờ chữ. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"24","mucDo":[1],"soCau":1}}],"nhan":"Xuôi Dòng suối câu — theo hành trình tự học"}]},{"anh":"kho-sang","bienCo":{"dong":[{"loi":"Sương kéo đến dày quá, mọi thứ nhòe đi như nhìn qua kính mờ!","nv":"Đức Trí"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"24","mucDo":[1],"soCau":1}},"danChuyen":"Trong góc khoa học là Hòm thư bí mật, cất những dòng tâm sự về niềm say mê tri thức. Muốn mở hòm phải hiểu điều tác giả gửi gắm. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"24","mucDo":[2],"soCau":1}},{"anh":"canh-chu","danChuyen":"Trước khi rời thư viện, Cây quả chữ bên cửa sổ còn một thử thách về từ ngữ và ý nghĩa của bài văn. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"24","mucDo":[2,3],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Câu chuyện nhà Phi-lít hiện ra trọn vẹn rồi! Say mê học tập là ngọn lửa không bao giờ tắt!","nv":"Minh Anh"},{"loi":"Cô tặng biệt đội Chiếc Kính Hiển Vi Nhỏ. Nhưng nhìn kìa...","nv":"Cô Ong Chăm Chữ"},{"loi":"Khà... khà... Bốn câu chuyện về sách vở thì đã sao? Cổng Trang Sách vẫn nằm trong tay ta...","nv":"Sương Mù"},{"loi":"Cổng Trang Sách hiện ra giữa thư viện, và Sương Mù đang giữ cổng! Cả lớp ơi, tập đặc biệt — mình cùng phá cổng nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t4","ten":"Tập 4 — Tinh thần học tập của nhà Phi-lít","tomTatTapTruoc":"Tập trước: Biệt đội viết lại lời giới thiệu sách Dế Mèn phiêu lưu kí, học cách giới thiệu một cuốn sách hay, rồi nhận Tấm Thiệp Giới Thiệu Sách. Cuối tập, câu chuyện về một nhà bác học tự học vọng lại từ phía thư viện...","tuan":"12","vatPham":"Chiếc Kính Hiển Vi Nhỏ"},{"bai":"21+22+23+24","canh":[{"anh":"canh-trum","dong":[{"loi":"Ta là Sương Mù Quên Lãng. Khiên sương của ta chỉ vỡ khi gặp câu trả lời đúng. Các ngươi dám thử không?","nv":"Sương Mù"},{"loi":"Biệt đội Ánh Sao sẵn sàng! Ý chính, kỷ niệm, trình tự giới thiệu, chi tiết ý chí — chúng mình đều nắm chắc!","nv":"Minh Anh"},{"loi":"Luật phá cổng: trên cổng có bốn ô chiêu thức phát sáng. Chọn chiêu thức là đáp án đúng, khiên sương nứt một phần. Bình tĩnh đọc kỹ, các cháu nhé.","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-trum","danChuyen":"Sương Mù thổi một làn khói che mất những trang sách quý. Cả lớp chọn chiêu thức đúng về những điều sách mang lại trong bài Thế giới trong trang sách nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"21","mucDo":[2],"soCau":1}},{"anh":"canh-trum","danChuyen":"Khiên sương rung lên! Sương Mù tung đòn Từ những câu chuyện ấu thơ với những kỷ niệm đầu đời. Cả lớp chọn chiêu thức đúng để phá tiếp nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"22","mucDo":[3],"soCau":1}},{"anh":"canh-trum","danChuyen":"Sương Mù làm mờ tấm thiệp giới thiệu Dế Mèn phiêu lưu kí trong làn khói. Cả lớp chọn chiêu thức đúng về cách giới thiệu sách nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"23","mucDo":[2],"soCau":1}},{"anh":"canh-trum","danChuyen":"Đòn cuối cùng! Sương Mù dồn hết sức vào tinh thần học tập của nhà Phi-lít. Cả lớp chọn chiêu thức đúng để phá tan khiên sương nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"24","mucDo":[2],"soCau":1}},{"anh":"cua-mo","dong":[{"loi":"Thôi được... Cổng này là của các ngươi. Nhưng phía sau cổng là cả một trời nghệ thuật muôn màu, sương của ta còn dày lắm...","nv":"Sương Mù"},{"loi":"Cổng Trang Sách đã mở! Biệt đội nhận Chìa Cổng Trang Sách. Thế giới trong trang sách — các cháu đã giữ trọn được rồi.","nv":"Cô Ong Chăm Chữ"},{"loi":"Phía sau cổng có tiếng đàn ngân vang trên sông và sắc màu tranh dân gian rực rỡ...","nv":"Đức Trí"},{"loi":"Đó là chủ điểm Nghệ thuật muôn màu đang chờ! Hẹn gặp cả lớp ở mùa tiếp theo nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"trum","laTapTrum":true,"ten":"Tập đặc biệt — Cổng Trang Sách","tomTatTapTruoc":"Biệt đội đã khôi phục bốn câu chuyện của thế giới trong trang sách: sức mạnh của sách, những câu chuyện ấu thơ, cuốn Dế Mèn phiêu lưu kí và tinh thần học tập của nhà Phi-lít. Giờ đây, Sương Mù Quên Lãng đang giữ Cổng Trang Sách bằng một khiên sương dày...","tuan":"12","vatPham":"Chìa Cổng Trang Sách"}],"tenMua":"Mùa 6 — Trang Sách Tuổi Thơ","tomTatMua":"Thế giới trong trang sách đón Biệt đội Ánh Sao bằng sức mạnh của sách, những câu chuyện ấu thơ gieo mầm tốt đẹp, cuốn Dế Mèn phiêu lưu kí của nhà văn Tô Hoài và ngọn lửa tự học của nhà Phi-lít. Sương Mù Quên Lãng phủ mờ từng trang sách, và biệt đội phải khôi phục tất cả để mở Cổng Trang Sách."},{"anhBia":"sac-mau-nghe-thuat","anhCanTao":[{"khoa":"sac-mau-nghe-thuat","moTa":"Một sân khấu nghệ thuật rực rỡ bên bờ sông trăng trong Khu Vườn Ngôn Từ: cây đàn ba-la-lai-ca lớn dựng bên bến sông, những bức tranh dân gian làng Hồ treo trên vách tre, đôi cánh tưởng tượng bằng giấy màu bay trên cao và dải lụa quan họ mềm mại; Cô Ong Chăm Chữ đeo kính bay giữa sắc màu, Biệt đội Ánh Sao áo trắng khăn quàng đỏ đứng trên sân khấu nhỏ; một góc sân khấu bị sương xám phủ mờ. Phong cách 3D Pixar, không chữ."}],"cacBai":["25","26","27","28"],"cacChuDe":["4"],"id":"tv5-c7","lop":5,"mon":"Tiếng Việt","nhanVat":{"Cô Ong Chăm Chữ":"Cô Ong Chăm Chữ — ong thợ chăm chỉ của Khu Vườn Ngôn Từ, bay lượn đọc chính tả vui; là người đọc lời giải thích sau mỗi thử thách trong thế giới Tiếng Việt.","Minh Anh":"Đội trưởng Biệt đội Ánh Sao — quyết đoán, luôn đi đầu.","Sương Mù":"Sương Mù Quên Lãng — thế lực xám lạnh chuyên xóa chữ và kiến thức trong các cuốn sách.","Thảo Nguyên":"Bạn ngôn ngữ — hoạt bát, giỏi chữ nghĩa và tiếng Việt.","Thủ thư Số":"Người giữ sách của Thư viện Ánh Sao — hiền từ, hiểu biết, luôn đưa ra lời giải thích sau mỗi thử thách.","Tuấn Kiệt":"Bạn kỹ thuật — mê máy móc, thao tác nhanh và chính xác.","Đức Trí":"Bạn logic — điềm tĩnh, hay suy luận trước khi hành động."},"tap":[{"bai":"25","canh":[{"anh":"canh-dau","dong":[{"loi":"Qua Cổng Trang Sách, Biệt đội Ánh Sao bước vào chủ điểm Nghệ thuật muôn màu. Bên dòng sông Đà, bài văn Tiếng đàn ba-la-lai-ca trên sông Đà mở ra một đêm trăng đầy nhạc và thơ.","nv":"Người kể"},{"loi":"Bài văn tả cảnh đêm trăng trên công trường sông Đà, nơi tiếng đàn ba-la-lai-ca của cô gái Nga hòa cùng tiếng sóng. Các cháu để ý những hình ảnh đẹp và cảm xúc mà khung cảnh gợi lên trong lòng người nghe.","nv":"Cô Ong Chăm Chữ"},{"loi":"Cảnh và tình hòa vào nhau — tiếng đàn làm đêm trăng như có hồn ạ.","nv":"Thảo Nguyên"},{"loi":"Bài còn là biểu tượng đẹp của tình hữu nghị giữa con người với con người.","nv":"Đức Trí"},{"loi":"Sương đêm đã làm nhòe mất mấy đoạn tả cảnh hay nhất rồi. Đọc kỹ từng hình ảnh, cả lớp sẽ khôi phục được đêm trăng trên sông Đà!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Bờ sông có hai lối xuống bến. Cả lớp chọn lối nào trước nhé!","nv":"Đức Trí"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"canh-chu","dong":[{"loi":"Quả chữ trên cây này ghi những hình ảnh của đêm trăng trên sông. Hái đúng quả là khung cảnh rõ thêm một phần!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"canh-chu","danChuyen":"Ngay lối xuống bến, Cây quả chữ mọc bên triền sông, cành lá che một phần bài văn chưa rõ chữ. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"25","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cây quả chữ — hái quả hình ảnh đêm trăng"},{"canh":[{"anh":"cau-suong","dong":[{"loi":"Tiếng đàn ngân trên mặt sông nghe rõ nhất từ trên cầu. Đứng trên cầu, nghe kỹ từng câu văn nhé!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Một chiếc cầu nhỏ bắc qua con suối đổ ra sông Đà. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"25","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cầu vần thơ — nghe tiếng đàn ngân"}]},{"anh":"canh-kho","bienCo":{"dong":[{"loi":"Ối, sương tràn xuống bất ngờ, chữ trên các thẻ mờ đi rồi!","nv":"Minh Anh"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"25","mucDo":[1],"soCau":1}},"danChuyen":"Giữa bến sông, Dòng suối câu chảy quanh bãi đá nơi người nghe đàn ngồi lặng ngắm trăng. Muốn hiểu hết vẻ đẹp của bài phải nắm được cảm xúc tác giả gửi gắm qua khung cảnh. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"25","mucDo":[2],"soCau":1}},{"anh":"kho-sang","danChuyen":"Cuối bến sông là Hòm thư bí mật, nơi cất những cảm nhận về tình hữu nghị và vẻ đẹp nghệ thuật trong bài văn. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"25","mucDo":[2,3],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Đêm trăng trên sông Đà hiện ra trọn vẹn rồi! Tiếng đàn ngân xa, cảnh và tình hòa làm một!","nv":"Thảo Nguyên"},{"loi":"Cô tặng biệt đội Chiếc Khóa Đàn Nhỏ. Nghe kìa... trong phòng tưởng tượng bên bờ sông, những ý tưởng lạ đang bay lượn.","nv":"Cô Ong Chăm Chữ"},{"loi":"Trí tưởng tượng phong phú — chắc là một bài học rất thú vị!","nv":"Tuấn Kiệt"},{"loi":"Tập sau, biệt đội mình vào phòng tưởng tượng nhé cả lớp!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t1","ten":"Tập 1 — Tiếng đàn trên sông Đà","tomTatTapTruoc":"Mùa trước: Biệt đội mở Cổng Trang Sách, giữ trọn thế giới trong trang sách và nhận Chìa Cổng Trang Sách. Phía sau cổng, tiếng đàn ba-la-lai-ca ngân vang trên dòng sông và sắc màu nghệ thuật rực rỡ mở ra...","tuan":"13","vatPham":"Chiếc Khóa Đàn Nhỏ"},{"bai":"26","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao bước vào phòng tưởng tượng của khu vườn, nơi bài văn Trí tưởng tượng phong phú kể về sức mạnh kỳ diệu của trí tưởng tượng trong sáng tạo nghệ thuật và cuộc sống.","nv":"Người kể"},{"loi":"Bài văn cho thấy trí tưởng tượng giúp con người sáng tạo không ngừng — từ những đồ vật quanh mình, người ta tưởng tượng ra bao điều mới lạ. Các cháu để ý cách tác giả nêu ví dụ để làm rõ vai trò của trí tưởng tượng.","nv":"Cô Ong Chăm Chữ"},{"loi":"Mỗi ví dụ là một minh chứng — tưởng tượng không phải mơ mộng viển vông mà là khởi đầu của sáng tạo ạ.","nv":"Đức Trí"},{"loi":"Nhờ tưởng tượng mà trẻ em biến que củi thành bao nhiêu trò chơi thú vị.","nv":"Thảo Nguyên"},{"loi":"Sương đã làm mờ mất mấy ví dụ hay nhất trong bài rồi. Đọc kỹ từng phần, cả lớp sẽ khôi phục được bài văn!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Phòng tưởng tượng có hai cánh cửa mơ mộng. Cả lớp chọn cánh nào trước?","nv":"Minh Anh"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"cau-suong","dong":[{"loi":"Đứng trên cầu nhìn xuống là thấy những ý tưởng bay như bướm. Theo mạch bài văn từ đầu nhé!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Cầu vần thơ bắc qua con suối nhỏ trong phòng tưởng tượng, từ trên cầu nhìn xuống thấy những đám mây hình thù kỳ lạ. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"26","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cầu vần thơ — theo cánh tưởng tượng"},{"canh":[{"anh":"canh-chu","dong":[{"loi":"Quả chữ trên cây này ghi các ví dụ về trí tưởng tượng. Hái đúng quả là hiểu bài thêm một phần!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"canh-chu","danChuyen":"Cây quả chữ mọc giữa phòng tưởng tượng, bóng cây che một phần đoạn văn đầu tiên chưa rõ chữ. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"26","mucDo":[1],"soCau":1}}],"nhan":"Đến Cây quả chữ — hái quả ví dụ sáng tạo"}]},{"anh":"kho-sang","bienCo":{"dong":[{"loi":"Sương làm đường trơn quá, mình suýt trượt chân rồi!","nv":"Tuấn Kiệt"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"26","mucDo":[1],"soCau":1}},"danChuyen":"Giữa phòng là Hòm thư bí mật, cất những dòng về những ước mơ và phát minh bắt đầu từ tưởng tượng. Muốn mở hòm phải hiểu điều tác giả muốn nói. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"26","mucDo":[1],"soCau":1}},{"anh":"canh-kho","danChuyen":"Bên cửa sổ phòng tưởng tượng, Dòng suối câu chảy qua bãi đất nơi những chi tiết hay nhất của bài văn đang chờ được vớt lên. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"26","mucDo":[1],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Bài văn hiện ra trọn vẹn rồi! Trí tưởng tượng là đôi cánh của mọi sáng tạo!","nv":"Đức Trí"},{"loi":"Cô tặng biệt đội Đôi Cánh Tưởng Tượng. Nhưng nhìn kìa... trong làng nghề bên kia có những bức tranh dân gian rực rỡ đang bị sương phủ.","nv":"Cô Ong Chăm Chữ"},{"loi":"Tranh làng Hồ — tranh dân gian nổi tiếng của quê hương mình!","nv":"Thảo Nguyên"},{"loi":"Tập sau mình về làng Hồ xem tranh nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t2","ten":"Tập 2 — Trí tưởng tượng phong phú","tomTatTapTruoc":"Tập trước: Biệt đội khôi phục đêm trăng và tiếng đàn trên sông Đà, cảm nhận vẻ đẹp của cảnh và tình, rồi nhận Chiếc Khóa Đàn Nhỏ. Cuối tập, một phòng tưởng tượng với những ý tưởng bay lượn mở ra bên bờ sông...","tuan":"13","vatPham":"Đôi Cánh Tưởng Tượng"},{"bai":"27","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao về làng Hồ, nơi bài văn Tranh làng Hồ giới thiệu dòng tranh dân gian nổi tiếng của Việt Nam với những nét vẽ mộc mạc mà tinh tế.","nv":"Người kể"},{"loi":"Bài văn tả vẻ đẹp của tranh làng Hồ: màu sắc lấy từ thiên nhiên, đường nét giản dị mà chứa chan tình quê. Các cháu để ý cách tác giả tả từng loại tranh và cảm xúc tự hào về nghệ thuật dân tộc.","nv":"Cô Ong Chăm Chữ"},{"loi":"Màu tranh làm từ lá cây, vỏ sò, than tre — thiên nhiên hóa thành sắc màu ạ.","nv":"Thảo Nguyên"},{"loi":"Bài còn giúp mình biết trân trọng những giá trị văn hóa truyền thống của cha ông.","nv":"Đức Trí"},{"loi":"Sương đã làm phai màu mấy bức tranh quý rồi. Đọc kỹ từng chi tiết, cả lớp sẽ trả lại sắc màu cho tranh làng Hồ!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Làng tranh có hai dãy gian hàng. Cả lớp chọn dãy nào trước?","nv":"Tuấn Kiệt"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"canh-kho","dong":[{"loi":"Thẻ câu trên suối ghi các loại tranh theo trình tự bài văn. Vớt đúng thẻ đầu tiên nhé!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"canh-kho","danChuyen":"Dòng suối câu chảy dọc làng tranh, in bóng những bức tranh phơi nắng xuống mặt nước. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"27","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Dòng suối câu — theo dấu sắc màu"},{"canh":[{"anh":"kho-sang","dong":[{"loi":"Trong hòm là những dòng kể về nghề làm tranh của người làng Hồ. Đọc kỹ là hiểu vì sao tranh quý!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"kho-sang","danChuyen":"Bên gian hàng đầu tiên, Hòm thư bí mật nằm im lìm, nắp hòm khắc hình một bản khắc gỗ nhỏ. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"27","mucDo":[1],"soCau":1}}],"nhan":"Mở Hòm thư bí mật — đọc chuyện nghề tranh"}]},{"anh":"canh-chu","bienCo":{"dong":[{"loi":"Ơ, sương che mất một nửa đáp án rồi, mình đọc không rõ nữa!","nv":"Thảo Nguyên"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"27","mucDo":[1],"soCau":1}},"danChuyen":"Giữa làng tranh, Cây quả chữ che mất phần tả bức tranh tiêu biểu nhất. Muốn tranh rõ phải nắm đúng chi tiết tác giả đã chọn để tả. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"27","mucDo":[2],"soCau":1}},{"anh":"cau-suong","danChuyen":"Muốn rời làng tranh phải qua Cầu vần thơ, nơi thử thách về từ ngữ và ý nghĩa của bài văn đang chờ. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"27","mucDo":[1,2],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Tranh làng Hồ rực rỡ trở lại rồi! Mộc mạc mà tinh tế — tự hào nghệ thuật dân tộc mình quá!","nv":"Thảo Nguyên"},{"loi":"Cô tặng biệt đội Bản Khắc Gỗ Nhỏ. Nghe kìa... phía đình làng có tiếng hát quan họ ngọt ngào đang ngân xa.","nv":"Cô Ong Chăm Chữ"},{"loi":"Quan họ — điệu hát giao duyên của vùng Kinh Bắc!","nv":"Minh Anh"},{"loi":"Tập sau mình ra đình làng nghe hát nhé cả lớp!","nv":"Tuấn Kiệt"}],"loai":"thoai"}],"id":"t3","ten":"Tập 3 — Tranh làng Hồ","tomTatTapTruoc":"Tập trước: Biệt đội khôi phục bài văn Trí tưởng tượng phong phú, hiểu vai trò của tưởng tượng trong sáng tạo, rồi nhận Đôi Cánh Tưởng Tượng. Cuối tập, những bức tranh dân gian rực rỡ hiện ra trong làng nghề phía xa...","tuan":"14","vatPham":"Bản Khắc Gỗ Nhỏ"},{"bai":"28","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao ra đình làng, nơi bài văn Tập hát quan họ kể về một buổi tập hát dân ca quan họ của các bạn nhỏ vùng Kinh Bắc.","nv":"Người kể"},{"loi":"Bài văn tả buổi tập hát quan họ với những làn điệu ngọt ngào và tình cảm gắn bó của người học hát với nghệ thuật truyền thống. Các cháu để ý trình tự buổi tập và những chi tiết về làn điệu, trang phục quan họ.","nv":"Cô Ong Chăm Chữ"},{"loi":"Nắm trình tự buổi tập là kể lại được cả buổi học hát ạ.","nv":"Minh Anh"},{"loi":"Giọng văn tha thiết — đọc mà nghe như tiếng hát đang ngân ngay bên tai.","nv":"Thảo Nguyên"},{"loi":"Sương đã làm lạc mất mấy làn điệu hay rồi. Đọc kỹ từng chi tiết, cả lớp sẽ nối lại được buổi tập hát!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Sân đình có hai lối vào chỗ tập hát. Cả lớp chọn lối nào trước?","nv":"Minh Anh"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"cau-suong","dong":[{"loi":"Đứng trên cầu nghe rõ từng làn điệu ngọt ngào. Câu văn hay là nhận ra ngay!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Cầu vần thơ bắc qua con suối nhỏ dẫn vào sân đình, ván cầu khắc những nốt nhạc dân ca. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"28","mucDo":[1],"soCau":1}}],"nhan":"Qua Cầu vần thơ — nghe làn điệu quan họ"},{"canh":[{"anh":"canh-kho","dong":[{"loi":"Thẻ câu trên suối ghi các phần của buổi tập theo trình tự bài văn. Vớt đúng thẻ là nối được buổi tập!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"canh-kho","danChuyen":"Dòng suối câu chảy êm qua sân đình, mang theo những thẻ câu còn mờ chữ. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"28","mucDo":[1],"soCau":1}}],"nhan":"Xuôi Dòng suối câu — theo trình tự buổi tập"}]},{"anh":"kho-sang","bienCo":{"dong":[{"loi":"Sương kéo đến dày quá, mọi thứ nhòe đi như nhìn qua kính mờ!","nv":"Đức Trí"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"28","mucDo":[1],"soCau":1}},"danChuyen":"Trong sân đình là Hòm thư bí mật, cất những dòng cảm nhận về tình yêu dân ca của các bạn nhỏ. Muốn mở hòm phải hiểu điều tác giả gửi gắm. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"28","mucDo":[1],"soCau":1}},{"anh":"canh-chu","danChuyen":"Trước khi rời sân đình, Cây quả chữ bên gốc đa còn một thử thách về từ ngữ và ý nghĩa của bài văn. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"28","mucDo":[1],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Buổi tập hát quan họ hiện ra trọn vẹn rồi! Làn điệu quê hương ngọt ngào sẽ còn ngân mãi!","nv":"Minh Anh"},{"loi":"Cô tặng biệt đội Chiếc Nón Quai Thao Nhỏ. Nhưng nhìn kìa...","nv":"Cô Ong Chăm Chữ"},{"loi":"Khà... khà... Bốn miền nghệ thuật thì đã sao? Cổng Sắc Màu vẫn nằm trong tay ta...","nv":"Sương Mù"},{"loi":"Cổng Sắc Màu hiện ra giữa sân đình, và Sương Mù đang giữ cổng! Cả lớp ơi, tập đặc biệt — mình cùng phá cổng nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t4","ten":"Tập 4 — Tập hát quan họ","tomTatTapTruoc":"Tập trước: Biệt đội trả lại sắc màu cho Tranh làng Hồ, học cách tả nghệ thuật dân gian, rồi nhận Bản Khắc Gỗ Nhỏ. Cuối tập, tiếng hát quan họ ngọt ngào ngân xa từ phía đình làng...","tuan":"14","vatPham":"Chiếc Nón Quai Thao Nhỏ"},{"bai":"25+26+27+28","canh":[{"anh":"canh-trum","dong":[{"loi":"Ta là Sương Mù Quên Lãng. Khiên sương của ta chỉ vỡ khi gặp câu trả lời đúng. Các ngươi dám thử không?","nv":"Sương Mù"},{"loi":"Biệt đội Ánh Sao sẵn sàng! Hình ảnh đẹp, ví dụ sáng tạo, chi tiết dân gian, trình tự — chúng mình đều nắm chắc!","nv":"Minh Anh"},{"loi":"Luật phá cổng: trên cổng có bốn ô chiêu thức phát sáng. Chọn chiêu thức là đáp án đúng, khiên sương nứt một phần. Bình tĩnh đọc kỹ, các cháu nhé.","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-trum","danChuyen":"Sương Mù thổi một làn khói che mất đêm trăng trên sông Đà. Cả lớp chọn chiêu thức đúng về hình ảnh và cảm xúc trong bài Tiếng đàn ba-la-lai-ca trên sông Đà nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"25","mucDo":[2,3],"soCau":1}},{"anh":"canh-trum","danChuyen":"Khiên sương rung lên! Sương Mù tung đòn Trí tưởng tượng phong phú với những ví dụ về sáng tạo. Cả lớp chọn chiêu thức đúng để phá tiếp nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"26","mucDo":[1],"soCau":1}},{"anh":"canh-trum","danChuyen":"Sương Mù làm phai màu những bức tranh làng Hồ trong làn khói. Cả lớp chọn chiêu thức đúng về nghệ thuật tranh dân gian nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"27","mucDo":[2],"soCau":1}},{"anh":"canh-trum","danChuyen":"Đòn cuối cùng! Sương Mù dồn hết sức vào buổi Tập hát quan họ. Cả lớp chọn chiêu thức đúng để phá tan khiên sương nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"28","mucDo":[1],"soCau":1}},{"anh":"cua-mo","dong":[{"loi":"Thôi được... Cổng này là của các ngươi. Nhưng phía sau cổng là cả một sân khấu muôn màu, sương của ta còn dày lắm...","nv":"Sương Mù"},{"loi":"Cổng Sắc Màu đã mở! Biệt đội nhận Chìa Cổng Sắc Màu. Nghệ thuật muôn màu — các cháu đã giữ trọn được rồi.","nv":"Cô Ong Chăm Chữ"},{"loi":"Phía sau cổng có tiếng nhạc phim hoạt hình và ánh đèn sân khấu rực rỡ...","nv":"Đức Trí"},{"loi":"Đó là sân khấu muôn màu đang chờ! Hẹn gặp cả lớp ở mùa tiếp theo nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"trum","laTapTrum":true,"ten":"Tập đặc biệt — Cổng Sắc Màu","tomTatTapTruoc":"Biệt đội đã khôi phục bốn miền nghệ thuật đầu tiên: tiếng đàn trên sông Đà, trí tưởng tượng phong phú, tranh làng Hồ và buổi tập hát quan họ. Giờ đây, Sương Mù Quên Lãng đang giữ Cổng Sắc Màu bằng một khiên sương dày...","tuan":"14","vatPham":"Chìa Cổng Sắc Màu"}],"tenMua":"Mùa 7 — Sắc Màu Nghệ Thuật","tomTatMua":"Chủ điểm Nghệ thuật muôn màu đưa Biệt đội Ánh Sao đến đêm trăng nghe đàn ba-la-lai-ca trên sông Đà, bay cùng trí tưởng tượng phong phú, về làng Hồ ngắm tranh dân gian và ra sân đình nghe hát quan họ. Sương Mù Quên Lãng phủ mờ từng miền nghệ thuật, và biệt đội phải khôi phục tất cả để mở Cổng Sắc Màu."},{"anhBia":"san-khau-muon-mau","anhCanTao":[{"khoa":"san-khau-muon-mau","moTa":"Một sân khấu ngoài trời rực rỡ bên mặt nước trong Khu Vườn Ngôn Từ lúc hoàng hôn: màn hình chiếu phim hoạt hình hình vỏ ốc lớn, vũ công ba lê nhỏ xoay mình trên đài sen, mái chùa cong cổ kính phía sau và chú rối nước Tễu cười tươi nhô lên mặt nước phía trước; Cô Ong Chăm Chữ đeo kính bay giữa ánh đèn sân khấu, Biệt đội Ánh Sao áo trắng khăn quàng đỏ ngồi ở hàng ghế đầu; một góc sân khấu bị sương xám phủ mờ. Phong cách 3D Pixar, không chữ."}],"cacBai":["29","30","31","32"],"cacChuDe":["4"],"id":"tv5-c8","lop":5,"mon":"Tiếng Việt","nhanVat":{"Cô Ong Chăm Chữ":"Cô Ong Chăm Chữ — ong thợ chăm chỉ của Khu Vườn Ngôn Từ, bay lượn đọc chính tả vui; là người đọc lời giải thích sau mỗi thử thách trong thế giới Tiếng Việt.","Minh Anh":"Đội trưởng Biệt đội Ánh Sao — quyết đoán, luôn đi đầu.","Sương Mù":"Sương Mù Quên Lãng — thế lực xám lạnh chuyên xóa chữ và kiến thức trong các cuốn sách.","Thảo Nguyên":"Bạn ngôn ngữ — hoạt bát, giỏi chữ nghĩa và tiếng Việt.","Thủ thư Số":"Người giữ sách của Thư viện Ánh Sao — hiền từ, hiểu biết, luôn đưa ra lời giải thích sau mỗi thử thách.","Tuấn Kiệt":"Bạn kỹ thuật — mê máy móc, thao tác nhanh và chính xác.","Đức Trí":"Bạn logic — điềm tĩnh, hay suy luận trước khi hành động."},"tap":[{"bai":"29","canh":[{"anh":"canh-dau","dong":[{"loi":"Qua Cổng Sắc Màu, Biệt đội Ánh Sao bước vào rạp chiếu của khu vườn, nơi bài văn về bộ phim hoạt hình Chú ốc sên bay kể câu chuyện cảm động về một chú ốc sên bé nhỏ có ước mơ lớn.","nv":"Người kể"},{"loi":"Bài văn giới thiệu bộ phim hoạt hình với nhân vật chú ốc sên dám mơ ước và kiên trì theo đuổi ước mơ. Các cháu để ý trình tự câu chuyện trong phim và bài học mà bộ phim gửi đến người xem.","nv":"Cô Ong Chăm Chữ"},{"loi":"Ốc sên chậm chạp mà dám mơ bay — bài học về nghị lực thật cảm động ạ.","nv":"Thảo Nguyên"},{"loi":"Nắm trình tự phim là kể lại được hành trình của chú ốc sên từ đầu đến cuối.","nv":"Đức Trí"},{"loi":"Sương đã làm mờ mất mấy cảnh phim hay nhất rồi. Đọc kỹ từng chi tiết, cả lớp sẽ chiếu lại được bộ phim!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Rạp chiếu có hai lối vào phòng chiếu. Cả lớp chọn lối nào trước nhé!","nv":"Đức Trí"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"canh-chu","dong":[{"loi":"Quả chữ trên cây này ghi các chi tiết của bộ phim. Hái đúng quả là cảnh phim rõ thêm một phần!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"canh-chu","danChuyen":"Ngay lối vào rạp, Cây quả chữ mọc bên quầy vé, cành lá che một phần áp phích phim chưa rõ chữ. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"29","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cây quả chữ — hái quả chi tiết bộ phim"},{"canh":[{"anh":"cau-suong","dong":[{"loi":"Câu chuyện phim cũng có nhịp như nhạc. Đứng trên cầu, nghe kỹ từng câu văn là nhận ra ngay!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Một chiếc cầu nhỏ bắc qua con suối trong khuôn viên rạp chiếu. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"29","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cầu vần thơ — theo nhịp câu chuyện phim"}]},{"anh":"canh-kho","bienCo":{"dong":[{"loi":"Ối, sương tràn xuống bất ngờ, chữ trên các thẻ mờ đi rồi!","nv":"Minh Anh"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"29","mucDo":[1],"soCau":1}},"danChuyen":"Giữa rạp chiếu, Dòng suối câu chảy quanh hàng ghế đầu tiên. Muốn hiểu hết bài học của bộ phim phải nắm được điều tác giả gửi gắm qua hành trình của chú ốc sên. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"29","mucDo":[1],"soCau":1}},{"anh":"kho-sang","danChuyen":"Cuối rạp là Hòm thư bí mật, nơi cất những cảm nhận của các bạn nhỏ sau khi xem phim. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"29","mucDo":[1],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Bộ phim hiện ra trọn vẹn rồi! Bé nhỏ mà dám ước mơ và kiên trì — ai cũng có thể bay theo cách của mình!","nv":"Thảo Nguyên"},{"loi":"Cô tặng biệt đội Vé Xem Phim Đầu Tiên. Nghe kìa... phía nhà hát có tiếng nhạc du dương và những bước múa uyển chuyển.","nv":"Cô Ong Chăm Chữ"},{"loi":"Múa ba lê — nghệ thuật của những bước chân thiên nga!","nv":"Tuấn Kiệt"},{"loi":"Tập sau, biệt đội mình vào nhà hát nhé cả lớp!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t1","ten":"Tập 1 — Chú ốc sên bay","tomTatTapTruoc":"Mùa trước: Biệt đội mở Cổng Sắc Màu, giữ trọn nghệ thuật muôn màu và nhận Chìa Cổng Sắc Màu. Phía sau cổng, ánh đèn rạp chiếu và tiếng nhạc phim hoạt hình vui nhộn mở ra một sân khấu mới...","tuan":"15","vatPham":"Vé Xem Phim Đầu Tiên"},{"bai":"30","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao bước vào nhà hát của khu vườn, nơi bài văn Nghệ thuật múa ba lê giới thiệu một loại hình nghệ thuật sân khấu đẹp và đầy khổ luyện.","nv":"Người kể"},{"loi":"Bài văn giới thiệu nghệ thuật múa ba lê: nguồn gốc, trang phục, những động tác uyển chuyển và sự khổ luyện thầm lặng của diễn viên. Các cháu để ý cách tác giả sắp xếp thông tin để giới thiệu một loại hình nghệ thuật.","nv":"Cô Ong Chăm Chữ"},{"loi":"Giới thiệu theo từng mặt rõ ràng — nguồn gốc, trang phục, động tác — là người đọc hình dung được cả nghệ thuật ạ.","nv":"Đức Trí"},{"loi":"Đẹp như thiên nga vậy mà đằng sau là bao ngày tập luyện đến rướm máu chân.","nv":"Thảo Nguyên"},{"loi":"Sương đã làm mờ mất mấy đoạn giới thiệu quan trọng rồi. Đọc kỹ từng ý, cả lớp sẽ khôi phục được bài văn!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Nhà hát có hai cánh sân khấu. Cả lớp chọn cánh nào trước?","nv":"Minh Anh"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"cau-suong","dong":[{"loi":"Đứng trên cầu nhìn xuống là thấy sàn tập múa sáng đèn. Theo mạch giới thiệu từ đầu nhé!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Cầu vần thơ bắc qua con suối nhỏ trong nhà hát, từ trên cầu nhìn xuống thấy những đôi giày múa xếp ngay ngắn. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"30","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Cầu vần thơ — theo nhịp điệu ba lê"},{"canh":[{"anh":"canh-chu","dong":[{"loi":"Quả chữ trên cây này ghi các thông tin về nghệ thuật ba lê. Hái đúng quả là hiểu nghệ thuật thêm một phần!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"canh-chu","danChuyen":"Cây quả chữ mọc bên cánh gà sân khấu, bóng cây che một phần đoạn văn đầu tiên chưa rõ chữ. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"30","mucDo":[1],"soCau":1}}],"nhan":"Đến Cây quả chữ — hái quả thông tin nghệ thuật"}]},{"anh":"kho-sang","bienCo":{"dong":[{"loi":"Sương làm đường trơn quá, mình suýt trượt chân rồi!","nv":"Tuấn Kiệt"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"30","mucDo":[1],"soCau":1}},"danChuyen":"Sau sân khấu là Hòm thư bí mật, cất những dòng về những ngày khổ luyện của diễn viên ba lê. Muốn mở hòm phải hiểu điều tác giả muốn nói. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"30","mucDo":[2],"soCau":1}},{"anh":"canh-kho","danChuyen":"Bên cửa sổ nhà hát, Dòng suối câu chảy qua bãi đất nơi những chi tiết hay nhất của bài văn đang chờ được vớt lên. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"30","mucDo":[2,3],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Bài văn hiện ra trọn vẹn rồi! Ba lê đẹp như thơ — và cũng là kết quả của khổ luyện bền bỉ!","nv":"Đức Trí"},{"loi":"Cô tặng biệt đội Đôi Giày Múa Nhỏ. Nhưng nhìn kìa... phía cuối vườn có một ngôi chùa cổ với kiến trúc rất lạ đang bị sương phủ.","nv":"Cô Ong Chăm Chữ"},{"loi":"Một ngôi chùa độc đáo — chắc hẳn có nhiều điều kỳ thú!","nv":"Thảo Nguyên"},{"loi":"Tập sau mình đến thăm ngôi chùa ấy nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t2","ten":"Tập 2 — Nghệ thuật múa ba lê","tomTatTapTruoc":"Tập trước: Biệt đội chiếu lại bộ phim Chú ốc sên bay, hiểu bài học về ước mơ và nghị lực, rồi nhận Vé Xem Phim Đầu Tiên. Cuối tập, tiếng nhạc du dương vọng lại từ nhà hát phía trước...","tuan":"15","vatPham":"Đôi Giày Múa Nhỏ"},{"bai":"31","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao đến thăm một ngôi chùa cổ, nơi bài văn Một ngôi chùa độc đáo giới thiệu kiến trúc có một không hai của ngôi chùa quê hương.","nv":"Người kể"},{"loi":"Bài văn tả ngôi chùa với kiến trúc độc đáo bằng những chi tiết quan sát tinh tế. Các cháu để ý trình tự miêu tả — từ xa đến gần, từ ngoài vào trong — và những chi tiết làm nên sự độc đáo của ngôi chùa.","nv":"Cô Ong Chăm Chữ"},{"loi":"Chi tiết độc đáo nhất là chi tiết không ngôi chùa nào khác có ạ.","nv":"Thảo Nguyên"},{"loi":"Bài còn gợi niềm tự hào về di sản văn hóa của quê hương mình.","nv":"Đức Trí"},{"loi":"Sương đã làm mờ mất mấy chi tiết kiến trúc quý rồi. Đọc kỹ từng phần, cả lớp sẽ khôi phục được vẻ đẹp của ngôi chùa!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Sân chùa có hai lối vào tam quan. Cả lớp chọn lối nào trước?","nv":"Tuấn Kiệt"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"canh-kho","dong":[{"loi":"Thẻ câu trên suối ghi các phần tả ngôi chùa theo trình tự. Vớt đúng thẻ đầu tiên nhé!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"canh-kho","danChuyen":"Dòng suối câu chảy dọc sân chùa, in bóng mái chùa cong cong xuống mặt nước. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"31","mucDo":[1],"soCau":1}}],"nhan":"Đi lối Dòng suối câu — theo trình tự tả chùa"},{"canh":[{"anh":"kho-sang","dong":[{"loi":"Trong hòm là những dòng kể về lịch sử và nét độc đáo của ngôi chùa. Đọc kỹ là hình dung được cả ngôi chùa!","nv":"Thảo Nguyên"}],"loai":"thoai"},{"anh":"kho-sang","danChuyen":"Bên tam quan, Hòm thư bí mật nằm im lìm, nắp hòm khắc hình một chiếc chuông nhỏ. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"31","mucDo":[1],"soCau":1}}],"nhan":"Mở Hòm thư bí mật — đọc chuyện về ngôi chùa"}]},{"anh":"canh-chu","bienCo":{"dong":[{"loi":"Ơ, sương che mất một nửa đáp án rồi, mình đọc không rõ nữa!","nv":"Thảo Nguyên"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"31","mucDo":[1],"soCau":1}},"danChuyen":"Giữa sân chùa, Cây quả chữ che mất phần tả chi tiết độc đáo nhất của kiến trúc. Muốn chùa rõ phải nắm đúng điều làm nên sự có một không hai của ngôi chùa. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"31","mucDo":[2],"soCau":1}},{"anh":"cau-suong","danChuyen":"Muốn rời sân chùa phải qua Cầu vần thơ, nơi thử thách về từ ngữ và ý nghĩa của bài văn đang chờ. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"31","mucDo":[1,2],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Ngôi chùa hiện ra trọn vẹn rồi — độc đáo và cổ kính, niềm tự hào của quê hương!","nv":"Thảo Nguyên"},{"loi":"Cô tặng biệt đội Chiếc Chuông Chùa Nhỏ. Nghe kìa... phía sân khấu ngoài trời có tiếng trống chầu và tiếng cười của khán giả xem rối nước.","nv":"Cô Ong Chăm Chữ"},{"loi":"Chú Tễu của sân khấu rối nước — nhân vật vui nhộn nhất làng quê!","nv":"Minh Anh"},{"loi":"Tập sau mình ra sân khấu rối nước nhé cả lớp!","nv":"Tuấn Kiệt"}],"loai":"thoai"}],"id":"t3","ten":"Tập 3 — Một ngôi chùa độc đáo","tomTatTapTruoc":"Tập trước: Biệt đội khôi phục bài văn Nghệ thuật múa ba lê, học cách giới thiệu một loại hình nghệ thuật, rồi nhận Đôi Giày Múa Nhỏ. Cuối tập, một ngôi chùa cổ độc đáo hiện ra ở cuối vườn...","tuan":"16","vatPham":"Chiếc Chuông Chùa Nhỏ"},{"bai":"32","canh":[{"anh":"canh-dau","dong":[{"loi":"Biệt đội Ánh Sao ra sân khấu rối nước ngoài trời, nơi bài văn Sự tích chú Tễu kể về nguồn gốc của nhân vật rối nước vui nhộn nhất làng quê Việt Nam.","nv":"Người kể"},{"loi":"Bài văn kể sự tích chú Tễu — nhân vật mở đầu mọi buổi diễn rối nước, với nụ cười hóm hỉnh và tấm lòng nhân hậu. Các cháu để ý trình tự sự tích và ý nghĩa của hình tượng chú Tễu trong văn hóa dân gian.","nv":"Cô Ong Chăm Chữ"},{"loi":"Nắm trình tự sự tích là kể lại được nguồn gốc của chú Tễu ạ.","nv":"Minh Anh"},{"loi":"Chú Tễu cười vui vậy mà chứa cả triết lý sống của người nông dân xưa.","nv":"Thảo Nguyên"},{"loi":"Sương đã làm lạc mất mấy đoạn sự tích rồi. Đọc kỹ từng phần, cả lớp sẽ nối lại được câu chuyện của chú Tễu!","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-chu","dong":[{"loi":"Sân khấu nước có hai phía khán đài. Cả lớp chọn phía nào trước?","nv":"Minh Anh"}],"loai":"re-nhanh","luaChon":[{"canh":[{"anh":"cau-suong","dong":[{"loi":"Đứng trên cầu nghe rõ tiếng trống chầu rộn ràng. Theo trình tự sự tích từ đầu nhé!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"cau-suong","danChuyen":"Cầu vần thơ bắc qua con suối nhỏ dẫn ra sân khấu nước, ván cầu khắc những con sóng tròn. Cầu vần thơ bắc qua suối chỉ còn thiếu một tấm ván. Các tấm ván ghi những đáp án khác nhau đang chờ bên bờ. Cả lớp chọn tấm ván đúng để lắp vào cầu nhé!","loai":"thu-thach","rutCau":{"bai":"32","mucDo":[1],"soCau":1}}],"nhan":"Qua Cầu vần thơ — nghe trống chầu rối nước"},{"canh":[{"anh":"canh-kho","dong":[{"loi":"Thẻ câu trên suối ghi sự tích chú Tễu theo trình tự bài văn. Vớt đúng thẻ là nối được câu chuyện!","nv":"Đức Trí"}],"loai":"thoai"},{"anh":"canh-kho","danChuyen":"Dòng suối câu chảy êm ra mặt sân khấu nước, mang theo những thẻ câu còn mờ chữ. Những thẻ câu trôi lững lờ trên Dòng suối câu, mỗi thẻ mang một đáp án. Cả lớp vớt đúng thẻ câu có đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"32","mucDo":[1],"soCau":1}}],"nhan":"Xuôi Dòng suối câu — theo dòng sự tích"}]},{"anh":"kho-sang","bienCo":{"dong":[{"loi":"Sương kéo đến dày quá, mọi thứ nhòe đi như nhìn qua kính mờ!","nv":"Đức Trí"},{"loi":"Đừng lo! Cô có câu cứu viện của Cô Ong Chăm Chữ đây. Trả lời đúng, sương sẽ tan và đường đi rõ lại ngay.","nv":"Cô Ong Chăm Chữ"}],"rutCauCuuVien":{"bai":"32","mucDo":[1],"soCau":1}},"danChuyen":"Bên sân khấu nước là Hòm thư bí mật, cất những dòng cảm nhận về nghệ thuật rối nước truyền thống. Muốn mở hòm phải hiểu điều tác giả gửi gắm. Hòm thư bí mật bật mở, bên trong là những lá thư viết các đáp án khác nhau. Cả lớp chọn lá thư viết đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"32","mucDo":[2],"soCau":1}},{"anh":"canh-chu","danChuyen":"Trước khi rời sân khấu, Cây quả chữ bên gốc đình còn một thử thách về từ ngữ và ý nghĩa của bài văn. Cây quả chữ rung rinh, những quả chín mang các đáp án khác nhau. Cả lớp hái quả chữ mang đáp án đúng nhé!","loai":"thu-thach","rutCau":{"bai":"32","mucDo":[2,3],"soCau":1}},{"anh":"sach-sang","dong":[{"loi":"Sự tích chú Tễu nối lại trọn vẹn rồi! Học kỳ 1 khép lại bằng nụ cười hóm hỉnh của làng quê Việt!","nv":"Minh Anh"},{"loi":"Cô tặng biệt đội Con Rối Chú Tễu Nhỏ. Nhưng nhìn kìa...","nv":"Cô Ong Chăm Chữ"},{"loi":"Khà... khà... Hết học kỳ 1 thì đã sao? Cổng Sân Khấu vẫn nằm trong tay ta, và học kỳ 2 sương của ta sẽ còn dày hơn...","nv":"Sương Mù"},{"loi":"Cổng Sân Khấu hiện ra giữa mặt nước, và Sương Mù đang giữ cổng! Cả lớp ơi, tập đặc biệt cuối học kỳ 1 — mình cùng phá cổng nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"t4","ten":"Tập 4 — Sự tích chú Tễu","tomTatTapTruoc":"Tập trước: Biệt đội khôi phục vẻ đẹp của ngôi chùa độc đáo, học cách tả theo trình tự và chọn chi tiết tiêu biểu, rồi nhận Chiếc Chuông Chùa Nhỏ. Cuối tập, tiếng trống chầu vọng lại từ sân khấu rối nước...","tuan":"16","vatPham":"Con Rối Chú Tễu Nhỏ"},{"bai":"29+30+31+32","canh":[{"anh":"canh-trum","dong":[{"loi":"Ta là Sương Mù Quên Lãng. Khiên sương của ta chỉ vỡ khi gặp câu trả lời đúng. Các ngươi dám thử không?","nv":"Sương Mù"},{"loi":"Biệt đội Ánh Sao sẵn sàng! Trình tự, ý chính, chi tiết tiêu biểu — chúng mình đều nắm chắc!","nv":"Minh Anh"},{"loi":"Luật phá cổng: trên cổng có bốn ô chiêu thức phát sáng. Chọn chiêu thức là đáp án đúng, khiên sương nứt một phần. Bình tĩnh đọc kỹ, các cháu nhé.","nv":"Cô Ong Chăm Chữ"}],"loai":"thoai"},{"anh":"canh-trum","danChuyen":"Sương Mù thổi một làn khói che mất những cảnh phim hay nhất. Cả lớp chọn chiêu thức đúng về hành trình và bài học của Chú ốc sên bay nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"29","mucDo":[1],"soCau":1}},{"anh":"canh-trum","danChuyen":"Khiên sương rung lên! Sương Mù tung đòn Nghệ thuật múa ba lê với những thông tin về loại hình nghệ thuật này. Cả lớp chọn chiêu thức đúng để phá tiếp nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"30","mucDo":[2],"soCau":1}},{"anh":"canh-trum","danChuyen":"Sương Mù làm mờ những chi tiết độc đáo của ngôi chùa trong làn khói. Cả lớp chọn chiêu thức đúng về kiến trúc ngôi chùa nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"31","mucDo":[2],"soCau":1}},{"anh":"canh-trum","danChuyen":"Đòn cuối cùng của học kỳ 1! Sương Mù dồn hết sức vào Sự tích chú Tễu. Cả lớp chọn chiêu thức đúng để phá tan khiên sương nhé!","laDonTrum":true,"loai":"thu-thach","rutCau":{"bai":"32","mucDo":[2],"soCau":1}},{"anh":"cua-mo","dong":[{"loi":"Thôi được... Cổng này là của các ngươi. Nhưng học kỳ 2, ta sẽ trở lại mạnh hơn ở những miền đất mới...","nv":"Sương Mù"},{"loi":"Cổng Sân Khấu đã mở! Biệt đội nhận Chìa Cổng Sân Khấu. Học kỳ 1 của khu vườn lớp 5 đã khép lại thật đẹp.","nv":"Cô Ong Chăm Chữ"},{"loi":"Phía sau cổng có tiếng hát ru và hương cốm mùa thu thoang thoảng từ học kỳ 2...","nv":"Đức Trí"},{"loi":"Hẹn gặp cả lớp ở học kỳ 2 — nơi những miền đất mới của Khu Vườn Ngôn Từ đang chờ nhé!","nv":"Minh Anh"}],"loai":"thoai"}],"id":"trum","laTapTrum":true,"ten":"Tập đặc biệt — Cổng Sân Khấu","tomTatTapTruoc":"Biệt đội đã khôi phục bốn miền nghệ thuật cuối của học kỳ 1: bộ phim Chú ốc sên bay, nghệ thuật múa ba lê, ngôi chùa độc đáo và sự tích chú Tễu. Giờ đây, Sương Mù Quên Lãng đang giữ Cổng Sân Khấu bằng một khiên sương dày...","tuan":"16","vatPham":"Chìa Cổng Sân Khấu"}],"tenMua":"Mùa 8 — Sân Khấu Muôn Màu","tomTatMua":"Sân khấu muôn màu khép lại học kỳ 1 của khu vườn lớp 5: bộ phim cảm động về chú ốc sên dám ước mơ, nghệ thuật múa ba lê uyển chuyển, ngôi chùa cổ độc đáo và chú Tễu hóm hỉnh của sân khấu rối nước. Sương Mù Quên Lãng phủ mờ từng miền nghệ thuật, và biệt đội phải khôi phục tất cả để mở Cổng Sân Khấu, khép lại học kỳ 1 trọn vẹn."}],"cauHoi":{"bai":{"1":{"cauHoi":[{"cauHoi":"Trong bài “Thanh âm của gió”, các bạn nhỏ thường làm gì bên suối?","dang":"TN","dapAn":2,"giaiThich":"Chúng tôi đi chăn trâu, ngày nào cũng qua suối; chiều về tìm những viên đá đẹp.","id":"V5-B01-01","mucDo":1,"phuongAn":["Đánh cá suốt ngày","Chỉ ngồi học bài bên suối","Đi chăn trâu, tìm những viên đá đẹp; trâu ăn cỏ men theo bờ suối rồi lên đồi, lên núi","Xây nhà trên đồi"]},{"cauHoi":"Em Bống đã phát hiện ra trò chơi gì?","dang":"TN","dapAn":0,"giaiThich":"Bống: bịt tai lại nghe tiếng gió lạ lắm; cả hội lần lượt bịt tai, mỗi đứa nghe một thanh âm.","id":"V5-B01-02","mucDo":1,"phuongAn":["Bịt tai rồi mở ra, lặp lại, để nghe “tiếng gió” (mỗi bạn nghe một thanh âm khác nhau)","Hát đồng ca","Thi chạy trên đồng cỏ","Ném đá xuống suối"]},{"cauHoi":"Việc bố hưởng ứng trò chơi bịt tai nghe gió cho thấy điều gì?","dang":"TN","dapAn":1,"giaiThich":"Tối đó tôi và Bống kể cho bố mẹ; bố thích và nói nhất định sáng mai sẽ thử.","id":"V5-B01-03","mucDo":2,"phuongAn":["Bố cấm các con chơi ngoài trời","Bố thích trò chơi ấy và muốn hoà vào thế giới trẻ thơ của các con (nhất định sáng mai sẽ thử)","Bố không tin có gió","Bố bắt các con về nhà ngay"]},{"cauHoi":"Danh từ là từ chỉ gì?","dang":"TN","dapAn":3,"giaiThich":"SGK: danh từ là từ chỉ sự vật (người, vật, hiện tượng tự nhiên, thời gian,...).","id":"V5-B01-04","mucDo":1,"phuongAn":["Đặc điểm của sự vật, hoạt động, trạng thái","Hoạt động, trạng thái của sự vật","Mối quan hệ nhân quả","Sự vật (người, vật, hiện tượng tự nhiên, thời gian,...)"]},{"cauHoi":"Trong các từ “suối, gió, chiều, trâu”, những từ nào là danh từ chỉ hiện tượng tự nhiên?","dang":"TN","dapAn":0,"giaiThich":"Suối, gió là danh từ chỉ hiện tượng tự nhiên; chiều chỉ thời gian; trâu chỉ con vật.","id":"V5-B01-05","mucDo":1,"phuongAn":["Suối, gió","Chiều (chỉ thời gian) là hiện tượng tự nhiên","Trâu","Không có danh từ nào"]},{"cauHoi":"Viết một đoạn văn kể chuyện sáng tạo (4 – 5 câu) về một trò chơi ngoài trời của em, có thêm ít nhất một chi tiết do em tưởng tượng.","dang":"TL","giaiThich":"Gợi ý: Nêu hoàn cảnh; kể diễn biến; thêm một chi tiết sáng tạo; kết lại cảm xúc.","id":"V5-B01-06","mucDo":3},{"cauHoi":"Khi bịt tai rồi mở ra, mỗi bạn nhỏ lại nghe “tiếng gió” một khác. Điều đó cho thấy điều gì?","dang":"TN","dapAn":2,"giaiThich":"Vẫn là tiếng gió ấy thôi, nhưng mỗi bạn nghe ra một thanh âm khác nhau. Trò chơi cho thấy: khi biết dừng lại và lắng nghe, ta sẽ nhận ra thiên nhiên quanh mình có biết bao âm thanh phong phú, và mỗi người cảm nhận chúng theo cách riêng.","id":"TV5-B01-BS01","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Gió mỗi lúc thổi một khác nên nghe không giống nhau","Tai của mỗi bạn có kích thước khác nhau","Cùng một tiếng gió nhưng mỗi người cảm nhận một cách riêng; thế giới âm thanh quanh ta rất phong phú nếu ta biết lắng nghe","Các bạn nghe chưa rõ vì bịt tai chưa kín"]}],"chuDe":"1","ten":"Thanh âm của gió","tenChuDe":"Chủ điểm 1. Thế giới tuổi thơ","tenGoc":"Bài 1. Thanh âm của gió","tuan":"1","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Đại từ và kết từ: đặc điểm và chức năng; ôn luyện danh từ, động từ, tính từ.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"10":{"cauHoi":[{"cauHoi":"Vì sao nhân vật “tôi” trong “Kì diệu rừng xanh” có cảm giác đi lạc vào kinh đô của vương quốc những người tí hon?","dang":"TN","dapAn":1,"giaiThich":"Mỗi chiếc nấm là một lâu đài kiến trúc tân kì; tôi như người khổng lồ lạc vào kinh đô của những người tí hon.","id":"V5-B10-01","mucDo":2,"phuongAn":["Vì nhìn thấy biển","Vì thấy một “thành phố nấm” lúp xúp: nấm to bằng ấm tích, sặc sỡ như lâu đài, đền đài, cung điện dưới chân","Vì gặp một thành phố thật sự của người","Vì trời tối không thấy gì"]},{"cauHoi":"Muông thú trong rừng được miêu tả thế nào?","dang":"TN","dapAn":3,"giaiThich":"Vượn bạc má chuyền như tia chớp; chồn sóc vút qua; mang vàng hệt màu lá.","id":"V5-B10-02","mucDo":1,"phuongAn":["Không có con vật nào","Chỉ có chim trong lồng","Chỉ có cá dưới sông","Vượn bạc má ôm con chuyền nhanh như tia chớp; chồn sóc với chùm lông đuôi to đẹp vút qua; ở rừng khộp, mấy con mang vàng hệt màu lá đang ăn cỏ non"]},{"cauHoi":"Vì sao cảnh rừng khộp được gọi là “giang sơn vàng rợi”?","dang":"TN","dapAn":2,"giaiThich":"Sắc vàng động đậy; chân vàng giẫm thảm lá vàng, nắng rực vàng trên lưng nó.","id":"V5-B10-03","mucDo":2,"phuongAn":["Vì có vàng sa khoáng","Vì toàn bộ rừng xanh ngắt, không có màu vàng","Lá úa vàng như mùa thu; chân, nắng, lưng con mang cũng rực vàng; chỉ vài vạt cỏ xanh biếc nổi lên giữa sắc vàng","Vì trời đang mưa tuyết"]},{"cauHoi":"Từ “tân kì” trong bài (theo chú thích SGK) nghĩa là gì?","dang":"TN","dapAn":2,"giaiThich":"Chú thích: Tân kì: mới lạ.","id":"V5-B10-04","mucDo":1,"phuongAn":["Rất buồn","Rất nhỏ","Mới lạ","Rất cũ"]},{"cauHoi":"Hình ảnh “chuyền nhanh như tia chớp” dùng biện pháp tu từ nào?","dang":"TN","dapAn":3,"giaiThich":"So sánh hoạt động của vượn với tia chớp.","id":"V5-B10-05","mucDo":1,"phuongAn":["Điệp từ (lặp lại cùng một từ nhiều lần liên tiếp, không so sánh)","Dấu gạch nối","Câu ghép có kết từ “nhưng”","So sánh"]},{"cauHoi":"Hãy đặt một tên ngắn cho từng đoạn trong bài “Kì diệu rừng xanh” (đoạn thành phố nấm – đoạn muông thú – đoạn rừng khộp) và giải thích vì sao em chọn những tên ấy (4 – 5 câu).","dang":"TL","giaiThich":"Gợi ý: Mỗi tên gói một hình ảnh chính; nêu lí do chọn.","id":"V5-B10-06","mucDo":3}],"chuDe":"2","ten":"Kì diệu rừng xanh","tenChuDe":"Chủ điểm 2. Thiên nhiên kì thú","tenGoc":"Bài 10. Kì diệu rừng xanh","tuan":"5","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nhận biết được văn bản viết theo tưởng tượng và văn bản viết về người thật, việc thật; hiểu từ ngữ, hình ảnh, biện pháp so sánh, nhân hoá trong văn bản.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản."]},"11":{"cauHoi":[{"cauHoi":"Theo bài đọc, hang Sơn Đoòng ở đâu, có niên đại khoảng bao lâu và hình thành như thế nào?","dang":"TN","dapAn":1,"giaiThich":"SGK: Hang Sơn Đoòng (Quảng Trị); niên đại tới 5 triệu năm; đứt gãy Trường Sơn, sông Rào Thương bào mòn.","id":"V5-B11-01","mucDo":1,"phuongAn":["Do người đục bằng tay ở đồng bằng","Ở Quảng Trị; khoảng 5 triệu năm tuổi; từ một vết đứt gãy của dãy Trường Sơn, bị nước sông Rào Thương bào mòn liên tục (từ 2 đến 5 triệu năm)","Do núi lửa phun trào tuần trước trên núi Bà Đen","Ở Thành phố Hồ Chí Minh, mới đào năm ngoái"]},{"cauHoi":"Những chi tiết nào cho thấy Sơn Đoòng rất lớn?","dang":"TN","dapAn":0,"giaiThich":"Chiều dài lên tới 9 ki-lô-mét, thể tích 38,5 triệu mét khối; 68 máy bay Bô-inh 777.","id":"V5-B11-02","mucDo":1,"phuongAn":["Được coi là hang động tự nhiên lớn nhất thế giới: dài tới 9 km, thể tích 38,5 triệu mét khối; có thể chứa 68 máy bay Bô-inh 777 hoặc khu phố nhà cao 40 tầng","Không có số liệu nào","Chỉ dài vài mét","Chỉ chứa được một chiếc xe đạp"]},{"cauHoi":"Hệ sinh thái trong hang có gì đặc biệt?","dang":"TN","dapAn":3,"giaiThich":"Rừng nguyên sinh; một số loài không có mắt và cơ thể trong suốt.","id":"V5-B11-03","mucDo":1,"phuongAn":["Không có sinh vật nào","Chỉ có thú lớn có mắt bình thường","Chỉ có lúa nước","Có khu rừng nguyên sinh, cây thân gỗ khá mỏng manh; nhiều loài cá, nhện, cuốn chiếu, bọ cạp,... không có mắt và cơ thể trong suốt"]},{"cauHoi":"Theo phần thông tin thêm ở SGK, năm 2013 hang Sơn Đoòng được ghi nhận điều gì?","dang":"TN","dapAn":1,"giaiThich":"Năm 2013, được ghi nhận là hang động tự nhiên lớn nhất thế giới.","id":"V5-B11-04","mucDo":1,"phuongAn":["Là toà nhà cao nhất Việt Nam","Là hang động tự nhiên lớn nhất thế giới","Là con sông dài nhất châu Á","Là sân vận động lớn nhất thế giới"]},{"cauHoi":"Từ “khổng lồ” và từ nào sau đây là cặp từ đồng nghĩa?","dang":"TN","dapAn":0,"giaiThich":"Khổng lồ đồng nghĩa với to lớn.","id":"V5-B11-05","mucDo":1,"phuongAn":["To lớn (rất lớn)","Mỏng manh","Bé nhỏ","Im lặng"]},{"cauHoi":"Hãy đóng vai hướng dẫn viên, viết 4 – 5 câu giới thiệu hang Sơn Đoòng với du khách (nêu tỉnh theo SGK, dãy núi / sông, tuổi hang, độ lớn và một nét đặc biệt của hệ sinh thái).","dang":"TL","giaiThich":"Gợi ý: Quảng Trị; dãy Trường Sơn, sông Rào Thương; 5 triệu năm; 9 km / 38,5 triệu m³; rừng nguyên sinh hoặc loài vật không mắt.","id":"V5-B11-06","mucDo":3},{"cauHoi":"Vì sao bài giới thiệu hang Sơn Đoòng lại đưa vào nhiều số liệu cụ thể như “dài tới 9 km”, “thể tích 38,5 triệu mét khối”, “có thể chứa 68 máy bay Bô-inh 777”?","dang":"TN","dapAn":1,"giaiThich":"Trong văn bản thông tin, số liệu và chi tiết so sánh cụ thể giúp người đọc hình dung đúng độ lớn của sự vật: hang dài 9 km, thể tích 38,5 triệu mét khối, chứa được 68 máy bay Bô-inh 777 hoặc một khu phố nhà cao 40 tầng.","id":"TV5-B11-BS01","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Để bài viết dài thêm cho đủ trang sách","Để giúp người đọc hình dung rõ ràng, cụ thể độ lớn kì vĩ của hang","Để quảng cáo cho hãng máy bay Bô-inh","Để thay thế hoàn toàn cho các hình ảnh minh hoạ"]},{"cauHoi":"Nhiều loài sinh vật trong hang Sơn Đoòng (cá, nhện, cuốn chiếu, bọ cạp,...) không có mắt và cơ thể trong suốt. Chi tiết này cho thấy điều gì?","dang":"TN","dapAn":1,"giaiThich":"Hang sâu tối tăm quanh năm, ánh sáng không lọt tới. Sống lâu đời trong bóng tối, các loài vật ấy không cần dùng đến mắt; cơ thể trong suốt cũng là cách thích nghi với môi trường đặc biệt trong hang.","id":"TV5-B11-BS02","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Chúng là những loài sinh vật mới sinh nên chưa mở mắt","Chúng sống lâu đời trong bóng tối của hang nên mắt không cần dùng tới, cơ thể thích nghi với môi trường thiếu ánh sáng","Nước trong hang có chất làm mắt chúng bị mờ đi trong chốc lát","Chúng cố tình nhắm mắt để tránh ánh đèn của du khách"]}],"chuDe":"2","ten":"Hang Sơn Đoòng - những điều kì thú","tenChuDe":"Chủ điểm 2. Thiên nhiên kì thú","tenGoc":"Bài 11. Hang Sơn Đoòng - những điều kì thú","tuan":"6","yeuCauCanDat":["Nhận biết được những chi tiết tiêu biểu và các thông tin chính của văn bản thông tin; xác định đề tài từ nhan đề, đề mục; nhận biết mục đích, đặc điểm, bố cục của văn bản giải thích, giới thiệu sách hoặc phim, quảng cáo, chương trình hoạt động; vai trò của hình ảnh, kí hiệu hoặc số liệu.","Từ đồng nghĩa: đặc điểm và tác dụng."]},"12":{"cauHoi":[{"cauHoi":"Câu văn nào (ý nào) miêu tả bao quát đảo ở vịnh Hạ Long trong bài?","dang":"TN","dapAn":2,"giaiThich":"Diện tích hẹp, mọc lên hàng nghìn đảo nhấp nhô khuất khúc như rồng chầu, phượng múa.","id":"V5-B12-01","mucDo":1,"phuongAn":["Chỉ có một hòn đảo duy nhất","Đảo chỉ xuất hiện vào ban đêm","Trên diện tích hẹp, mọc lên hàng nghìn đảo nhấp nhô khuất khúc như rồng chầu, phượng múa","Không có đảo nào trên vịnh"]},{"cauHoi":"Những hòn đảo được ví với hình ảnh sự sống nào?","dang":"TN","dapAn":2,"giaiThich":"Hòn Gà Chọi, hòn Mái Nhà, hòn Con Cóc, hòn Ông Lã Vọng,...","id":"V5-B12-02","mucDo":1,"phuongAn":["Chỉ ví với máy bay","Không hòn nào có tên","Hòn Gà Chọi (đôi gà xoè cánh chọi nhau), hòn Mái Nhà, hòn Con Cóc (ngồi bờ giếng), hòn Ông Lã Vọng (ông lão ngồi câu cá)","Chỉ ví với xe ô tô"]},{"cauHoi":"Khi ngắm đảo, vì sao tác giả có cảm giác được chiêm ngưỡng một thế giới sống động đã hoá đá?","dang":"TN","dapAn":0,"giaiThich":"Ngắm trăm nghìn đảo đá sừng sững, ta có cảm giác được chiêm ngưỡng một thế giới sống động đã trải qua hàng triệu năm hoá đá.","id":"V5-B12-03","mucDo":2,"phuongAn":["Vì mỗi hòn, mỗi dáng đều thấp thoáng hình ảnh của sự sống, lại sừng sững như đã trải qua hàng triệu năm","Vì tác giả không nhìn thấy đảo","Vì không có hình ảnh nào","Vì đảo mới được đúc bằng bê tông tuần trước"]},{"cauHoi":"Các cặp “khơi – lộng”, “sừng sững – vững chãi” trong bài / chú thích gần với việc hiểu từ đồng nghĩa hoặc trái nghĩa như thế nào?","dang":"TN","dapAn":3,"giaiThich":"Chú thích: Khơi: vùng biển xa bờ. Lộng: vùng biển gần bờ.","id":"V5-B12-04","mucDo":1,"phuongAn":["Khơi là gần bờ, lộng là xa bờ","Không cặp nào có nghĩa","Cả hai cặp đều chỉ đồ ăn","Khơi là vùng biển xa bờ, lộng là vùng biển gần bờ (trái nghĩa theo không gian); sừng sững, vững chãi gần nghĩa “cao, chắc”"]},{"cauHoi":"Chủ đề gần nhất của bài “Những hòn đảo trên vịnh Hạ Long” (Thi Sảnh) là gì?","dang":"TN","dapAn":1,"giaiThich":"Mỗi hòn đảo thấp thoáng hình ảnh sự sống; một thế giới đã hoá đá.","id":"V5-B12-05","mucDo":2,"phuongAn":["Nội quy thư viện","Vẻ đẹp độc đáo, sống động của hàng nghìn đảo đá trên vịnh Hạ Long","Cách nấu canh chua","Lịch sử một trận đánh"]},{"cauHoi":"Viết 4 – 5 câu tả hình dáng một vài hòn đảo ở vịnh Hạ Long dựa vào bài đọc (có thể dùng so sánh như trong bài).","dang":"TL","giaiThich":"Gợi ý: Nêu tên hòn (Gà Chọi, Mái Nhà, Con Cóc, Ông Lã Vọng); dùng 1 hình ảnh so sánh.","id":"V5-B12-06","mucDo":3}],"chuDe":"2","ten":"Những hòn đảo trên vịnh Hạ Long","tenChuDe":"Chủ điểm 2. Thiên nhiên kì thú","tenGoc":"Bài 12. Những hòn đảo trên vịnh Hạ Long","tuan":"6","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Từ đồng nghĩa: đặc điểm và tác dụng.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"13":{"cauHoi":[{"cauHoi":"Trong hai khổ đầu bài “Mầm non” (Võ Quảng), mầm non được miêu tả thế nào?","dang":"TN","dapAn":0,"giaiThich":"Một mầm non nho nhỏ / Còn nằm nép lặng im... Mầm non mắt lim dim / Cố nhìn qua kẽ lá.","id":"V5-B13-01","mucDo":1,"phuongAn":["Một mầm non nho nhỏ nằm nép lặng im dưới vỏ cành bàng; “mắt lim dim” cố nhìn qua kẽ lá","Đã thành cây đại thụ","Không xuất hiện trong thơ","Đang chạy nhảy trên sân"]},{"cauHoi":"Cảnh vật mùa đông hiện ra qua cảm nhận của mầm non như thế nào?","dang":"TN","dapAn":2,"giaiThich":"Thấy mây bay hối hả, thấy lất phất mưa phùn; rào rào trận lá tuôn, rừng cây trông thưa thớt.","id":"V5-B13-02","mucDo":2,"phuongAn":["Biển động, sóng lớn","Nắng chang chang, hoa nở rộ","Mây bay hối hả, mưa phùn lất phất; trận lá tuôn rải vàng mặt đất, rừng thưa chỉ còn cội với cành; thỏ phóng nấp, mọi vật im ắng","Phố xá đông vui"]},{"cauHoi":"Nhờ đâu mầm non nhận ra mùa xuân đến?","dang":"TN","dapAn":1,"giaiThich":"Chợt một tiếng chim kêu: Chíp chiu chiu! Xuân đến.","id":"V5-B13-03","mucDo":2,"phuongAn":["Nhờ tuyết rơi dày hơn","Nhờ một tiếng chim kêu “Chíp chiu chiu! Xuân đến.”; trăm ngọn suối reo, ngàn chim muông hát ca","Nhờ người chặt cây","Không có dấu hiệu nào"]},{"cauHoi":"Hình ảnh mầm non ở khổ cuối có gì đáng nhớ?","dang":"TN","dapAn":3,"giaiThich":"Vội bật chiếc vỏ rơi / Nó đứng dậy giữa trời / Khoác áo màu xanh biếc.","id":"V5-B13-04","mucDo":2,"phuongAn":["Mầm non vẫn nằm im mãi","Mầm non biến thành đá","Mầm non bay lên mây","Mầm non vội bật, chiếc vỏ rơi, đứng dậy giữa trời, khoác áo màu xanh biếc – như một em bé lớn lên đón xuân"]},{"cauHoi":"Từ “mắt” trong “Mầm non mắt lim dim” được dùng theo nghĩa nào là hợp lí hơn?","dang":"TN","dapAn":3,"giaiThich":"Mầm non được nhân hoá: có “mắt lim dim”.","id":"V5-B13-05","mucDo":1,"phuongAn":["Nghĩa là “mắt cáo” trên gỗ thôi","Không có nghĩa","Chỉ nghĩa gốc: cơ quan nhìn của người, không gán cho cây","Nghĩa chuyển (gán “mắt” cho mầm non, như người) – nhân hoá"]},{"cauHoi":"Viết 4 – 5 câu nêu nội dung chính của bài thơ “Mầm non” và điều em tâm đắc nhất về hình ảnh mầm non đón xuân.","dang":"TL","giaiThich":"Gợi ý: Mầm non nép trong đông, nhận ra xuân và bật lên khoác áo xanh; nêu vì sao em thích.","id":"V5-B13-06","mucDo":3}],"chuDe":"2","ten":"Mầm non","tenChuDe":"Chủ điểm 2. Thiên nhiên kì thú","tenGoc":"Bài 13. Mầm non","tuan":"7","yeuCauCanDat":["Nhận biết được văn bản viết theo tưởng tượng và văn bản viết về người thật, việc thật; hiểu từ ngữ, hình ảnh, biện pháp so sánh, nhân hoá trong văn bản.","Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Từ đa nghĩa và nghĩa của từ đa nghĩa trong văn bản.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản."]},"14":{"cauHoi":[{"cauHoi":"Theo bài “Những ngọn núi nóng rẫy”, núi lửa có luôn cùng một hình dạng và cách phun không?","dang":"TN","dapAn":2,"giaiThich":"Có quả hình nón, có quả hình tròn thoai thoải; một số phun lửa, một số chỉ phun khói...","id":"V5-B14-01","mucDo":1,"phuongAn":["Tất cả núi lửa đều giống hệt nhau","Núi lửa chỉ có trên mặt trăng","Không: có quả hình nón, có quả hình tròn thoai thoải; có cái phun lửa, có cái chỉ phun khói, khí hoặc tro; có cái nổ kinh hoàng, có cái chỉ ít lên khe khẽ; còn có núi lửa ngầm dưới biển","Không có núi lửa nào phun khói"]},{"cauHoi":"Vì sao Trái Đất được miêu tả “y hệt một củ hành khổng lồ”?","dang":"TN","dapAn":1,"giaiThich":"Trái Đất được tạo bởi nhiều lớp khác nhau, y hệt một củ hành khổng lồ với nhiều lớp áo.","id":"V5-B14-02","mucDo":2,"phuongAn":["Vì Trái Đất chỉ có một lớp duy nhất","Vì Trái Đất được tạo bởi nhiều lớp khác nhau, như củ hành có nhiều lớp áo","Vì Trái Đất có mùi hành","Vì Trái Đất vuông"]},{"cauHoi":"Núi lửa được hình thành ra sao?","dang":"TN","dapAn":0,"giaiThich":"Dòng mác-ma sôi sùng sục len lên, xuyên qua kẽ nứt ở lớp vỏ và phun trào.","id":"V5-B14-03","mucDo":1,"phuongAn":["Dưới lớp vỏ cứng, đá bị sức nóng nung chảy thành mác-ma (khoảng 700 đến 1 300 độ C); mác-ma len lên, xuyên qua kẽ nứt ở lớp vỏ và phun trào, tạo thành núi lửa","Do gió thổi cát","Do mưa tạo thành","Do người đắp đất thành núi rồi đốt lửa"]},{"cauHoi":"Từ “lửa” trong “núi lửa” và từ “lửa” trong “ánh lửa bếp” cho thấy điều gì về từ đa nghĩa?","dang":"TN","dapAn":3,"giaiThich":"SGK luyện từ đa nghĩa (từ quả, từ lửa) gắn với bài này.","id":"V5-B14-04","mucDo":1,"phuongAn":["Mọi từ đều không có nghĩa","Chỉ có một từ trong tiếng Việt","Từ “lửa” không bao giờ đổi nghĩa","Cùng một từ “lửa” có thể dùng trong những kết hợp khác nhau; cần xác định nghĩa trong từng ngữ cảnh"]},{"cauHoi":"Hình ảnh so sánh Trái Đất với củ hành là biện pháp gì?","dang":"TN","dapAn":1,"giaiThich":"Y hệt một củ hành khổng lồ – so sánh.","id":"V5-B14-05","mucDo":1,"phuongAn":["Câu hỏi tu từ không có hình ảnh","So sánh","Dấu gạch nối","Điệp ngữ bắt buộc lặp lại ba lần"]},{"cauHoi":"Viết 4 – 5 câu giải thích cho bạn cùng lớp: núi lửa hình thành như thế nào (dựa vào bài đọc, dùng lời của em).","dang":"TL","giaiThich":"Gợi ý: Lớp vỏ cứng – mác-ma nóng chảy – len qua kẽ nứt – phun trào; có thể nêu núi lửa không chỉ một kiểu.","id":"V5-B14-06","mucDo":3},{"cauHoi":"Việc tác giả kể ra nhiều hình dạng (hình nón, hình tròn thoai thoải, núi lửa ngầm dưới biển) và nhiều cách phun khác nhau của núi lửa giúp người đọc hiểu điều gì?","dang":"TN","dapAn":1,"giaiThich":"Có quả hình nón, có quả thoai thoải; có cái phun lửa, có cái chỉ phun khói, khí hoặc tro; có cái nổ kinh hoàng, có cái chỉ ít lên khe khẽ. Liệt kê như vậy, bài viết cho thấy núi lửa vô cùng đa dạng.","id":"TV5-B14-BS01","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Núi lửa ở nước nào cũng giống hệt nhau","Núi lửa rất đa dạng, không quả nào hoàn toàn giống quả nào về hình dạng và cách phun trào","Núi lửa chỉ phun một lần duy nhất trong đời","Núi lửa nào cũng nguy hiểm như nhau"]}],"chuDe":"2","ten":"Những ngọn núi nóng rẫy","tenChuDe":"Chủ điểm 2. Thiên nhiên kì thú","tenGoc":"Bài 14. Những ngọn núi nóng rẫy","tuan":"7","yeuCauCanDat":["Nhận biết được những chi tiết tiêu biểu và các thông tin chính của văn bản thông tin; xác định đề tài từ nhan đề, đề mục; nhận biết mục đích, đặc điểm, bố cục của văn bản giải thích, giới thiệu sách hoặc phim, quảng cáo, chương trình hoạt động; vai trò của hình ảnh, kí hiệu hoặc số liệu.","Nhận biết được văn bản viết theo tưởng tượng và văn bản viết về người thật, việc thật; hiểu từ ngữ, hình ảnh, biện pháp so sánh, nhân hoá trong văn bản.","Từ đa nghĩa và nghĩa của từ đa nghĩa trong văn bản."]},"15":{"cauHoi":[{"cauHoi":"Nhân vật “tôi” trong “Bài ca về mặt trời” thức dậy sớm đã thấy, nghe thấy gì trước khi thấy mặt trời?","dang":"TN","dapAn":2,"giaiThich":"Sương mù như tấm khăn voan mỏng màu sữa; chim sẻ thi nhau cất tiếng hót, dàn đồng ca khi bổng khi trầm.","id":"V5-B15-01","mucDo":1,"phuongAn":["Một trận mưa đá","Biển đang nổi sóng dữ","Sương mù như khăn voan mỏng màu sữa; trên ngọn cau, chim sẻ thi nhau hót như một dàn đồng ca","Trời đã tối đen, không có chim"]},{"cauHoi":"Cảnh mặt trời mọc được miêu tả bằng những hình ảnh nào?","dang":"TN","dapAn":0,"giaiThich":"Nhô lên nửa vành mũ màu đỏ... Vầng mặt trời giống một chiếc mâm đồng đỏ.","id":"V5-B15-02","mucDo":1,"phuongAn":["Nửa vành mũ màu đỏ nhô lên sau vòm cây phương đông, rồi như chiếc mâm đồng đỏ bay lên chiếm lĩnh nền trời","Một ngọn núi lửa đang tắt","Một chiếc thuyền buồm","Một quả bóng đá"]},{"cauHoi":"Khi phát hiện vầng mặt trời như mâm đồng đỏ, cảm xúc của “tôi” ra sao?","dang":"TN","dapAn":2,"giaiThich":"Trái tim tôi bỗng vang lên một bài ca hoà với bài ca của những con chim sẻ. Bài ca về mặt trời.","id":"V5-B15-03","mucDo":2,"phuongAn":["Tối không nhìn lên trời","Tối sợ hãi chạy trốn","Trái tim bỗng vang lên một bài ca hoà với bài ca của những con chim sẻ – bài ca về mặt trời","Tối bỏ về ngủ tiếp, không xúc động"]},{"cauHoi":"“Sương mù như tấm khăn voan mỏng màu sữa” dùng biện pháp tu từ nào?","dang":"TN","dapAn":0,"giaiThich":"So sánh sương mù với tấm khăn voan.","id":"V5-B15-04","mucDo":1,"phuongAn":["So sánh","Điệp từ bắt buộc","Câu ghép có kết từ “nếu... thì”","Danh từ riêng"]},{"cauHoi":"Từ “hạt” có nhiều nghĩa (hạt giống, hạt mưa, hạt nắng). Đó là hiện tượng gì?","dang":"TN","dapAn":3,"giaiThich":"SGK luyện tập về từ đa nghĩa (từ hạt, từ chân) ở bài này.","id":"V5-B15-05","mucDo":1,"phuongAn":["Dấu gạch ngang","Đại từ nghi vấn","Từ đồng âm bắt buộc khác hẳn, không liên hệ nghĩa","Từ đa nghĩa"]},{"cauHoi":"Viết 4 – 5 câu tả cảnh mặt trời mọc hoặc lặn mà em đã thấy (hoặc hình dung), có dùng ít nhất một hình ảnh so sánh.","dang":"TL","giaiThich":"Gợi ý: Có thể liên hệ “mũ đỏ”, “mâm đồng đỏ”; nêu cảm xúc.","id":"V5-B15-06","mucDo":3},{"cauHoi":"Tiếng hót của đàn chim sẻ được ví như “một dàn đồng ca”, còn trong trái tim nhân vật “tôi” lại vang lên “một bài ca về mặt trời”. Hai hình ảnh ấy có mối liên hệ gì?","dang":"TN","dapAn":2,"giaiThich":"Nghe dàn đồng ca của chim sẻ và ngắm vầng mặt trời như mâm đồng đỏ bay lên, trái tim “tôi” cũng vang lên một bài ca. Thiên nhiên hát trước, lòng người hát theo — đó là sự hoà điệu giữa cảnh buổi sớm và cảm xúc của người ngắm cảnh.","id":"TV5-B15-BS01","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Chim sẻ hót hay hơn con người hát","Nhân vật “tôi” muốn hát thi với đàn chim sẻ","Bài ca của thiên nhiên đã khơi dậy bài ca trong lòng người: thiên nhiên và con người hoà chung niềm vui đón chào ngày mới","Đàn chim sẻ bay đi nên bài ca trong tim cũng tắt"]}],"chuDe":"2","ten":"Bài ca về mặt trời","tenChuDe":"Chủ điểm 2. Thiên nhiên kì thú","tenGoc":"Bài 15. Bài ca về mặt trời","tuan":"8","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nhận biết được văn bản viết theo tưởng tượng và văn bản viết về người thật, việc thật; hiểu từ ngữ, hình ảnh, biện pháp so sánh, nhân hoá trong văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Từ đa nghĩa và nghĩa của từ đa nghĩa trong văn bản.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"16":{"cauHoi":[{"cauHoi":"Sang phía nam dãy Át-lát, thiên nhiên hiện ra khắc nghiệt như thế nào?","dang":"TN","dapAn":1,"giaiThich":"Nắng như rải lửa khiến tóc trở nên giòn tan; bốn bề giống như sao Hoả.","id":"V5-B16-01","mucDo":1,"phuongAn":["Rừng rậm ẩm ướt","Rặng đá xám xỉn rồi ngả đen rám hoặc đỏ quạch, bốn bề giống như sao Hoả; nắng như rải lửa, tóc trở nên giòn tan","Phố xá đông đúc","Mưa phùn, trời lạnh như mùa đông miền Bắc"]},{"cauHoi":"Cát Xa-ha-ra được so sánh, phân biệt thế nào với cát Phan Thiết, Sầm Sơn?","dang":"TN","dapAn":2,"giaiThich":"Cát sa mạc mịn như bột và mỏng manh như gió bụi, không to như cát Phan Thiết hay ẩm ướt như cát Sầm Sơn.","id":"V5-B16-02","mucDo":1,"phuongAn":["Không có cát ở Xa-ha-ra","Cát Xa-ha-ra ẩm ướt hơn cát Sầm Sơn","Cát sa mạc mịn như bột và mỏng manh như gió bụi, không to như cát Phan Thiết hay ẩm ướt như cát Sầm Sơn","Cát Xa-ha-ra to hơn cát Phan Thiết"]},{"cauHoi":"Những điều đặc biệt nào ở Xa-ha-ra được kể trong bài?","dang":"TN","dapAn":0,"giaiThich":"Trời tối dần, lạ thay, trời rất mát, thậm chí rất lạnh; mọi người nằm ngắm sao.","id":"V5-B16-03","mucDo":1,"phuongAn":["Sa mạc lớn nhất châu Phi; lạc đà vô địch khi chạy trên cát lún; đêm rất mát, thậm chí rất lạnh; đoàn khách nằm trên chiếu dạ ngắm sao; bình minh trên cồn cát óng vàng","Không có lạc đà","Đêm nóng hơn ngày","Ngày nào cũng mưa tuyết"]},{"cauHoi":"Câu cuối “ở giữa hoang mạc, ai cũng trở nên nhỏ bé như một hạt cát” nhấn mạnh điều gì đã được viết rõ trong bài?","dang":"TN","dapAn":3,"giaiThich":"Việc mang quốc tịch gì đâu có quan trọng, khi mà ở giữa hoang mạc, ai cũng trở nên nhỏ bé như một hạt cát.","id":"V5-B16-04","mucDo":3,"phuongAn":["Cát không liên quan đến con người","Chỉ người lái xe là lớn","Mỗi người phải giấu quốc tịch","Giữa thiên nhiên kì vĩ, con người trở nên nhỏ bé (việc mang quốc tịch gì cũng không còn quan trọng)"]},{"cauHoi":"Từ “tối”, “lạnh” trong câu “Trời tối dần, lạ thay, trời rất mát, thậm chí rất lạnh” được dùng theo nghĩa nào?","dang":"TN","dapAn":1,"giaiThich":"SGK hỏi: từ tối và từ lạnh dùng với nghĩa gốc hay nghĩa chuyển.","id":"V5-B16-05","mucDo":1,"phuongAn":["Nghĩa chuyển hoàn toàn không liên quan thời tiết","Nghĩa gốc (trời chuyển tối, nhiệt độ lạnh)","Là kết từ","Là đại từ"]},{"cauHoi":"Viết 4 – 5 câu nêu cảm xúc của nhân vật “tôi” khi đặt chân tới Xa-ha-ra và một điều em học được từ câu cuối bài.","dang":"TL","giaiThich":"Gợi ý: “Xin chào, Xa-ha-ra”; giấc mơ thành sự thật; con người nhỏ bé như hạt cát giữa hoang mạc.","id":"V5-B16-06","mucDo":3},{"cauHoi":"Hình ảnh “bốn bề giống như sao Hoả” và “nắng như rải lửa” ở vùng đất phía nam dãy Át-lát giúp em hiểu điều gì?","dang":"TN","dapAn":2,"giaiThich":"“Sao Hoả” gợi mặt đất đỏ quạch, khô khốc, không một bóng cây; “nắng như rải lửa” gợi cái nóng thiêu đốt khiến tóc cũng giòn tan. Hai hình ảnh cùng vẽ nên một vùng đất khắc nghiệt ở rìa sa mạc Xa-ha-ra.","id":"TV5-B16-BS01","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Nơi đây mát mẻ, dễ chịu như ở một hành tinh khác","Nơi đây là chặng dừng chân đông vui của du khách","Nơi đây khô cằn, nóng bức, hoang vắng và khắc nghiệt như bề mặt một hành tinh xa lạ","Nơi đây có nhiều đá quý đỏ phát sáng trong đêm"]},{"cauHoi":"Từ “lửa” trong “nắng như rải lửa” và từ “lửa” trong “ngọn lửa bếp” được dùng khác nhau như thế nào?","dang":"TN","dapAn":1,"giaiThich":"“Lửa” là từ đa nghĩa. Trong “ngọn lửa bếp”, “lửa” chỉ ngọn lửa thật (nghĩa gốc). Trong “nắng như rải lửa”, không hề có lửa thật — “lửa” được dùng theo nghĩa chuyển để diễn tả cái nắng nóng như thiêu như đốt.","id":"TV5-B16-BS02","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Cả hai đều dùng theo nghĩa gốc là ngọn lửa thật","“Rải lửa” dùng theo nghĩa chuyển để chỉ nắng nóng gay gắt như lửa; “lửa bếp” dùng theo nghĩa gốc là ngọn lửa thật để đun nấu","“Rải lửa” dùng theo nghĩa gốc; “lửa bếp” dùng theo nghĩa chuyển","Hai từ “lửa” này hoàn toàn không liên quan gì đến nhau"]}],"chuDe":"2","ten":"Xin chào, Xa-ha-ra","tenChuDe":"Chủ điểm 2. Thiên nhiên kì thú","tenGoc":"Bài 16. Xin chào, Xa-ha-ra","tuan":"8","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Từ đa nghĩa và nghĩa của từ đa nghĩa trong văn bản."]},"17":{"cauHoi":[{"cauHoi":"Thư “Thư gửi các học sinh” của Hồ Chí Minh được viết nhân dịp nào?","dang":"TN","dapAn":0,"giaiThich":"Chú thích SGK: thư gửi học sinh cả nước nhân ngày khai giảng năm học đầu tiên của nước Việt Nam Dân chủ Cộng hoà, tháng 9 năm 1945.","id":"V5-B17-01","mucDo":1,"phuongAn":["Ngày khai trường đầu tiên của nước Việt Nam Dân chủ Cộng hoà, tháng 9 năm 1945","Một buổi họp phụ huynh gần đây","Ngày thành lập Đội Thiếu niên","Ngày khai giảng năm 1976"]},{"cauHoi":"Chi tiết nào cho thấy Bác vui cùng niềm vui của học sinh?","dang":"TN","dapAn":3,"giaiThich":"Tôi đã tưởng tượng thấy trước mắt cái cảnh nhộn nhịp tưng bừng của ngày tựu trường ở khắp các nơi.","id":"V5-B17-02","mucDo":1,"phuongAn":["Bác bảo các em ở nhà, không đến trường","Bác chỉ nói về việc làm toán","Bác không nhắc gì đến ngày tựu trường","Bác tưởng tượng thấy cảnh nhộn nhịp tưng bừng của ngày tựu trường ở khắp nơi; các em vui vì được gặp thầy gặp bạn"]},{"cauHoi":"Bác nhắc học sinh nhớ đến ai trong giờ phút hạnh phúc ấy?","dang":"TN","dapAn":1,"giaiThich":"Các em được hưởng sự may mắn đó là nhờ sự hi sinh của biết bao nhiêu đồng bào các em. Vậy các em nghĩ sao?","id":"V5-B17-03","mucDo":2,"phuongAn":["Chỉ nhớ đến đồ chơi","Nhớ sự hi sinh của biết bao đồng bào; nhờ đó các em mới được nhận một nền giáo dục hoàn toàn Việt Nam","Chỉ nhớ kỳ nghỉ hè","Không nhớ đến ai"]},{"cauHoi":"Vì sao Bác khuyên các em phải cố gắng, siêng năng học tập?","dang":"TN","dapAn":2,"giaiThich":"Non sông Việt Nam có trở nên tươi đẹp hay không... chính là nhờ một phần lớn ở công học tập của các em.","id":"V5-B17-04","mucDo":2,"phuongAn":["Vì việc học không liên quan đến tương lai nước nhà","Vì Bác muốn các em nghỉ học","Vì sau 80 năm nô lệ, phải xây dựng lại cơ đồ; non sông có tươi đẹp, dân tộc có sánh vai được với các cường quốc, một phần lớn nhờ công học tập của các em","Vì chỉ cần vui chơi là đủ xây dựng đất nước"]},{"cauHoi":"Theo bài luyện từ, muốn tra nghĩa một từ trong từ điển tiếng Việt, em cần dựa vào đâu?","dang":"TN","dapAn":2,"giaiThich":"SGK hướng dẫn đọc thông tin trong từ điển và tra cứu nghĩa từ.","id":"V5-B17-05","mucDo":1,"phuongAn":["Đoán đại, không cần mở sách","Chỉ nhìn bìa từ điển là đủ","Tìm mục từ theo thứ tự chữ cái (và đọc các nghĩa, ví dụ được ghi trong từ điển)","Hỏi người khác rồi bỏ qua từ điển"]},{"cauHoi":"Viết 4 – 5 câu nêu cảm nghĩ của em sau khi đọc thư Bác Hồ gửi các học sinh (có thể gắn với ngày khai giảng em đã trải qua).","dang":"TL","giaiThich":"Gợi ý: Nêu dịp thư được viết; điều Bác mong ở học sinh; cảm xúc / điều em muốn làm theo.","id":"V5-B17-06","mucDo":3}],"chuDe":"3","ten":"Thư gửi các học sinh","tenChuDe":"Chủ điểm 3. Trên con đường học tập","tenGoc":"Bài 17. Thư gửi các học sinh","tuan":"9","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Sử dụng được một số từ điển tiếng Việt thông dụng để tìm từ, nghĩa của từ, cách dùng từ và tra cứu thông tin khác."]},"18":{"cauHoi":[{"cauHoi":"Đoạn đầu bài “Tấm gương tự học” giới thiệu Tạ Quang Bửu như thế nào?","dang":"TN","dapAn":1,"giaiThich":"Tạ Quang Bửu (1910-1986) sinh ra trong một gia đình nhà nho ở Nghệ An. Ông là nhà khoa học và nhà giáo dục đa tài, uyên bác hiếm có.","id":"V5-B18-01","mucDo":1,"phuongAn":["Không rõ năm sinh, chỉ chơi thể thao","Sinh năm 1910, mất 1986, trong gia đình nhà nho ở Nghệ An; là nhà khoa học và nhà giáo dục đa tài, uyên bác hiếm có","Là nhạc sĩ người Pháp","Sinh ở Đà Lạt năm 2000, chỉ làm thơ"]},{"cauHoi":"Những chi tiết nào cho thấy ông là tấm gương tự học, học suốt đời?","dang":"TN","dapAn":0,"giaiThich":"Ngồi trên lưng ngựa, mải đọc sách, ông ngã tòm xuống suối. Ông học đến lúc cuối đời, ngay cả khi đau ốm.","id":"V5-B18-02","mucDo":1,"phuongAn":["Có thói quen đọc sách mọi lúc, mọi nơi, đọc nhanh, nhớ lâu; từng ngã tòm xuống suối vì mải đọc trên lưng ngựa; học từ lúc trẻ đến cuối đời, cả khi đau ốm","Ông cấm người khác đọc sách","Ông chỉ học đúng một ngày rồi thôi","Ông chưa từng đọc sách"]},{"cauHoi":"Sự đa tài, uyên bác của ông được thể hiện ra sao?","dang":"TN","dapAn":3,"giaiThich":"Ông sử dụng thành thạo tiếng Anh, Pháp, Đức, Ba Lan; nhiều người coi ông là “Lê Quý Đôn thời nay”.","id":"V5-B18-03","mucDo":2,"phuongAn":["Không quan tâm nghệ thuật","Chỉ giỏi một môn thể dục","Không biết ngoại ngữ nào","Xuất sắc ở toán, lí, hoá, sinh, triết học,... và ngoại ngữ (Anh, Pháp, Đức, Ba Lan; đọc hiểu Nga, Trung, Hy Lạp cổ, La-tinh); tự học tiếng Nga ba tháng đã dịch tài liệu quân sự; có hiểu biết về âm nhạc, hội hoạ, kiến trúc, thể thao; được gọi là “Lê Quý Đôn thời nay”"]},{"cauHoi":"Tài năng, công lao của ông được ghi nhận thế nào?","dang":"TN","dapAn":3,"giaiThich":"Tên được đặt cho các con phố; Giải thưởng Tạ Quang Bửu cho các nhà khoa học xuất sắc.","id":"V5-B18-04","mucDo":2,"phuongAn":["Không có giải thưởng nào","Không ai nhớ đến ông","Chỉ có một con đường ở nước ngoài mang tên ông","Tên ông được đặt cho các con phố ở Hà Nội, Thành phố Hồ Chí Minh, Huế, Đà Nẵng,...; có Giải thưởng Tạ Quang Bửu dành cho các nhà khoa học xuất sắc"]},{"cauHoi":"Vì sao ông nhiều lần được cùng Bác Hồ tiếp chính khách nước ngoài?","dang":"TN","dapAn":2,"giaiThich":"Ông giúp Bác Hồ soạn thảo những bức công hàm bằng tiếng Anh, nhiều lần cùng Bác tiếp các chính khách nước ngoài.","id":"V5-B18-05","mucDo":1,"phuongAn":["Vì ông không liên quan đến ngoại giao","Vì ông không biết tiếng Anh","Vì ông nói tiếng Anh rất giỏi (được nhận xét là “hoàn hảo đến mức người Anh phải kinh ngạc”) và từng giúp Bác soạn công hàm tiếng Anh","Vì ông là người phiên dịch duy nhất của Pháp"]},{"cauHoi":"Viết đoạn văn (4 – 5 câu) giới thiệu Tạ Quang Bửu với bạn, nêu rõ vì sao ông là tấm gương tự học.","dang":"TL","giaiThich":"Gợi ý: Năm sinh, quê; thói quen đọc sách; sự đa tài; một chi tiết đáng nhớ (ngã xuống suối / ngoại ngữ / giải thưởng).","id":"V5-B18-06","mucDo":3}],"chuDe":"3","ten":"Tấm gương tự học","tenChuDe":"Chủ điểm 3. Trên con đường học tập","tenGoc":"Bài 18. Tấm gương tự học","tuan":"9","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"19":{"cauHoi":[{"cauHoi":"An-đéc-xen sinh ra ở đâu, trong gia đình nào?","dang":"TN","dapAn":0,"giaiThich":"An-đéc-xen sinh ra trong một gia đình thợ giày ở Đan Mạch.","id":"V5-B19-01","mucDo":1,"phuongAn":["Ở Đan Mạch, trong một gia đình thợ giày","Ở Nhật Bản, gia đình ngư dân","Ở sa mạc Xa-ha-ra","Ở Việt Nam, gia đình nhà nho"]},{"cauHoi":"Những trải nghiệm nào thời thơ ấu đã hun đúc tài năng của ông?","dang":"TN","dapAn":1,"giaiThich":"Cha làm kính nhìn xa, làm rối gỗ, dựng sân khấu; cậu viết câu chuyện Sao chổi.","id":"V5-B19-02","mucDo":2,"phuongAn":["Ông không được chơi gì cả","Cha đưa tới đồng cỏ, làm chiếc kính nhìn xa; cậu quan sát rồi liên tưởng thành câu chuyện; lên năm tuổi được cha làm rối gỗ, dựng sân khấu; xúc động vì sao chổi, viết chuyện Sao chổi","Ông chưa từng kể chuyện","Ông chỉ học vẽ trứng"]},{"cauHoi":"An-đéc-xen đã bày tỏ tâm nguyện gì với Quốc vương Đan Mạch?","dang":"TN","dapAn":1,"giaiThich":"Ông nói rằng mình muốn đến nhiều nơi để trải nghiệm cuộc sống. Quốc vương bèn tặng ông một số tiền.","id":"V5-B19-03","mucDo":2,"phuongAn":["Muốn bỏ viết truyện","Muốn đến nhiều nơi để trải nghiệm cuộc sống; Quốc vương tặng ông một số tiền để thoả nguyện","Muốn ở yên một chỗ, không đi đâu","Muốn làm thợ giày như cha"]},{"cauHoi":"Nhờ đâu ông viết được nhiều tác phẩm hay như “Vịt con xấu xí”, “Cô bé bán diêm”, “Nàng tiên cá”, “Chú lính chì dũng cảm”?","dang":"TN","dapAn":0,"giaiThich":"Bằng những trải nghiệm phong phú và một trái tim nhân hậu, ông đã cho ra đời một loạt tác phẩm...","id":"V5-B19-04","mucDo":2,"phuongAn":["Nhờ những trải nghiệm phong phú khi chu du và một trái tim nhân hậu (thương cảm thân phận bé nhỏ, trân trọng tâm hồn trong sáng)","Nhờ chỉ viết về máy móc","Nhờ bỏ hết cảm xúc","Nhờ không đi đâu, không gặp ai"]},{"cauHoi":"Theo bài luyện từ, muốn tra nghĩa thành ngữ “mắt thấy tai nghe” hoặc “học một biết mười”, em nên dùng loại từ điển nào và làm thế nào?","dang":"TN","dapAn":3,"giaiThich":"SGK: Bước 1: Chọn từ điển thành ngữ. Bước 2: Tìm mục từ bắt đầu bằng chữ H.","id":"V5-B19-05","mucDo":1,"phuongAn":["Chỉ mở từ điển ngoại ngữ Anh – Việt","Không cần từ điển","Dùng tập bản đồ, tìm theo màu sắc","Dùng từ điển thành ngữ; tìm mục từ theo chữ cái đầu của thành ngữ (ví dụ “học một biết mười” tìm ở chữ H)"]},{"cauHoi":"Viết 4 – 5 câu nêu điều câu chuyện “Trải nghiệm để sáng tạo” muốn nói với em (gắn với việc quan sát, trải nghiệm và sáng tạo).","dang":"TL","giaiThich":"Gợi ý: Quan sát, tưởng tượng từ nhỏ; dám đi trải nghiệm; viết bằng trái tim nhân hậu. Không cần chọn đáp án A/B/C in sách.","id":"V5-B19-06","mucDo":3}],"chuDe":"3","ten":"Trải nghiệm để sáng tạo","tenChuDe":"Chủ điểm 3. Trên con đường học tập","tenGoc":"Bài 19. Trải nghiệm để sáng tạo","tuan":"10","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Sử dụng được một số từ điển tiếng Việt thông dụng để tìm từ, nghĩa của từ, cách dùng từ và tra cứu thông tin khác."]},"2":{"cauHoi":[{"cauHoi":"Các bạn nhỏ trong bài “Cánh đồng hoa” thường vui chơi ở đâu và như thế nào?","dang":"TN","dapAn":3,"giaiThich":"Ở đầu làng có đồng cỏ khá rộng; Ja Ka vỗ trống, các bạn múa hát.","id":"V5-B02-01","mucDo":1,"phuongAn":["Ngoài biển, đánh cá","Trên núi, hái nấm","Trong lớp học, chỉ đọc sách","Ở đồng cỏ đầu làng: Ja Ka vỗ trống, các bạn cùng múa hát tưng bừng"]},{"cauHoi":"Vì sao các bạn lo buồn và Mư Hoa nảy ra ý tưởng gì?","dang":"TN","dapAn":2,"giaiThich":"Bãi rác lớn dần, bốc mùi; Mư Hoa: chúng ta sẽ biến nơi đây thành cánh đồng hoa.","id":"V5-B02-02","mucDo":2,"phuongAn":["Vì hết trống; đề nghị chuyển lớp","Vì trời mưa; đề nghị ở nhà","Đồng cỏ xuất hiện bãi rác ngày một lớn; Mư Hoa đề nghị biến nơi đó thành cánh đồng hoa để người ta không nỡ đổ rác","Vì thiếu bạn; đề nghị bỏ cuộc"]},{"cauHoi":"Ý tưởng đó được thực hiện như thế nào và kết quả ra sao?","dang":"TN","dapAn":1,"giaiThich":"Nhiều cô bác hưởng ứng; ba tháng sau hoa đua sắc, ngôi làng nổi tiếng.","id":"V5-B02-03","mucDo":2,"phuongAn":["Đồng cỏ bị san làm đường","Các bạn và dân làng dọn rác, xới đất, gieo hạt, trồng cây, tưới nước, nhổ cỏ, bắt sâu; ba tháng sau hoa khoe sắc, không ai đổ rác nữa, làng đón khách tham quan","Người lớn cấm không cho trồng hoa","Chỉ có bốn bạn dọn một buổi rồi bỏ"]},{"cauHoi":"Cúc bách nhật, cúc vạn thọ, mào gà trong bài là những từ loại gì?","dang":"TN","dapAn":2,"giaiThich":"Đó là danh từ chỉ sự vật (loài hoa).","id":"V5-B02-04","mucDo":1,"phuongAn":["Động từ","Kết từ","Danh từ (chỉ các loài hoa)","Tính từ"]},{"cauHoi":"Bài học gần nhất mà câu chuyện “Cánh đồng hoa” gửi tới là gì?","dang":"TN","dapAn":0,"giaiThich":"Nhờ quyết tâm của nhóm bạn và dân làng, đồng cỏ thành cánh đồng hoa, không còn đổ rác.","id":"V5-B02-05","mucDo":2,"phuongAn":["Chung sức cải tạo, bảo vệ môi trường sống thì chỗ chơi sẽ đẹp trở lại, cả cộng đồng cùng vui","Rác không ảnh hưởng gì đến chỗ chơi","Chỉ cần một người làm là đủ","Không nên để người lớn tham gia"]},{"cauHoi":"Viết 4 – 5 câu kể tóm tắt câu chuyện “Cánh đồng hoa” theo trình tự: vui chơi – nguy cơ – ý tưởng – hành động – kết quả.","dang":"TL","giaiThich":"Gợi ý: Nêu đúng tên nhân vật (Ja Ka, Mư Hoa, Ja Prok, Mư Nhơ); không kể lan man.","id":"V5-B02-06","mucDo":3}],"chuDe":"1","ten":"Cánh đồng hoa","tenChuDe":"Chủ điểm 1. Thế giới tuổi thơ","tenGoc":"Bài 2. Cánh đồng hoa","tuan":"1","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản.","Đại từ và kết từ: đặc điểm và chức năng; ôn luyện danh từ, động từ, tính từ.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện."]},"20":{"cauHoi":[{"cauHoi":"Những ngày đầu học vẽ, vì sao Lê-ô-nác-đô đa Vin-xi cảm thấy chán nản?","dang":"TN","dapAn":2,"giaiThich":"Rồi mấy ngày sau cũng vậy. Cậu cảm thấy chán nản... cho rằng thầy coi thường năng lực của mình.","id":"V5-B20-01","mucDo":2,"phuongAn":["Vì thầy không cho cậu cầm bút","Vì cậu không thích hội hoạ","Thầy Vê-rô-ki-ô bắt cậu vẽ quả trứng gà mãi nhiều ngày; cậu nghĩ việc ấy quá dễ và thầy coi thường năng lực của mình","Vì quả trứng bị mất"]},{"cauHoi":"Vì sao thầy giáo cho rằng việc vẽ trứng không dễ dàng?","dang":"TN","dapAn":0,"giaiThich":"Trong một nghìn quả trứng, không thể tìm ra hai quả hoàn toàn giống nhau... ánh sáng cũng ảnh hưởng đến hình dạng.","id":"V5-B20-02","mucDo":2,"phuongAn":["Trong một nghìn quả trứng không có hai quả hoàn toàn giống nhau; cùng một quả, nhìn từ góc độ khác thì hình dạng khác; ánh sáng cũng làm thay đổi hình dạng","Vì không ai vẽ được trứng","Vì trứng luôn giống hệt nhau","Vì trứng không có hình dạng"]},{"cauHoi":"Lê-ô-nác-đô hiểu ra điều gì và kết quả ra sao?","dang":"TN","dapAn":2,"giaiThich":"Nghe những lời đó, Lê-ô-nác-đô bỗng hiểu ra... khổ luyện... xuất sắc hơn thầy... trở thành hoạ sĩ Ý nổi tiếng.","id":"V5-B20-03","mucDo":2,"phuongAn":["Ông bỏ học ngay hôm đó","Ông chỉ vẽ trứng đến hết đời, không tiến bộ","Thầy muốn luyện tầm nhìn – bước đầu của hội hoạ; chỉ vẽ tốt quả trứng đơn giản mới vẽ được sự vật phức tạp. Từ đó ông khổ luyện, cuối cùng xuất sắc hơn thầy, trở thành hoạ sĩ Ý nổi tiếng","Ông không bao giờ vẽ nữa"]},{"cauHoi":"Câu tục ngữ nào nói đúng nhất ý nghĩa câu chuyện “Khổ luyện thành tài”?","dang":"TN","dapAn":1,"giaiThich":"Câu chuyện nhấn mạnh sự khổ luyện bền bỉ dẫn đến thành tài – đúng với “Có công mài sắt, có ngày nên kim”.","id":"V5-B20-04","mucDo":2,"phuongAn":["Ăn quả nhớ người trồng cây","Có công mài sắt, có ngày nên kim","Ăn kỹ no lâu","Lá lành đùm lá rách"]},{"cauHoi":"Theo chú thích / bài đọc, Lê-ô-nác-đô đa Vin-xi sống khoảng thời gian nào?","dang":"TN","dapAn":3,"giaiThich":"Chú thích SGK: Lê-ô-nác-đô đa Vin-xi (1452-1519).","id":"V5-B20-05","mucDo":1,"phuongAn":["2010–2020","1910–1986","1945–1976","1452–1519"]},{"cauHoi":"Viết 4 – 5 câu nêu điều em học được từ câu chuyện thầy Vê-rô-ki-ô dạy Lê-ô-nác-đô vẽ trứng.","dang":"TL","giaiThich":"Gợi ý: Việc tưởng chừng dễ cũng cần khổ luyện; chú ý quan sát; kiên trì mới thành tài.","id":"V5-B20-06","mucDo":3},{"cauHoi":"Thầy giáo dạy vẽ của Lê-ô-nác-đô đa Vin-xi tên là gì?","dang":"TN","dapAn":2,"giaiThich":"Thầy Vê-rô-ki-ô là người đã bắt Lê-ô-nác-đô vẽ đi vẽ lại quả trứng gà trong những ngày đầu học vẽ, để luyện cho cậu tầm nhìn — bước đầu của hội hoạ.","id":"TV5-B20-BS01","mucDo":1,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Mi-ken-lăng-giê-lô","Ra-pha-en","Vê-rô-ki-ô","Tô Hoài"]}],"chuDe":"3","ten":"Khổ luyện thành tài","tenChuDe":"Chủ điểm 3. Trên con đường học tập","tenGoc":"Bài 20. Khổ luyện thành tài","tuan":"10","yeuCauCanDat":["Nhận xét được hình dáng, tính cách của nhân vật; nhận biết thời gian, địa điểm và tác dụng của chúng trong câu chuyện.","Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện."]},"21":{"cauHoi":[{"cauHoi":"Trong bài thơ “Thế giới trong trang sách” (Huệ Triệu), thế giới diệu kì mà sách mang đến được thể hiện bằng những hình ảnh nào ở khổ 1?","dang":"TN","dapAn":3,"giaiThich":"Trên bầu trời những vì sao lấp lánh / Mặt biển xanh, cánh buồm nâu trong nắng / Sau cơn mưa hiện bảy sắc cầu vồng.","id":"V5-B21-01","mucDo":1,"phuongAn":["Chỉ có đường phố đông xe","Chỉ có bàn học và thước kẻ","Không có hình ảnh thiên nhiên nào","Vì sao lấp lánh, mặt biển xanh, cánh buồm nâu trong nắng, bảy sắc cầu vồng sau cơn mưa"]},{"cauHoi":"Câu “Trang sách trả lời câu hỏi tuổi thơ” được hiểu như thế nào theo khổ thơ thứ hai?","dang":"TN","dapAn":2,"giaiThich":"Vũ trụ bao la bao điều bí mật / Trái đất rộng có chân người chinh phục / Mặt trăng hiền giấu chú Cuội ở đâu?","id":"V5-B21-02","mucDo":2,"phuongAn":["Sách chỉ dạy vẽ trứng","Sách không trả lời câu hỏi nào","Sách giúp bạn nhỏ giải đáp những thắc mắc về vũ trụ, Trái Đất, mặt trăng (chú Cuội), những điều bí mật tuổi thơ muốn biết","Sách chỉ nói về đường đi học"]},{"cauHoi":"Khổ thơ thứ ba nói lên ý nghĩa gì của trang sách đối với tuổi thơ?","dang":"TN","dapAn":1,"giaiThich":"Trang sách thắp lên ngọn lửa khát khao / Những ước mơ tuổi thơ luôn rộng mở / Con đường dài tít tắp đợi mong ta.","id":"V5-B21-03","mucDo":2,"phuongAn":["Sách khuyên các em bỏ học","Sách thắp lên ngọn lửa khát khao, những ước mơ rộng mở, con đường dài phía trước","Sách làm các em sợ hãi, không dám ước mơ","Sách chỉ kể chuyện quá khứ, không liên quan ước mơ"]},{"cauHoi":"Khổ cuối nhắn gửi điều gì đã được viết rõ trong thơ?","dang":"TN","dapAn":0,"giaiThich":"Nhân nghĩa bao đời cha ông gìn giữ / Như dòng sông sẽ chảy về biển cả / Lớn khôn rồi vẫn nhớ tiếng mẹ ru.","id":"V5-B21-04","mucDo":2,"phuongAn":["Nhớ bài học nhân nghĩa cha ông gìn giữ; lớn khôn rồi vẫn nhớ tiếng mẹ ru (như dòng sông chảy về biển cả)","Không cần nhớ tiếng mẹ ru","Quên hết truyền thống khi lớn","Chỉ cần đọc sách khoa học, bỏ nhân nghĩa"]},{"cauHoi":"Trong câu “Ngày Sách và Văn hoá đọc Việt Nam – sự kiện văn hoá quan trọng – được tổ chức vào ngày 21 tháng 4”, dấu gạch ngang dùng để làm gì?","dang":"TN","dapAn":3,"giaiThich":"SGK: dấu gạch ngang đánh dấu bộ phận chú thích, giải thích trong câu.","id":"V5-B21-05","mucDo":1,"phuongAn":["Đánh dấu kết thúc bài văn","Thay cho dấu chấm hỏi","Nối các tiếng trong từ mượn (dấu gạch nối)","Đánh dấu bộ phận chú thích, giải thích trong câu"]},{"cauHoi":"Viết 4 – 5 câu nêu tình cảm, cảm xúc của em về bài thơ “Thế giới trong trang sách” hoặc về một trang sách đã thắp lên ước mơ cho em.","dang":"TL","giaiThich":"Gợi ý: Chọn một khổ thơ / một hình ảnh; nêu vì sao em thích; cảm xúc khi đọc sách.","id":"V5-B21-06","mucDo":3}],"chuDe":"3","ten":"Thế giới trong trang sách","tenChuDe":"Chủ điểm 3. Trên con đường học tập","tenGoc":"Bài 21. Thế giới trong trang sách","tuan":"11","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản.","Công dụng của dấu gạch ngang (đánh dấu bộ phận chú thích, giải thích trong câu) và dấu gạch nối (nối các tiếng trong những từ mượn gồm nhiều tiếng).","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"22":{"cauHoi":[{"cauHoi":"Những câu chuyện đầu tiên, bạn nhỏ trong bài Nguyễn Nhật Ánh được nghe ai kể, kể chuyện gì?","dang":"TN","dapAn":2,"giaiThich":"Ba tôi đi làm xa nên những câu chuyện đầu tiên tôi nghe được là từ bà tôi và chú tôi.","id":"V5-B22-01","mucDo":1,"phuongAn":["Chỉ nghe thời sự trên đài","Chỉ thầy giáo kể bài toán","Bà kể Tấm Cám, Thạch Sanh, Cây tre trăm đốt, Đôi hài bảy dặm,...; chú kể chuyện Tôn Ngộ Không và một số truyện trong Nghìn lẻ một đêm (ba đi làm xa)","Không ai kể chuyện"]},{"cauHoi":"Bạn nhỏ đã làm gì để tự khám phá thế giới trong sách?","dang":"TN","dapAn":0,"giaiThich":"Tôi cố gắng học chữ để tự mình khám phá thế giới kì diệu kia.","id":"V5-B22-02","mucDo":1,"phuongAn":["Khi bà và chú kể hết chuyện, chú mách những câu ấy có trong sách; bạn cố gắng học chữ để tự đọc","Chờ đến khi lớn mới học chữ","Cấm không cho mở sách","Bỏ học chữ, chỉ nghe kể mãi"]},{"cauHoi":"Hành trình đọc sách của bạn nhỏ diễn ra theo thứ tự nào?","dang":"TN","dapAn":1,"giaiThich":"Bảy tuổi mê sách ba mua; tám, chín tuổi đọc hết rương truyện; rồi Không gia đình, Những người khốn khổ.","id":"V5-B22-03","mucDo":1,"phuongAn":["Không đọc quyển nào","Bảy tuổi mê sách ba mua về; tám, chín tuổi đọc hết rương truyện Trung Hoa của ông thợ hớt tóc; rồi tìm đến Không gia đình, Những người khốn khổ,...","Chỉ đọc báo lúc 15 tuổi","Trước hết đọc Không gia đình, sau đó mới nghe bà kể"]},{"cauHoi":"Những trang sách có ý nghĩa thế nào, và việc các em nhao nhao “Anh Hai kể chuyện đi” cho thấy điều gì?","dang":"TN","dapAn":1,"giaiThich":"Sách đã bồi đắp tâm hồn... mở rộng đến vô biên bờ cõi của trí tưởng tượng. Rồi tới lượt mấy đứa em... Anh Hai kể chuyện đi!","id":"V5-B22-04","mucDo":3,"phuongAn":["Bạn nhỏ cấm các em nghe","Sách bồi đắp tâm hồn, làm trưởng thành tình cảm, mở rộng trí tưởng tượng; các em cũng háo hức được nghe kể – thói quen đọc/kể chuyện được truyền tiếp","Các em không thích nghe chuyện","Sách không ảnh hưởng gì"]},{"cauHoi":"Từ “vô biên” trong câu “mở rộng đến vô biên bờ cõi của trí tưởng tượng” nghĩa là gì?","dang":"TN","dapAn":3,"giaiThich":"SGK phân biệt: vô biên – không có giới hạn; vô số – nhiều không đếm được; vô hình – không có hình dáng cụ thể.","id":"V5-B22-05","mucDo":1,"phuongAn":["Nhiều tới mức không đếm được (vô số)","Không có hình dáng cụ thể","Không hợp lẽ phải","Không có giới hạn"]},{"cauHoi":"Viết đoạn văn (4 – 5 câu) thể hiện tình cảm, cảm xúc về một câu chuyện em đã được nghe hoặc đã đọc (có thể liên hệ bài Nguyễn Nhật Ánh).","dang":"TL","giaiThich":"Gợi ý: Nêu tên chuyện, người kể / tác giả; cảm xúc khi nghe, đọc; điều em nhớ nhất.","id":"V5-B22-06","mucDo":3},{"cauHoi":"Vì sao khi bà và chú đã kể hết chuyện, bạn nhỏ trong bài lại cố gắng học chữ thật nhanh?","dang":"TN","dapAn":3,"giaiThich":"Chú mách rằng những câu chuyện hay đều có trong sách. Muốn tự mình khám phá thế giới kì diệu ấy mà không phải chờ bà hay chú kể, bạn nhỏ cố gắng học chữ để tự đọc sách.","id":"TV5-B22-BS01","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Để được bà khen là cháu ngoan","Để sớm đi học ở trường xa nhà","Để viết thư gửi cho ba đang đi làm xa","Để tự mình đọc sách, khám phá thế giới kì diệu trong sách mà không phải chờ người khác kể"]},{"cauHoi":"Hành trình đọc của bạn nhỏ — từ nghe bà, chú kể chuyện, đến mê sách ba mua, đọc hết rương truyện của ông thợ hớt tóc, rồi tìm đến “Không gia đình”, “Những người khốn khổ” — cho thấy điều gì?","dang":"TN","dapAn":0,"giaiThich":"Thứ tự các mốc đọc cho thấy sự trưởng thành của người đọc: từ nghe kể, đến tự đọc truyện ngắn, rồi chinh phục những tác phẩm dài và sâu sắc hơn. Sách cứ thế bồi đắp tâm hồn và mở rộng trí tưởng tượng của bạn nhỏ.","id":"TV5-B22-BS02","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Càng lớn, bạn nhỏ càng đọc được nhiều hơn và tìm đến những cuốn sách dài, khó hơn","Bạn nhỏ chỉ thích truyện cổ tích, không đọc loại sách nào khác","Bạn nhỏ đọc sách chỉ để giết thời gian những lúc buồn","Bạn nhỏ càng lớn càng ít đọc sách đi"]}],"chuDe":"3","ten":"Từ những câu chuyện ấu thơ","tenChuDe":"Chủ điểm 3. Trên con đường học tập","tenGoc":"Bài 22. Từ những câu chuyện ấu thơ","tuan":"11","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Sử dụng được một số từ điển tiếng Việt thông dụng để tìm từ, nghĩa của từ, cách dùng từ và tra cứu thông tin khác.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"23":{"cauHoi":[{"cauHoi":"Lời giới thiệu sách cho biết những thông tin cơ bản nào về “Dế Mèn phiêu lưu kí”?","dang":"TN","dapAn":0,"giaiThich":"Dế Mèn phiêu lưu kí của nhà văn Tô Hoài là cuốn sách gồm 10 chương...","id":"V5-B23-01","mucDo":1,"phuongAn":["Tác giả Tô Hoài; gồm 10 chương; kể cuộc phiêu lưu của Dế Mèn trong thế giới côn trùng","Không có nhân vật chính","Sách chỉ có thơ, không có chuyện","Tác giả Nguyễn Nhật Ánh; 2 chương"]},{"cauHoi":"Nhân vật Dế Mèn được giới thiệu thay đổi như thế nào?","dang":"TN","dapAn":2,"giaiThich":"Lúc đầu kiêu căng, ngạo mạn... dần khôn lớn, trở thành một chú dế can đảm, tốt bụng, trượng nghĩa.","id":"V5-B23-02","mucDo":1,"phuongAn":["Dế Mèn không thay đổi gì","Dế Mèn không xuất hiện trong sách","Lúc đầu kiêu căng, ngạo mạn, gây hậu quả tai hại; trên đường phiêu lưu dần khôn lớn, trở thành chú dế can đảm, tốt bụng, trượng nghĩa","Dế Mèn vốn đã hoàn hảo từ đầu"]},{"cauHoi":"Theo lời giới thiệu, cuốn sách mang lại bài học và ước mơ gì?","dang":"TN","dapAn":2,"giaiThich":"Bài học nhẹ nhàng về tình bạn... truyền tải ước mơ cao đẹp về một thế giới đại đồng.","id":"V5-B23-03","mucDo":2,"phuongAn":["Chỉ dạy cách đá bóng","Khuyên không kết bạn","Bài học về tình bạn, thái độ và cách ứng xử; ước mơ về một thế giới đại đồng, nơi tất cả đều là bạn bè, anh em","Không có bài học nào"]},{"cauHoi":"Những con số nào cho thấy sức sống của cuốn sách?","dang":"TN","dapAn":1,"giaiThich":"Hơn 100 lần tái bản; gần 40 quốc gia; dịch sang 15 thứ tiếng.","id":"V5-B23-04","mucDo":1,"phuongAn":["In ở 2 trường trong một xã","Hơn 100 lần tái bản trong nước; xuất bản ở gần 40 quốc gia; dịch sang 15 thứ tiếng – tác phẩm văn học Việt Nam được dịch ra nhiều thứ tiếng nhất tính đến nay (theo bài)","Không nêu số liệu nào","Chỉ in đúng 1 lần, chưa dịch ra tiếng nào"]},{"cauHoi":"Từ “trượng nghĩa” theo chú thích SGK nghĩa là gì?","dang":"TN","dapAn":3,"giaiThich":"Chú thích: Trượng nghĩa: trọng điều phải, dựa vào lẽ phải để hành động.","id":"V5-B23-05","mucDo":1,"phuongAn":["Không quan tâm ai","Chỉ thích đùa","Sợ khó, bỏ cuộc","Trọng điều phải, dựa vào lẽ phải để hành động"]},{"cauHoi":"Sau khi đọc lời giới thiệu, hãy viết 4 – 5 câu nêu cảm nghĩ của em về cuốn “Dế Mèn phiêu lưu kí” và vì sao em muốn (hoặc đã) đọc cuốn sách này.","dang":"TL","giaiThich":"Gợi ý: Nhân vật thay đổi; bài học tình bạn; sức sống của tác phẩm (tái bản, dịch thuật).","id":"V5-B23-06","mucDo":3},{"cauHoi":"Dế Mèn lúc đầu “kiêu căng, ngạo mạn”, sau chuyến phiêu lưu trở thành chú dế “can đảm, tốt bụng, trượng nghĩa”. Sự thay đổi ấy cho thấy điều gì?","dang":"TN","dapAn":1,"giaiThich":"Chính những chuyến đi, những lần vấp ngã và trả giá cho tính kiêu căng đã dạy Dế Mèn trưởng thành. Sự thay đổi của nhân vật là kết quả của cả một hành trình trải nghiệm — cũng là điều làm nên sức hấp dẫn của cuốn sách.","id":"TV5-B23-BS01","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Dế Mèn thay đổi vì được các bạn côn trùng khen ngợi","Nhờ những trải nghiệm và va vấp trên đường phiêu lưu, Dế Mèn đã khôn lớn và trưởng thành hơn","Dế Mèn thay đổi vì sợ bị bạn bè xa lánh","Dế Mèn vốn đã tốt bụng ngay từ đầu câu chuyện"]}],"chuDe":"3","ten":"Giới thiệu sách Dế Mèn phiêu lưu kí","tenChuDe":"Chủ điểm 3. Trên con đường học tập","tenGoc":"Bài 23. Giới thiệu sách Dế Mèn phiêu lưu kí","tuan":"12","yeuCauCanDat":["Nhận biết được những chi tiết tiêu biểu và các thông tin chính của văn bản thông tin; xác định đề tài từ nhan đề, đề mục; nhận biết mục đích, đặc điểm, bố cục của văn bản giải thích, giới thiệu sách hoặc phim, quảng cáo, chương trình hoạt động; vai trò của hình ảnh, kí hiệu hoặc số liệu.","Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"24":{"cauHoi":[{"cauHoi":"Ở đoạn mở đầu, Phi-lít được giới thiệu như thế nào?","dang":"TN","dapAn":0,"giaiThich":"Cậu bé rất ham học hỏi. Cậu hăng say nghiền ngẫm mọi cuốn sách hay tờ báo mình có được.","id":"V5-B24-01","mucDo":1,"phuongAn":["Sinh ra và lớn lên trong một thị trấn nhỏ cùng bố mẹ và anh trai; rất ham học hỏi, nghiền ngẫm sách báo, lắng nghe chuyện trò để biết thế giới bên ngoài","Ghét việc học","Không thích nghe ai nói","Sống một mình trên núi, không đọc sách"]},{"cauHoi":"Cha Phi-lít yêu cầu cả gia đình làm gì mỗi ngày? Vì sao?","dang":"TN","dapAn":3,"giaiThich":"Để giữ gìn tinh thần học tập, ông yêu cầu mỗi ngày ai cũng phải học được kiến thức mới, rồi trao đổi sau bữa tối.","id":"V5-B24-02","mucDo":2,"phuongAn":["Không được nói chuyện lúc ăn","Chỉ được chơi, không học","Chỉ mẹ phải học, con không cần","Mỗi ngày ai cũng phải học được kiến thức mới, rồi trao đổi với nhau sau bữa tối; vì ông cho rằng điều đáng buồn nhất là cả ngày không học được thứ gì"]},{"cauHoi":"Chi tiết cả nhà xúm lại xem bản đồ tìm Nê-pan cho thấy điều gì?","dang":"TN","dapAn":0,"giaiThich":"Tấm bản đồ được trải ra nền nhà. Cả nhà xúm lại tìm xem Nê-pan ở đâu.","id":"V5-B24-03","mucDo":2,"phuongAn":["Cả gia đình cùng học một cách vui vẻ, mở rộng kiến thức từ một điều con vừa học được","Mẹ cấm mở bản đồ","Cha trách mắng con vì nói sai","Không ai quan tâm Nê-pan ở đâu"]},{"cauHoi":"Phương pháp ấy mang lại lợi ích gì cho Phi-lít sau này?","dang":"TN","dapAn":2,"giaiThich":"Có những kiến thức các giáo sư dạy khá giống với thứ cha từng yêu cầu cậu học, chỉ là phát triển hơn lên.","id":"V5-B24-04","mucDo":2,"phuongAn":["Cậu quên hết những gì đã học","Cậu không vào được đại học","Khi thi đỗ đại học, cậu thấy nhiều kiến thức các giáo sư dạy khá giống điều cha từng yêu cầu, chỉ là phát triển hơn","Cậu trách cha vì phương pháp đó vô ích"]},{"cauHoi":"Trong câu “Dế Mèn phiêu lưu kí – cuốn sách gồm 10 chương – mang đến nhiều cảm xúc”, dấu gạch ngang dùng để làm gì?","dang":"TN","dapAn":1,"giaiThich":"Dấu gạch ngang đặt giữa câu để đánh dấu bộ phận chú thích, giải thích.","id":"V5-B24-05","mucDo":1,"phuongAn":["Thay dấu chấm than","Đánh dấu bộ phận chú thích, giải thích trong câu","Nối tiếng trong từ mượn ba-la-lai-ca","Ngắt câu thành hai câu hỏi"]},{"cauHoi":"Viết 4 – 5 câu nêu điều em muốn điều chỉnh hoặc học tập thêm về cách học của mình sau khi đọc chuyện gia đình nhà Phi-lít.","dang":"TL","giaiThich":"Gợi ý: Mỗi ngày học một điều mới; chia sẻ với người thân; học vui, học cùng nhau.","id":"V5-B24-06","mucDo":3}],"chuDe":"3","ten":"Tinh thần học tập của nhà Phi-lít","tenChuDe":"Chủ điểm 3. Trên con đường học tập","tenGoc":"Bài 24. Tinh thần học tập của nhà Phi-lít","tuan":"12","yeuCauCanDat":["Nhận xét được hình dáng, tính cách của nhân vật; nhận biết thời gian, địa điểm và tác dụng của chúng trong câu chuyện.","Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản.","Công dụng của dấu gạch ngang (đánh dấu bộ phận chú thích, giải thích trong câu) và dấu gạch nối (nối các tiếng trong những từ mượn gồm nhiều tiếng).","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"25":{"cauHoi":[{"cauHoi":"Tám dòng thơ đầu bài “Tiếng đàn ba-la-lai-ca trên sông Đà” miêu tả tiếng đàn như thế nào?","dang":"TN","dapAn":3,"giaiThich":"Tiếng đàn ba-la-lai-ca / Như ngọn gió bình yên... Như ngọn sóng / Vỗ trắng phau ghềnh đá.","id":"V5-B25-01","mucDo":2,"phuongAn":["Như tiếng còi xe giữa phố","Không có hình ảnh so sánh nào","Như tiếng trống trận ồn ào","Như ngọn gió bình yên thổi qua rừng bạch dương; như ngọn sóng vỗ trắng phau ghềnh đá, làm những dòng sông nóng lòng tìm biển cả thêm náo nức"]},{"cauHoi":"Tác giả nghe tiếng đàn trong khung cảnh nào trên công trường thuỷ điện sông Đà?","dang":"TN","dapAn":0,"giaiThich":"Cả công trường say ngủ cạnh dòng sông... Chỉ còn tiếng đàn ngân nga / Với một dòng trăng lấp loáng sông Đà.","id":"V5-B25-02","mucDo":2,"phuongAn":["Một đêm trăng chơi vơi; công trường say ngủ, tháp khoan, xe ủi, xe ben nằm nghỉ; chỉ còn tiếng đàn ngân nga với dòng trăng lấp loáng sông Đà; cô gái Nga mái tóc hạt dẻ, ngón tay đan trên dây đồng","Giữa trưa ồn ào, máy khoan đang chạy","Trong lớp học ở thành phố","Giữa chợ phiên"]},{"cauHoi":"Theo chú thích SGK, ba-la-lai-ca và sông Đà là gì?","dang":"TN","dapAn":2,"giaiThich":"Chú thích SGK: Ba-la-lai-ca: đàn 3 dây của người Nga; sông Đà: phụ lưu lớn nhất của sông Hồng.","id":"V5-B25-03","mucDo":1,"phuongAn":["Ba-la-lai-ca là trống; sông Đà là hồ nước ngọt nhỏ","Không có chú thích","Ba-la-lai-ca: đàn 3 dây của người Nga; sông Đà: phụ lưu lớn nhất của sông Hồng (chảy từ Lai Châu qua Điện Biên, Sơn La, Phú Thọ), nơi có công trình thuỷ điện nhờ chuyên gia Liên Xô","Ba-la-lai-ca là một loài cá; sông Đà ở đồng bằng sông Cửu Long"]},{"cauHoi":"Trong đoạn ca dao “Trông trời, trông đất, trông mây / Trông mưa, trông nắng...”, từ “trông” được lặp lại nhiều lần. Đó là biện pháp gì?","dang":"TN","dapAn":1,"giaiThich":"Điệp từ, điệp ngữ là biện pháp lặp lại từ ngữ để nhấn mạnh nội dung được nói đến.","id":"V5-B25-04","mucDo":1,"phuongAn":["Dấu gạch nối","Điệp từ (điệp ngữ) – lặp lại từ ngữ để nhấn mạnh nội dung","Từ đa nghĩa bắt buộc không lặp","Câu ghép có kết từ “nếu... thì”"]},{"cauHoi":"Hình ảnh cô gái Nga chơi đàn trên công trường gợi cảm nghĩ gì?","dang":"TN","dapAn":1,"giaiThich":"Một cô gái Nga mái tóc màu hạt dẻ / Ngón tay đan trên những sợi dây đồng; chỉ còn tiếng đàn và dòng trăng.","id":"V5-B25-05","mucDo":3,"phuongAn":["Không có ý nghĩa gì","Sự giao cảm bình yên, đẹp đẽ giữa con người (bạn bè quốc tế) với thiên nhiên và công trình trên sông Đà trong đêm trăng","Sự ồn ào, hỗn loạn của ngày thi công","Cô gái đang cấm mọi người nghe nhạc"]},{"cauHoi":"Viết 4 – 5 câu nêu cảm xúc của em khi đọc hai dòng “Chỉ còn tiếng đàn ngân nga / Với một dòng trăng lấp loáng sông Đà”.","dang":"TL","giaiThich":"Gợi ý: Tả lại khung cảnh em hình dung; nêu nét đẹp của âm nhạc giữa thiên nhiên / công trường về đêm.","id":"V5-B25-06","mucDo":3}],"chuDe":"4","ten":"Tiếng đàn ba-la-lai-ca trên sông Đà","tenChuDe":"Chủ điểm 4. Nghệ thuật muôn màu","tenGoc":"Bài 25. Tiếng đàn ba-la-lai-ca trên sông Đà","tuan":"13","yeuCauCanDat":["Nhận biết được văn bản viết theo tưởng tượng và văn bản viết về người thật, việc thật; hiểu từ ngữ, hình ảnh, biện pháp so sánh, nhân hoá trong văn bản.","Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Biện pháp tu từ điệp từ, điệp ngữ: đặc điểm và tác dụng.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"26":{"cauHoi":[{"cauHoi":"Chi tiết nào cho thấy từ nhỏ Giô-an Rô-linh đã có trí tưởng tượng phong phú?","dang":"TN","dapAn":2,"giaiThich":"Chỉ cần nhìn thấy một chú thỏ là Giô-an có ngay một câu chuyện.","id":"V5-B26-01","mucDo":1,"phuongAn":["Cô chỉ học thuộc lòng, không bịa thêm","Cô sợ thỏ, không dám nhìn","Chỉ cần nhìn thấy một chú thỏ là cô có ngay câu chuyện kể cho em gái (thỏ bị sốt, cô ong mang bánh quy mật ong,...)","Cô không bao giờ kể chuyện"]},{"cauHoi":"Cô ấp ủ ước mơ trở thành nhà văn từ khi nào và đã làm gì?","dang":"TN","dapAn":0,"giaiThich":"Giô-an nghĩ cô nên viết ra câu chuyện... Đó cũng là lần đầu tiên Giô-an ấp ủ ước mơ trở thành nhà văn.","id":"V5-B26-02","mucDo":1,"phuongAn":["Từ lần viết ra câu chuyện “Chú thỏ con” vì em gái nhắc cô kể khác hôm trước; cô bắt đầu ghi những câu chuyện mới vào một cuốn sổ","Từ khi tốt nghiệp đại học mới nghĩ đến viết","Cô không viết gì ra giấy","Cô chỉ kể miệng, không bao giờ ghi lại"]},{"cauHoi":"Ý tưởng về Ha-ri Pót-tơ đến với cô trong tình huống nào?","dang":"TN","dapAn":3,"giaiThich":"Ngồi trên tàu, nhìn ra cửa sổ, cô chợt nghĩ tới hình ảnh một cậu bé với cặp kính và một vết sẹo hình tia chớp trên trán.","id":"V5-B26-03","mucDo":1,"phuongAn":["Khi đọc bản đồ tìm Nê-pan","Khi đang đá bóng trên sân","Khi vẽ quả trứng","Sau khi tốt nghiệp, một lần ngồi trên tàu, nhìn ra cửa sổ, cô nghĩ tới cậu bé đeo kính, có vết sẹo hình tia chớp trên trán; cả đoàn tàu như đi vào thế giới phép thuật"]},{"cauHoi":"Tập truyện đầu “Ha-ri Pót-tơ và hòn đá phù thuỷ” được đón nhận như thế nào?","dang":"TN","dapAn":3,"giaiThich":"Cô gửi bản thảo đến nhiều nhà xuất bản nhưng đều bị từ chối. Rất may, một nhà xuất bản đã nhận lời... thu hút sự chú ý của rất nhiều trẻ em.","id":"V5-B26-04","mucDo":1,"phuongAn":["Chỉ in đúng 10 bản rồi dừng","Không ai đọc","Bị cấm ngay từ đầu","Bản thảo từng bị nhiều nhà xuất bản từ chối; khi được xuất bản, cuốn sách thu hút rất nhiều trẻ em trên thế giới, Giô-an trở thành nhà văn nổi tiếng"]},{"cauHoi":"Theo chú thích SGK, Giô-an Rô-linh thường được biết đến với bút danh nào?","dang":"TN","dapAn":2,"giaiThich":"Chú thích: Giô-an Rô-linh (thường được biết đến với bút danh J.K. Rô-linh): nhà văn người Anh.","id":"V5-B26-05","mucDo":1,"phuongAn":["Tô Hoài","An-đéc-xen","J.K. Rô-linh (nhà văn người Anh, tác giả bộ truyện Ha-ri Pót-tơ)","Nguyễn Nhật Ánh"]},{"cauHoi":"Viết 4 – 5 câu nêu vì sao, theo em, nhà văn Giô-an Rô-linh viết được cuốn sách có sức hấp dẫn lớn (trí tưởng tượng, kiên trì, quan sát,...).","dang":"TL","giaiThich":"Gợi ý: Tưởng tượng từ nhỏ; ghi chép; ý tưởng trên tàu; không bỏ cuộc khi bị từ chối. Có thể dẫn lời: “Nếu không sáng tác, tôi sẽ không thể ngủ ngon.”","id":"V5-B26-06","mucDo":3},{"cauHoi":"Vì sao chi tiết “chỉ cần nhìn thấy một chú thỏ là Giô-an có ngay một câu chuyện kể cho em gái” được kể ngay từ đầu bài?","dang":"TN","dapAn":1,"giaiThich":"Một chú thỏ tình cờ nhìn thấy cũng lập tức biến thành cả một câu chuyện có thỏ bị sốt, có cô ong mang bánh quy mật ong — chi tiết mở đầu này chứng tỏ trí tưởng tượng của nhà văn tương lai đã rất phong phú ngay từ thuở nhỏ.","id":"TV5-B26-BS01","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Để giới thiệu với người đọc về loài thỏ trong rừng","Để cho thấy trí tưởng tượng phong phú của Giô-an đã bộc lộ từ khi cô còn rất nhỏ","Để kể một câu chuyện cười cho em gái của Giô-an","Để giải thích vì sao Giô-an thích nuôi thỏ"]},{"cauHoi":"Bản thảo “Ha-ri Pót-tơ” từng bị nhiều nhà xuất bản từ chối, nhưng Giô-an Rô-linh vẫn kiên trì gửi tiếp. Điều đó cho thấy cô là người như thế nào?","dang":"TN","dapAn":2,"giaiThich":"Bị từ chối nhiều lần mà vẫn tiếp tục gửi bản thảo đi, Giô-an cho thấy niềm tin vào câu chuyện của mình và ý chí không bỏ cuộc — nhờ vậy cuốn sách mới đến được với trẻ em khắp thế giới.","id":"TV5-B26-BS02","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Cô không quan tâm người khác nghĩ gì về truyện của mình","Cô định bỏ viết văn để làm nghề khác","Cô tin vào câu chuyện của mình và không bỏ cuộc khi gặp khó khăn","Cô chỉ viết truyện cho riêng mình đọc"]}],"chuDe":"4","ten":"Trí tưởng tượng phong phú","tenChuDe":"Chủ điểm 4. Nghệ thuật muôn màu","tenGoc":"Bài 26. Trí tưởng tượng phong phú","tuan":"13","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nhận xét được hình dáng, tính cách của nhân vật; nhận biết thời gian, địa điểm và tác dụng của chúng trong câu chuyện.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện."]},"27":{"cauHoi":[{"cauHoi":"Những bức tranh làng Hồ nào được nhắc tới trong bài Nguyễn Tuân?","dang":"TN","dapAn":1,"giaiThich":"Những tranh lợn, gà, chuột, ếch, tranh cây dừa, tranh tố nữ của làng Hồ.","id":"V5-B27-01","mucDo":1,"phuongAn":["Chỉ có tranh phong cảnh phố thị hiện đại","Tranh lợn, gà, chuột, ếch, tranh cây dừa, tranh tố nữ; cụ thể có tranh lợn ráy (lợn ăn cây ráy), Đàn gà mẹ con (và ở phần minh hoạ: Vinh quy bái tổ, Đám cưới chuột)","Chỉ có ảnh chụp núi lửa","Không nêu tên bức nào"]},{"cauHoi":"Hai bức tranh lợn ăn cây ráy và Đàn gà mẹ con được miêu tả thế nào?","dang":"TN","dapAn":0,"giaiThich":"Phải yêu mến cuộc đời trồng trọt, chăn nuôi lắm mới khắc được những tranh lợn ráy có những khoáy âm dương rất có duyên, mới vẽ được những đàn gà con tưng bừng như ca múa.","id":"V5-B27-02","mucDo":1,"phuongAn":["Tranh lợn ráy có những khoáy âm dương rất có duyên; đàn gà con tưng bừng như ca múa bên gà mái mẹ – cho thấy tình yêu đời sống trồng trọt, chăn nuôi","Chỉ vẽ nhà cao tầng","Không tả gì về lợn, gà","Hai bức đều vẽ biển và tàu"]},{"cauHoi":"Kĩ thuật tạo màu của tranh làng Hồ có gì đặc biệt?","dang":"TN","dapAn":0,"giaiThich":"Màu đen luyện bằng bột than của rơm bếp, cói chiếu và lá tre; màu trắng điệp từ vỏ sò, vỏ điệp.","id":"V5-B27-03","mucDo":1,"phuongAn":["Màu đen lĩnh không pha bằng thuốc mà luyện bằng bột than từ rơm bếp, cói chiếu, lá tre mùa thu; màu trắng điệp từ bột vỏ sò, vỏ điệp trộn hồ bột nếp, hạt cát điệp nhấp nhánh như phấn","Chỉ vẽ bằng bút chì, không màu","Màu mua sẵn ở cửa hàng hoá chất hiện đại, không liên quan đồng quê","Không dùng màu trắng"]},{"cauHoi":"Theo chú thích SGK, làng Hồ (làng Đông Hồ) thuộc đâu?","dang":"TN","dapAn":2,"giaiThich":"Chú thích: Làng Hồ (làng Đông Hồ): thuộc phường Thuận Thành, tỉnh Bắc Ninh, chuyên nghề làm tranh.","id":"V5-B27-04","mucDo":1,"phuongAn":["Quận Ba Đình, Hà Nội","Tỉnh Quảng Trị","Phường Thuận Thành, tỉnh Bắc Ninh, chuyên nghề làm tranh","Bờ sông Đà, Phú Thọ"]},{"cauHoi":"Tác giả biết ơn những người nghệ sĩ dân gian làng Hồ vì điều gì đã được viết rõ trong bài?","dang":"TN","dapAn":1,"giaiThich":"Lòng tôi thấm thía một nỗi biết ơn... Họ đã đem vào cuộc sống một cách nhìn thuần phác, càng ngắm càng thấy đậm đà, lành mạnh, hóm hỉnh và tươi vui.","id":"V5-B27-05","mucDo":2,"phuongAn":["Vì tranh không có màu","Họ đem vào cuộc sống một cách nhìn thuần phác, đậm đà, lành mạnh, hóm hỉnh, tươi vui; kĩ thuật trang trí tinh tế, gắn với tình yêu đồng quê","Vì họ không liên quan đến nhân dân","Vì họ vẽ rất ít, không ai xem"]},{"cauHoi":"Viết 4 – 5 câu nêu cảm nhận của em khi “ngắm” những bức tranh làng Hồ được tả trong bài (có thể chọn lợn ráy, đàn gà, tố nữ, đám cưới chuột).","dang":"TL","giaiThich":"Gợi ý: Nêu một bức; nét đẹp (hóm hỉnh, màu điệp, tình yêu đồng quê); cảm xúc.","id":"V5-B27-06","mucDo":3},{"cauHoi":"Vì sao Nguyễn Tuân cho rằng phải “yêu mến cuộc đời trồng trọt, chăn nuôi lắm” mới khắc được những bức tranh lợn, gà “rất có duyên” như tranh làng Hồ?","dang":"TN","dapAn":3,"giaiThich":"Những khoáy âm dương trên lưng lợn, đàn gà con tưng bừng như ca múa bên gà mẹ — vẻ đẹp ấy chỉ người thật sự yêu đời sống trồng trọt, chăn nuôi mới nhìn ra và khắc được. Tình yêu cuộc sống lao động là nguồn cảm hứng của nghệ sĩ dân gian làng Hồ.","id":"TV5-B27-BS01","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Vì chỉ những người nông dân mới được học nghề làm tranh làng Hồ","Vì lợn và gà là hai con vật khó vẽ nhất trong hội hoạ","Vì tranh làng Hồ chỉ vẽ duy nhất về trồng trọt và chăn nuôi","Vì tình yêu đời sống lao động giúp người nghệ sĩ nhìn ra vẻ đẹp gần gũi, hóm hỉnh trong những con vật quen thuộc quanh mình"]}],"chuDe":"4","ten":"Tranh làng Hồ","tenChuDe":"Chủ điểm 4. Nghệ thuật muôn màu","tenGoc":"Bài 27. Tranh làng Hồ","tuan":"14","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nhận biết được những chi tiết tiêu biểu và các thông tin chính của văn bản thông tin; xác định đề tài từ nhan đề, đề mục; nhận biết mục đích, đặc điểm, bố cục của văn bản giải thích, giới thiệu sách hoặc phim, quảng cáo, chương trình hoạt động; vai trò của hình ảnh, kí hiệu hoặc số liệu.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"28":{"cauHoi":[{"cauHoi":"Các liền chị tập hát quan họ trong khung cảnh nào?","dang":"TN","dapAn":3,"giaiThich":"Trong khung cảnh thơ mộng ấy, chúng tôi được nghe các cô gái tập hát quan họ dưới sự chỉ dẫn của bà Trưởng. Tôi vẫn nhớ những buổi tập hát trong vườn táo mùa xuân.","id":"V5-B28-01","mucDo":1,"phuongAn":["Trên công trường thuỷ điện","Giữa sa mạc","Trong nhà hát lớn ở thành phố vào đêm đông","Ngày nào cũng đến nhà bà Trưởng (nguyên trưởng bè quan họ nữ): đường cong, hoa tầm xuân, hồ sen, vườn táo cổ thụ; mùa xuân tập trong vườn táo, trời se se, nắng ấm"]},{"cauHoi":"Bà Trưởng dạy mỗi điệu quan họ ra sao?","dang":"TN","dapAn":2,"giaiThich":"Điệu Ngỏ lời phải hát với giọng thẹn thùng, e ấp... Thương nhau phải hát nồng cháy, thiết tha... Giã bạn... giọng lưu luyến, dùng dằng, đau đáu.","id":"V5-B28-02","mucDo":1,"phuongAn":["Chỉ tập đúng một điệu quanh năm","Cả ba điệu đều hát rất nhanh, to, không phân biệt","Điệu Ngỏ lời: giọng thẹn thùng, e ấp, như nước suối thượng nguồn trong vắt; điệu Thương nhau (đêm trăng mùa hè): nồng cháy, thiết tha, lấy hơi, nhả chữ, ngân rung luyến láy; điệu Giã bạn (cuối thu): lưu luyến, dùng dằng, đau đáu, buồn","Không dạy lấy hơi"]},{"cauHoi":"Những chi tiết nào cho thấy nhân vật “tôi” say mê quan họ?","dang":"TN","dapAn":3,"giaiThich":"Tâm trí tôi vẫn cứ ngân nga điệp khúc da diết... Tôi vẫn mong ngóng đến ngày điệp khúc đó sẽ được ngân lên bằng giọng hát của chính tôi.","id":"V5-B28-03","mucDo":1,"phuongAn":["Tôi cấm các chị hát","Tôi chỉ ghé một lần rồi quên","Tôi không thích điệu Giã bạn","Ngày nào cũng đến nghe tập; ra về vẫn ngân nga điệp khúc “Quan họ nghỉ, chúng em ra về...” của điệu Giã bạn; mong đến ngày chính mình được hát, không chỉ vang trong tâm trí"]},{"cauHoi":"Theo chú thích SGK, “liền chị” nghĩa là gì?","dang":"TN","dapAn":0,"giaiThich":"Chú thích: Liền chị: người nữ hát quan họ.","id":"V5-B28-04","mucDo":1,"phuongAn":["Người nữ hát quan họ","Người quản phường rối nước","Người đánh trống","Người vẽ tranh làng Hồ"]},{"cauHoi":"Câu “tôi vẫn cứ ngân nga điệp khúc da diết” có từ “điệp khúc”. “Điệp từ, điệp ngữ” trong tiếng Việt là gì?","dang":"TN","dapAn":1,"giaiThich":"Điệp từ, điệp ngữ là biện pháp lặp lại từ ngữ để nhấn mạnh nội dung được nói đến.","id":"V5-B28-05","mucDo":1,"phuongAn":["Cách viết tên người nước ngoài","Biện pháp lặp lại từ ngữ để nhấn mạnh nội dung được nói đến","Dấu dùng để chú thích","Từ chỉ sự vật"]},{"cauHoi":"Viết 4 – 5 câu nêu cảm nhận của em về nghệ thuật hát quan họ qua bài “Tập hát quan họ”.","dang":"TL","giaiThich":"Gợi ý: Khung cảnh nhà bà Trưởng; cách bà dạy từng điệu; sự lưu luyến của điệu Giã bạn; tình yêu nghệ thuật của nhân vật “tôi”.","id":"V5-B28-06","mucDo":3},{"cauHoi":"Bà Trưởng dạy điệu “Giã bạn” phải hát với giọng lưu luyến, dùng dằng, đau đáu. Vì sao điệu hát này cần một giọng hát như vậy?","dang":"TN","dapAn":1,"giaiThich":"“Giã bạn” là lời hát tiễn biệt ở cuối buổi. Giọng lưu luyến, dùng dằng, đau đáu diễn tả đúng tâm trạng của người hát: muốn níu giữ thêm khoảnh khắc bên nhau, buồn vì sắp phải chia xa.","id":"TV5-B28-BS01","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Vì trời cuối thu se lạnh nên giọng người hát run lên","Vì đây là điệu hát lúc chia tay, gói trọn nỗi buồn và sự bịn rịn khi phải xa nhau","Vì người hát đã mệt sau cả buổi tập hát","Vì điệu Giã bạn là điệu khó hát nhất trong quan họ"]},{"cauHoi":"Hình ảnh so sánh giọng điệu “Ngỏ lời” với “nước suối thượng nguồn trong vắt” gợi cho em cảm nhận gì về điệu hát này?","dang":"TN","dapAn":3,"giaiThich":"Nước suối ở thượng nguồn trong vắt, chảy nhẹ nhàng. So sánh như vậy, tác giả gợi giọng hát Ngỏ lời trong trẻo, e ấp — đúng với lời ngỏ làm quen thẹn thùng của liền anh, liền chị.","id":"TV5-B28-BS02","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Giọng hát to, vang xa như tiếng thác đổ","Giọng hát buồn và chậm rãi như dòng sông lững lờ","Giọng hát nhanh, gấp gáp như nước chảy xiết","Giọng hát trong trẻo, nhẹ nhàng, thẹn thùng kín đáo như tình cảm mới chớm của người mới làm quen"]}],"chuDe":"4","ten":"Tập hát quan họ","tenChuDe":"Chủ điểm 4. Nghệ thuật muôn màu","tenGoc":"Bài 28. Tập hát quan họ","tuan":"14","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nhận xét được hình dáng, tính cách của nhân vật; nhận biết thời gian, địa điểm và tác dụng của chúng trong câu chuyện.","Biện pháp tu từ điệp từ, điệp ngữ: đặc điểm và tác dụng.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện."]},"29":{"cauHoi":[{"cauHoi":"Tờ quảng cáo cho biết những thông tin nào về bộ phim “Chú ốc sên bay”?","dang":"TN","dapAn":0,"giaiThich":"Hãng phim Hoạt hình Việt Nam trân trọng giới thiệu... Khởi chiếu từ ngày 28.5.2022 tại Trung tâm Chiếu phim Quốc gia.","id":"V5-B29-01","mucDo":1,"phuongAn":["Phim hoạt hình của Hãng phim Hoạt hình Việt Nam; khởi chiếu từ 28.5.2022 tại Trung tâm Chiếu phim Quốc gia","Phim ca nhạc, chiếu ở sân trường","Phim tài liệu của một hãng nước ngoài, chiếu năm 1945","Không nêu ngày, nơi chiếu"]},{"cauHoi":"Nội dung và kĩ xảo của phim được giới thiệu thế nào?","dang":"TN","dapAn":2,"giaiThich":"Mỗi tập phim (với độ dài 10 phút)... Công nghệ 3D vô cùng chân thực, bắt mắt, sống động.","id":"V5-B29-02","mucDo":1,"phuongAn":["Phim đen trắng, không có nhân vật","Ốc sên không bao giờ được bay","Chú ốc sên khát vọng bay đi khám phá thế giới, được nhà khoa học trẻ gắn đôi cánh; mỗi tập khoảng 10 phút; kĩ xảo công nghệ 3D chân thực, bắt mắt, sống động","Mỗi tập dài 2 giờ, không có kĩ xảo"]},{"cauHoi":"Chi tiết nào trong tờ quảng cáo nhằm thu hút khán giả?","dang":"TN","dapAn":1,"giaiThich":"Để quảng bá phim hoạt hình Việt Nam, 5 tập đầu của bộ phim sẽ được khởi chiếu với giá vé 0 đồng.","id":"V5-B29-03","mucDo":1,"phuongAn":["Không nêu nội dung phim","Các từ ngữ mang tính hấp dẫn (đặc sắc, hấp dẫn, dí dỏm, thú vị, chân thực, bắt mắt...) và ưu đãi: 5 tập đầu khởi chiếu với giá vé 0 đồng để quảng bá phim hoạt hình Việt Nam","Không mời khán giả đến rạp","Chỉ ghi giá vé rất cao, không ưu đãi"]},{"cauHoi":"Tờ quảng cáo thuộc kiểu văn bản thông tin nào?","dang":"TN","dapAn":3,"giaiThich":"CT: nhận biết mục đích, đặc điểm của văn bản quảng cáo.","id":"V5-B29-04","mucDo":1,"phuongAn":["Thư riêng của Bác Hồ","Biên bản họp lớp","Đơn xin phép","Văn bản quảng cáo (giới thiệu phim, nhằm thu hút người xem)"]},{"cauHoi":"Các từ như “mặc dù... nhưng”, “không những... mà còn”, “nếu... thì” được gọi là gì?","dang":"TN","dapAn":0,"giaiThich":"SGK: Có những kết từ dùng theo cặp như: mặc dù... nhưng,...","id":"V5-B29-05","mucDo":1,"phuongAn":["Cặp kết từ (dùng để nối các vế, các bộ phận của câu)","Dấu gạch ngang","Điệp từ bắt buộc","Danh từ riêng"]},{"cauHoi":"Viết 4 – 5 câu giới thiệu (theo hướng quảng cáo ngắn) một bộ phim hoạt hình em yêu thích, có dùng ít nhất một kết từ.","dang":"TL","giaiThich":"Gợi ý: Tên phim, thể loại, nội dung hấp dẫn; vì sao nên xem; dùng kết từ (vì, nhưng, không những... mà còn...).","id":"V5-B29-06","mucDo":3},{"cauHoi":"Vì sao Hãng phim Hoạt hình Việt Nam lại chiếu 5 tập đầu của “Chú ốc sên bay” với giá vé 0 đồng?","dang":"TN","dapAn":1,"giaiThich":"Tờ quảng cáo ghi rõ: để quảng bá phim hoạt hình Việt Nam, 5 tập đầu được khởi chiếu với giá vé 0 đồng. Vé miễn phí là cách thu hút khán giả đến rạp, làm quen và yêu thích bộ phim.","id":"TV5-B29-BS01","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Vì năm tập đầu làm chưa hay nên không bán vé","Để thu hút thật nhiều khán giả đến xem, quảng bá và lan toả tình yêu phim hoạt hình Việt Nam","Vì rạp chiếu phim còn thừa quá nhiều ghế trống","Vì mỗi tập phim quá ngắn, chỉ khoảng 10 phút"]},{"cauHoi":"Chú ốc sên vốn chậm chạp, nhỏ bé nhưng khát khao bay đi khám phá thế giới và được gắn đôi cánh. Câu chuyện trong phim muốn gửi gắm điều gì?","dang":"TN","dapAn":3,"giaiThich":"Ốc sên là loài bò chậm nhất, vậy mà nhờ khát vọng khám phá và đôi cánh do nhà khoa học trẻ gắn cho, chú đã bay được. Câu chuyện khích lệ mỗi người dám ước mơ và nỗ lực vươn lên dù xuất phát điểm nhỏ bé.","id":"TV5-B29-BS02","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Ốc sên thì nên ở yên một chỗ cho an toàn","Chỉ có nhà khoa học mới làm được những việc lớn lao","Bay lên trời là việc rất nguy hiểm, không nên mơ ước","Dù nhỏ bé, chậm chạp, nếu có ước mơ và được mọi người giúp đỡ, ta vẫn có thể vươn tới những điều tưởng như không thể"]}],"chuDe":"4","ten":"Phim hoạt hình Chú ốc sên bay","tenChuDe":"Chủ điểm 4. Nghệ thuật muôn màu","tenGoc":"Bài 29. Phim hoạt hình Chú ốc sên bay","tuan":"15","yeuCauCanDat":["Nhận biết được những chi tiết tiêu biểu và các thông tin chính của văn bản thông tin; xác định đề tài từ nhan đề, đề mục; nhận biết mục đích, đặc điểm, bố cục của văn bản giải thích, giới thiệu sách hoặc phim, quảng cáo, chương trình hoạt động; vai trò của hình ảnh, kí hiệu hoặc số liệu.","Đại từ và kết từ: đặc điểm và chức năng; ôn luyện danh từ, động từ, tính từ.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"3":{"cauHoi":[{"cauHoi":"Bài thơ “Tuổi Ngựa” (Xuân Quỳnh) mở đầu bằng cuộc trò chuyện nào?","dang":"TN","dapAn":1,"giaiThich":"Mẹ ơi, con tuổi gì? – Tuổi con là tuổi Ngựa / Ngựa không yên một chỗ / Tuổi con là tuổi đi.","id":"V5-B03-01","mucDo":1,"phuongAn":["Mẹ hỏi con muốn ăn gì","Bạn nhỏ hỏi mẹ mình tuổi gì; mẹ đáp tuổi Ngựa – tuổi đi, không yên một chỗ","Bạn hỏi mẹ về bài học","Bạn hỏi bố về ngựa thật"]},{"cauHoi":"Theo trí tưởng tượng, chú ngựa con sẽ đi qua những đâu?","dang":"TN","dapAn":3,"giaiThich":"Con sẽ phi qua bao nhiêu ngọn gió; ngựa con sẽ đi khắp trên những cánh đồng hoa.","id":"V5-B03-02","mucDo":2,"phuongAn":["Chỉ quanh sân nhà","Chỉ trên mặt biển","Không đi đâu cả","Qua gió xanh trung du, gió hồng đất đỏ, gió đen đại ngàn; khắp cánh đồng hoa (hoa mơ, hoa huệ, cúc dại)"]},{"cauHoi":"Đoạn thơ cuối, bạn nhỏ muốn nói với mẹ điều gì?","dang":"TN","dapAn":0,"giaiThich":"Dẫu cách núi cách rừng... Con tìm về với mẹ / Ngựa con vẫn nhớ đường.","id":"V5-B03-03","mucDo":2,"phuongAn":["Dẫu cách núi, rừng, sông, biển, con vẫn tìm về với mẹ; ngựa con vẫn nhớ đường","Con sẽ không bao giờ về","Con quên đường về","Mẹ đừng chờ con"]},{"cauHoi":"Trong câu thơ “Mẹ ơi, con tuổi gì?”, từ “con” được dùng để làm gì?","dang":"TN","dapAn":1,"giaiThich":"Đại từ xưng hô: con – mẹ.","id":"V5-B03-04","mucDo":1,"phuongAn":["Chỉ một con vật cụ thể trong chuồng","Xưng hô (đại từ, tự xưng của bạn nhỏ với mẹ)","Là kết từ nối câu","Là tính từ"]},{"cauHoi":"Qua bài thơ, bạn nhỏ hiện lên với vẻ đẹp nào?","dang":"TN","dapAn":2,"giaiThich":"Tuổi Ngựa là tuổi đi; nhưng mẹ ơi đừng buồn, con vẫn nhớ đường về.","id":"V5-B03-05","mucDo":3,"phuongAn":["Không quan tâm đến mẹ","Sợ gió và núi","Yêu tự do, muốn đi nhiều miền, nhưng vẫn gắn bó, nhớ về mẹ","Chỉ muốn ở yên một chỗ"]},{"cauHoi":"Viết 4 – 5 câu nêu cảm xúc của em về lời hứa “Ngựa con vẫn nhớ đường” trong bài thơ “Tuổi Ngựa”.","dang":"TL","giaiThich":"Gợi ý: Nêu cảm xúc; giải thích vì sao lời ấy đáng nhớ; liên hệ với tình cảm gia đình.","id":"V5-B03-06","mucDo":3}],"chuDe":"1","ten":"Tuổi Ngựa","tenChuDe":"Chủ điểm 1. Thế giới tuổi thơ","tenGoc":"Bài 3. Tuổi Ngựa","tuan":"2","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Đại từ và kết từ: đặc điểm và chức năng; ôn luyện danh từ, động từ, tính từ.","Nhận xét được hình dáng, tính cách của nhân vật; nhận biết thời gian, địa điểm và tác dụng của chúng trong câu chuyện."]},"30":{"cauHoi":[{"cauHoi":"Nghệ thuật múa ba lê được giới thiệu như thế nào?","dang":"TN","dapAn":3,"giaiThich":"Ba lê là môn nghệ thuật múa có nguồn gốc từ châu Âu... thể loại vũ kịch có sự kết hợp giữa kịch, âm nhạc và vũ đạo.","id":"V5-B30-01","mucDo":1,"phuongAn":["Môn võ thuật của Việt Nam","Một điệu quan họ","Một loại đàn 3 dây của người Nga","Môn nghệ thuật múa có nguồn gốc từ châu Âu; được biết đến qua những vở ba lê – vũ kịch kết hợp kịch, âm nhạc và vũ đạo"]},{"cauHoi":"Nội dung các vở ba lê nổi tiếng (Hồ thiên nga, Người đẹp ngủ trong rừng, Lọ Lem,...) ca ngợi điều gì?","dang":"TN","dapAn":2,"giaiThich":"Mỗi vở kịch là một câu chuyện ca ngợi tình yêu, sự thánh thiện và ước mơ vươn tới những điều tốt đẹp.","id":"V5-B30-02","mucDo":2,"phuongAn":["Cách nấu ăn","Chiến trận và máy móc","Tình yêu, sự thánh thiện và ước mơ vươn tới những điều tốt đẹp","Nội quy thư viện"]},{"cauHoi":"Trong các vở ba lê, diễn viên thể hiện nội dung bằng cách nào? Điều đó được thể hiện ra sao trong “Hồ thiên nga”?","dang":"TN","dapAn":1,"giaiThich":"Người diễn viên dùng động tác múa để thể hiện nội dung thay cho lời nói... đứng một chân xoay liên tục tới 32 vòng trên đầu mũi chân.","id":"V5-B30-03","mucDo":2,"phuongAn":["Chỉ chiếu chữ lên màn hình, không diễn","Dùng động tác múa thay lời nói; trong Hồ thiên nga: xoay người đẹp mắt, bước đi nhẹ như cánh hoa, diễn viên chính đứng một chân xoay tới 32 vòng trên đầu mũi chân","Chỉ đứng nói thoại, không múa","Chỉ hát quan họ"]},{"cauHoi":"Vì sao diễn viên múa ba lê phải dày công khổ luyện?","dang":"TN","dapAn":1,"giaiThich":"Để thực hiện được những kĩ thuật rất khó này, người diễn viên phải dày công khổ luyện trong một thời gian dài.","id":"V5-B30-04","mucDo":2,"phuongAn":["Vì ba lê không cần kĩ thuật","Vì phải thực hiện những kĩ thuật rất khó (xoay, đứng mũi chân,...) một cách chuẩn xác để khán giả cảm nhận được nội dung, cảm xúc của nhân vật","Vì khán giả không nhìn động tác","Vì diễn viên không được tập"]},{"cauHoi":"Sắp xếp đúng trật tự thông tin trong bài đọc:","dang":"TN","dapAn":0,"giaiThich":"Bài đi từ khái niệm, nguồn gốc → nội dung vở nổi tiếng → cách thể hiện (Hồ thiên nga) → ba lê được dạy rộng rãi hiện nay.","id":"V5-B30-05","mucDo":1,"phuongAn":["Thông tin chung về nghệ thuật múa ba lê → Nội dung các vở ba lê → Cách thể hiện nội dung trong các vở ba lê → Sự phổ biến của múa ba lê hiện nay","Sự phổ biến hiện nay đứng đầu bài, rồi mới nói nguồn gốc","Nội dung vở đứng trước phần giới thiệu chung","Chỉ nói cách thể hiện, không nói nguồn gốc"]},{"cauHoi":"Viết đoạn văn (4 – 5 câu) nêu cảm nghĩ của em về nghệ thuật múa ba lê (có thể gắn với vở “Hồ thiên nga” và sự khổ luyện của diễn viên).","dang":"TL","giaiThich":"Gợi ý: Nguồn gốc, nội dung đẹp; động tác thay lời nói; phải khổ luyện mới thực hiện được kĩ thuật khó.","id":"V5-B30-06","mucDo":3}],"chuDe":"4","ten":"Nghệ thuật múa ba lê","tenChuDe":"Chủ điểm 4. Nghệ thuật muôn màu","tenGoc":"Bài 30. Nghệ thuật múa ba lê","tuan":"15","yeuCauCanDat":["Nhận biết được những chi tiết tiêu biểu và các thông tin chính của văn bản thông tin; xác định đề tài từ nhan đề, đề mục; nhận biết mục đích, đặc điểm, bố cục của văn bản giải thích, giới thiệu sách hoặc phim, quảng cáo, chương trình hoạt động; vai trò của hình ảnh, kí hiệu hoặc số liệu.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"31":{"cauHoi":[{"cauHoi":"Chùa Một Cột ở đâu và được xây dựng vào năm nào, thời vua nào?","dang":"TN","dapAn":2,"giaiThich":"Ở quận Ba Đình – trung tâm Thủ đô Hà Nội – có một ngôi chùa được xây dựng năm 1049, thời vua Lý Thái Tông.","id":"V5-B31-01","mucDo":1,"phuongAn":["Ở phường Thuận Thành, Bắc Ninh, năm 1945","Ở bờ sông Đà, năm 1452","Ở quận Ba Đình, trung tâm Thủ đô Hà Nội; xây năm 1049, thời vua Lý Thái Tông","Ở Đan Mạch, thế kỉ XIX"]},{"cauHoi":"Vì sao chùa có tên Một Cột và Liên Hoa Đài?","dang":"TN","dapAn":3,"giaiThich":"Chùa ngự trên một cột đá tròn... Nhìn từ xa, chùa Một Cột tựa đoá sen khổng lồ vươn lên từ mặt nước... ban đầu chùa có tên gọi là Liên Hoa Đài.","id":"V5-B31-02","mucDo":2,"phuongAn":["Vì chùa không có mái","Vì chùa có một trăm cột vuông, không liên quan đến sen","Vì chùa xây trên núi, không có nước","Vì chùa ngự trên một cột đá tròn (tám thanh gỗ bao quanh trụ đá giống hình đài sen); nhìn từ xa tựa đoá sen khổng lồ vươn lên từ mặt nước, nên ban đầu gọi là Liên Hoa Đài"]},{"cauHoi":"Ngoài nét “một cột”, chùa còn có những nét cổ kính nào? Năm 2012 chùa được xác nhận điều gì?","dang":"TN","dapAn":0,"giaiThich":"Nóc chùa được trang trí hai con rồng chầu mặt nguyệt. Năm 2012... “Ngôi chùa có kiến trúc độc đáo nhất châu Á”.","id":"V5-B31-03","mucDo":1,"phuongAn":["Nóc trang trí hai con rồng chầu mặt nguyệt, bốn mái cong mềm mại, nổi bật giữa cây xanh và hồ nước; năm 2012, Tổ chức Kỉ lục châu Á xác nhận là “Ngôi chùa có kiến trúc độc đáo nhất châu Á”","Chùa không đứng cạnh hồ","Chùa không có rồng, mái thẳng, chưa được ghi nhận","Chùa mới xây năm 2012"]},{"cauHoi":"Trong câu “Chùa Một Cột – di tích văn hoá vô giá – đã trở thành một biểu tượng của Thủ đô Hà Nội”, dấu gạch ngang dùng để làm gì?","dang":"TN","dapAn":3,"giaiThich":"Bộ phận “di tích văn hoá vô giá” là phần chú thích, giải thích, được đánh dấu bằng dấu gạch ngang.","id":"V5-B31-04","mucDo":1,"phuongAn":["Nối các tiếng của từ mượn","Thay dấu chấm hỏi","Đánh dấu hết bài","Đánh dấu bộ phận chú thích, giải thích trong câu"]},{"cauHoi":"Các từ “vì”, “nên”, “và” trong câu giải thích tên chùa thuộc từ loại nào?","dang":"TN","dapAn":2,"giaiThich":"Kết từ dùng để nối các vế, các bộ phận của câu.","id":"V5-B31-05","mucDo":1,"phuongAn":["Đại từ xưng hô","Danh từ riêng","Kết từ (nối các bộ phận, các ý trong câu)","Điệp từ bắt buộc"]},{"cauHoi":"Hãy tóm tắt bài “Một ngôi chùa độc đáo” thành một đoạn 4 – 5 câu theo 3 phần: giới thiệu chung – nét độc đáo, cổ kính – giá trị của ngôi chùa.","dang":"TL","giaiThich":"Gợi ý: 1049, Lý Thái Tông, Ba Đình; một cột / đài sen; rồng chầu mặt nguyệt; biểu tượng Hà Nội, kỉ lục 2012.","id":"V5-B31-06","mucDo":3},{"cauHoi":"Hình ảnh “hai con rồng chầu mặt nguyệt” trên nóc chùa, bốn mái cong mềm mại nổi bật giữa cây xanh và hồ nước góp phần tạo nên vẻ đẹp gì của chùa Một Cột?","dang":"TN","dapAn":1,"giaiThich":"Rồng chầu mặt nguyệt, mái cong mềm mại là những nét trang trí cổ kính; chùa lại ngự giữa hồ nước và cây xanh. Tất cả hoà quyện tạo nên vẻ đẹp cổ kính mà hài hoà với thiên nhiên của ngôi chùa độc đáo nhất châu Á.","id":"TV5-B31-BS01","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Vẻ đẹp hiện đại, hoành tráng như những toà nhà cao tầng","Vẻ đẹp cổ kính, hài hoà với thiên nhiên xung quanh","Vẻ đẹp bí hiểm, khó lại gần","Vẻ đẹp đơn sơ, không có trang trí gì"]}],"chuDe":"4","ten":"Một ngôi chùa độc đáo","tenChuDe":"Chủ điểm 4. Nghệ thuật muôn màu","tenGoc":"Bài 31. Một ngôi chùa độc đáo","tuan":"16","yeuCauCanDat":["Nhận biết được những chi tiết tiêu biểu và các thông tin chính của văn bản thông tin; xác định đề tài từ nhan đề, đề mục; nhận biết mục đích, đặc điểm, bố cục của văn bản giải thích, giới thiệu sách hoặc phim, quảng cáo, chương trình hoạt động; vai trò của hình ảnh, kí hiệu hoặc số liệu.","Công dụng của dấu gạch ngang (đánh dấu bộ phận chú thích, giải thích trong câu) và dấu gạch nối (nối các tiếng trong những từ mượn gồm nhiều tiếng).","Đại từ và kết từ: đặc điểm và chức năng; ôn luyện danh từ, động từ, tính từ."]},"32":{"cauHoi":[{"cauHoi":"Ở cảnh 1, vì sao anh Tễu tìm gặp ông quản phường rối nước?","dang":"TN","dapAn":1,"giaiThich":"Con thích ca hát mà tướng mạo khó coi... vào phường ta mới mong được giấu mặt mình, trình mặt rối mà hát sau bức mành ạ.","id":"V5-B32-01","mucDo":1,"phuongAn":["Xin làm hướng dẫn viên hang động","Xin học nghề rối nước: thích ca hát mà tướng mạo khó coi, muốn “giấu mặt mình, trình mặt rối mà hát sau bức mành”","Xin vào đội bóng","Xin học vẽ tranh làng Hồ"]},{"cauHoi":"Qua lời trò chuyện, anh Tễu hiện lên là người thế nào? Ông quản dạy Tễu diễn quân hề vì sao?","dang":"TN","dapAn":1,"giaiThich":"Ta thấy con ngộ nghĩnh, hoạt bát đấy chứ! ... Phường ta đưa tiếng cười mua vui cho làng xóm.","id":"V5-B32-02","mucDo":2,"phuongAn":["Tễu rất dữ dằn, ông quản đuổi về","Ngộ nghĩnh, hoạt bát, thành thật; tên Tễu có nghĩa là cười. Ông quản thấy vậy và phường cần tiếng cười (“Một nụ cười bằng mười thang thuốc bổ”), nên dạy diễn mấy quân hề","Tễu không muốn cười","Ông quản không nhận Tễu"]},{"cauHoi":"Ở cảnh 2 (ba năm sau), điều gì khiến Tễu đăm chiêu? Ông quản khích lệ thế nào?","dang":"TN","dapAn":3,"giaiThich":"Ta nghĩ đó chính là mong ước tìm cho nghề rối nước những tích trò hay hơn, những quân rối đẹp hơn! Con cứ đi theo tâm nguyện của mình.","id":"V5-B32-03","mucDo":1,"phuongAn":["Tễu muốn bỏ nghề vì không được hát","Không có cảnh 2","Ông quản cấm Tễu đi","Tễu mơ thấy thuỷ đình rộng, người đẹp múa ca vẫy gọi – khát vọng tìm tích trò hay hơn, quân rối đẹp hơn. Ông quản bảo Tễu đi theo tâm nguyện, chỉ xin lấy hình Tễu khắc một quân rối mới thay Tễu ở lại"]},{"cauHoi":"Vở kịch giải thích sự xuất hiện nhân vật chú Tễu trong rối nước như thế nào?","dang":"TN","dapAn":0,"giaiThich":"Xin con cho phường rối làng ta lấy chính con làm hình mẫu khắc tạc một quân rối mới... Quân rối chú Tễu sẽ thay con ca hát với mọi người.","id":"V5-B32-04","mucDo":2,"phuongAn":["Quân rối chú Tễu được khắc theo hình mẫu anh Tễu, ở lại múa ca với bạn nghề khi anh ra đi theo ước mơ; cả phường hát “vui như chú Tễu”","Chú Tễu không liên quan đến ai","Chú Tễu là một con vật dưới ao","Chú Tễu chỉ xuất hiện trong tranh làng Hồ"]},{"cauHoi":"Bài “Sự tích chú Tễu” thuộc thể loại nào?","dang":"TN","dapAn":2,"giaiThich":"Nhân vật, cảnh 1, cảnh 2, lời thoại – đặc điểm văn bản kịch.","id":"V5-B32-05","mucDo":1,"phuongAn":["Tờ quảng cáo phim","Báo cáo công việc","Kịch bản (vở kịch có nhân vật, lời thoại, cảnh diễn)","Bài thơ lục bát không nhân vật"]},{"cauHoi":"Viết 4 – 5 câu nêu cảm nghĩ của em về anh Tễu và ý nghĩa của tiếng cười trong nghệ thuật rối nước (theo vở kịch).","dang":"TL","giaiThich":"Gợi ý: Ham học nghề, yêu tiếng cười; dám theo đuổi tâm nguyện; quân rối chú Tễu còn mãi với phường.","id":"V5-B32-06","mucDo":3}],"chuDe":"4","ten":"Sự tích chú Tễu","tenChuDe":"Chủ điểm 4. Nghệ thuật muôn màu","tenGoc":"Bài 32. Sự tích chú Tễu","tuan":"16","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nhận xét được hình dáng, tính cách của nhân vật; nhận biết thời gian, địa điểm và tác dụng của chúng trong câu chuyện.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Nhận biết được văn bản viết theo tưởng tượng và văn bản viết về người thật, việc thật; hiểu từ ngữ, hình ảnh, biện pháp so sánh, nhân hoá trong văn bản."]},"33":{"cauHoi":[{"cauHoi":"Mỏm đá trên đỉnh núi cao ở vùng Chư Bô-đa có gì đặc biệt và được mọi vật yêu quý thế nào?","dang":"TN","dapAn":0,"giaiThich":"Trên đỉnh núi cao ở vùng Chư Bô-đa, có một mỏm đá xanh giống hình một em bé cưỡi voi. Nắng, mưa, gió, chim yêu quý mỏm đá.","id":"V5-B33-01","mucDo":1,"phuongAn":["Mỏm đá xanh giống hình một em bé cưỡi voi; nắng, mưa tắm gội sưởi ấm; gió kể chuyện, chim hát cho mỏm đá nghe","Đó là một cây cổ thụ giữa đồng bằng","Không có gì đặc biệt, không ai đoái hoài","Đó là một ngôi chùa một cột"]},{"cauHoi":"Khi mỏm đá hoá thành em bé, chuyện gì xảy ra?","dang":"TN","dapAn":1,"giaiThich":"Em bé liền cất giọng hát... Mọi người đặt tên cho em là Nai Ngọc.","id":"V5-B33-02","mucDo":1,"phuongAn":["Muông thú phá lúa nhiều hơn","Em bước xuống núi, cất giọng hát khiến muông thú quên phá lúa, nhảy múa theo; dân làng đặt tên em là Nai Ngọc","Dân làng đuổi em đi","Em chạy trốn, không giúp ai"]},{"cauHoi":"Khi giặc kéo đến, Nai Ngọc đã làm gì? Kết quả ra sao?","dang":"TN","dapAn":2,"giaiThich":"Giọng hát của Nai Ngọc khiến giặc đứng sững như những pho tượng, vũ khí tuột khỏi tay.","id":"V5-B33-03","mucDo":1,"phuongAn":["Em cầm giáo xung trận một mình","Nai Ngọc đi theo giặc","Em trèo lên mỏm núi, hát kêu gọi kẻ xâm lược hãy trở về với vợ con, với cuộc sống hoà bình; giặc đứng sững như pho tượng, vũ khí tuột khỏi tay. Giặc tan, Nai Ngọc trở lên núi, biến thành đá như trước","Dân làng đầu hàng ngay"]},{"cauHoi":"Lời hát của em bé người đá thể hiện ước nguyện gì?","dang":"TN","dapAn":3,"giaiThich":"Nai Ngọc hát kêu gọi những kẻ xâm lược chớ đi ăn cướp, hãy trở về với vợ con, đi hái rau ngọt, cắt lúa vàng...","id":"V5-B33-04","mucDo":2,"phuongAn":["Ước có nhiều vũ khí","Ước muông thú phá hết lúa","Ước được làm vua","Ước nguyện cuộc sống hoà bình, no ấm (hái rau ngọt, cắt lúa vàng, ngủ bên lửa ấm, thức dậy theo mặt trời), không đi ăn cướp"]},{"cauHoi":"Câu “Câu đơn có một cụm chủ ngữ – vị ngữ; câu ghép gồm các cụm chủ ngữ – vị ngữ ghép lại” nói về kiến thức nào?","dang":"TN","dapAn":1,"giaiThich":"SGK: Câu đơn là câu có một cụm chủ ngữ - vị ngữ. Câu ghép là câu gồm các cụm chủ ngữ - vị ngữ ghép lại.","id":"V5-B33-05","mucDo":1,"phuongAn":["Từ đa nghĩa","Câu đơn và câu ghép: đặc điểm của câu","Dấu gạch nối","Điệp từ"]},{"cauHoi":"Hãy viết một kết thúc khác (4 – 5 câu) cho câu chuyện “Tiếng hát của người đá” theo mong muốn của em (có thể để Nai Ngọc ở lại với dân làng).","dang":"TL","giaiThich":"Gợi ý: Giữ nhân vật Nai Ngọc; nêu sự việc nối tiếp; kết thúc rõ ràng, thể hiện ước nguyện hoà bình.","id":"V5-B33-06","mucDo":3}],"chuDe":"5","ten":"Tiếng hát của người đá","tenChuDe":"Chủ điểm 5. Vẻ đẹp cuộc sống","tenGoc":"Bài 1. Tiếng hát của người đá","tuan":"19","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Câu đơn và câu ghép: đặc điểm và chức năng; cách nối các vế câu ghép."]},"34":{"cauHoi":[{"cauHoi":"Những từ ngữ nào cho thấy bài “Khúc hát ru những em bé lớn trên lưng mẹ” (Nguyễn Khoa Điềm) như lời ru của mẹ?","dang":"TN","dapAn":2,"giaiThich":"Lưng đưa nôi và tim hát thành lời: Ngủ ngoan a-kay ơi... A-kay (tiếng Tà-ôi): con.","id":"V5-B34-01","mucDo":1,"phuongAn":["Không có lời ru nào","Chỉ có hiệu lệnh tập trận","“Em cu Tai ngủ trên lưng mẹ ơi”, “Ngủ ngoan a-kay ơi, ngủ ngoan a-kay hỡi”, nhịp chày, vai mẹ làm gối, lưng đưa nôi, tim hát thành lời","Chỉ có tiếng trống hội"]},{"cauHoi":"Người mẹ làm những công việc gì và ý nghĩa ra sao?","dang":"TN","dapAn":0,"giaiThich":"Mẹ giã gạo mẹ nuôi bộ đội... Mẹ đang tỉa bắp trên núi Ka-lư.","id":"V5-B34-02","mucDo":2,"phuongAn":["Giã gạo nuôi bộ đội; tỉa bắp trên núi Ka-lư – vừa chăm con trên lưng vừa lao động, góp phần nuôi quân, sản xuất","Không liên quan đến bộ đội","Chỉ đi chợ xa","Chỉ ngồi ru con, không làm việc gì"]},{"cauHoi":"Khổ thơ thứ hai, mẹ gửi gắm mong ước gì?","dang":"TN","dapAn":3,"giaiThich":"Mẹ thương a-kay, mẹ thương bộ đội / Con mơ cho mẹ hạt gạo trắng ngần / Mai sau con lớn vung chày lún sân.","id":"V5-B34-03","mucDo":2,"phuongAn":["Mong hết lúa bắp","Không có mong ước nào","Mong con bỏ việc giúp mẹ","Thương con, thương bộ đội; mong con mơ cho mẹ hạt gạo trắng ngần, mai sau con lớn vung chày lún sân"]},{"cauHoi":"Hai dòng “Mặt trời của bắp thì nằm trên đồi / Mặt trời của mẹ, em nằm trên lưng” có thể hiểu thế nào?","dang":"TN","dapAn":2,"giaiThich":"Đối chiếu mặt trời của bắp (trên đồi) với mặt trời của mẹ (em trên lưng).","id":"V5-B34-04","mucDo":3,"phuongAn":["Em là mặt trời thật trên trời","Mẹ không yêu con","Bắp cần mặt trời trên đồi để lớn; với mẹ, em chính là “mặt trời” – nguồn vui, nguồn sức sống – đang nằm trên lưng mẹ","Bắp không cần nắng"]},{"cauHoi":"Theo chú thích SGK, núi Ka-lư ở đâu? “A-kay” nghĩa là gì?","dang":"TN","dapAn":0,"giaiThich":"Chú thích SGK: Núi Ka-lư: một ngọn núi ở phía tây thành phố Huế và tỉnh Quảng Trị. A-kay: con.","id":"V5-B34-05","mucDo":1,"phuongAn":["Một ngọn núi ở phía tây thành phố Huế và tỉnh Quảng Trị; a-kay (tiếng Tà-ôi) nghĩa là con","Ở Bắc Ninh; a-kay nghĩa là lúa","Ở đồng bằng sông Cửu Long; a-kay nghĩa là núi","Không có chú thích"]},{"cauHoi":"Viết 4 – 5 câu nêu chủ đề bài thơ và tình cảm của em đối với người mẹ trong “Khúc hát ru những em bé lớn trên lưng mẹ”.","dang":"TL","giaiThich":"Gợi ý: Tình mẫu tử; mẹ vừa địu con vừa lao động, nuôi bộ đội; em là mặt trời của mẹ.","id":"V5-B34-06","mucDo":3}],"chuDe":"5","ten":"Khúc hát ru những em bé lớn trên lưng mẹ","tenChuDe":"Chủ điểm 5. Vẻ đẹp cuộc sống","tenGoc":"Bài 2. Khúc hát ru những em bé lớn trên lưng mẹ","tuan":"19","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Nhận biết được văn bản viết theo tưởng tượng và văn bản viết về người thật, việc thật; hiểu từ ngữ, hình ảnh, biện pháp so sánh, nhân hoá trong văn bản.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản."]},"35":{"cauHoi":[{"cauHoi":"Ở khổ thơ đầu “Hạt gạo làng ta” (Trần Đăng Khoa), chi tiết nào cho thấy hạt gạo kết tinh từ tinh tuý của thiên nhiên?","dang":"TN","dapAn":1,"giaiThich":"Có vị phù sa / Của sông Kinh Thầy / Có hương sen thơm / Trong hồ nước đầy / Có lời mẹ hát...","id":"V5-B35-01","mucDo":1,"phuongAn":["Không gắn với sông, hồ","Có vị phù sa của sông Kinh Thầy, có hương sen thơm trong hồ nước đầy, có lời mẹ hát","Chỉ có mùi khói xe","Chỉ nói về máy móc"]},{"cauHoi":"Bài thơ cho thấy nét đẹp gì của người nông dân khi làm ra hạt gạo?","dang":"TN","dapAn":3,"giaiThich":"Giọt mồ hôi sa những trưa tháng Sáu... Sớm nào chống hạn, trưa nào bắt sâu, chiều nào gánh phân.","id":"V5-B35-02","mucDo":2,"phuongAn":["Chỉ mua gạo ở cửa hàng","Ngại khó, bỏ ruộng","Không ai làm việc đồng áng","Chịu khó, gắn bó với đồng ruộng: mồ hôi những trưa tháng Sáu nắng như nấu, mẹ xuống cấy; chống hạn, bắt sâu, gánh phân; cả những năm bom đạn vẫn làm ra bát cơm"]},{"cauHoi":"Các bạn nhỏ đã đóng góp gì để làm ra hạt gạo?","dang":"TN","dapAn":3,"giaiThich":"Hạt gạo làng ta / Có công các bạn / Sớm nào chống hạn / Vục mẻ miệng gàu / Trưa nào bắt sâu...","id":"V5-B35-03","mucDo":1,"phuongAn":["Chỉ ăn, không làm","Chỉ đứng nhìn","Không tham gia việc gì","Có công chống hạn (vục mẻ miệng gàu), bắt sâu, gánh phân (quang trành quết đất)"]},{"cauHoi":"Vì sao hạt gạo được gọi là “hạt vàng”? Điều “Bát cơm mùa gặt / Thơm hào giao thông” gợi nên?","dang":"TN","dapAn":0,"giaiThich":"Những năm bom Mỹ... Bát cơm mùa gặt / Thơm hào giao thông... Gửi ra tiền tuyến... Hạt vàng làng ta.","id":"V5-B35-04","mucDo":2,"phuongAn":["Hạt gạo quý như vàng vì công sức, mồ hôi và cả sự hi sinh thời chiến; bát cơm thơm gửi ra tiền tuyến, gắn hậu phương với tiền tuyến","Vì hạt gạo không liên quan chiến tranh","Vì không ai ăn cơm","Vì gạo được sơn màu vàng"]},{"cauHoi":"Theo chú thích SGK, sông Kinh Thầy ở đâu? “Hào giao thông” là gì?","dang":"TN","dapAn":1,"giaiThich":"Chú thích SGK: Kinh Thầy: tên một con sông ở thành phố Hải Phòng. Hào giao thông: đường đào sâu dưới đất...","id":"V5-B35-05","mucDo":1,"phuongAn":["Không có chú thích","Sông Kinh Thầy ở thành phố Hải Phòng; hào giao thông là đường đào sâu dưới đất để đi lại an toàn trong chiến tranh","Sông ở Cà Mau; hào là sân vận động","Sông ở Tây Nguyên; hào là chợ nổi"]},{"cauHoi":"Viết 4 – 5 câu nêu vì sao, theo em, hạt gạo làng ta được gọi là “hạt vàng”.","dang":"TL","giaiThich":"Gợi ý: Tinh tuý thiên nhiên; công người lớn và các bạn; gửi ra tiền tuyến; quý như vàng.","id":"V5-B35-06","mucDo":3}],"chuDe":"5","ten":"Hạt gạo làng ta","tenChuDe":"Chủ điểm 5. Vẻ đẹp cuộc sống","tenGoc":"Bài 3. Hạt gạo làng ta","tuan":"20","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện."]},"36":{"cauHoi":[{"cauHoi":"Lớp Tân có dự định gì trong buổi tổng kết năm học?","dang":"TN","dapAn":2,"giaiThich":"Ngày mai tổng kết năm học, mỗi bạn sẽ viết một lá thư như một món quà đặc biệt để tặng cô chủ nhiệm.","id":"V5-B36-01","mucDo":1,"phuongAn":["Không tặng cô gì cả","Tổ chức đá bóng với lớp khác","Mỗi bạn viết một lá thư như món quà đặc biệt tặng cô chủ nhiệm; các thư được xếp vào hộp màu thiên thanh","Chỉ tặng một bó hoa, không viết thư"]},{"cauHoi":"Khi viết thư, Tân nhớ lại kỉ niệm gì?","dang":"TN","dapAn":1,"giaiThich":"Tân nhớ về kỉ niệm một lần đi học muộn vì mải bẻ ngô giúp mẹ.","id":"V5-B36-02","mucDo":1,"phuongAn":["Tân quên mang sách","Một lần đi học muộn vì mải bẻ ngô giúp mẹ; Huệ nói giúp Tân; cô khen Tân thương mẹ nhưng khuyên vừa giúp mẹ vừa đi học đúng giờ","Cô phạt Tân đứng ngoài cửa","Tân bị điểm kém môn Toán"]},{"cauHoi":"Vì sao Tân cố gắng và có nhiều tiến bộ?","dang":"TN","dapAn":3,"giaiThich":"Cô nhìn Tân trìu mến... Tân thầm hứa sẽ không đi học muộn nữa... Cuối năm, Tân được cô giáo khen vì có nhiều tiến bộ.","id":"V5-B36-03","mucDo":2,"phuongAn":["Vì không nhớ lời cô","Vì muốn bỏ học","Vì bị ép, không quý cô","Vì lời khuyên dịu dàng của cô (thương mẹ hơn nữa nếu đi học đúng giờ); Tân thầm hứa, dậy sớm học bài, giúp mẹ, cuối năm được cô khen"]},{"cauHoi":"Những chi tiết nào thể hiện tình cảm cô trò trong lễ tổng kết?","dang":"TN","dapAn":2,"giaiThich":"Cô giáo mặc áo dài màu thiên thanh bước vào lớp trong tiếng vỗ tay giòn giã... Ba mươi lăm lá thư... Chỉ cô giáo mới biết từng học trò đã viết gì.","id":"V5-B36-04","mucDo":1,"phuongAn":["Cô không nhận quà","Không ai vỗ tay","Cô mặc áo dài màu thiên thanh, tiếng vỗ tay giòn giã; Quang cảm ơn cô; đôi má cô ửng hồng khi nhận hộp quà; 35 lá thư giữ bí mật, chỉ cô được đọc","Không có thư nào"]},{"cauHoi":"Hình ảnh “hộp quà màu thiên thanh” có ý nghĩa gì?","dang":"TN","dapAn":0,"giaiThich":"Ba mươi lăm lá thư tạo thành một hộp quà đặc biệt tặng cô được giữ bí mật tuyệt đối.","id":"V5-B36-05","mucDo":2,"phuongAn":["Là món quà tinh thần: tình cảm, lời tri ân của cả lớp (35 lá thư) dành cho cô, đẹp và kín đáo như màu thiên thanh","Là phần thưởng tiền mặt","Là hộp đồ chơi","Chỉ là hộp rỗng không có ý nghĩa"]},{"cauHoi":"Viết 4 – 5 câu nêu ý nghĩa hình ảnh “hộp quà màu thiên thanh” và tình cảm của em đối với thầy cô (có thể nghĩ một nhan đề khác cho câu chuyện).","dang":"TL","giaiThich":"Gợi ý: Quà là lời nói từ trái tim; màu áo dài cô và màu hộp; sự biết ơn.","id":"V5-B36-06","mucDo":3}],"chuDe":"5","ten":"Hộp quà màu thiên thanh","tenChuDe":"Chủ điểm 5. Vẻ đẹp cuộc sống","tenGoc":"Bài 4. Hộp quà màu thiên thanh","tuan":"20","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nhận xét được hình dáng, tính cách của nhân vật; nhận biết thời gian, địa điểm và tác dụng của chúng trong câu chuyện.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"37":{"cauHoi":[{"cauHoi":"Ngày lễ nào được các bạn nhỏ trong bài “Giỏ hoa tháng Năm” mong chờ? Việc làm nào khiến các bạn thấy thú vị?","dang":"TN","dapAn":0,"giaiThich":"Chú thích: Lễ Mừng xuân... diễn ra vào tháng Năm. Chúng tôi... đặt lên bậc thềm... gõ cửa rồi ba chân bốn cẳng chạy trốn.","id":"V5-B37-01","mucDo":1,"phuongAn":["Lễ Mừng xuân (tháng Năm, muôn hoa đua nở); các bạn hái hoa, làm giỏ hoa, đặt lên bậc thềm nhà người quen rồi chạy trốn, nhìn chủ nhà ngạc nhiên, thích thú","Chỉ ngồi nhà, không tặng hoa","Lễ hội thổi cơm thi","Tết Trung thu rước đèn"]},{"cauHoi":"Vì sao Xu-di giận Pam, bạn thân nhất của mình?","dang":"TN","dapAn":3,"giaiThich":"Pam đã kết thân với con gái của họ... thời gian Pam dành cho tôi không còn nhiều như trước. Tôi cảm thấy như bị bỏ rơi.","id":"V5-B37-02","mucDo":2,"phuongAn":["Xu-di không bao giờ có bạn","Pam lấy mất giỏ hoa của Xu-di","Pam chuyển trường xa","Pam kết thân với con gái một gia đình mới chuyển đến, thời gian dành cho Xu-di ít hơn; Xu-di cảm thấy bị bỏ rơi"]},{"cauHoi":"Xu-di quyết định tặng Pam giỏ hoa như thế nào và Pam đón nhận ra sao?","dang":"TN","dapAn":1,"giaiThich":"Tôi chọn thật nhiều hoa màu vàng mà Pam yêu thích... Pam nâng giỏ hoa lên, dịu dàng áp mặt vào những bông hoa...","id":"V5-B37-03","mucDo":1,"phuongAn":["Mẹ cấm Xu-di tặng hoa","Xu-di chọn nhiều hoa màu vàng Pam yêu thích, nhờ chị đem đến; từ chỗ nấp, thấy Pam nâng giỏ, áp mặt vào hoa và nói: “Cảm ơn Xu-di, hi vọng cậu không còn giận mình!”","Pam từ chối giỏ hoa","Xu-di không tặng hoa"]},{"cauHoi":"Đoạn kết muốn nói điều gì?","dang":"TN","dapAn":2,"giaiThich":"Lần ấy tôi học được rằng là bạn bè đích thực, ta sẽ đặt bạn trong tim nhưng không buộc họ luôn ở bên mình.","id":"V5-B37-04","mucDo":2,"phuongAn":["Không cần xin lỗi","Bạn bè không được kết bạn mới","Là bạn bè đích thực, ta đặt bạn trong tim nhưng không buộc họ luôn ở bên mình (mẹ đã khuyên: càng lớn càng có nhiều bạn)","Phải giận nhau mãi"]},{"cauHoi":"Cặp từ như “vì... nên...”, “nếu... thì...”, “mặc dù... nhưng...” dùng để làm gì?","dang":"TN","dapAn":0,"giaiThich":"SGK: Các vế của câu ghép có thể nối với nhau bằng các cặp kết từ.","id":"V5-B37-05","mucDo":1,"phuongAn":["Nối các vế của câu ghép (cặp kết từ)","Tạo danh từ riêng","Tạo điệp từ bắt buộc","Làm dấu gạch ngang"]},{"cauHoi":"Viết 4 – 5 câu nêu bài học em rút ra từ chuyện Xu-di tặng Pam giỏ hoa tháng Năm.","dang":"TL","giaiThich":"Gợi ý: Biết chia sẻ bạn bè; không giữ ích kỉ tình bạn; dám bày tỏ tình cảm.","id":"V5-B37-06","mucDo":3}],"chuDe":"5","ten":"Giỏ hoa tháng Năm","tenChuDe":"Chủ điểm 5. Vẻ đẹp cuộc sống","tenGoc":"Bài 5. Giỏ hoa tháng Năm","tuan":"21","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nhận xét được hình dáng, tính cách của nhân vật; nhận biết thời gian, địa điểm và tác dụng của chúng trong câu chuyện.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Câu đơn và câu ghép: đặc điểm và chức năng; cách nối các vế câu ghép."]},"38":{"cauHoi":[{"cauHoi":"Ở khổ thơ đầu “Thư của bố”, bạn nhỏ chia sẻ điều gì?","dang":"TN","dapAn":2,"giaiThich":"Con lớn lên, quen vắng bố trong nhà / Hai mẹ con, nhà một phòng cũng trống / Chỉ mong đợi những lá thư gió lộng.","id":"V5-B38-01","mucDo":1,"phuongAn":["Bố ở nhà suốt ngày","Bạn không bao giờ nhận thư","Lớn lên đã quen vắng bố trong nhà; hai mẹ con nhà trống, chỉ mong những lá thư gió lộng, mặn mòi hương biển xa xôi","Nhà rất đông người"]},{"cauHoi":"Những chi tiết nào cho thấy bố vất vả khi bảo vệ biển đảo?","dang":"TN","dapAn":1,"giaiThich":"Thư không kể về cơn bão chờ phía trước, dải đá ngầm, thăm thẳm nước đen... Áo đọng muối khô, da nhận mùi nắng khét.","id":"V5-B38-02","mucDo":1,"phuongAn":["Bố làm việc trong thư viện","Cơn bão chờ phía trước, dải đá ngầm, nước đen thăm thẳm, nhịp bước khẩn trương khi khẩu lệnh vang, mắt dõi ra-đa, áo đọng muối khô, da nhận mùi nắng khét","Bố chỉ đi dạo trên phố","Không có khó khăn nào"]},{"cauHoi":"Vì sao trong thư bố không kể những khó khăn ấy?","dang":"TN","dapAn":3,"giaiThich":"Thư không kể về cơn bão... Thư chỉ nói về nỗi nhớ với thương yêu...","id":"V5-B38-03","mucDo":2,"phuongAn":["Bố quên cách viết thư","Bố không thương con","Bố không gặp khó khăn gì","Thư chỉ nói về nỗi nhớ với thương yêu – bố muốn che chở con, gửi tình cảm dịu dàng hơn là kể nỗi vất vả"]},{"cauHoi":"Hai dòng “Nơi đầu sóng, sẵn sàng nghênh chiến / Vẫn dịu dàng, êm ái lá thư xanh” cho hiểu điều gì về người lính biển?","dang":"TN","dapAn":2,"giaiThich":"Nơi đầu sóng, sẵn sàng nghênh chiến — Vẫn dịu dàng, êm ái lá thư xanh.","id":"V5-B38-04","mucDo":3,"phuongAn":["Chỉ biết chiến đấu, không có tình cảm","Không gắn với biển đảo","Vừa sẵn sàng chiến đấu nơi đầu sóng, vừa giữ nét dịu dàng, yêu thương qua thư gửi con","Chỉ viết thư, không làm nhiệm vụ"]},{"cauHoi":"Bạn nhỏ thể hiện tình cảm với bố như thế nào?","dang":"TN","dapAn":0,"giaiThich":"Con đã lớn khôn, đọc được cả những điều / Chưa được viết trong thư người lính biển.","id":"V5-B38-05","mucDo":2,"phuongAn":["Làm quen cuộc sống vắng bố, mong đợi thư, và đã lớn khôn đọc được cả những điều bố chưa viết trong thư người lính biển","Chỉ giận vì bố vắng nhà","Không nhớ đến bố","Không đọc thư bố"]},{"cauHoi":"Viết 4 – 5 câu nêu tình cảm của em đối với người lính biển (hoặc người thân đang làm nhiệm vụ) qua bài thơ “Thư của bố”.","dang":"TL","giaiThich":"Gợi ý: Nỗi vất vả nơi đầu sóng; tình thương trong thư; sự thấu hiểu của con.","id":"V5-B38-06","mucDo":3}],"chuDe":"5","ten":"Thư của bố","tenChuDe":"Chủ điểm 5. Vẻ đẹp cuộc sống","tenGoc":"Bài 6. Thư của bố","tuan":"21","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Nhận xét được hình dáng, tính cách của nhân vật; nhận biết thời gian, địa điểm và tác dụng của chúng trong câu chuyện.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"39":{"cauHoi":[{"cauHoi":"Ở khổ thơ đầu “Đoàn thuyền đánh cá”, đoàn thuyền ra khơi trong khung cảnh nào? Cách tả có gì đặc biệt?","dang":"TN","dapAn":3,"giaiThich":"Mặt trời xuống biển như hòn lửa / Sóng đã cài then, đêm sập cửa / Đoàn thuyền đánh cá lại ra khơi.","id":"V5-B39-01","mucDo":2,"phuongAn":["Đoàn thuyền ra khơi lúc bình minh êm ả, không có hình ảnh so sánh","Thuyền neo ở bến, không ra khơi","Trời đang mưa tuyết trên núi","Mặt trời xuống biển như hòn lửa, sóng đã cài then, đêm sập cửa; đoàn thuyền lại ra khơi, câu hát căng buồm cùng gió khơi – dùng so sánh, nhân hoá giàu hình ảnh"]},{"cauHoi":"Những chi tiết nào thể hiện tình cảm của người đánh cá với biển?","dang":"TN","dapAn":1,"giaiThich":"Biển cho ta cá như lòng mẹ / Nuôi lớn đời ta tự buổi nào.","id":"V5-B39-02","mucDo":1,"phuongAn":["Họ không kể gì về cá","Câu hát gọi cá, cá thu như đoàn thoi dệt biển muôn luồng sáng; “Biển cho ta cá như lòng mẹ / Nuôi lớn đời ta tự buổi nào”; gõ thuyền đã có nhịp trăng cao","Họ sợ biển, không hát","Họ muốn rời biển mãi"]},{"cauHoi":"Bài thơ giúp em cảm nhận những vẻ đẹp nào của cuộc sống?","dang":"TN","dapAn":3,"giaiThich":"Đoàn thuyền ra khơi trong đêm, hát gọi cá, biết ơn biển như mẹ.","id":"V5-B39-03","mucDo":2,"phuongAn":["Không có vẻ đẹp lao động","Chỉ vẻ đẹp của phố thị","Cuộc sống buồn tẻ, không hát","Vẻ đẹp của thiên nhiên biển đêm, của lao động cần cù và của tình cảm gắn bó, ân nghĩa giữa người và biển"]},{"cauHoi":"Hình ảnh “Mặt trời xuống biển như hòn lửa”, “Biển cho ta cá như lòng mẹ” dùng biện pháp tu từ nào?","dang":"TN","dapAn":0,"giaiThich":"Như hòn lửa, như lòng mẹ – so sánh.","id":"V5-B39-04","mucDo":1,"phuongAn":["So sánh","Câu hỏi tu từ không có hình ảnh","Chỉ là câu đơn không biện pháp","Dấu gạch nối"]},{"cauHoi":"Câu “Sóng đã cài then, đêm sập cửa” dùng biện pháp nào?","dang":"TN","dapAn":1,"giaiThich":"Sóng cài then, đêm sập cửa – nhân hoá.","id":"V5-B39-05","mucDo":1,"phuongAn":["Điệp từ “học”","Nhân hoá (gán hành động của người cho sóng, đêm)","Chỉ liệt kê số liệu","Từ đa nghĩa “mắt”"]},{"cauHoi":"Viết 4 – 5 câu nêu cảm nhận của em về vẻ đẹp cuộc sống trong bài thơ “Đoàn thuyền đánh cá” (có thể dẫn một hình ảnh em thích).","dang":"TL","giaiThich":"Gợi ý: Cảnh trời đêm trên biển; câu hát căng buồm; biển như mẹ; lao động của người ngư dân.","id":"V5-B39-06","mucDo":3}],"chuDe":"5","ten":"Đoàn thuyền đánh cá","tenChuDe":"Chủ điểm 5. Vẻ đẹp cuộc sống","tenGoc":"Bài 7. Đoàn thuyền đánh cá","tuan":"22","yeuCauCanDat":["Nhận biết được văn bản viết theo tưởng tượng và văn bản viết về người thật, việc thật; hiểu từ ngữ, hình ảnh, biện pháp so sánh, nhân hoá trong văn bản.","Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"4":{"cauHoi":[{"cauHoi":"Từ nhỏ, những hình ảnh nào của quê hương đã thân thuộc với bạn nhỏ trong “Bến sông tuổi thơ”?","dang":"TN","dapAn":3,"giaiThich":"Từ khi sinh ra, tôi đã thấy trước nhà một dòng sông êm đềm, hàng bần xanh soi bóng.","id":"V5-B04-01","mucDo":1,"phuongAn":["Sa mạc cát trắng","Núi lửa đang phun","Dãy phố cao tầng","Dòng sông êm đềm trước nhà, hàng bần xanh soi bóng nghiêng nghiêng"]},{"cauHoi":"Các bạn nhỏ có những kỉ niệm gì trên bến sông?","dang":"TN","dapAn":3,"giaiThich":"Bọn trẻ tụ ở bến sông, hái bần ăn, nghe trái chín rớt tỏm; lội bãi kiếm cá.","id":"V5-B04-02","mucDo":2,"phuongAn":["Chỉ ngồi học bài trên bến","Xây nhà trên sông","Cấm không được xuống sông","Tụ nhau mỗi chiều, hái trái bần chấm muối ớt hoặc mắm; nghe trái bần chín rớt tỏm xuống sông; lội bắt cá, nấu canh chua"]},{"cauHoi":"Theo chú thích SGK, “cù lao” nghĩa là gì?","dang":"TN","dapAn":2,"giaiThich":"Chú thích: Cù lao (đảo): vùng đất nổi lên giữa sông hoặc ở biển.","id":"V5-B04-03","mucDo":1,"phuongAn":["Tên một trò chơi","Một loài cá","Vùng đất nổi lên giữa sông hoặc ở biển (đảo)","Một loại muối"]},{"cauHoi":"Bạn nhỏ nhắc đến đặc sản nào của quê?","dang":"TN","dapAn":0,"giaiThich":"Trái bần chua là đặc sản; nấu canh chua cá bống sao hay cá bông lau thì khó có món nào ngon hơn.","id":"V5-B04-04","mucDo":1,"phuongAn":["Trái bần chua; canh chua cá bống sao hoặc cá bông lau nấu với bần","Chỉ có chè shan tuyết","Không có món nào","Chỉ có bánh mì"]},{"cauHoi":"“Bần, cù lao, cá bống sao” là những từ loại gì?","dang":"TN","dapAn":1,"giaiThich":"Đó là danh từ chỉ sự vật.","id":"V5-B04-05","mucDo":1,"phuongAn":["Đại từ nghi vấn","Danh từ","Tính từ","Động từ"]},{"cauHoi":"Viết 4 – 5 câu nêu hình ảnh quê hương em yêu thích nhất (có thể liên hệ bến sông, hàng bần trong bài) và giải thích vì sao.","dang":"TL","giaiThich":"Gợi ý: Tả ngắn một hình ảnh; nêu cảm xúc; vì sao hình ảnh ấy đáng nhớ.","id":"V5-B04-06","mucDo":3},{"cauHoi":"Trong câu kể về trái bần chín “rớt tỏm” xuống sông, từ “tỏm” gợi cho em điều gì?","dang":"TN","dapAn":1,"giaiThich":"“Tỏm” là từ gợi tả âm thanh và hình ảnh của vật vừa rơi xuống nước: nghe rõ tiếng “tỏm” rồi mặt nước gợn sóng. Nhờ từ ngữ gợi tả ấy, cảnh bến sông tuổi thơ hiện lên sống động trước mắt người đọc.","id":"TV5-B04-BS01","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Trái bần rơi rất chậm, lơ lửng mãi trên mặt nước","Âm thanh và hình ảnh trái bần vừa chạm mặt nước, tạo tiếng “tỏm” rồi những vòng sóng lan ra","Trái bần rơi xuống đáy sông mà không gây tiếng động","Trái bần bị cá đớp ngay khi vừa rơi"]}],"chuDe":"1","ten":"Bến sông tuổi thơ","tenChuDe":"Chủ điểm 1. Thế giới tuổi thơ","tenGoc":"Bài 4. Bến sông tuổi thơ","tuan":"2","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Đại từ và kết từ: đặc điểm và chức năng; ôn luyện danh từ, động từ, tính từ.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện."]},"40":{"cauHoi":[{"cauHoi":"“Trang trại rừng” và sự gắn bó của Mát được giới thiệu thế nào?","dang":"TN","dapAn":2,"giaiThich":"Mát sống với ông nội ở “Trang trại rừng”... Năm Mát tròn mười tám tuổi, ông nội qua đời... Mát cũng hứa sẽ bảo vệ trang trại thật tốt.","id":"V5-B40-01","mucDo":1,"phuongAn":["Mát không quen ông nội","Trang trại không trồng cây","Trang trại rộng lớn, nổi tiếng, cơ nghiệp tổ tiên, trồng nhiều cây quý hiếm; Mát sống với ông nội, được ông dạy tên và đặc tính cây; 18 tuổi ông mất, gửi trang trại và Mát hứa gìn giữ","Mát bỏ trại đi thành phố từ nhỏ"]},{"cauHoi":"Sự việc gì xảy ra với trang trại? Mát rơi vào tình trạng nào?","dang":"TN","dapAn":2,"giaiThich":"Một tia sét đánh trúng ngọn cây cao nhất... Trang trại cháy suốt một ngày một đêm. Mát đau xót và kiệt sức, ngất lịm.","id":"V5-B40-02","mucDo":1,"phuongAn":["Không có cháy rừng","Trại được mùa, Mát vui vẻ","Một đêm sét đánh cháy rừng, lửa lan, dập không nổi, cháy một ngày một đêm; Mát đau xót, kiệt sức, ngất, rồi buồn bã, tuyệt vọng","Mát bán trại ngay"]},{"cauHoi":"Mát đã làm gì để khôi phục trang trại?","dang":"TN","dapAn":1,"giaiThich":"Mát thuê người... biến những thân cây bị đốt cháy thành than củi... mua cây giống, trồng trong trang trại, thực hiện lời hứa với ông.","id":"V5-B40-03","mucDo":1,"phuongAn":["Anh chờ cây tự mọc, không bán than","Nghe bà lão khuyên “cây bị thiêu thì trồng lại được”, anh bừng tỉnh; bán than từ thân cây cháy để lấy vốn mua cây giống, trồng lại; nhiều năm sau trại xanh mướt, được gọi là “Rừng của Mát”","Anh cấm mọi người đến trại","Anh bỏ trại, không làm gì"]},{"cauHoi":"Vì sao Mát bừng tỉnh khi nghe bà lão? Điều đó nói lên phẩm chất gì?","dang":"TN","dapAn":3,"giaiThich":"Cây bị thiêu cháy thì trồng lại là được. Cậu còn trẻ mà! Nghe bà cụ nói, Mát bừng tỉnh.","id":"V5-B40-04","mucDo":3,"phuongAn":["Anh không nghe bà","Anh trách bà","Anh chỉ nghĩ đến việc bỏ cuộc","Bà nhắc anh còn trẻ, có thể trồng lại; anh tìm ra cách dùng chính cây cháy làm vốn – thể hiện ý chí, trách nhiệm với lời hứa và tình yêu trang trại"]},{"cauHoi":"Câu “Mát còn trẻ nên anh quyết tâm trồng lại rừng” là câu gì?","dang":"TN","dapAn":0,"giaiThich":"Hai cụm chủ ngữ - vị ngữ được nối bằng kết từ nên.","id":"V5-B40-05","mucDo":1,"phuongAn":["Câu ghép (hai vế được nối bằng kết từ “nên”)","Câu hỏi","Câu đơn chỉ có một vế","Danh từ riêng"]},{"cauHoi":"Viết 4 – 5 câu nêu cảm nghĩ của em về nhân vật Mát (tình cảm với ông, cách đứng dậy sau đám cháy, lời hứa).","dang":"TL","giaiThich":"Gợi ý: Đau xót nhưng không bỏ cuộc; biết lắng nghe; biến khó khăn thành vốn; giữ lời hứa.","id":"V5-B40-06","mucDo":3}],"chuDe":"5","ten":"Khu rừng của Mát","tenChuDe":"Chủ điểm 5. Vẻ đẹp cuộc sống","tenGoc":"Bài 8. Khu rừng của Mát","tuan":"22","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Câu đơn và câu ghép: đặc điểm và chức năng; cách nối các vế câu ghép."]},"41":{"cauHoi":[{"cauHoi":"Hội thổi cơm thi ở Đồng Vân bắt nguồn từ đâu? Làng Đồng Vân thuộc đâu (theo chú thích SGK)?","dang":"TN","dapAn":0,"giaiThich":"Hội thổi cơm thi ở làng Đồng Vân bắt nguồn từ các cuộc trẩy quân đánh giặc của người Việt cổ bên bờ sông Đáy xưa. Chú thích: Đồng Vân thuộc xã Đan Phượng, Hà Nội.","id":"V5-B41-01","mucDo":1,"phuongAn":["Từ các cuộc trẩy quân đánh giặc của người Việt cổ bên bờ sông Đáy xưa; làng thuộc xã Đan Phượng, Hà Nội","Từ một hội chợ hiện đại ở nước ngoài","Không rõ nguồn gốc","Làng ở Cà Mau"]},{"cauHoi":"Hội thi bắt đầu bằng việc lấy lửa như thế nào?","dang":"TN","dapAn":3,"giaiThich":"Bốn thanh niên thoăn thoắt leo lên bốn cây chuối bôi mỡ bóng nhẫy để lấy nén hương, được phát ba que diêm.","id":"V5-B41-02","mucDo":1,"phuongAn":["Không cần lấy lửa","Lấy lửa sẵn từ bếp nhà","Chỉ dùng bếp điện","Khi trống hiệu dứt, bốn thanh niên của bốn đội leo bốn cây chuối bôi mỡ để lấy nén hương trên ngọn, rồi được phát ba que diêm châm hương thành lửa"]},{"cauHoi":"Cách thổi cơm và tiêu chí chấm ra sao?","dang":"TN","dapAn":1,"giaiThich":"Ban giám khảo chấm theo ba tiêu chí: cơm trắng, dẻo và không có cháy.","id":"V5-B41-03","mucDo":1,"phuongAn":["Chấm theo màu nồi","Người nấu đeo cần tre hình cánh cung, đầu treo nồi, vừa giữ cần vừa cầm đuốc, các đội uốn lượn trên sân đình; khoảng một giờ rưỡi, cơm được đánh số; chấm theo ba tiêu chí: trắng, dẻo, không cháy","Nấu trong bếp kín, không ai xem","Không có tiêu chí"]},{"cauHoi":"Qua bài đọc, tác giả muốn nói điều gì đã được thể hiện rõ?","dang":"TN","dapAn":2,"giaiThich":"Việc giật giải đã trở thành niềm tự hào khó có gì sánh nổi đối với dân làng.","id":"V5-B41-04","mucDo":2,"phuongAn":["Hội thi không còn ý nghĩa","Không ai muốn giật giải","Hội thổi cơm thi là nét đẹp văn hoá, sự khéo léo, đoàn kết và niềm tự hào của dân làng","Chỉ là trò chơi của trẻ nhỏ"]},{"cauHoi":"Các câu trong đoạn văn có thể liên kết bằng cách lặp lại từ ngữ. Đó là kiến thức về gì?","dang":"TN","dapAn":3,"giaiThich":"SGK luyện liên kết câu bằng cách lặp từ ngữ.","id":"V5-B41-05","mucDo":1,"phuongAn":["Dấu gạch nối","Cách viết tên nước ngoài","Từ đa nghĩa bắt buộc","Liên kết câu trong đoạn văn (biện pháp lặp từ ngữ)"]},{"cauHoi":"Viết 4 – 5 câu nêu tình cảm, cảm xúc của em về hội thổi cơm thi ở Đồng Vân (một chi tiết em thích và vì sao).","dang":"TL","giaiThich":"Gợi ý: Leo cây chuối lấy lửa; cần tre treo nồi; tiêu chí cơm trắng, dẻo, không cháy; niềm tự hào dân làng.","id":"V5-B41-06","mucDo":3}],"chuDe":"6","ten":"Hội thổi cơm thi ở Đồng Vân","tenChuDe":"Chủ điểm 6. Hương sắc trăm miền","tenGoc":"Bài 9. Hội thổi cơm thi ở Đồng Vân","tuan":"23","yeuCauCanDat":["Nhận biết được những chi tiết tiêu biểu và các thông tin chính của văn bản thông tin; xác định đề tài từ nhan đề, đề mục; nhận biết mục đích, đặc điểm, bố cục của văn bản giải thích, giới thiệu sách hoặc phim, quảng cáo, chương trình hoạt động; vai trò của hình ảnh, kí hiệu hoặc số liệu.","Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Liên kết giữa các câu trong một đoạn văn; một số biện pháp liên kết câu và các từ ngữ liên kết: đặc điểm và tác dụng.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"42":{"cauHoi":[{"cauHoi":"Thào A Sùng là ai và luôn trăn trở điều gì?","dang":"TN","dapAn":2,"giaiThich":"Tôi có một cậu bạn người Mông tên là Thào A Sùng. Cậu luôn trăn trở vì còn ít người biết đến chè Tà Xùa.","id":"V5-B42-01","mucDo":1,"phuongAn":["Cậu không kể về quê","Cậu không thích chè","Cậu bạn người Mông, quê bản Tà Xùa; tự hào về cây chè cổ thụ và trăn trở vì còn ít người biết đến chè Tà Xùa","Cậu sống ở thành phố, không biết chè"]},{"cauHoi":"Trong cuộc thi “Bảy sắc cầu vồng”, Thào A Sùng giới thiệu chè Tà Xùa thế nào?","dang":"TN","dapAn":1,"giaiThich":"Búp chè to, lông tơ mịn trắng như tuyết; nước vàng ánh xanh, thơm; vị lúc đầu hơi chát, sau ngọt.","id":"V5-B42-02","mucDo":1,"phuongAn":["Chè chỉ màu đen, không thơm","Chè làm từ búp to, dưới lá có lông tơ mịn trắng như tuyết, trên cây cổ thụ; nước pha màu vàng ánh xanh, thơm; vị lúc đầu hơi chát, sau ngọt; cây còn ít nên ít người biết","Chè có vị mặn như muối","Cậu không trả lời được"]},{"cauHoi":"Thào A Sùng mơ ước điều gì?","dang":"TN","dapAn":0,"giaiThich":"Em ước làm kĩ sư nông nghiệp để giúp bản trồng được nhiều chè hơn. Em sẽ mang chè Tà Xùa đi khắp thế giới.","id":"V5-B42-03","mucDo":2,"phuongAn":["Làm kĩ sư nông nghiệp để giúp bản trồng nhiều chè hơn và mang chè Tà Xùa đi khắp thế giới","Chỉ bán chè trong bản, không đi đâu","Giấu nghề, không cho ai biết","Bỏ quê, không trồng chè nữa"]},{"cauHoi":"Vì sao khi nghe cậu nói, các bạn như quên cuộc thi?","dang":"TN","dapAn":2,"giaiThich":"Trong phút chốc, chúng tôi như quên mất cuộc thi, chỉ xôn xao hỏi nhau về cây chè quê hương.","id":"V5-B42-04","mucDo":2,"phuongAn":["Vì hết giờ thi","Vì chuông báo cháy","Vì câu chuyện và ước mơ về chè quê hương cuốn hút, đánh thức tình yêu sản vật quê hơn cả việc hơn thua tỉ số","Vì không ai nghe thấy"]},{"cauHoi":"Bắc Yên, Tà Xùa là những tên riêng cần viết như thế nào?","dang":"TN","dapAn":3,"giaiThich":"Tên địa lí được viết hoa.","id":"V5-B42-05","mucDo":1,"phuongAn":["Chỉ viết hoa chữ cuối","Không cần viết hoa","Viết thường toàn bộ","Viết hoa (tên địa lí)"]},{"cauHoi":"Hãy tưởng tượng Thào A Sùng đã trưởng thành và viết 4 – 5 câu kể tiếp: cậu đã làm gì để biến ước mơ về chè Tà Xùa thành hiện thực.","dang":"TL","giaiThich":"Gợi ý: Học thành kĩ sư; về bản trồng, chăm chè; giới thiệu chè ra xa; giữ được tự hào quê hương.","id":"V5-B42-06","mucDo":3}],"chuDe":"6","ten":"Những búp chè trên cây cổ thụ","tenChuDe":"Chủ điểm 6. Hương sắc trăm miền","tenGoc":"Bài 10. Những búp chè trên cây cổ thụ","tuan":"23","yeuCauCanDat":["Nhận xét được hình dáng, tính cách của nhân vật; nhận biết thời gian, địa điểm và tác dụng của chúng trong câu chuyện.","Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản.","Quy tắc viết tên người, tên địa lí nước ngoài; viết hoa danh từ chung để thể hiện sự tôn trọng đặc biệt."]},"43":{"cauHoi":[{"cauHoi":"Khổ thơ đầu “Hương cốm mùa thu” tả khung cảnh và cảm xúc khi mùa cốm đến như thế nào?","dang":"TN","dapAn":0,"giaiThich":"Tháng Chín heo may về phố / Dắt theo hương cốm vào thu / Sớm nay xôn xao ô cửa / Gió thơm vừa ghé – ô kìa!","id":"V5-B43-01","mucDo":1,"phuongAn":["Tháng Chín heo may về phố, dắt theo hương cốm vào thu; sớm xôn xao ô cửa, gió thơm vừa ghé – ô kìa!","Mùa hè nắng cháy, không có cốm","Không có gió, không có hương","Mùa đông tuyết rơi trên phố"]},{"cauHoi":"Hành trình làm ra hạt cốm theo lời gió diễn ra như thế nào?","dang":"TN","dapAn":1,"giaiThich":"Tay mẹ, tay bà sàng sảy / Cốm mang hồn đất, hồn người.","id":"V5-B43-02","mucDo":1,"phuongAn":["Chỉ máy móc làm, không có tay mẹ","Trời gieo hạt thóc tặng nhà nông; sớm khuya mồ hôi đợi lúa trĩu bông; hạt lúa căng sữa; tay mẹ, tay bà sàng sảy; cốm mang hồn đất, hồn người","Cốm được làm từ ngô, không cần lúa","Không có công đoạn nào"]},{"cauHoi":"Cách tả màu sắc hạt cốm cho thấy bạn nhỏ cảm nhận thế nào?","dang":"TN","dapAn":2,"giaiThich":"Em thấy màu vàng của nắng / Em thấy màu xanh của trời / Em thấy màu nâu của đất / Ủ trong hạt cốm xanh ngời!","id":"V5-B43-03","mucDo":2,"phuongAn":["Không gắn với nắng, trời, đất","Chỉ thấy màu đen","Thấy màu vàng của nắng, xanh của trời, nâu của đất ủ trong hạt cốm xanh ngời – cốm kết tinh thiên nhiên","Cốm không có màu"]},{"cauHoi":"Chi tiết nào cho thấy cốm là thức quà đặc trưng của Hà Nội?","dang":"TN","dapAn":0,"giaiThich":"Hồ Gươm chớp đôi mắt biếc / Nhắc mùa hương cốm vừa lên!","id":"V5-B43-04","mucDo":1,"phuongAn":["Tháng Chín ra phố, tay lùa gió thơm; Hồ Gươm chớp đôi mắt biếc, nhắc mùa hương cốm vừa lên","Không nhắc Hà Nội, Hồ Gươm","Cốm chỉ có ở miền núi Tây Nguyên","Cốm được tả vào tháng Bảy ở biển"]},{"cauHoi":"Các từ “đầu tiên, sau đó, tiếp theo, cuối cùng” dùng để làm gì trong đoạn văn?","dang":"TN","dapAn":3,"giaiThich":"Các câu trong một đoạn văn có thể liên kết bằng từ ngữ nối như: đầu tiên, sau đó, tiếp theo, cuối cùng...","id":"V5-B43-05","mucDo":1,"phuongAn":["Làm dấu gạch ngang","Làm danh từ riêng","Làm đại từ xưng hô","Từ ngữ nối, liên kết các câu (thường đứng đầu câu) theo trình tự"]},{"cauHoi":"Viết 4 – 5 câu nêu cảm nhận của em về tình cảm trong bài “Hương cốm mùa thu” (có thể gắn với Hà Nội, Hồ Gươm, tay mẹ tay bà).","dang":"TL","giaiThich":"Gợi ý: Heo may, hương cốm; công sức làm cốm; màu sắc thiên nhiên trong hạt cốm.","id":"V5-B43-06","mucDo":3}],"chuDe":"6","ten":"Hương cốm mùa thu","tenChuDe":"Chủ điểm 6. Hương sắc trăm miền","tenGoc":"Bài 11. Hương cốm mùa thu","tuan":"24","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nhận biết được văn bản viết theo tưởng tượng và văn bản viết về người thật, việc thật; hiểu từ ngữ, hình ảnh, biện pháp so sánh, nhân hoá trong văn bản.","Liên kết giữa các câu trong một đoạn văn; một số biện pháp liên kết câu và các từ ngữ liên kết: đặc điểm và tác dụng.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện."]},"44":{"cauHoi":[{"cauHoi":"Điệu múa Da dá của người Cơ-tu là gì? Hoa văn da dá ở đâu?","dang":"TN","dapAn":1,"giaiThich":"Điệu múa Da dá là một trong những điệu múa cổ xưa nhất của phụ nữ Cơ-tu. Đây là điệu múa cầu mùa.","id":"V5-B44-01","mucDo":1,"phuongAn":["Da dá là một món ăn","Điệu múa cầu mùa, thường trong lễ hội cộng đồng của phụ nữ Cơ-tu; hoa văn da dá được thợ dệt khắc từ điệu múa ấy trên thổ cẩm, trang trí váy, áo","Hoa văn chép từ chữ nước ngoài","Không có hoa văn nào"]},{"cauHoi":"Phụ nữ Cơ-tu múa Da dá như thế nào và để làm gì?","dang":"TN","dapAn":1,"giaiThich":"Khi múa, đôi tay của người phụ nữ xoè lên trời như để cầu xin và đón nhận hạt lúa từ thần linh.","id":"V5-B44-02","mucDo":1,"phuongAn":["Múa để đuổi thú rừng","Đôi tay xoè lên trời như để cầu xin và đón nhận hạt lúa từ thần linh – cầu mùa","Ngồi im không giơ tay","Múa dưới nước"]},{"cauHoi":"Hoa văn da dá trên váy, áo được thực hiện thế nào?","dang":"TN","dapAn":0,"giaiThich":"Người thợ dệt đã đính những hạt cườm trắng vào nền vải thô rám, tạo thành hoa văn da dá.","id":"V5-B44-03","mucDo":1,"phuongAn":["Thợ dệt đính hạt cườm trắng vào nền vải thô rám, tạo hoa văn da dá trang trí trên váy, áo phụ nữ","Vẽ bằng bút chì lên giấy","Thêu trên lụa trắng công nghiệp","Không làm trên vải"]},{"cauHoi":"Vì sao nói hoa văn da dá mang đậm sắc thái tộc người Cơ-tu?","dang":"TN","dapAn":2,"giaiThich":"Với vẻ đẹp mang đậm sắc thái tộc người, hoa văn da dá thực sự góp phần làm cho di sản trang phục của đồng bào Cơ-tu thêm giá trị.","id":"V5-B44-04","mucDo":2,"phuongAn":["Vì không liên quan đến lễ hội","Vì không dùng thổ cẩm","Vì nó tái hiện điệu múa cầu mùa cổ truyền, được dệt khéo trên thổ cẩm, góp phần làm tăng giá trị di sản trang phục của đồng bào Cơ-tu","Vì hoa văn giống hết mọi dân tộc khác"]},{"cauHoi":"Theo chú thích SGK, “thổ cẩm” và “di sản” nghĩa là gì?","dang":"TN","dapAn":3,"giaiThich":"Chú thích SGK: Thổ cẩm: loại vải... Di sản: sản phẩm vật chất và tinh thần của thời trước để lại.","id":"V5-B44-05","mucDo":1,"phuongAn":["Thổ cẩm là đá; di sản là đồ chơi","Không có chú thích","Thổ cẩm là tên một dòng sông","Thổ cẩm: loại vải của một số dân tộc thiểu số, dệt bằng sợi nhiều màu sặc sỡ; di sản: sản phẩm vật chất và tinh thần của thời trước để lại"]},{"cauHoi":"Viết 4 – 5 câu nêu điều tác giả muốn nói qua bài “Vũ điệu trên nền thổ cẩm” và cảm nghĩ của em về việc giữ gìn hoa văn, điệu múa dân tộc.","dang":"TL","giaiThich":"Gợi ý: Điệu múa cầu mùa; hoa văn trên thổ cẩm; sắc thái tộc người; tự hào và gìn giữ.","id":"V5-B44-06","mucDo":3}],"chuDe":"6","ten":"Vũ điệu trên nền thổ cẩm","tenChuDe":"Chủ điểm 6. Hương sắc trăm miền","tenGoc":"Bài 12. Vũ điệu trên nền thổ cẩm","tuan":"24","yeuCauCanDat":["Nhận biết được những chi tiết tiêu biểu và các thông tin chính của văn bản thông tin; xác định đề tài từ nhan đề, đề mục; nhận biết mục đích, đặc điểm, bố cục của văn bản giải thích, giới thiệu sách hoặc phim, quảng cáo, chương trình hoạt động; vai trò của hình ảnh, kí hiệu hoặc số liệu.","Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện."]},"45":{"cauHoi":[{"cauHoi":"Bài “Đàn trưng – tiếng ca đại ngàn” nói về điểm nổi bật nào của Tây Nguyên?","dang":"TN","dapAn":2,"giaiThich":"Đến Tây Nguyên, ta thường được nghe tiếng đàn trưng ngân dài theo dòng suối, hoà cùng tiếng gió trên đèo núi hoang vu.","id":"V5-B45-01","mucDo":1,"phuongAn":["Không nói về nhạc cụ nào","Chỉ nói về phố thị","Tiếng đàn trưng – nhạc cụ gắn bó với thiên nhiên, cuộc sống và tâm hồn người Tây Nguyên","Chỉ nói về biển đảo"]},{"cauHoi":"Tiếng đàn trưng gắn bó với người Tây Nguyên như thế nào?","dang":"TN","dapAn":1,"giaiThich":"Cùng với điệu hát ru, tiếng đàn trưng đã đi vào kí ức tuổi thơ; mỗi bước chân đều vấn vương nhịp điệu.","id":"V5-B45-02","mucDo":1,"phuongAn":["Chỉ xuất hiện trong thành phố","Cùng điệu hát ru, đi vào kí ức tuổi thơ từ lúc địu trên lưng mẹ; theo bước vào rừng, xuống suối, ra nương; khi khoan khi nhặt, trầm hùng như thác, thánh thót như suối","Không ai nghe từ nhỏ","Chỉ dùng trong giờ học Toán"]},{"cauHoi":"Chi tiết nào cho thấy đàn trưng phổ biến, được yêu thích?","dang":"TN","dapAn":3,"giaiThich":"Dưới mỗi gầm chòi... đều có một chiếc đàn trưng. Từ buôn này sang buôn khác, còn thấy đàn trưng trên đỉnh dốc cao.","id":"V5-B45-03","mucDo":1,"phuongAn":["Không ai gõ đàn","Chỉ có một chiếc đàn trong bảo tàng","Đàn chỉ để trang trí, không dùng","Dưới mỗi gầm chòi canh rẫy có đàn trưng cong như võng; trai làng gõ đuổi chim thú phá lúa, tiếng đàn rộn cả ngày lẫn đêm; trên đỉnh dốc cao cũng có đàn, người đi rừng gõ cho yên tâm vượt đường u tịch"]},{"cauHoi":"Vì sao tiếng đàn trưng trở thành niềm thương, nỗi nhớ của người Tây Nguyên?","dang":"TN","dapAn":0,"giaiThich":"Cùng với mái nhà rông thân thương, tiếng đàn trưng rộn ràng, lưu luyến đã trở thành niềm thương, nỗi nhớ của người Tây Nguyên.","id":"V5-B45-04","mucDo":2,"phuongAn":["Vì nó đã hoà vào đời sống hằng ngày, bên nhà rông, theo bước chân và kí ức tuổi thơ – thành âm thanh của quê hương","Vì người ta cấm gõ đàn","Vì đàn không có âm thanh","Vì đàn rất hiếm, không ai biết"]},{"cauHoi":"Từ “u tịch” theo chú thích SGK nghĩa là gì?","dang":"TN","dapAn":2,"giaiThich":"Chú thích: U tịch: vắng vẻ và tĩnh mịch.","id":"V5-B45-05","mucDo":1,"phuongAn":["Rất đông người","Rất ồn ào","Vắng vẻ và tĩnh mịch","Rất sáng"]},{"cauHoi":"Viết 4 – 5 câu nêu cảm nhận của em về cuộc sống và con người Tây Nguyên qua bài đọc về đàn trưng.","dang":"TL","giaiThich":"Gợi ý: Đàn trưng trong tuổi thơ, trên rẫy, trên đường rừng; sự gắn bó với thiên nhiên và cộng đồng.","id":"V5-B45-06","mucDo":3}],"chuDe":"6","ten":"Đàn trưng - tiếng ca đại ngàn","tenChuDe":"Chủ điểm 6. Hương sắc trăm miền","tenGoc":"Bài 13. Đàn trưng - tiếng ca đại ngàn","tuan":"25","yeuCauCanDat":["Nhận biết được những chi tiết tiêu biểu và các thông tin chính của văn bản thông tin; xác định đề tài từ nhan đề, đề mục; nhận biết mục đích, đặc điểm, bố cục của văn bản giải thích, giới thiệu sách hoặc phim, quảng cáo, chương trình hoạt động; vai trò của hình ảnh, kí hiệu hoặc số liệu.","Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện."]},"46":{"cauHoi":[{"cauHoi":"Ở khổ thơ đầu “Đường quê Đồng Tháp Mười” (Trần Quốc Toàn), đường về quê thú vị như thế nào?","dang":"TN","dapAn":3,"giaiThich":"Bông súng thả lồng đèn / Sáng bồng bềnh mặt nước / Cá lòng tong chạy trước / Dẫn đường về thăm ông.","id":"V5-B46-01","mucDo":1,"phuongAn":["Không có cá, hoa","Đường núi đá, không có nước","Đường phố đèn điện cao áp","Bông súng thả lồng đèn sáng bồng bềnh mặt nước; cá lòng tong chạy trước dẫn đường về thăm ông"]},{"cauHoi":"Những nét đẹp riêng nào của Đồng Tháp Mười được tả trong bài?","dang":"TN","dapAn":1,"giaiThich":"Xuồng lướt như tên bắn; cò bay lẫn mây trắng; thuyền đuôi tôm chở lúa vàng; kìa mấy búp sen hồng.","id":"V5-B46-02","mucDo":1,"phuongAn":["Núi lửa, tuyết","Đường quê sào vít cong, xuồng lướt như tên bắn, cò bay lẫn mây trắng, trâu đầm sừng loé nắng, thuyền đuôi tôm chở lúa vàng, búp sen hồng, nước lớn sông Cửu Long, cầu trăm đốt tre","Sa mạc, lạc đà","Cao ốc, tàu điện ngầm"]},{"cauHoi":"Ở khổ cuối, bạn nhỏ muốn nói điều gì về quê hương?","dang":"TN","dapAn":0,"giaiThich":"Về xứ mười tầng tháp / Leo cầu trăm đốt tre / Ông đứng như bụt hiện / Chờ cháu cuối đường quê.","id":"V5-B46-03","mucDo":2,"phuongAn":["Về xứ mười tầng tháp, leo cầu tre, ông đứng như bụt hiện chờ cháu cuối đường quê – tình thân và sự ấm áp của quê","Không muốn về quê","Ông không chờ cháu","Quê không có cầu, không có ông"]},{"cauHoi":"Theo chú thích, “xứ mười tầng tháp” chỉ vùng nào? “Cá lòng tong” là gì?","dang":"TN","dapAn":1,"giaiThich":"Chú thích: Xứ mười tầng tháp: chỉ Đồng Tháp Mười. Cá lòng tong: cá nước ngọt...","id":"V5-B46-04","mucDo":1,"phuongAn":["Tây Nguyên; một loài chim","Đồng Tháp Mười; cá lòng tong là cá nước ngọt nhỏ, sống thành đàn, mình dẹt, cùng họ cá chép","Sa mạc; một loại thuyền","Hà Nội; một loài hoa"]},{"cauHoi":"“Xuồng lướt như tên bắn”, “Ông đứng như bụt hiện” là biện pháp gì?","dang":"TN","dapAn":3,"giaiThich":"Như tên bắn, như bụt hiện – so sánh.","id":"V5-B46-05","mucDo":1,"phuongAn":["Dấu gạch nối","Cặp kết từ nếu thì","Từ điển thành ngữ","So sánh"]},{"cauHoi":"Viết 4 – 5 câu nêu những hình ảnh em thích nhất về Đồng Tháp Mười trong bài thơ và vì sao.","dang":"TL","giaiThich":"Gợi ý: Bông súng, cá lòng tong, xuồng, sen, ông chờ cháu cuối đường quê.","id":"V5-B46-06","mucDo":3}],"chuDe":"6","ten":"Đường quê Đồng Tháp Mười","tenChuDe":"Chủ điểm 6. Hương sắc trăm miền","tenGoc":"Bài 14. Đường quê Đồng Tháp Mười","tuan":"25","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Nhận biết được văn bản viết theo tưởng tượng và văn bản viết về người thật, việc thật; hiểu từ ngữ, hình ảnh, biện pháp so sánh, nhân hoá trong văn bản.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"47":{"cauHoi":[{"cauHoi":"Tác giả giới thiệu xuồng ba lá như thế nào?","dang":"TN","dapAn":0,"giaiThich":"Gọi là xuồng ba lá vì xuồng được ghép bởi ba tấm ván: hai tấm ván be và một tấm ván đáy.","id":"V5-B47-01","mucDo":1,"phuongAn":["Xuồng ghép bởi ba tấm ván (hai ván be, một ván đáy); dùng những chiếc cong đóng trong lòng xuồng, tạo khung hình xương cá cho vững chắc","Xuồng không có đáy","Xuồng có mái che kín","Xuồng làm bằng bốn tấm nhựa"]},{"cauHoi":"Xuồng ba lá gợi kỉ niệm nào với người thân?","dang":"TN","dapAn":2,"giaiThich":"Những sáng nội chèo xuồng mang bánh lá dừa, giỏ cua đồng; chiều chị bẻ bông điên điển cho má nấu canh chua.","id":"V5-B47-02","mucDo":1,"phuongAn":["Không có kỉ niệm nào","Chỉ đi ô tô với bố","Sáng nội chèo xuồng mang bánh lá dừa, giỏ cua đồng; chiều chị chèo dọc triền sông, bẻ bông điên điển cho má nấu canh chua","Chỉ đi máy bay"]},{"cauHoi":"Từ xưa, xuồng gắn bó thế nào với người dân Nam Bộ, cả trong kháng chiến?","dang":"TN","dapAn":1,"giaiThich":"Từ độ cha ông đi mở cõi, xuồng là đôi chân của người dân Nam Bộ. Xuồng chở lương thực tiếp tế cho bộ đội.","id":"V5-B47-03","mucDo":2,"phuongAn":["Xuồng chỉ mới xuất hiện năm ngoái","Là đôi chân của người dân Nam Bộ từ thuở cha ông mở cõi; thời bom đạn, xuồng cùng dân bám trụ, chở lương thực cho bộ đội, đưa du kích qua sông vào căn cứ","Xuồng chỉ để trang trí","Xuồng không dùng trong kháng chiến"]},{"cauHoi":"Trong cuộc sống thanh bình, hình ảnh xuồng hiện ra thế nào?","dang":"TN","dapAn":2,"giaiThich":"Mỗi sớm mai, những chiếc xuồng ba lá theo dòng nước toả đi, chở đầy ước mơ, khát vọng của tình đất, tình người phương Nam.","id":"V5-B47-04","mucDo":2,"phuongAn":["Xuồng bị bỏ hết, không còn dùng","Không còn sông nước","Xuồng ngược xuôi chợ nổi, lướt trên cánh đồng lúa, giăng câu thả lưới; sớm mai toả đi, chở ước mơ, khát vọng tình đất, tình người phương Nam","Xuồng chỉ nằm trong bảo tàng"]},{"cauHoi":"Theo chú thích SGK, “xuồng” là gì?","dang":"TN","dapAn":3,"giaiThich":"Chú thích: Xuồng: thuyền nhỏ, không có mái che.","id":"V5-B47-05","mucDo":1,"phuongAn":["Máy bay","Xe đạp","Tàu lớn có cabin","Thuyền nhỏ, không có mái che"]},{"cauHoi":"Viết 4 – 5 câu nêu điều bài đọc giúp em hiểu thêm về cảnh vật và con người phương Nam qua hình ảnh xuồng ba lá.","dang":"TL","giaiThich":"Gợi ý: Phương tiện sông nước; kỉ niệm gia đình; đôi chân mở cõi và kháng chiến; ước mơ đời thường.","id":"V5-B47-06","mucDo":3}],"chuDe":"6","ten":"Xuồng ba lá quê tôi","tenChuDe":"Chủ điểm 6. Hương sắc trăm miền","tenGoc":"Bài 15. Xuồng ba lá quê tôi","tuan":"26","yeuCauCanDat":["Nhận biết được những chi tiết tiêu biểu và các thông tin chính của văn bản thông tin; xác định đề tài từ nhan đề, đề mục; nhận biết mục đích, đặc điểm, bố cục của văn bản giải thích, giới thiệu sách hoặc phim, quảng cáo, chương trình hoạt động; vai trò của hình ảnh, kí hiệu hoặc số liệu.","Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện."]},"48":{"cauHoi":[{"cauHoi":"Những hình ảnh nào cho thấy vẻ đẹp độc đáo của cây cối ở Đất Mũi?","dang":"TN","dapAn":0,"giaiThich":"Về đây trông đước chạy / Những bước chân ngập sình. Ngút ngàn rừng mắm, đước / Xanh đến tận vô cùng.","id":"V5-B48-01","mucDo":2,"phuongAn":["Đước chạy những bước chân ngập sình; ngút ngàn rừng mắm, đước xanh đến vô cùng; rễ mắm ăn lên, rễ đước cắm xuống, bền bỉ trong tình yêu của đất; phù sa như dòng sữa nuôi đất rừng Năm Căn","Không có cây đước, cây mắm","Chỉ có thông và sồi trên núi","Rừng khô, không có phù sa"]},{"cauHoi":"Thiên nhiên Đất Mũi (gió, biển, đất trời) được tả thế nào?","dang":"TN","dapAn":0,"giaiThich":"Về đây nghe đất thở / Phập phồng trước bình minh. Nơi đây biển gặp rừng / Đất và trời gần lại / Cho bãi bồi vươn xa / Đất nước mình lớn mãi.","id":"V5-B48-02","mucDo":2,"phuongAn":["Đất thở phập phồng trước bình minh; gió châu thổ mở hội trên đồng, ca bài ca mở cõi; nơi biển gặp rừng, đất và trời gần lại, bãi bồi vươn xa, đất nước lớn mãi","Không có gió, không có biển","Đất hẹp dần, không bồi","Trời đóng băng"]},{"cauHoi":"Hai dòng “Nơi địa đầu Tổ quốc / Rạng ngời ánh bình minh!” và cảm giác “như về với nhà mình” gợi điều gì?","dang":"TN","dapAn":1,"giaiThich":"Lần đầu về Đất Mũi / Như về với nhà mình / Nơi địa đầu Tổ quốc / Rạng ngời ánh bình minh!","id":"V5-B48-03","mucDo":3,"phuongAn":["Tác giả cảm thấy xa lạ, muốn về ngay","Đất Mũi là cực Nam thiêng liêng của Tổ quốc; dù lần đầu đến, tác giả vẫn thấy thân thuộc như về nhà mình","Không gắn với Tổ quốc","Đó là vùng đất của nước ngoài"]},{"cauHoi":"Theo chú thích SGK, Đất Mũi (Mũi Cà Mau) ở đâu?","dang":"TN","dapAn":2,"giaiThich":"Chú thích: Đất Mũi (thường gọi là Mũi Cà Mau)... thuộc địa phận xóm Mũi, xã Đất Mũi, tỉnh Cà Mau.","id":"V5-B48-04","mucDo":1,"phuongAn":["Thuộc thành phố Hải Phòng","Thuộc Tây Nguyên","Vùng đất nhô ra ở điểm cực Nam trên đất liền của Tổ quốc, thuộc xóm Mũi, xã Đất Mũi, tỉnh Cà Mau","Thuộc tỉnh Quảng Trị"]},{"cauHoi":"Khổ đầu “Về đây nghe đất thở / Phập phồng trước bình minh” chủ yếu dùng biện pháp nào?","dang":"TN","dapAn":3,"giaiThich":"Đất thở phập phồng; đước chạy những bước chân – nhân hoá.","id":"V5-B48-05","mucDo":1,"phuongAn":["Câu ghép có nếu thì","Dấu gạch nối","Chỉ liệt kê số liệu","Nhân hoá (đất thở, đước chạy, gió ca bài ca mở cõi)"]},{"cauHoi":"Hãy viết 4 – 5 câu giới thiệu Đất Mũi Cà Mau với bạn (vị trí theo SGK, cảnh rừng đước – mắm, ý nghĩa địa đầu Tổ quốc).","dang":"TL","giaiThich":"Gợi ý: Cực Nam, tỉnh Cà Mau; rừng ngập mặn; phù sa; đất nước lớn mãi; cảm giác như về nhà.","id":"V5-B48-06","mucDo":3}],"chuDe":"6","ten":"Về thăm Đất Mũi","tenChuDe":"Chủ điểm 6. Hương sắc trăm miền","tenGoc":"Bài 16. Về thăm Đất Mũi","tuan":"26","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nhận biết được văn bản viết theo tưởng tượng và văn bản viết về người thật, việc thật; hiểu từ ngữ, hình ảnh, biện pháp so sánh, nhân hoá trong văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Nhận biết được những chi tiết tiêu biểu và các thông tin chính của văn bản thông tin; xác định đề tài từ nhan đề, đề mục; nhận biết mục đích, đặc điểm, bố cục của văn bản giải thích, giới thiệu sách hoặc phim, quảng cáo, chương trình hoạt động; vai trò của hình ảnh, kí hiệu hoặc số liệu."]},"49":{"cauHoi":[{"cauHoi":"Văn Miếu Thăng Long và Quốc Tử Giám được xây khi nào, để làm gì?","dang":"TN","dapAn":1,"giaiThich":"Năm 1070, vua Lý Thánh Tông cho xây Văn Miếu Thăng Long để thờ Khổng Tử; xây Quốc Tử Giám làm nơi dạy học.","id":"V5-B49-01","mucDo":1,"phuongAn":["Không rõ năm xây","Năm 1070, vua Lý Thánh Tông cho xây Văn Miếu để thờ Khổng Tử; ở đó còn xây Quốc Tử Giám dạy học cho hoàng tử, con em quý tộc, về sau cả con em dân thường học giỏi","Năm 2012, để làm bảo tàng hiện đại","Năm 1945, để làm chợ"]},{"cauHoi":"Từ năm nào nước ta mở khoa thi tiến sĩ? Đến năm nào? Có bao nhiêu khoa thi, lấy đỗ khoảng bao nhiêu tiến sĩ (theo bài)?","dang":"TN","dapAn":3,"giaiThich":"Từ năm 1075 đến khoa thi cuối cùng năm 1919: 185 khoa thi, lấy đỗ gần 3 000 tiến sĩ.","id":"V5-B49-02","mucDo":1,"phuongAn":["Không mở khoa thi nào","Chỉ thi năm 1070, không có số liệu","Từ năm 2000, chỉ 2 khoa thi, 10 tiến sĩ","Từ năm 1075 đến khoa cuối năm 1919; các triều vua tổ chức 185 khoa thi, lấy đỗ gần 3 000 tiến sĩ"]},{"cauHoi":"Chi tiết nào cho thấy ông cha coi trọng đào tạo nhân tài?","dang":"TN","dapAn":0,"giaiThich":"82 tấm bia khắc tên tuổi 306 vị tiến sĩ từ khoa thi năm 1442 đến khoa thi năm 1779 như chứng tích về một nền văn hiến lâu đời.","id":"V5-B49-03","mucDo":2,"phuongAn":["Quốc Tử Giám được coi là trường đại học đầu tiên của Việt Nam; dân thường học giỏi cũng được học; bên giếng Thiên Quang còn 82 tấm bia khắc tên 306 vị tiến sĩ (khoa 1442-1779)","Chỉ dạy cho một người","Không lưu tên người đỗ","Không có bia, không có trường"]},{"cauHoi":"Theo chú thích SGK, “văn hiến”, “Văn Miếu”, “Quốc Tử Giám” nghĩa là gì?","dang":"TN","dapAn":2,"giaiThich":"Chú thích SGK nêu rõ nghĩa các thuật ngữ.","id":"V5-B49-04","mucDo":1,"phuongAn":["Không có chú thích","Văn hiến là một loại đàn; Văn Miếu là chợ","Văn hiến: truyền thống văn hoá lâu đời và tốt đẹp; Văn Miếu: nơi thờ Khổng Tử và người có công mở mang giáo dục; Quốc Tử Giám: trường Nho học cao cấp thời xưa, đặt ở khu vực Văn Miếu","Quốc Tử Giám là tên một dòng sông"]},{"cauHoi":"Bài đọc giúp em hiểu điều gì về truyền thống khoa cử Việt Nam?","dang":"TN","dapAn":1,"giaiThich":"Ngót 10 thế kỉ... chứng tích về một nền văn hiến lâu đời.","id":"V5-B49-05","mucDo":2,"phuongAn":["Không ai được đỗ tiến sĩ","Đây là truyền thống lâu đời (ngót 10 thế kỉ), coi trọng học vấn và nhân tài, để lại chứng tích cụ thể ở Văn Miếu – Quốc Tử Giám","Khoa cử chỉ kéo dài một năm","Nước ta không có khoa cử"]},{"cauHoi":"Viết đoạn văn (4 – 5 câu) nêu ý kiến tán thành việc giữ gìn di tích Văn Miếu – Quốc Tử Giám (nêu lí do, dẫn chứng từ bài đọc).","dang":"TL","giaiThich":"Gợi ý: Trường đại học đầu tiên; 185 khoa thi; bia tiến sĩ; truyền thống văn hiến cần gìn giữ.","id":"V5-B49-06","mucDo":3}],"chuDe":"7","ten":"Nghìn năm văn hiến","tenChuDe":"Chủ điểm 7. Tiếp bước cha ông","tenGoc":"Bài 17. Nghìn năm văn hiến","tuan":"27","yeuCauCanDat":["Nhận biết được những chi tiết tiêu biểu và các thông tin chính của văn bản thông tin; xác định đề tài từ nhan đề, đề mục; nhận biết mục đích, đặc điểm, bố cục của văn bản giải thích, giới thiệu sách hoặc phim, quảng cáo, chương trình hoạt động; vai trò của hình ảnh, kí hiệu hoặc số liệu.","Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"5":{"cauHoi":[{"cauHoi":"Ở khổ thơ đầu bài “Tiếng hạt nảy mầm” (Tô Hà), chi tiết nào cho thấy đây là lớp học của trẻ khiếm thính?","dang":"TN","dapAn":2,"giaiThich":"Đôi tay cô cụp mở, báo tưng bừng thanh âm; các bé lặng chăm nhìn theo cô mấp máy.","id":"V5-B05-01","mucDo":1,"phuongAn":["Lớp không có cô giáo","Các em che tai vì ồn","Đôi tay cô cụp mở / Báo tưng bừng thanh âm (cô giáo dùng tay để “nói” thanh âm); các bé nhìn theo cô mấp máy","Các em đang ngủ"]},{"cauHoi":"Cô giáo đã gợi trong tâm trí học trò những hình ảnh, âm thanh nào?","dang":"TN","dapAn":3,"giaiThich":"Sau ngón tay cô đấy / Là tiếng hạt nảy mầm / Tiếng lá động trong vườn / Tiếng sớm mai mẹ gọi.","id":"V5-B05-02","mucDo":2,"phuongAn":["Không gợi âm thanh nào","Chỉ có bảng cửu chương","Chỉ có tiếng còi xe","Tiếng hạt nảy mầm, tiếng lá động trong vườn, tiếng sớm mai mẹ gọi; tàu biển, ngôi sao, vó ngựa,..."]},{"cauHoi":"Chi tiết nào cho thấy các bạn học rất chăm chú?","dang":"TN","dapAn":1,"giaiThich":"Mắt sáng, nhìn lên bảng; các bé vẫn lặng chăm nhìn theo cô.","id":"V5-B05-03","mucDo":1,"phuongAn":["Không ai nhìn cô","Mắt sáng nhìn lên bảng; các bé vẫn lặng chăm / Nhìn theo cô mấp máy","Các em bịt mắt","Các em chạy ra sân"]},{"cauHoi":"Hai khổ thơ cuối gợi suy nghĩ gì về cô giáo?","dang":"TN","dapAn":0,"giaiThich":"Bao nghĩ suy vất vả trong mắt người lo toan / Để từng âm có nghĩa bật lên từ môi em.","id":"V5-B05-04","mucDo":3,"phuongAn":["Cô vất vả lo toan để từng âm có nghĩa bật lên từ môi em; giữa lớp học hồn nhiên, ai cũng xúc động (nụ cười rưng rưng)","Cô không quan tâm học trò","Cô chỉ dạy một buổi rồi nghỉ","Cô cấm các em nhìn tay"]},{"cauHoi":"Từ “cô, các bé, em” trong bài thơ chủ yếu thuộc từ loại nào?","dang":"TN","dapAn":1,"giaiThich":"Đó là các đại từ dùng để xưng hô, chỉ người.","id":"V5-B05-05","mucDo":1,"phuongAn":["Từ đa nghĩa bắt buộc","Đại từ (xưng hô, chỉ người)","Kết từ","Dấu câu"]},{"cauHoi":"Viết 4 – 5 câu nêu suy nghĩ, tình cảm của em về cô giáo trong bài thơ “Tiếng hạt nảy mầm”.","dang":"TL","giaiThich":"Gợi ý: Nêu điều em tâm đắc; dẫn 1 – 2 chi tiết trong thơ; giải thích vì sao.","id":"V5-B05-06","mucDo":3},{"cauHoi":"Bài thơ về lớp học của trẻ khiếm thính được đặt tên là “Tiếng hạt nảy mầm”. Theo em, nhan đề ấy có ý nghĩa gì?","dang":"TN","dapAn":2,"giaiThich":"Với trẻ khiếm thính, âm thanh đến từ đôi tay cụp mở của cô giáo. Những “hạt” âm thanh ấy được gieo vào tâm hồn trẻ thơ, rồi nảy mầm thành từng tiếng nói có nghĩa — nhan đề gói trọn công việc thầm lặng và cao đẹp của cô giáo.","id":"TV5-B05-BS01","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Vì lớp học của các em nằm cạnh một khu vườn trồng cây","Vì các em được học thêm môn Tự nhiên về hạt giống","Vì qua đôi tay của cô giáo, những âm thanh của cuộc sống như hạt giống được gieo vào tâm hồn các em, dần nảy mầm thành tiếng nói có nghĩa","Vì cô giáo thường mang hạt giống đến lớp tặng học trò"]}],"chuDe":"1","ten":"Tiếng hạt nảy mầm","tenChuDe":"Chủ điểm 1. Thế giới tuổi thơ","tenGoc":"Bài 5. Tiếng hạt nảy mầm","tuan":"3","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nhận xét được hình dáng, tính cách của nhân vật; nhận biết thời gian, địa điểm và tác dụng của chúng trong câu chuyện.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Đại từ và kết từ: đặc điểm và chức năng; ôn luyện danh từ, động từ, tính từ."]},"50":{"cauHoi":[{"cauHoi":"Chu Văn An được giới thiệu như thế nào?","dang":"TN","dapAn":3,"giaiThich":"Chu Văn An là một nhà giáo nổi tiếng đời Trần. Cụ đỗ cao nhưng không làm quan mà mở trường dạy học ở quê nhà.","id":"V5-B50-01","mucDo":1,"phuongAn":["Làm quan to, không dạy học","Sống đời Nguyễn, không mở trường","Không có học trò","Nhà giáo nổi tiếng đời Trần; đỗ cao nhưng không làm quan, mở trường dạy học ở quê nhằm truyền bá đạo lí và đào tạo nhân tài; học trò đông, nhiều người thành nhân vật nổi tiếng"]},{"cauHoi":"Chi tiết nào cho thấy các môn sinh kính trọng cụ giáo Chu?","dang":"TN","dapAn":2,"giaiThich":"Từ sáng sớm, các môn sinh đã tề tựu trước sân nhà cụ. Các môn sinh đồng thanh dạ ran.","id":"V5-B50-02","mucDo":2,"phuongAn":["Mọi người bỏ về sớm","Học trò không mang gì","Ngày mừng thọ cụ tròn sáu mươi tuổi, môn sinh tề tựu từ sáng sớm; học trò cũ từ xa về dâng sách quý họ sưu tầm, chép lại; khi cụ mời đi, đồng thanh dạ ran, đi theo thứ tự tuổi","Không ai đến mừng thọ"]},{"cauHoi":"Cụ giáo Chu dẫn môn sinh đi đâu, làm gì?","dang":"TN","dapAn":0,"giaiThich":"Lạy thầy! Hôm nay con đem tất cả môn sinh đến tạ ơn thầy. Thì ra đây là cụ đồ xưa kia đã dạy vỡ lòng cho cụ giáo Chu.","id":"V5-B50-03","mucDo":2,"phuongAn":["Đến nhà tranh cuối làng thăm cụ đồ già trên tám mươi tuổi – người thầy đã dạy vỡ lòng cho cụ; cụ chắp tay cung kính vái Lạy thầy!, nói to vì cụ đồ nặng tai; các môn sinh lần lượt vái tạ","Đến chợ mua sách","Ở nhà, không đi đâu","Đến kinh thành nhận chức"]},{"cauHoi":"Em học được điều gì từ câu chuyện “Người thầy của muôn đời”?","dang":"TN","dapAn":0,"giaiThich":"Ngày mừng thọ thầy Chu năm ấy, họ được thêm một bài học thấm thía về nghĩa thầy trò.","id":"V5-B50-04","mucDo":2,"phuongAn":["Nghĩa thầy trò thiêng liêng: dù đã thành danh vẫn nhớ, tôn kính người thầy đã dạy mình; đó là bài học thấm thía về đạo làm trò","Không cần nhớ thầy cũ","Chỉ cần học giỏi, không cần lễ phép","Thầy trò không liên quan nhau"]},{"cauHoi":"Câu “Cụ đỗ cao nhưng không làm quan mà mở trường dạy học” là câu gì? Các vế nối bằng từ nào?","dang":"TN","dapAn":2,"giaiThich":"Có hơn một cụm chủ ngữ - vị ngữ, nối bằng kết từ nhưng, mà.","id":"V5-B50-05","mucDo":1,"phuongAn":["Câu hỏi","Câu cảm không có vế","Câu ghép; các vế nối bằng kết từ nhưng, mà","Câu đơn không có kết từ"]},{"cauHoi":"Viết 4 – 5 câu nêu điều em học được về đạo thầy trò qua chuyện Chu Văn An tạ ơn người thầy dạy vỡ lòng.","dang":"TL","giaiThich":"Gợi ý: Uống nước nhớ nguồn; tôn sư trọng đạo; dù thành danh vẫn biết ơn thầy đầu tiên.","id":"V5-B50-06","mucDo":3}],"chuDe":"7","ten":"Người thầy của muôn đời","tenChuDe":"Chủ điểm 7. Tiếp bước cha ông","tenGoc":"Bài 18. Người thầy của muôn đời","tuan":"27","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nhận xét được hình dáng, tính cách của nhân vật; nhận biết thời gian, địa điểm và tác dụng của chúng trong câu chuyện.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Câu đơn và câu ghép: đặc điểm và chức năng; cách nối các vế câu ghép."]},"51":{"cauHoi":[{"cauHoi":"Tuệ Tĩnh là ai? Ông dẫn học trò lên núi Nam Tào, Bắc Đẩu để nói điều gì?","dang":"TN","dapAn":3,"giaiThich":"Tuệ Tĩnh (1330-1400) là một danh y đời Trần. Ý nguyện: Ta muốn từ nay về sau, dân ta có thể dùng thuốc nam để chữa bệnh cho người Nam.","id":"V5-B51-01","mucDo":1,"phuongAn":["Không lên núi, không nói gì","Sống thế kỉ XX, ở Pháp","Một tướng nhà Trần, không làm thuốc","Danh y đời Trần (1330-1400), tên Nguyễn Bá Tĩnh, được suy tôn là tiên thánh của ngành thuốc nam; ông nói ý nguyện dùng thuốc nam chữa bệnh cho người Nam, nối gót người đi trước"]},{"cauHoi":"Câu chuyện Tuệ Tĩnh kể xảy ra lúc nào, tình hình ra sao?","dang":"TN","dapAn":1,"giaiThich":"Khi giặc ngoại xâm nhòm ngó nước ta... việc vận chuyển thuốc men từ Trung Quốc sang nước ta đã bị ngăn cấm.","id":"V5-B51-02","mucDo":2,"phuongAn":["Đời Nguyễn, không có giặc","Thời Trần, khi giặc ngoại xâm nhòm ngó; thuốc men từ Trung Quốc bị ngăn cấm; vua quan lo khi giáp trận người bị thương, ốm thì lấy gì chạy chữa","Thời bình, thuốc men rất dư dả","Không có chuyện vận chuyển thuốc"]},{"cauHoi":"Người xưa đã làm gì và kết quả ra sao?","dang":"TN","dapAn":0,"giaiThich":"Các thái y bèn toả đi khắp mọi miền quê học cách chữa bệnh bằng cây cỏ trong dân gian. Vườn thuốc mọc lên khắp nơi.","id":"V5-B51-03","mucDo":2,"phuongAn":["Các thái y toả đi khắp miền quê học cách chữa bệnh bằng cây cỏ dân gian; vườn thuốc mọc lên khắp nơi; Nam Tào, Bắc Đẩu là hai ngọn dược sơn (theo chú thích SGK: ở thành phố Hải Phòng)","Không ai học thuốc dân gian","Không có vườn thuốc","Chỉ mua thuốc nước ngoài"]},{"cauHoi":"Vì sao ý nguyện của Tuệ Tĩnh trở thành hiện thực và được kế thừa đến nay?","dang":"TN","dapAn":3,"giaiThich":"Theo con đường của danh y Tuệ Tĩnh, cho đến nay, hàng trăm vị thuốc từ cây cỏ nước Nam, hàng nghìn phương thuốc được tổng hợp từ dân gian.","id":"V5-B51-04","mucDo":2,"phuongAn":["Vì ý nguyện bị lãng quên ngay","Vì ông cấm dùng thuốc nam","Vì không ai theo ông","Vì ông biết quý ngọn cây sợi cỏ của non sông, truyền cho học trò nối gót; đến nay đã có hàng trăm vị thuốc từ cây cỏ nước Nam, hàng nghìn phương thuốc tổng hợp từ dân gian"]},{"cauHoi":"Theo chú thích SGK, núi Nam Tào, Bắc Đẩu ở đâu?","dang":"TN","dapAn":2,"giaiThich":"Chú thích SGK: Núi Nam Tào, Bắc Đẩu: hai ngọn núi ở thành phố Hải Phòng.","id":"V5-B51-05","mucDo":1,"phuongAn":["Ở Tây Nguyên","Ở Pháp","Hai ngọn núi ở thành phố Hải Phòng","Ở Cà Mau"]},{"cauHoi":"Viết 4 – 5 câu nêu cảm nghĩ của em về danh y Tuệ Tĩnh và ý nghĩa của việc dùng thuốc nam chữa bệnh cho người Nam.","dang":"TL","giaiThich":"Gợi ý: 1330-1400, đời Trần; ý nguyện thuốc nam; kế thừa đến hôm nay.","id":"V5-B51-06","mucDo":3}],"chuDe":"7","ten":"Danh y Tuệ Tĩnh","tenChuDe":"Chủ điểm 7. Tiếp bước cha ông","tenGoc":"Bài 19. Danh y Tuệ Tĩnh","tuan":"28","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nhận biết được những chi tiết tiêu biểu và các thông tin chính của văn bản thông tin; xác định đề tài từ nhan đề, đề mục; nhận biết mục đích, đặc điểm, bố cục của văn bản giải thích, giới thiệu sách hoặc phim, quảng cáo, chương trình hoạt động; vai trò của hình ảnh, kí hiệu hoặc số liệu.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện."]},"52":{"cauHoi":[{"cauHoi":"Nguyễn Đình Chiểu sinh năm nào, ở đâu (theo bài và chú thích địa danh hiện nay)?","dang":"TN","dapAn":1,"giaiThich":"Nguyễn Đình Chiểu (1822-1888) sinh ra... tỉnh Gia Định (nay là Thành phố Hồ Chí Minh).","id":"V5-B52-01","mucDo":1,"phuongAn":["1452-1519 ở Ý","1822-1888, sinh trong gia đình nhà nho ở làng Tân Thới, huyện Bình Dương, phủ Tân Bình, tỉnh Gia Định (nay là Thành phố Hồ Chí Minh)","1330-1400 ở Hải Phòng","1910-1986 ở Nghệ An"]},{"cauHoi":"Tóm tắt những thử thách chính trong đời ông trước khi mở trường, làm thuốc?","dang":"TN","dapAn":3,"giaiThich":"Trên đường về, ông bị ốm nặng, mù cả hai mắt... lỡ bề báo hiếu, lỡ đường lập thân.","id":"V5-B52-02","mucDo":2,"phuongAn":["Ông không bao giờ về Nam","Ông sống suốt đời bình yên, không thi cử","Ông không bị đau mắt","Năm 1833 gia đình li tán, mười hai tuổi phải ra Huế ăn học; 1843 đỗ tú tài Gia Định; 1848 mẹ mất, ông bỏ thi về chịu tang, trên đường bị ốm nặng, mù cả hai mắt, về đến Gia Định cuối 1849 với nỗi lỡ bề báo hiếu, lỡ đường lập thân"]},{"cauHoi":"Sau những thử thách ấy và khi giặc Pháp xâm lược (1858), ông đã làm gì?","dang":"TN","dapAn":0,"giaiThich":"Ông mở trường dạy học và làm thuốc chữa bệnh cho dân... Năm 1858... cùng các lãnh tụ nghĩa quân bàn mưu tính kế đánh giặc. Ông sáng tác thơ văn...","id":"V5-B52-03","mucDo":2,"phuongAn":["Không gục ngã: mở trường dạy học, làm thuốc chữa bệnh, học trò đông; cùng nghĩa quân bàn mưu đánh giặc; sáng tác thơ văn tiếc thương người hi sinh, khích lệ tinh thần chiến đấu","Ông không quan tâm đất nước","Ông bỏ hết việc dạy và viết","Ông ra làm việc cho giặc"]},{"cauHoi":"Vì sao nhân dân Lục tỉnh gọi ông bằng cái tên trìu mến “cụ Đồ Chiểu”?","dang":"TN","dapAn":1,"giaiThich":"Ông được nhân dân Lục tỉnh gọi bằng cái tên trìu mến cụ Đồ Chiểu như một cách tri ân với người thầy đáng kính của lòng dân.","id":"V5-B52-04","mucDo":2,"phuongAn":["Vì ông là quan to của triều đình","Như cách tri ân người thầy đáng kính của lòng dân – người vừa dạy học, vừa làm thuốc, vừa gắn bó sắt son với vận mệnh đất nước","Vì ông sống ở nước ngoài","Vì ông không dạy ai"]},{"cauHoi":"Chủ đề gần nhất của bài đọc là gì?","dang":"TN","dapAn":2,"giaiThich":"Trái tim nhân hậu của ông luôn gắn bó sắt son với vận mệnh của đất nước.","id":"V5-B52-05","mucDo":2,"phuongAn":["Chỉ kể về một chuyến du lịch","Không gắn với lịch sử","Tấm lòng yêu nước, thương dân và ý chí không gục ngã của nhà giáo, nhà thơ, thầy thuốc Nguyễn Đình Chiểu","Chỉ nói về kĩ thuật làm thuốc Tây"]},{"cauHoi":"Viết 4 – 5 câu tóm tắt cuộc đời cụ Đồ Chiểu và nêu vì sao em kính trọng ông.","dang":"TL","giaiThich":"Gợi ý: Gia Định, mù mắt vẫn dạy học, làm thuốc; thơ văn yêu nước; tên gọi của lòng dân.","id":"V5-B52-06","mucDo":3}],"chuDe":"7","ten":"Cụ Đồ Chiểu","tenChuDe":"Chủ điểm 7. Tiếp bước cha ông","tenGoc":"Bài 20. Cụ Đồ Chiểu","tuan":"28","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nhận xét được hình dáng, tính cách của nhân vật; nhận biết thời gian, địa điểm và tác dụng của chúng trong câu chuyện.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"53":{"cauHoi":[{"cauHoi":"Anh hùng Lao động Trần Đại Nghĩa tên khai sinh, quê quán, năm sinh mất và quá trình học tập như thế nào?","dang":"TN","dapAn":3,"giaiThich":"Anh hùng Lao động Trần Đại Nghĩa tên khai sinh là Phạm Quang Lễ, quê ở tỉnh Vĩnh Long. (1913-1997). Năm 1935 được cấp học bổng sang Pháp.","id":"V5-B53-01","mucDo":1,"phuongAn":["Sinh năm 1822, học ở Huế","Không học ở nước ngoài","Tên thật Nguyễn Đình Chiểu, quê Hà Nội","Tên khai sinh Phạm Quang Lễ, quê tỉnh Vĩnh Long, 1913-1997; học trung học ở Sài Gòn, năm 1935 được học bổng sang Pháp học kĩ sư cầu cống, điện, hàng không, đồng thời nghiên cứu kĩ thuật chế tạo vũ khí"]},{"cauHoi":"Việc ông về nước năm 1946 nói lên điều gì?","dang":"TN","dapAn":0,"giaiThich":"Năm 1946, nghe theo tiếng gọi thiêng liêng của Tổ quốc, Phạm Quang Lễ đã rời bỏ cuộc sống đầy đủ tiện nghi ở nước ngoài, theo Bác Hồ về nước.","id":"V5-B53-02","mucDo":2,"phuongAn":["Ông nghe tiếng gọi Tổ quốc, rời bỏ cuộc sống đầy đủ tiện nghi ở nước ngoài, theo Bác Hồ về nước – lòng yêu nước, sẵn sàng cống hiến","Ông không theo Bác","Ông về để nghỉ ngơi, không làm gì","Ông về vì hết việc ở Pháp"]},{"cauHoi":"Ông có những đóng góp gì? Nhà nước ghi nhận ra sao?","dang":"TN","dapAn":1,"giaiThich":"Chế tạo thành công súng ba-dô-ca, súng không giật, bom bay... Năm 1952, ông được tuyên dương Anh hùng Lao động.","id":"V5-B53-03","mucDo":2,"phuongAn":["Ông không chế tạo vũ khí nào","Bác đặt tên Trần Đại Nghĩa, giao nghiên cứu chế tạo vũ khí kháng chiến: súng ba-dô-ca, súng không giật, bom bay; còn có công xây dựng nền khoa học trẻ của nước nhà. Năm 1948 phong Thiếu tướng; 1952 tuyên dương Anh hùng Lao động; được tặng Giải thưởng Hồ Chí Minh và nhiều huân chương","Không được ghi nhận","Chỉ làm thơ, không làm khoa học"]},{"cauHoi":"Chủ đề gần nhất của bài đọc là gì?","dang":"TN","dapAn":2,"giaiThich":"Bên cạnh những cống hiến xuất sắc cho sự nghiệp quốc phòng, Trần Đại Nghĩa còn có công lớn trong việc xây dựng nền khoa học trẻ tuổi của nước nhà.","id":"V5-B53-04","mucDo":2,"phuongAn":["Chỉ kể về một chuyến du lịch Pháp","Chỉ nói về nghề nông","Tấm gương yêu nước, tài năng khoa học và cống hiến của Trần Đại Nghĩa cho quốc phòng và nền khoa học nước nhà","Không gắn với kháng chiến"]},{"cauHoi":"Theo chú thích SGK, “Anh hùng Lao động” là gì?","dang":"TN","dapAn":3,"giaiThich":"Chú thích: Anh hùng Lao động: danh hiệu Nhà nước phong tặng...","id":"V5-B53-05","mucDo":1,"phuongAn":["Tên một môn thể thao","Một loại huân chương bằng gỗ","Tên một dòng sông","Danh hiệu Nhà nước phong tặng cho đơn vị hoặc cá nhân có thành tích đặc biệt trong lao động"]},{"cauHoi":"Viết 4 – 5 câu giới thiệu Anh hùng Lao động Trần Đại Nghĩa và nêu điều em học được từ việc ông về nước năm 1946.","dang":"TL","giaiThich":"Gợi ý: Phạm Quang Lễ, Vĩnh Long; học ở Pháp; theo Bác về nước; vũ khí kháng chiến; Anh hùng Lao động 1952.","id":"V5-B53-06","mucDo":3}],"chuDe":"7","ten":"Anh hùng Lao động Trần Đại Nghĩa","tenChuDe":"Chủ điểm 7. Tiếp bước cha ông","tenGoc":"Bài 21. Anh hùng Lao động Trần Đại Nghĩa","tuan":"29","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Nhận biết được những chi tiết tiêu biểu và các thông tin chính của văn bản thông tin; xác định đề tài từ nhan đề, đề mục; nhận biết mục đích, đặc điểm, bố cục của văn bản giải thích, giới thiệu sách hoặc phim, quảng cáo, chương trình hoạt động; vai trò của hình ảnh, kí hiệu hoặc số liệu.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"54":{"cauHoi":[{"cauHoi":"Những từ ngữ nào thể hiện nỗi niềm mong nhớ các anh bộ đội của dân làng trong bài Hoàng Trung Thông?","dang":"TN","dapAn":1,"giaiThich":"Các anh đi / Ngày ấy đã lâu rồi / Xóm làng tôi còn nhớ mãi... Bao giờ trở lại / Xóm làng tôi trai gái vẫn chờ mong.","id":"V5-B54-01","mucDo":1,"phuongAn":["Không ai nhớ các anh","Các anh đi, ngày ấy đã lâu rồi, xóm làng tôi còn nhớ mãi; Bao giờ trở lại, trai gái vẫn chờ mong","Dân làng muốn các anh đi mãi","Không có từ ngữ mong nhớ"]},{"cauHoi":"Không khí xóm làng thay đổi thế nào khi bộ đội về? Hình ảnh nào cho thấy điều đó?","dang":"TN","dapAn":2,"giaiThich":"Các anh về mái ấm nhà vui / Tiếng hát câu cười / Rộn ràng xóm nhỏ... Mẹ già bịn rịn áo nâu.","id":"V5-B54-02","mucDo":2,"phuongAn":["Mọi người tránh các anh","Làng im ắng, đóng cửa","Mái ấm nhà vui, tiếng hát câu cười rộn ràng; tưng bừng trước ngõ, lớp lớp đàn em hớn hở theo sau; mẹ già bịn rịn áo nâu, vui đàn con ở rừng sâu mới về; nhà lá đơn sơ nhưng tấm lòng rộng mở, nồi cơm nấu dở, bát nước chè xanh, kể chuyện tâm tình","Không ai ra đón"]},{"cauHoi":"Năm dòng thơ cuối gợi cảm xúc, suy nghĩ gì?","dang":"TN","dapAn":0,"giaiThich":"Nhà lá đơn sơ, / Nhưng tấm lòng rộng mở, / Nồi cơm nấu dở / Bát nước chè xanh / Ngồi vui kể chuyện tâm tình bên nhau.","id":"V5-B54-03","mucDo":2,"phuongAn":["Dù nhà lá đơn sơ, tấm lòng dân vẫn rộng mở; sự đón tiếp chân tình bằng nồi cơm, bát nước chè, lời kể chuyện – tình quân dân ấm áp","Dân làng thờ ơ","Không có gì để đãi","Các anh không vào nhà"]},{"cauHoi":"Người dân dành tình cảm gì cho bộ đội? Chủ đề gần nhất của bài thơ?","dang":"TN","dapAn":3,"giaiThich":"Tình cảm bịn rịn, chờ mong, đón tiếp tưng bừng – tình quân dân.","id":"V5-B54-04","mucDo":2,"phuongAn":["Không chờ đợi","Thờ ơ, không quan tâm","Chỉ sợ hãi","Tình thương yêu, nhớ thương, trân trọng, gắn bó như người nhà; tình quân dân thắm thiết, hậu phương và tiền tuyến gắn bó"]},{"cauHoi":"Theo chú thích SGK, “bịn rịn” và “đơn sơ” nghĩa là gì?","dang":"TN","dapAn":0,"giaiThich":"Chú thích: Bịn rịn: lưu luyến, không muốn rời xa. Đơn sơ: đơn giản và sơ sài.","id":"V5-B54-05","mucDo":1,"phuongAn":["Bịn rịn: lưu luyến, không muốn rời xa; đơn sơ: đơn giản và sơ sài","Bịn rịn: chạy nhanh","Không có chú thích","Bịn rịn: giận dữ; đơn sơ: xa hoa"]},{"cauHoi":"Viết đoạn văn (4 – 5 câu) thể hiện tình cảm, cảm xúc về hình ảnh bộ đội về làng trong bài thơ (có thể liên hệ một việc làm vì cộng đồng của bộ đội mà em biết).","dang":"TL","giaiThich":"Gợi ý: Sự chờ mong; không khí vui; nhà đơn sơ nhưng tấm lòng rộng mở; tình quân dân.","id":"V5-B54-06","mucDo":3}],"chuDe":"7","ten":"Bộ đội về làng","tenChuDe":"Chủ điểm 7. Tiếp bước cha ông","tenGoc":"Bài 22. Bộ đội về làng","tuan":"29","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"55":{"cauHoi":[{"cauHoi":"Tìm trong bài “Về ngôi nhà đang xây” (Đồng Xuân Lan) những hình ảnh so sánh, nhân hoá.","dang":"TN","dapAn":2,"giaiThich":"Trụ bê tông nhú lên như một mầm cây; ngôi nhà giống bài thơ sắp làm xong; nắng đứng ngủ quên; ngôi nhà như trẻ nhỏ.","id":"V5-B55-01","mucDo":2,"phuongAn":["Chỉ liệt kê dụng cụ","Chỉ có số liệu, không hình ảnh","So sánh: giàn giáo tựa cái lồng che chở, trụ bê tông nhú lên như một mầm cây, ngôi nhà giống bài thơ sắp làm xong, ngôi nhà như trẻ nhỏ. Nhân hoá: bác thợ huơ cái bay tạm biệt, ngôi nhà thở ra mùi vôi vữa, bầy chim rót vào ô cửa vài nốt nhạc, nắng đứng ngủ quên","Không có so sánh, nhân hoá"]},{"cauHoi":"Chi tiết nào cho thấy thiên nhiên mang lại sự sống động cho ngôi nhà đang xây?","dang":"TN","dapAn":1,"giaiThich":"Bầy chim đi ăn về / Rót vào ô cửa chưa sơn vài nốt nhạc. Nắng đứng ngủ quên / Trên những bức tường.","id":"V5-B55-02","mucDo":2,"phuongAn":["Không có chim, nắng, gió","Bầy chim đi ăn về rót vào ô cửa chưa sơn vài nốt nhạc; nắng đứng ngủ quên trên tường; gió mang hương ủ đầy những rãnh tường chưa trát vữa","Nhà đã đóng kín hết cửa","Chỉ có tiếng máy, không thiên nhiên"]},{"cauHoi":"Hai dòng “Ngôi nhà như trẻ nhỏ / Lớn lên với trời xanh” và hình ảnh ngôi nhà đang xây nói lên điều gì?","dang":"TN","dapAn":1,"giaiThich":"Bao ngôi nhà đã hoàn thành / Đều qua những ngày xây dở. Ngôi nhà như trẻ nhỏ / Lớn lên với trời xanh.","id":"V5-B55-03","mucDo":3,"phuongAn":["Không ai xây nhà","Công trình đang lớn dần như một đứa trẻ; cuộc sống luôn có những ngày xây dở rồi hoàn thành – sự vươn lên, hi vọng của cuộc sống","Nhà không bao giờ lớn","Cuộc sống không thay đổi"]},{"cauHoi":"Trong câu thơ có “Bác thợ nề”, việc viết hoa “Bác” thể hiện điều gì?","dang":"TN","dapAn":0,"giaiThich":"SGK: viết hoa danh từ chung để thể hiện sự tôn trọng đặc biệt.","id":"V5-B55-04","mucDo":1,"phuongAn":["Viết hoa danh từ chung để thể hiện sự tôn trọng đặc biệt","Không có quy tắc nào","Viết hoa vì là tên nước ngoài","Lỗi chính tả"]},{"cauHoi":"Theo chú thích, “cái bay” là gì?","dang":"TN","dapAn":3,"giaiThich":"Chú thích: Cái bay: dụng cụ của thợ nề... dùng để xây, trát, láng.","id":"V5-B55-05","mucDo":1,"phuongAn":["Một loại thuyền","Một loại chim","Một loại đàn","Dụng cụ của thợ nề: miếng thép mỏng hình lá tra vào cán, dùng để xây, trát, láng"]},{"cauHoi":"Viết 4 – 5 câu nêu cảm nghĩ của em khi đọc “Ngôi nhà như trẻ nhỏ / Lớn lên với trời xanh” và điều bài thơ nói về cuộc sống.","dang":"TL","giaiThich":"Gợi ý: So sánh nhà với trẻ nhỏ, mầm cây, bài thơ dở; mọi hoàn thành đều qua ngày xây dở.","id":"V5-B55-06","mucDo":3}],"chuDe":"7","ten":"Về ngôi nhà đang xây","tenChuDe":"Chủ điểm 7. Tiếp bước cha ông","tenGoc":"Bài 23. Về ngôi nhà đang xây","tuan":"30","yeuCauCanDat":["Nhận biết được văn bản viết theo tưởng tượng và văn bản viết về người thật, việc thật; hiểu từ ngữ, hình ảnh, biện pháp so sánh, nhân hoá trong văn bản.","Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Quy tắc viết tên người, tên địa lí nước ngoài; viết hoa danh từ chung để thể hiện sự tôn trọng đặc biệt."]},"56":{"cauHoi":[{"cauHoi":"Bài thơ “Việt Nam quê hương ta” (Nguyễn Đình Thi) mở ra vẻ đẹp nào của đất nước?","dang":"TN","dapAn":2,"giaiThich":"Việt Nam đất nước ta ơi / Mênh mông biển lúa đâu trời đẹp hơn / Cánh cò bay lả rập rờn / Mây mờ che đỉnh Trường Sơn sớm chiều.","id":"V5-B56-01","mucDo":2,"phuongAn":["Chỉ tả sa mạc","Không có hình ảnh thiên nhiên","Biển lúa mênh mông, cánh cò bay lả, mây mờ che đỉnh Trường Sơn; đất nắng chan hoà, hoa thơm quả ngọt bốn mùa; đất trăm nghề của trăm vùng, tay người như có phép tiên","Chỉ tả một thành phố nước ngoài"]},{"cauHoi":"Hình ảnh con người Việt Nam trong những năm thương đau được tả thế nào?","dang":"TN","dapAn":1,"giaiThich":"Đất nghèo nuôi những anh hùng / Chìm trong máu lửa lại vùng đứng lên / Đạp quân thù xuống đất đen / Súng gươm vứt bỏ lại hiền như xưa.","id":"V5-B56-02","mucDo":2,"phuongAn":["Không có anh hùng","Quê hương chịu nhiều thương đau, mặt người vất vả in sâu, gái trai áo nâu nhuộm bùn; đất nghèo nuôi những anh hùng, chìm trong máu lửa lại vùng đứng lên, đạp quân thù rồi lại hiền như xưa","Không ai đứng lên","Con người không trải qua gian khó"]},{"cauHoi":"Tác giả muốn nói điều gì và thể hiện tình cảm gì?","dang":"TN","dapAn":3,"giaiThich":"Quê hương biết mấy thân yêu... Mắt đen cô gái long lanh / Yêu ai yêu trọn tấm tình thuỷ chung.","id":"V5-B56-03","mucDo":2,"phuongAn":["Không có tình cảm","Chỉ chê đất nước","Thờ ơ với quê hương","Tự hào, yêu thương đất nước tươi đẹp, con người cần cù, thuỷ chung, anh hùng mà nhân hậu, khéo tay; tình yêu quê hương sâu nặng"]},{"cauHoi":"Từ “thân yêu” gần nghĩa với từ nào?","dang":"TN","dapAn":2,"giaiThich":"SGK yêu cầu tìm từ đồng nghĩa với thân yêu.","id":"V5-B56-04","mucDo":1,"phuongAn":["Ghét bỏ","Lạnh nhạt","Thân thương, yêu quý","Xa lạ"]},{"cauHoi":"Trong câu “Việt Nam đất nước ta ơi / Mênh mông biển lúa”, từ “biển” được dùng theo nghĩa nào là hợp lí?","dang":"TN","dapAn":0,"giaiThich":"Biển lúa là nghĩa chuyển, so sánh sự mênh mông của ruộng lúa.","id":"V5-B56-05","mucDo":1,"phuongAn":["Nghĩa chuyển (biển lúa: ruộng lúa mênh mông như biển), không phải nghĩa gốc “biển nước mặn”","Là danh từ riêng","Nghĩa gốc: vùng nước mặn","Là kết từ"]},{"cauHoi":"Viết 4 – 5 câu nêu những câu thơ em thích trong bài “Việt Nam quê hương ta” và vì sao; thể hiện tình cảm của em với quê hương.","dang":"TL","giaiThich":"Gợi ý: Chọn 2-3 hình ảnh (biển lúa, Trường Sơn, anh hùng, trăm nghề); nêu cảm xúc tự hào, yêu quý.","id":"V5-B56-06","mucDo":3}],"chuDe":"7","ten":"Việt Nam quê hương ta","tenChuDe":"Chủ điểm 7. Tiếp bước cha ông","tenGoc":"Bài 24. Việt Nam quê hương ta","tuan":"30","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản.","Từ đồng nghĩa: đặc điểm và tác dụng.","Từ đa nghĩa và nghĩa của từ đa nghĩa trong văn bản.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"57":{"cauHoi":[{"cauHoi":"Bài thơ “Bài ca trái đất” (Định Hải) mở đầu bằng hình ảnh nào?","dang":"TN","dapAn":0,"giaiThich":"Trái đất này là của chúng mình / Quả bóng xanh bay giữa trời xanh / Bồ câu ơi... Hải âu ơi... Cùng bay nào, cho trái đất quay!","id":"V5-B57-01","mucDo":1,"phuongAn":["Trái đất là của chúng mình, như quả bóng xanh bay giữa trời xanh; bồ câu, hải âu cùng bay cho trái đất quay","Trái đất là một khối lửa không có sự sống","Không có chim","Chỉ có khói hình nấm"]},{"cauHoi":"Khổ thơ thứ hai ý nói gì?","dang":"TN","dapAn":1,"giaiThich":"Vàng, trắng, đen... dù da khác màu / Ta là nụ, là hoa của đất / Màu hoa nào cũng quý, cũng thơm!","id":"V5-B57-02","mucDo":2,"phuongAn":["Không ai là hoa của đất","Trái đất của bạn trẻ năm châu, dù da vàng, trắng, đen khác màu, ta đều là nụ, là hoa của đất; màu hoa nào cũng quý, cũng thơm – mọi dân tộc đều bình đẳng, đáng quý","Trái đất không dành cho trẻ em","Chỉ một màu da là đáng quý"]},{"cauHoi":"Những hình ảnh nào đối lập với hoà bình? Hai dòng “Tiếng hát vui giữ bình yên trái đất / Tiếng cười ran cho trái đất không già” nói điều gì?","dang":"TN","dapAn":3,"giaiThich":"Khói hình nấm là tai hoạ đấy / Bom H, bom A không phải bạn ta / Tiếng hát vui giữ bình yên trái đất / Tiếng cười ran cho trái đất không già.","id":"V5-B57-03","mucDo":2,"phuongAn":["Không có hình ảnh chiến tranh","Tiếng hát làm trái đất già đi","Bom A, bom H là bạn của trẻ em","Khói hình nấm, bom H, bom A không phải bạn ta – đối lập với hoà bình. Tiếng hát, tiếng cười giữ bình yên, làm trái đất không già"]},{"cauHoi":"Theo chú thích SGK, “năm châu” và “khói hình nấm” nghĩa là gì?","dang":"TN","dapAn":2,"giaiThich":"Chú thích SGK: Năm châu... Khói hình nấm: cột khói giống hình cây nấm khổng lồ, sinh ra sau vụ nổ bom H, bom A.","id":"V5-B57-04","mucDo":1,"phuongAn":["Khói hình nấm là khói bếp","Năm châu là năm làng; khói hình nấm là mây mùa hạ","Năm châu: Á, Âu, Phi, Mỹ, Đại Dương; khói hình nấm: cột khói giống cây nấm khổng lồ sinh ra sau vụ nổ bom H, bom A","Không có chú thích"]},{"cauHoi":"Khi viết tên người, tên địa lí nước ngoài, em cần theo quy tắc nào đã học?","dang":"TN","dapAn":3,"giaiThich":"CT và SGK: quy tắc viết tên người, tên địa lí nước ngoài.","id":"V5-B57-05","mucDo":1,"phuongAn":["Chỉ viết chữ số","Không được viết tên nước ngoài","Viết thường toàn bộ, không cần quy tắc","Viết đúng tên người, tên địa lí nước ngoài (theo quy tắc phiên âm / viết hoa đã học ở lớp 5)"]},{"cauHoi":"Viết 4 – 5 câu nêu điều em tâm đắc nhất trong “Bài ca trái đất” và một việc nhỏ em có thể làm để giữ bình yên, bảo vệ trái đất.","dang":"TL","giaiThich":"Gợi ý: Quả bóng xanh; mọi màu da đều quý; không với bom A, bom H; tiếng hát, tiếng cười.","id":"V5-B57-06","mucDo":3}],"chuDe":"8","ten":"Bài ca trái đất","tenChuDe":"Chủ điểm 8. Thế giới của chúng ta","tenGoc":"Bài 25. Bài ca trái đất","tuan":"31","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản.","Quy tắc viết tên người, tên địa lí nước ngoài; viết hoa danh từ chung để thể hiện sự tôn trọng đặc biệt."]},"58":{"cauHoi":[{"cauHoi":"Những chi tiết nào cho thấy hậu quả việc Mỹ ném hai quả bom nguyên tử xuống Nhật Bản?","dang":"TN","dapAn":0,"giaiThich":"Hai quả bom lần lượt ném xuống Hi-rô-si-ma và Na-ga-xa-ki đã cướp đi mạng sống của hàng trăm nghìn người... lên đến nửa triệu.","id":"V5-B58-01","mucDo":1,"phuongAn":["Hai quả bom ném xuống Hi-rô-si-ma và Na-ga-xa-ki cướp mạng sống hàng trăm nghìn người; đến cuối năm 1945, số người chết vì bom và nhiễm phóng xạ lên đến nửa triệu","Không có ai bị thương","Chỉ hỏng vài ngôi nhà, không có người chết","Bom không nổ"]},{"cauHoi":"Chuyện gì xảy ra với cô bé Xa-xa-ki Xa-đa-cô? Em hi vọng khỏi bệnh bằng cách nào?","dang":"TN","dapAn":2,"giaiThich":"Em bị nhiễm phóng xạ... tin vào một truyền thuyết nói rằng nếu gấp đủ một nghìn con hạc bằng giấy... sẽ khỏi bệnh.","id":"V5-B58-02","mucDo":2,"phuongAn":["Em không gấp hạc","Em khỏi bệnh ngay từ đầu","Khi Hi-rô-si-ma bị ném bom, em mới hai tuổi may mắn thoát nạn nhưng nhiễm phóng xạ; mười năm sau sức khoẻ giảm sút, nằm viện. Em tin truyền thuyết: gấp đủ một nghìn con hạc giấy treo quanh phòng sẽ khỏi bệnh, nên nén đau miệt mài gấp hạc","Em không bị ảnh hưởng gì"]},{"cauHoi":"Các bạn nhỏ đã làm gì? Điều gì xảy ra với Xa-đa-cô và sau đó?","dang":"TN","dapAn":1,"giaiThich":"Năm 1958, tượng đài Hoà bình cho trẻ em, còn gọi là tháp Xên-ba-du-rư (Ngàn cánh hạc) được dựng lên... cao 9 mét.","id":"V5-B58-03","mucDo":2,"phuongAn":["Không ai giúp em","Trẻ em toàn nước Nhật gửi hàng nghìn con hạc giấy; Xa-đa-cô vẫn không qua khỏi dù đã gấp hơn một nghìn con. Học sinh Hi-rô-si-ma quyên góp xây đài tưởng niệm; năm 1958, tượng đài Hoà bình cho trẻ em (tháp Xên-ba-du-rư – Ngàn cánh hạc) cao 9 mét được dựng ở công viên Hoà bình","Em sống đến già, không có đài tưởng niệm","Không có tượng đài"]},{"cauHoi":"Câu chuyện “Những con hạc giấy” có ý nghĩa gì? Lời khắc “Hoà bình cho thế giới!” nhấn mạnh điều gì?","dang":"TN","dapAn":1,"giaiThich":"Chúng em kêu gọi / Chúng em nguyện cầu: / Hoà bình cho thế giới!","id":"V5-B58-04","mucDo":2,"phuongAn":["Không liên quan đến hoà bình","Lên án chiến tranh, tôn vinh khát vọng sống và tình đoàn kết của trẻ em; kêu gọi hoà bình cho thế giới (trạng thái không có chiến tranh)","Ca ngợi chiến tranh","Chỉ nói về cách gấp giấy"]},{"cauHoi":"Tên thành phố Hi-rô-si-ma, Na-ga-xa-ki được viết như thế nào?","dang":"TN","dapAn":2,"giaiThich":"Quy tắc viết tên địa lí nước ngoài; dấu gạch nối nối các tiếng trong từ mượn nhiều tiếng.","id":"V5-B58-05","mucDo":1,"phuongAn":["Viết thường hết","Không được viết tên thành phố Nhật Bản","Viết hoa, phiên âm tên địa lí nước ngoài theo cách đã học (có gạch nối giữa các tiếng)","Chỉ viết chữ H, N"]},{"cauHoi":"Viết 4 – 5 câu nêu ý nghĩa câu chuyện những con hạc giấy và điều em nguyện cầu cho trẻ em thế giới.","dang":"TL","giaiThich":"Gợi ý: Hậu quả bom nguyên tử; ước mơ nghìn cánh hạc; tượng đài 1958; hoà bình cho thế giới.","id":"V5-B58-06","mucDo":3}],"chuDe":"8","ten":"Những con hạc giấy","tenChuDe":"Chủ điểm 8. Thế giới của chúng ta","tenGoc":"Bài 26. Những con hạc giấy","tuan":"31","yeuCauCanDat":["Nhận biết được những chi tiết tiêu biểu và các thông tin chính của văn bản thông tin; xác định đề tài từ nhan đề, đề mục; nhận biết mục đích, đặc điểm, bố cục của văn bản giải thích, giới thiệu sách hoặc phim, quảng cáo, chương trình hoạt động; vai trò của hình ảnh, kí hiệu hoặc số liệu.","Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Quy tắc viết tên người, tên địa lí nước ngoài; viết hoa danh từ chung để thể hiện sự tôn trọng đặc biệt."]},"59":{"cauHoi":[{"cauHoi":"Vì sao ông Uyn-tơn bay sang Tiệp Khắc tháng 12 năm 1938?","dang":"TN","dapAn":3,"giaiThich":"Uyn-tơn quyết định bay sang Tiệp Khắc khi một người bạn nhờ ông tìm cách đưa những đứa trẻ Do Thái từ Pra-ha sang Anh.","id":"V5-B59-01","mucDo":1,"phuongAn":["Ông đi du lịch nghỉ mát","Ông không liên quan đến trẻ em","Ông đi thi đại học","Một người bạn nhờ ông tìm cách đưa những đứa trẻ Do Thái từ Pra-ha sang Anh, vì chiến tranh sắp nổ ra, cơ hội trốn thoát hầu như không có, nhất là với trẻ em"]},{"cauHoi":"Ông đã làm gì để giải cứu các em? Việc làm đó có ý nghĩa gì?","dang":"TN","dapAn":0,"giaiThich":"Từ tháng 3 đến tháng 8 năm 1939, Uyn-tơn tổ chức thành công tám chuyến tàu, đưa 669 đứa trẻ rời Pra-ha... đến Luân Đôn.","id":"V5-B59-02","mucDo":2,"phuongAn":["Cùng bạn bè quyên góp, kêu gọi các gia đình ở Anh nhận nuôi; từ tháng 3 đến tháng 8 năm 1939 tổ chức thành công tám chuyến tàu, đưa 669 đứa trẻ rời Pra-ha, qua Đức, Hà Lan,... đến Luân Đôn. Ngày 1-9-1939 biên giới đóng, ông phải dừng. Ông đã cứu sống 669 em khỏi thảm sát","Ông chỉ cứu 2 người lớn","Ông kể khoe ngay từ đầu","Ông không tổ chức được chuyến nào"]},{"cauHoi":"Chi tiết ông “chưa một lần kể với ai” và 50 năm sau chuyện được hé mở cho thấy điều gì?","dang":"TN","dapAn":0,"giaiThich":"Việc giải cứu 669 đứa trẻ năm xưa ông chưa một lần kể với ai. 50 năm sau, vợ ông vô tình tìm thấy cuốn sổ.","id":"V5-B59-03","mucDo":2,"phuongAn":["Ông làm việc nghĩa một cách thầm lặng, không khoe khoang; 50 năm sau vợ tìm thấy cuốn sổ, đưa cho nhà sử học, câu chuyện mới được biết đến","Không ai được cứu","Ông kể khắp nơi ngay năm 1939","Ông không ghi chép gì"]},{"cauHoi":"Cuộc gặp năm 1988 (cả hội trường đứng lên, mọi người khóc) và việc dựng tượng ở sân ga Pra-ha nói lên điều gì?","dang":"TN","dapAn":1,"giaiThich":"Khi người dẫn chương trình hỏi: Trong số những người ngồi đây, ai đã được Uyn-tơn cứu sống? cả hội trường đứng lên. Năm 2015... Người dân Tiệp Khắc đã dựng tượng ông trên sân ga thành phố Pra-ha.","id":"V5-B59-04","mucDo":3,"phuongAn":["Không ai nhớ ông","Lòng biết ơn sâu nặng của những người được cứu; ông là người hùng thầm lặng đáng kính (mất năm 2015, thọ 106 tuổi)","Tượng được dựng ở Việt Nam, không liên quan Pra-ha","Mọi người giận ông"]},{"cauHoi":"Theo chú thích SGK, Pra-ha và Tiệp Khắc là gì?","dang":"TN","dapAn":2,"giaiThich":"Chú thích SGK: Pra-ha: thủ đô nước Cộng hoà Séc. Tiệp Khắc... từ năm 1993 tách thành hai quốc gia.","id":"V5-B59-05","mucDo":1,"phuongAn":["Pra-ha ở Nhật Bản; Tiệp Khắc ở châu Phi","Pra-ha là một dòng sông","Pra-ha: thủ đô nước Cộng hoà Séc; Tiệp Khắc: một nước ở châu Âu, từ năm 1993 tách thành Cộng hoà Séc và Cộng hoà Xlô-va-ki-a","Không có chú thích"]},{"cauHoi":"Viết 4 – 5 câu nêu ý nghĩa câu chuyện “Một người hùng thầm lặng” và phẩm chất em học được từ ông Uyn-tơn.","dang":"TL","giaiThich":"Gợi ý: Cứu 669 trẻ em; không khoe khoang; được biết ơn sau 50 năm; dũng cảm, nhân ái.","id":"V5-B59-06","mucDo":3}],"chuDe":"8","ten":"Một người hùng thầm lặng","tenChuDe":"Chủ điểm 8. Thế giới của chúng ta","tenGoc":"Bài 27. Một người hùng thầm lặng","tuan":"32","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nhận biết được những chi tiết tiêu biểu và các thông tin chính của văn bản thông tin; xác định đề tài từ nhan đề, đề mục; nhận biết mục đích, đặc điểm, bố cục của văn bản giải thích, giới thiệu sách hoặc phim, quảng cáo, chương trình hoạt động; vai trò của hình ảnh, kí hiệu hoặc số liệu.","Nhận xét được hình dáng, tính cách của nhân vật; nhận biết thời gian, địa điểm và tác dụng của chúng trong câu chuyện.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện."]},"6":{"cauHoi":[{"cauHoi":"Việt được giới thiệu như thế nào ở đầu bài “Ngôi sao sân cỏ”?","dang":"TN","dapAn":2,"giaiThich":"Tôi được bạn bè khu phố công nhận là cầu thủ xuất sắc; đợi mãi mới ra mắt trận đấu với lớp 5C.","id":"V5-B06-01","mucDo":1,"phuongAn":["Là thủ môn của lớp 5C","Chưa bao giờ đá bóng","Được bạn bè khu phố công nhận là cầu thủ xuất sắc; lần đầu ra mắt “giới hâm mộ” trường nhà trong trận với lớp 5C","Không thích bóng đá"]},{"cauHoi":"Ở đầu trận, hành động của Mạnh và Việt khác nhau ra sao?","dang":"TN","dapAn":0,"giaiThich":"Mạnh chuyền cho tôi; tôi vẫn cố hất bóng vì không muốn nhường ai cơ hội ghi bàn.","id":"V5-B06-02","mucDo":1,"phuongAn":["Mạnh lăn xả cướp bóng rồi chuyền cho đồng đội; Việt cố hất bóng một mình, không muốn nhường ai cơ hội ghi bàn","Cả hai đều chỉ chuyền bóng","Việt làm thủ môn, Mạnh không đá","Cả hai đều bỏ cuộc"]},{"cauHoi":"Vì sao Việt không đá hiệp hai và em hiểu điều gì khi Việt xem hiệp hai?","dang":"TN","dapAn":3,"giaiThich":"Vĩnh: đừng ích kỉ thế. Hiệp hai bộ ba chuyền rất ăn ý; Việt bần thần, rồi chạy vào khi được gọi.","id":"V5-B06-03","mucDo":2,"phuongAn":["Vì lớp C xin thua","Vì hết giờ học","Vì Việt bị đau chân từ đầu","Vì bị các bạn phê bình ích kỉ, ôm bóng; khi xem, Việt nhận ra chơi tập thể mới tạo được bàn thắng đẹp, rồi trở lại sân khi Chiến đau chân"]},{"cauHoi":"Câu cuối “cứ như vừa đón được một đường bóng đồng đội chuyền đến cho tôi” gợi điều gì?","dang":"TN","dapAn":2,"giaiThich":"Vĩnh gọi Việt vào vì Chiến đau chân; Việt tức tốc chạy theo, như đón đường bóng đồng đội.","id":"V5-B06-04","mucDo":3,"phuongAn":["Trận đấu bị huỷ","Việt bị đuổi khỏi sân","Việt được đồng đội tin lại, và cũng đã hiểu ra giá trị của việc chơi bóng cùng nhau","Không ai chuyền bóng nữa"]},{"cauHoi":"Trong câu “Mạnh lăn xả cướp bóng rồi chuyền cho tôi”, từ “tôi” là gì?","dang":"TN","dapAn":3,"giaiThich":"Đại từ tôi dùng để xưng hô, thay cho người kể.","id":"V5-B06-05","mucDo":1,"phuongAn":["Danh từ chỉ môn thể thao","Tính từ","Kết từ","Đại từ xưng hô (thay cho nhân vật kể chuyện – Việt)"]},{"cauHoi":"Viết 4 – 5 câu nêu ý kiến: vì sao khi chơi thể thao (hay làm việc nhóm) cần biết chuyền bóng, không ôm lấy cơ hội một mình.","dang":"TL","giaiThich":"Gợi ý: Nêu ý kiến; dẫn chuyện Việt; liên hệ bản thân.","id":"V5-B06-06","mucDo":3},{"cauHoi":"Lời phê bình thẳng thắn của Vĩnh (“đừng ích kỉ thế”) có tác dụng gì đối với Việt?","dang":"TN","dapAn":1,"giaiThich":"Bị bạn phê bình vì lối chơi ích kỉ, ôm bóng, Việt phải ngồi xem hiệp hai. Chính lúc ấy Việt mới nhận ra chơi tập thể mới tạo được bàn thắng đẹp — lời nói thẳng của bạn bè đã giúp Việt thay đổi.","id":"TV5-B06-BS01","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Khiến Việt giận bạn và không muốn chơi bóng nữa","Giúp Việt giật mình nhận ra lối chơi chỉ biết đến bản thân mình, mở đầu cho sự thay đổi của Việt","Khiến Việt càng cố ghi bàn một mình hơn","Không có tác dụng gì, Việt bỏ ngoài tai"]}],"chuDe":"1","ten":"Ngôi sao sân cỏ","tenChuDe":"Chủ điểm 1. Thế giới tuổi thơ","tenGoc":"Bài 6. Ngôi sao sân cỏ","tuan":"3","yeuCauCanDat":["Nhận xét được hình dáng, tính cách của nhân vật; nhận biết thời gian, địa điểm và tác dụng của chúng trong câu chuyện.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Đại từ và kết từ: đặc điểm và chức năng; ôn luyện danh từ, động từ, tính từ.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"60":{"cauHoi":[{"cauHoi":"Sự kiện Giờ Trái Đất do tổ chức nào phát động, nhằm mục đích gì?","dang":"TN","dapAn":3,"giaiThich":"Giờ Trái Đất là một sự kiện được Quỹ Quốc tế Bảo tồn Thiên nhiên tổ chức hằng năm nhằm nâng cao nhận thức về biến đổi khí hậu...","id":"V5-B60-01","mucDo":1,"phuongAn":["Nhằm khuyến khích dùng thêm điện","Do một trường học tổ chức để vui chơi","Không có mục đích bảo vệ môi trường","Do Quỹ Quốc tế Bảo tồn Thiên nhiên tổ chức hằng năm nhằm nâng cao nhận thức về biến đổi khí hậu và khuyến khích mọi người hành động bảo vệ Trái Đất"]},{"cauHoi":"Sự kiện được tổ chức như thế nào? Bắt đầu từ đâu, khi nào?","dang":"TN","dapAn":2,"giaiThich":"Được tổ chức vào thứ Bảy cuối cùng của tháng Ba... từ 20 giờ 30 phút đến 21 giờ 30 phút giờ địa phương. Khởi xướng lần đầu tiên tại Xít-ni, Ô-xtrây-li-a vào năm 2007.","id":"V5-B60-02","mucDo":2,"phuongAn":["Bắt đầu ở Hà Nội năm 1945","Tắt đèn cả ngày, không nêu giờ","Vào thứ Bảy cuối cùng của tháng Ba, các thành phố, thị trấn trên toàn cầu tắt đèn một giờ, từ 20 giờ 30 đến 21 giờ 30 giờ địa phương. Khởi xướng lần đầu tại Xít-ni, Ô-xtrây-li-a năm 2007","Vào mỗi sáng thứ Hai, bật thêm đèn"]},{"cauHoi":"Chi tiết nào cho thấy sự kiện thu hút thế giới? Việt Nam tham gia từ năm nào?","dang":"TN","dapAn":3,"giaiThich":"Năm 2022, sự kiện đã ghi nhận sự tham gia của hơn 190 quốc gia và vùng lãnh thổ. Việt Nam chính thức tham gia từ năm 2009.","id":"V5-B60-03","mucDo":2,"phuongAn":["Không có số liệu năm 2022","Việt Nam chưa bao giờ tham gia","Chỉ có 2 nước tham gia","Năm 2022 ghi nhận sự tham gia của hơn 190 quốc gia và vùng lãnh thổ; Việt Nam chính thức hưởng ứng từ năm 2009"]},{"cauHoi":"Sự kiện mang lại lợi ích gì? Bài đọc muốn nói điều gì?","dang":"TN","dapAn":0,"giaiThich":"Mỗi hành động nhỏ của từng cá nhân khi được nhân lên trên diện rộng sẽ lan toả và có thể làm cho môi trường sống tốt hơn.","id":"V5-B60-04","mucDo":2,"phuongAn":["Tắt thiết bị điện không cần thiết trong 60 phút giúp tiết kiệm điện, giảm khí các-bô-níc, chống biến đổi khí hậu; mỗi hành động nhỏ khi được nhân lên sẽ làm môi trường tốt hơn","Làm tăng khí các-bô-níc","Hành động nhỏ không có ý nghĩa","Không tiết kiệm điện"]},{"cauHoi":"Trong các từ quốc ca, quốc kì, quốc khánh: bài hát Tiến quân ca là gì, lá cờ đỏ sao vàng là gì, ngày 2 tháng 9 là gì?","dang":"TN","dapAn":1,"giaiThich":"SGK: Ngày 2 tháng 9 là ngày quốc khánh; quốc kì là lá cờ đỏ sao vàng; quốc ca là bài hát Tiến quân ca.","id":"V5-B60-05","mucDo":1,"phuongAn":["Ngày 2 tháng 9 là quốc ngữ","Tiến quân ca là quốc ca; cờ đỏ sao vàng là quốc kì; ngày 2 tháng 9 là quốc khánh","Tiến quân ca là quốc kì; cờ là quốc ca","Không từ nào đúng"]},{"cauHoi":"Viết đoạn văn (4 – 5 câu) nêu ý kiến tán thành việc hưởng ứng Giờ Trái Đất và những việc em có thể làm để bảo vệ Trái Đất.","dang":"TL","giaiThich":"Gợi ý: Tắt điện không cần thiết; tiết kiệm, giảm các-bô-níc; hành động nhỏ nhân lên thành sức mạnh.","id":"V5-B60-06","mucDo":3}],"chuDe":"8","ten":"Giờ Trái Đất","tenChuDe":"Chủ điểm 8. Thế giới của chúng ta","tenGoc":"Bài 28. Giờ Trái Đất","tuan":"32","yeuCauCanDat":["Nhận biết được những chi tiết tiêu biểu và các thông tin chính của văn bản thông tin; xác định đề tài từ nhan đề, đề mục; nhận biết mục đích, đặc điểm, bố cục của văn bản giải thích, giới thiệu sách hoặc phim, quảng cáo, chương trình hoạt động; vai trò của hình ảnh, kí hiệu hoặc số liệu.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Sử dụng được một số từ điển tiếng Việt thông dụng để tìm từ, nghĩa của từ, cách dùng từ và tra cứu thông tin khác.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"61":{"cauHoi":[{"cauHoi":"Cuộc gọi đầu tiên bằng điện thoại di động được giới thiệu thế nào?","dang":"TN","dapAn":1,"giaiThich":"Ngày 3 tháng 4 năm 1973, nhà phát minh Mác-tin Cúp-pơ thực hiện cuộc gọi với phiên bản đầu tiên... nặng tới 1,1 ki-lô-gam.","id":"V5-B61-01","mucDo":1,"phuongAn":["Năm 1945, bằng máy bàn","Ngày 3 tháng 4 năm 1973, nhà phát minh Mác-tin Cúp-pơ thực hiện cuộc gọi với phiên bản đầu tiên của điện thoại di động “cục gạch”, nặng tới 1,1 ki-lô-gam","Không ai phát minh điện thoại di động","Năm 2000, một học sinh lớp 5 gọi điện"]},{"cauHoi":"Điện thoại “cục gạch” ban đầu và điện thoại ngày nay khác nhau ra sao?","dang":"TN","dapAn":2,"giaiThich":"Ngày nay... nặng chưa đến 85 gam... Hệ thống định vị toàn cầu cho phép điện thoại di động có thể xác định vị trí của bạn ở bất cứ đâu.","id":"V5-B61-02","mucDo":2,"phuongAn":["Xưa đã có đầy đủ mọi chức năng như nay","Ngày nay nặng hơn xưa","Ban đầu: màn hình chỉ hiện chữ, pin dùng được khoảng hai mươi phút, nặng 1,1 kg. Ngày nay: nặng chưa đến 85 gam, bỏ vừa túi áo; gọi được cả tiếng và hình, nhắn tin, chụp ảnh, nghe nhạc, chơi game, xem phim; mua sắm, giao dịch trực tuyến, định vị toàn cầu","Ngày nay không gọi được tiếng"]},{"cauHoi":"Theo em, nếu không có điện thoại di động, con người ngày nay có thể gặp khó khăn gì (dựa vào các chức năng nêu trong bài)?","dang":"TN","dapAn":3,"giaiThich":"Bài liệt kê nhiều chức năng đã trở thành công cụ quen thuộc trong đời sống hiện đại.","id":"V5-B61-03","mucDo":2,"phuongAn":["Chỉ khó đá bóng","Không gặp khó khăn gì","Chỉ khó nấu ăn","Khó liên lạc nhanh (gọi, nhắn tin, hình ảnh), khó mua sắm và giao dịch trực tuyến, khó định vị, tìm đường, chia sẻ thông tin,..."]},{"cauHoi":"Theo chú thích SGK, Mác-tin Cúp-pơ và hệ thống định vị toàn cầu là gì?","dang":"TN","dapAn":0,"giaiThich":"Chú thích SGK nêu rõ về Mác-tin Cúp-pơ và hệ thống định vị toàn cầu.","id":"V5-B61-04","mucDo":1,"phuongAn":["Mác-tin Cúp-pơ: người nghiên cứu chế tạo điện thoại di động đầu tiên vào năm 1972-1973; hệ thống định vị toàn cầu: xác định vị trí, dẫn đường, xem bản đồ mọi nơi trên thế giới","Ông sống ở thế kỉ XIX","Không có chú thích","Ông là nhạc sĩ; định vị là một môn thể thao"]},{"cauHoi":"Trong đoạn văn, các từ “Chẳng hạn, Tuy nhiên, Vì thế” có tác dụng gì?","dang":"TN","dapAn":1,"giaiThich":"SGK luyện tập về liên kết câu trong đoạn văn (từ ngữ nối).","id":"V5-B61-05","mucDo":1,"phuongAn":["Dấu gạch nối","Từ ngữ nối, liên kết các câu trong đoạn văn","Đại từ xưng hô","Danh từ riêng"]},{"cauHoi":"Viết 4 – 5 câu nêu chức năng điện thoại di động em thấy hữu ích nhất và một lưu ý khi sử dụng (có thể dùng từ ngữ nối: tuy nhiên, vì thế).","dang":"TL","giaiThich":"Gợi ý: Liên lạc, học tập, định vị; dùng vừa phải, không lạm dụng.","id":"V5-B61-06","mucDo":3}],"chuDe":"8","ten":"Điện thoại di động","tenChuDe":"Chủ điểm 8. Thế giới của chúng ta","tenGoc":"Bài 29. Điện thoại di động","tuan":"33","yeuCauCanDat":["Nhận biết được những chi tiết tiêu biểu và các thông tin chính của văn bản thông tin; xác định đề tài từ nhan đề, đề mục; nhận biết mục đích, đặc điểm, bố cục của văn bản giải thích, giới thiệu sách hoặc phim, quảng cáo, chương trình hoạt động; vai trò của hình ảnh, kí hiệu hoặc số liệu.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Liên kết giữa các câu trong một đoạn văn; một số biện pháp liên kết câu và các từ ngữ liên kết: đặc điểm và tác dụng.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"62":{"cauHoi":[{"cauHoi":"Dự án “Thành phố thông minh Mát-xđa” được đặt ở đâu, khởi công khi nào, nhằm mục đích gì?","dang":"TN","dapAn":3,"giaiThich":"Mát-xđa là một ốc đảo nằm giữa sa mạc, thuộc UAE. Năm 2008, UAE khởi công... nhằm biến Mát-xđa trở thành thành phố không các-bô-níc đầu tiên trên thế giới.","id":"V5-B62-01","mucDo":1,"phuongAn":["Ở Hà Nội năm 1945, nhằm xây chợ","Không nêu địa điểm, thời gian","Ở Nhật Bản năm 1958, nhằm dựng tượng đài","Ở Mát-xđa, một ốc đảo giữa sa mạc, thuộc Các Tiểu vương quốc Á Rập Thống nhất (UAE); khởi công năm 2008; nhằm biến Mát-xđa thành thành phố không các-bô-níc đầu tiên trên thế giới"]},{"cauHoi":"Thành phố được thiết kế thế nào để dùng điện năng lượng mặt trời?","dang":"TN","dapAn":2,"giaiThich":"Ban ngày, những chiếc ô này vừa giúp lưu trữ năng lượng mặt trời vừa là những tấm che nắng khổng lồ. Ban đêm, chúng sẽ khép lại... cung cấp điện.","id":"V5-B62-02","mucDo":2,"phuongAn":["Chỉ dùng than đá","Ô hoa hướng dương chỉ để trang trí, không phát điện","Những chiếc ô hình hoa hướng dương: ban ngày lưu trữ năng lượng mặt trời và che nắng; ban đêm khép lại, toả nhiệt, cung cấp điện năng lượng mặt trời cho toàn thành phố","Không có tấm che nắng"]},{"cauHoi":"Vì sao Mát-xđa đối phó được với tình trạng nóng lên? Chi tiết nào cho thấy thành phố giúp giảm ô nhiễm?","dang":"TN","dapAn":0,"giaiThich":"Các toà nhà được thiết kế chụm lại với nhau... một tháp gió... khuyến khích người dân đi bộ, đi xe đạp hoặc sử dụng các phương tiện giao thông công cộng chạy bằng điện năng lượng mặt trời.","id":"V5-B62-03","mucDo":2,"phuongAn":["Nhà xây chụm, có lối đi giúp không khí lưu thông, giảm nhiệt mùa hè; tháp gió lấy không khí trên cao, mang gió mát vào. Công viên, khu thương mại theo vườn Ả Rập, nhiều cây xanh; khuyến khích đi bộ, xe đạp, phương tiện công cộng chạy điện năng lượng mặt trời","Không có tháp gió","Nhà xây thưa, không có cây","Khuyến khích dùng xe chạy xăng"]},{"cauHoi":"Câu nói việc xây thành công Mát-xđa đã truyền cảm hứng cho các dự án ở Anh, Bồ Đào Nha gợi suy nghĩ gì?","dang":"TN","dapAn":3,"giaiThich":"Đây sẽ là những đô thị sinh thái tiếp theo giúp ngăn chặn ô nhiễm môi trường và biến đổi khí hậu.","id":"V5-B62-04","mucDo":2,"phuongAn":["Không nước nào học tập","Không liên quan đến khí hậu","Chỉ có hại cho môi trường","Mô hình đô thị sinh thái có thể nhân rộng, góp phần ngăn chặn ô nhiễm và biến đổi khí hậu trên thế giới"]},{"cauHoi":"Theo chú thích SGK, “ốc đảo” và “Các Tiểu vương quốc Á Rập Thống nhất” là gì?","dang":"TN","dapAn":2,"giaiThich":"Chú thích SGK: Ốc đảo: khoảng đất có nước và cây cối giữa sa mạc. Các Tiểu vương quốc Á Rập Thống nhất: quốc gia Tây Á...","id":"V5-B62-05","mucDo":1,"phuongAn":["Không có chú thích","Ốc đảo là hòn đảo giữa biển; UAE ở châu Âu","Ốc đảo: khoảng đất có nước và cây cối giữa sa mạc; UAE: quốc gia Tây Á nằm ở phía đông nam bán đảo Ả Rập, bên vịnh Ba Tư","UAE là một thành phố của Nhật Bản"]},{"cauHoi":"Viết 4 – 5 câu nêu ý kiến tán thành việc xây dựng các đô thị sinh thái như Mát-xđa và một việc học sinh có thể làm để giảm ô nhiễm, tiết kiệm năng lượng.","dang":"TL","giaiThich":"Gợi ý: Năng lượng mặt trời, giảm các-bô-níc; đi bộ, xe đạp; hành động nhỏ hằng ngày.","id":"V5-B62-06","mucDo":3}],"chuDe":"8","ten":"Thành phố thông minh Mát-xđa","tenChuDe":"Chủ điểm 8. Thế giới của chúng ta","tenGoc":"Bài 30. Thành phố thông minh Mát-xđa","tuan":"33","yeuCauCanDat":["Nhận biết được những chi tiết tiêu biểu và các thông tin chính của văn bản thông tin; xác định đề tài từ nhan đề, đề mục; nhận biết mục đích, đặc điểm, bố cục của văn bản giải thích, giới thiệu sách hoặc phim, quảng cáo, chương trình hoạt động; vai trò của hình ảnh, kí hiệu hoặc số liệu.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"7":{"cauHoi":[{"cauHoi":"Thầy Dương muốn cả lớp làm gì dịp gần Tết?","dang":"TN","dapAn":1,"giaiThich":"Sắp nghỉ Tết, mỗi bạn sẽ sưu tầm một món đồ; ra Tết tổ chức triển lãm.","id":"V5-B07-01","mucDo":1,"phuongAn":["Cả lớp đi du lịch biển","Mỗi bạn sưu tầm một món đồ, ra Tết tổ chức triển lãm; thầy nhấn mạnh ý nghĩa, đừng chú trọng giá trị vật chất","Mỗi bạn viết một bài kiểm tra","Không tổ chức hoạt động nào"]},{"cauHoi":"Loan nảy ra ý tưởng sưu tầm gì và vì sao?","dang":"TN","dapAn":0,"giaiThich":"Loan thấy bố nghe lại băng ghi âm các bài giảng, chợt nảy ra ý tưởng sưu tầm giọng nói của cả lớp.","id":"V5-B07-02","mucDo":2,"phuongAn":["Sưu tầm giọng nói của cả lớp (câu chúc), vì thấy bố (giáo viên) nghe lại băng ghi âm bài giảng","Không sưu tầm gì","Sưu tầm kẹp sách như Khánh","Sưu tầm tem như Long"]},{"cauHoi":"Vì sao thầy Dương khen bộ sưu tập của Loan là độc đáo, ý nghĩa?","dang":"TN","dapAn":3,"giaiThich":"Mỗi giọng nói cất lên đều thật thân thương; thầy Dương: Độc đáo quá, ý nghĩa quá!","id":"V5-B07-03","mucDo":2,"phuongAn":["Vì Loan sưu tầm nhiều tem nhất","Vì không ai đến xem","Vì máy ghi âm rất đắt tiền","Đó là giọng nói, lời chúc của chính các bạn – thân thương, quen thuộc, không phải món đồ mua được"]},{"cauHoi":"Từ “tôi, chúng ta, cậu” trong lời thoại của các bạn thuộc từ loại nào?","dang":"TN","dapAn":0,"giaiThich":"Các từ ấy là đại từ xưng hô.","id":"V5-B07-04","mucDo":1,"phuongAn":["Đại từ (dùng để xưng hô)","Động từ","Dấu gạch ngang","Từ đồng nghĩa bắt buộc"]},{"cauHoi":"Bài đọc “Bộ sưu tập độc đáo” thuộc kiểu văn bản nào?","dang":"TN","dapAn":2,"giaiThich":"Bài kể câu chuyện lớp tổ chức triển lãm gần Tết.","id":"V5-B07-05","mucDo":1,"phuongAn":["Đơn xin phép","Thời khoá biểu","Truyện (kể về người và việc, có nhân vật Loan, thầy Dương, các bạn)","Bản đồ"]},{"cauHoi":"Nếu lớp em tổ chức triển lãm như lớp của Loan, em sẽ sưu tầm gì? Viết 4 – 5 câu nêu món sưu tầm và vì sao nó có ý nghĩa.","dang":"TL","giaiThich":"Gợi ý: Nêu món sưu tầm; ý nghĩa với tình bạn hoặc kỉ niệm lớp; không chỉ nói về giá trị tiền bạc.","id":"V5-B07-06","mucDo":3}],"chuDe":"1","ten":"Bộ sưu tập độc đáo","tenChuDe":"Chủ điểm 1. Thế giới tuổi thơ","tenGoc":"Bài 7. Bộ sưu tập độc đáo","tuan":"4","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Đại từ và kết từ: đặc điểm và chức năng; ôn luyện danh từ, động từ, tính từ.","Nhận biết được văn bản viết theo tưởng tượng và văn bản viết về người thật, việc thật; hiểu từ ngữ, hình ảnh, biện pháp so sánh, nhân hoá trong văn bản.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]},"8":{"cauHoi":[{"cauHoi":"Vì sao con tàu trong “Hành tinh kì lạ” phải đáp xuống hành tinh gần nhất?","dang":"TN","dapAn":1,"giaiThich":"Các kim đồng hồ rối loạn, rồi không nhúc nhích nữa. Tàu buộc phải đáp xuống hành tinh gần nhất.","id":"V5-B08-01","mucDo":1,"phuongAn":["Vì tàu muốn đáp xuống Trái Đất","Khi vượt hành lang lửa, tia sáng nhấp nháy xuất hiện, kim đồng hồ buồng lái rối loạn rồi đứng, tàu buộc phải hạ cánh","Vì hết nhiên liệu từ đầu","Vì hành khách muốn tham quan"]},{"cauHoi":"Hai nhà du hành phát hiện những điều gì đặc biệt?","dang":"TN","dapAn":2,"giaiThich":"Chăn-bai: Người máy. Da nhiều màu, tay thép; một ngày mười giờ,...; ô tô vừa chạy vừa bay.","id":"V5-B08-02","mucDo":1,"phuongAn":["Không có máy móc","Chỉ có đại dương","Người ở đó là người máy (da nhiều màu, cánh tay thép); thời gian theo hệ mười; mọi việc do máy làm; ô tô vừa chạy vừa bay theo lệnh giọng nói","Mọi thứ giống hệt Trái Đất"]},{"cauHoi":"Vì sao nhân vật “tôi” bỗng nhớ Trái Đất?","dang":"TN","dapAn":0,"giaiThich":"Càng lại gần cây càng nóng ran; đây cũng chỉ là cái máy mang hình cây. Chao ôi, tôi bỗng nhớ Trái Đất!","id":"V5-B08-03","mucDo":2,"phuongAn":["Khi sờ thân “cây đại thụ” mới thấy đó cũng chỉ là cái máy mang hình cây; thèm bóng cây râm mát và tiếng chim hót","Vì không thấy gì lạ","Vì tàu đã về ngay","Vì hết đồ ăn"]},{"cauHoi":"Bài “Hành tinh kì lạ” là văn bản viết theo tưởng tượng hay về người thật, việc thật?","dang":"TN","dapAn":1,"giaiThich":"CT: nhận biết văn bản viết theo tưởng tượng và văn bản viết về người thật, việc thật.","id":"V5-B08-04","mucDo":1,"phuongAn":["Báo cáo điểm số thật","Văn bản viết theo tưởng tượng (chuyến thám hiểm không gian, hành tinh người máy)","Biên bản họp lớp","Giấy khai sinh"]},{"cauHoi":"Trong câu “Tôi thích nhất những chiếc ô tô vừa chạy vừa bay. Chúng hoạt động theo yêu cầu bằng giọng nói.”, từ “Chúng” dùng để làm gì?","dang":"TN","dapAn":3,"giaiThich":"Chúng thay thế cho những chiếc ô tô vừa chạy vừa bay.","id":"V5-B08-05","mucDo":1,"phuongAn":["Tính từ","Đại từ xưng hô chỉ người nói","Danh từ riêng","Đại từ thay thế (thay cho những chiếc ô tô)"]},{"cauHoi":"Hãy viết một kết thúc khác (4 – 5 câu) cho câu chuyện “Hành tinh kì lạ”, trong đó hai nhà du hành tìm được cách trở về Trái Đất hoặc phát hiện thêm một điều bất ngờ.","dang":"TL","giaiThich":"Gợi ý: Bắt đầu bằng một sự việc nối tiếp (Bỗng nhiên...); giữ nhân vật “tôi” và Chăn-bai; kết rõ ràng.","id":"V5-B08-06","mucDo":3},{"cauHoi":"Chi tiết những chiếc ô tô “vừa chạy vừa bay”, hoạt động theo lệnh bằng giọng nói cho thấy người viết tưởng tượng khoa học kĩ thuật trên hành tinh ấy như thế nào?","dang":"TN","dapAn":1,"giaiThich":"Ô tô biết bay, nghe và làm theo giọng nói, mọi việc đều do máy móc đảm nhiệm — những chi tiết tưởng tượng ấy vẽ nên một nền khoa học kĩ thuật cực kì phát triển trên hành tinh của người máy.","id":"TV5-B08-BS01","mucDo":2,"nguon":"Muse soạn bổ sung cho 007 — chờ thầy duyệt","phuongAn":["Giống hệt như ở Trái Đất ngày nay","Rất phát triển, hiện đại vượt xa Trái Đất hiện nay","Lạc hậu hơn Trái Đất rất nhiều","Chỉ dùng để phục vụ việc đánh cá và trồng trọt"]}],"chuDe":"1","ten":"Hành tinh kì lạ","tenChuDe":"Chủ điểm 1. Thế giới tuổi thơ","tenGoc":"Bài 8. Hành tinh kì lạ","tuan":"4","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Nhận biết được văn bản viết theo tưởng tượng và văn bản viết về người thật, việc thật; hiểu từ ngữ, hình ảnh, biện pháp so sánh, nhân hoá trong văn bản.","Đại từ và kết từ: đặc điểm và chức năng; ôn luyện danh từ, động từ, tính từ."]},"9":{"cauHoi":[{"cauHoi":"Khổ thơ đầu bài “Trước cổng trời” (Nguyễn Đình Ảnh) tả “cổng trời” như thế nào?","dang":"TN","dapAn":0,"giaiThich":"Giữa hai bên vách đá / Mở ra một khoảng trời / Có gió thoảng, mây trôi / Cổng trời trên mặt đất?","id":"V5-B09-01","mucDo":1,"phuongAn":["Giữa hai bên vách đá mở ra một khoảng trời, có gió thoảng, mây trôi – như cổng trời trên mặt đất","Một cánh cửa nhà sàn","Một sân vận động","Một hang động dưới biển"]},{"cauHoi":"Từ cổng trời, cảnh vật hiện ra với những hình ảnh nào?","dang":"TN","dapAn":1,"giaiThich":"Bao sắc màu cỏ hoa, con thác réo, đàn dê soi đáy suối; vạt nương, lúa chín, tiếng nhạc ngựa...","id":"V5-B09-02","mucDo":1,"phuongAn":["Chỉ có phố xá và xe cộ","Sắc màu cỏ hoa, thác réo, đàn dê soi đáy suối, rừng nguyên sơ, ráng chiều, vạt nương màu mật, lúa chín, tiếng nhạc ngựa, người Giáy, người Dao tìm măng hái nấm","Không có hình ảnh nào","Chỉ có mặt biển và tàu"]},{"cauHoi":"Điều gì khiến cảnh rừng sương giá như ấm lên?","dang":"TN","dapAn":3,"giaiThich":"Vạt áo chàm thấp thoáng / Nhuộm xanh cả nắng chiều / Và gió thổi, suối reo / Ấm giữa rừng sương giá.","id":"V5-B09-03","mucDo":2,"phuongAn":["Vì không có ai trong rừng","Vì trời hoàn toàn im ắng, không gió","Vì có lửa núi","Hình ảnh con người (người Giáy, người Dao đi tìm măng, hái nấm; vạt áo chàm nhuộm xanh nắng chiều) cùng gió thổi, suối reo"]},{"cauHoi":"Những từ “ngút ngát, nguyên sơ” gần nghĩa với nhóm nào?","dang":"TN","dapAn":2,"giaiThich":"Nguyên sơ (chú thích): còn nguyên vẻ tự nhiên như lúc ban đầu.","id":"V5-B09-04","mucDo":1,"phuongAn":["Rất nhỏ / đã bị phá hết","Rất tối / không có ánh sáng","Rộng mênh mông / còn giữ vẻ tự nhiên ban đầu","Rất ồn ào / nhân tạo hoàn toàn"]},{"cauHoi":"Chủ đề gần nhất của bài thơ “Trước cổng trời” là gì?","dang":"TN","dapAn":0,"giaiThich":"Cảnh cổng trời, rừng nguyên sơ và người Giáy, người Dao trong nắng chiều.","id":"V5-B09-05","mucDo":2,"phuongAn":["Vẻ đẹp hùng vĩ, thơ mộng của thiên nhiên vùng cao và sự gắn bó của con người với núi rừng","Kĩ thuật đá bóng","Cách viết báo cáo công việc","Cuộc sống dưới đáy biển"]},{"cauHoi":"Viết 4 – 5 câu tả lại khung cảnh “cổng trời” theo hình dung của em (dựa vào khổ thơ thứ nhất và những hình ảnh em thích trong bài).","dang":"TL","giaiThich":"Gợi ý: Tả khoảng trời giữa vách đá; thêm 1 – 2 hình ảnh (thác, dê, nương lúa, áo chàm); dùng 1 cặp từ đồng nghĩa nếu được.","id":"V5-B09-06","mucDo":3}],"chuDe":"2","ten":"Trước cổng trời","tenChuDe":"Chủ điểm 2. Thiên nhiên kì thú","tenGoc":"Bài 9. Trước cổng trời","tuan":"5","yeuCauCanDat":["Nhận biết được một số chi tiết tiêu biểu và nội dung chính của văn bản; hiểu được nội dung hàm ẩn dễ nhận biết của văn bản.","Nêu những điều học được từ câu chuyện, bài thơ, màn kịch; lựa chọn điều tâm đắc nhất và giải thích vì sao; tìm được một cách kết thúc khác cho câu chuyện.","Từ đồng nghĩa: đặc điểm và tác dụng.","Chỉ ra được mối liên hệ giữa các chi tiết; biết tóm tắt văn bản; hiểu chủ đề của văn bản.","Viết được đoạn văn, bài văn theo kiểu đã học (kể chuyện sáng tạo, tả phong cảnh, tả người, báo cáo công việc, giới thiệu nhân vật trong sách hoặc phim, thể hiện tình cảm cảm xúc, nêu ý kiến tán thành hoặc phản đối, chương trình hoạt động) dựa vào gợi ý."]}},"lop":5,"mon":"Tiếng Việt","phienBan":"nen-004-v1"}};
